window.HB_TR["jeremiah"]["ur"]=["1۔ یرمیاہ بیٹے حلقیاہ کے الفاظ، ان کاہنوں کے جو انتھوت میں بنیامین کی سرزمین میں تھے:\n2۔ جس کے پاس خداوند کا کلام یوشیا کے زمانے میں آیا، جو یہوداہ کے بادشاہ آمون کا بیٹا تھا، اس کی حکومت کے تیرہویں سال میں۔\n3۔ یہ یہویاکیم کے زمانے میں بھی آیا، جو یہوداہ کے بادشاہ یوسیاہ کے بیٹے کے گیارہویں سال کے آخر تک تھا، اور پانچویں مہینے میں یروشلم کو قید کر لیا گیا۔\n4۔ پھر خداوند کا کلام میرے پاس آیا، جس نے کہا،\n5۔ اس سے پہلے کہ میں تمہیں پیٹ میں بناتا، میں تمہیں جانتا تھا؛ اور اس سے پہلے کہ تم رحم سے پیدا ہو، میں نے تمہیں مقدس بنایا، {اور} تمہیں قوموں کے لیے نبی مقرر کیا۔ {مقرر: عبرانی۔ دیا گیا}\n6۔ پھر میں نے کہا، آہ، خداوند! دیکھو، میں بول نہیں سکتا: کیونکہ میں ایک بچہ ہوں۔\n7۔ لیکن خداوند نے مجھ سے کہا، یہ نہ کہو، میں بچہ ہوں، کیونکہ تم ہر اس چیز کے پاس جاؤ گے جو میں تمہیں بھیجوں گا، اور جو کچھ میں تمہیں حکم دوں گا تو تم کہہ دینا۔\n8۔ ان کے چہروں سے مت ڈرو: کیونکہ میں تمہارے ساتھ ہوں تاکہ تمہیں نجات دوں، خداوند فرماتا ہے۔\n9۔ پھر خداوند نے اپنا ہاتھ بڑھایا اور میرے منہ کو چھوا۔ اور خداوند نے مجھ سے کہا، دیکھو، میں نے اپنے الفاظ تیرے منہ میں ڈال دیے ہیں۔\n10۔ دیکھو، آج میں نے تمہیں قوموں اور بادشاہتوں پر مقرر کیا ہے، جڑ سے اکھاڑو، ختم کرو، تباہ کرو، تباہ کرو، زمین پر ڈالو، تعمیر کرو اور بواؤ۔\n11۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا گیا، یرمیاہ، کیا دیکھا؟ اور میں نے کہا، میں بادام کے درخت کی چھڑی دیکھ رہا ہوں۔\n12۔ پھر خداوند نے مجھ سے فرمایا، تو نے اچھی طرح دیکھا: کیونکہ میں جلدی سے اپنا کلام پورا کروں گا۔\n13۔ اور خداوند کا کلام مجھ پر دوسری بار آیا، کہتا ہے: کیا دیکھا؟ اور میں نے کہا، میں ایک ابلتا ہوا برتن دیکھ رہا ہوں؛ اور اس کا رخ شمال کی طرف ہے۔ {کی طرف...: عبرانی۔ شمال کے چہرے سے}\n14۔ پھر خداوند نے مجھ سے کہا، شمال سے ایک برائی زمین کے تمام باشندوں پر پھوٹے گی۔ {ہوگا...: عبرانی کھولا جائے گا}\n15۔ کیونکہ، دیکھو، میں شمال کی سلطنتوں کے تمام خاندانوں کو بلاؤں گا، خداوند فرماتا ہے؛ اور وہ آئیں گے، اور وہ ہر ایک کو یروشلم کے دروازوں کے داخلے پر، اور اس کے ارد گرد کی تمام دیواروں کے خلاف، اور یہوداہ کے تمام شہروں کے خلاف اس کا تخت بٹھائیں گے۔\n16۔ اور میں ان کے خلاف اپنے فیصلے سناؤں گا، ان کی تمام برائیوں کے بارے میں، جنہوں نے مجھے چھوڑ دیا، اور دوسرے دیوتاؤں کے لیے لوبان جلائی، اور اپنے ہاتھوں کے کاموں کی عبادت کی۔\n17۔ لہٰذا تم اپنی کمر باندھو، اٹھو، اور ان سب سے وہ سب کہو جو میں تمہیں حکم دیتا ہوں: ان کے چہروں سے مایوس نہ ہو، ورنہ میں تمہیں ان کے سامنے الجھن میں ڈال دوں گا۔ {الجھاؤ: یا، ٹکڑے ٹکڑے ہو جاؤ}\n18۔ کیونکہ دیکھو، میں نے آج تمہیں ایک محفوظ شہر، ایک لوہے کا ستون اور پورے زمین کے خلاف، یہوداہ کے بادشاہوں کے خلاف، اس کے بادشاہوں کے خلاف، اس کے کاہنوں کے خلاف، اور زمین کے لوگوں کے خلاف ایک مضبوط شہر بنا دیا ہے۔\n19۔ اور وہ تمہارے خلاف لڑیں گے؛ لیکن وہ تم پر غالب نہیں آ سکیں گے؛ کیونکہ میں تمہارے ساتھ ہوں، خداوند فرماتا ہے، تاکہ تمہیں نجات دوں۔","1۔ مزید یہ کہ خداوند کا کلام میرے پاس آیا، جس میں کہا،\n2۔ جاؤ اور یروشلم کے کانوں میں پکار کر کہو، خداوند یوں فرماتا ہے؛ میں تمہیں یاد کرتا ہوں، تمہاری جوانی کی مہربانی، تمہارے حامیوں کی محبت، جب تم میرے پیچھے بیابان میں آتے تھے، ایک ایسی زمین میں جو ابھی بویا نہیں گیا تھا۔ {تم: یا، تمہاری خاطر}\n3۔ اسرائیل خداوند کے لیے پاکیزگی تھا، {اور} اس کی بڑھتی ہوئی پیداوار کے پہلے پھل: جو بھی اسے کھا جائے گا وہ ناراض ہوگا؛ ان پر برائی آئے گی، خداوند فرماتا ہے۔\n4۔ اے یعقوب کے گھرانے اور اسرائیل کے تمام خاندانوں کے خداوند کا کلام سنو:\n5۔ خداوند یوں فرماتا ہے، تمہارے آباؤ اجداد نے مجھ میں کون سی بدکاری دیکھی ہے کہ وہ مجھ سے دور چلے گئے، اور باطل کے پیچھے چل پڑے اور بیکار ہو گئے؟\n6۔ انہوں نے بھی نہیں کہا، وہ خداوند کہاں ہے جس نے ہمیں مصر کی سرزمین سے نکالا، جس نے ہمیں بیابانوں سے گزارا، صحرا اور گڑھوں کی زمین، خشک سالی اور موت کے سائے کی زمین سے، ایک ایسی زمین سے جہاں سے کوئی انسان نہیں گزرا، اور جہاں کوئی انسان نہیں رہتا؟\n7۔ اور میں نے تمہیں ایک بھرپور ملک میں لایا تاکہ اس کے پھل اور اس کی بھلائی کھاؤ؛ لیکن جب تم اندر آئے، تو تم نے میری زمین کو ناپاک کیا، اور میری میراث کو مکروہ بنا دیا۔ {ایک بہت...: یا، کرمل کی زمین}\n8۔ کاہنوں نے نہیں کہا، خداوند کہاں ہے؟ اور جو قانون کا خیال رکھتے تھے وہ مجھے نہیں جانتے تھے: پادری بھی میرے خلاف گناہ کرتے تھے، اور بعل کی پیش گوئی کے انبیاء نے بھی ان چیزوں کے پیچھے چلتے جو فائدہ نہیں دیتیں۔\n9۔ اسی لیے میں پھر بھی تم سے درخواست کروں گا، خداوند فرماتا ہے، اور تمہارے بچوں کے بچوں سے بھی میں درخواست کروں گا۔\n10۔ چتیم کے جزائر سے گزر کر دیکھیں؛ اور کیدار کو بھیج دو، اور غور و فکر کرو، اور دیکھو کہ کیا ایسا کچھ ہے۔ {اوور: یا، اوور ٹو}\n11. کیا کسی قوم نے اپنے دیوتاؤں کو بدل دیا ہے، جو ابھی تک کوئی خدا نہیں ہیں؟ لیکن میرے لوگوں نے اپنی شان و شوکت بدل دی ہے {اس چیز کے لیے جو فائدہ نہیں دیتی}۔\n12. اے آسمانوں، اس پر حیران ہو جاؤ، اور بہت ڈر جاؤ، تم بہت ویران ہو جاؤ، خداوند فرماتا ہے۔\n13۔ کیونکہ میرے لوگوں نے دو برائیاں کی ہیں؛ انہوں نے مجھے زندہ پانیوں کے چشمے کو چھوڑ دیا، {اور} انہیں تراشے، ٹوٹے ہوئے حوض، جو پانی نہیں رکھ سکتے۔\n14. {کیا} اسرائیل خادم ہے؟ {کیا} وہ گھر میں پیدا ہونے والا {غلام} ہے؟ وہ کیوں بگاڑا ہوا ہے؟ {سپوائلڈ: عبوری۔ برا ملنے والا؟}\n15۔ نوجوان شیر اس پر دھاڑے، {اور} چیخے، اور اس کی زمین کو ویران کر دیا: اس کے شہر بغیر کسی باشندے کے جل گئے۔ {چلا: عبرانی۔ اپنی آواز نکالی}\n16۔ نوف اور تہاپانیس کے بچوں نے بھی تمہارے سر کا تاج توڑ دیا ہے۔ {ہے...: یا، اپنے تاج پر پلاؤ}\n17۔ کیا تم نے یہ اپنے لیے حاصل نہیں کیا، کیونکہ تم نے اپنے خداوند خدا کو چھوڑ دیا، جب وہ تمہیں راستے پر لے گیا؟\n18. اور اب مصر کے راستے میں تمہیں کیا کرنا ہے، سیحور کے پانی پینے کے لیے؟ یا آشور کے راستے میں تمہیں کیا کرنا ہے، دریا کے پانی پینے کے لیے؟\n19۔ تمہاری اپنی برائی تمہیں درست کرے گی، اور تمہاری واپسی تمہیں سزا دے گی: اس لیے جان لو اور دیکھو کہ یہ ایک بری چیز ہے اور تلخ ہے، کہ تم نے خداوند اپنے خدا کو چھوڑ دیا ہے، اور میرا خوف تم میں نہیں ہے، خداوند خدا لشکروں کا فرماتا ہے۔\n20۔ کیونکہ پرانے زمانے میں میں نے تمہارا جوا توڑ دیا ہے، {اور} تمہاری پٹیاں توڑ دی ہیں؛ اور تم نے کہا، میں گناہ نہیں کروں گا؛ جب ہر اونچی پہاڑی اور ہر سبز درخت کے نیچے تم بھٹک رہے ہو، بدکار بن رہے ہو۔ {خلاف ورزی: یا، سرو}\n21۔ پھر بھی میں نے تمہارے لیے ایک عظیم بیل بوئی تھی، مکمل طور پر صحیح بیج تھی: تو پھر تم میرے لیے ایک اجنبی بیل کے زوال پذیر پودے میں کیسے بدل گئے؟\n22۔ اگرچہ تم خود کو نائٹر سے دھوتے ہو، اور بہت سا صابن لیتے ہو، {پھر بھی} تمہاری گناہ میرے سامنے نشان زد ہے، خداوند خدا فرماتا ہے۔\n23۔ تم کیسے کہہ سکتے ہو، میں آلودہ نہیں ہوں، میں بعلیم کے پیچھے نہیں گیا؟ وادی میں اپنا راستہ دیکھو، جانو تم نے کیا کیا: {تو} ایک تیز رفتار سڑک ہے جو اس کے راستوں پر چل رہا ہے؛ {تم ہو...: یا، اے تیز رفتار ڈرومیڈری}\n24۔ ایک جنگلی گدھے جو جنگل کا عادی ہے، {جو} اس کی مرضی سے ہوا کو بجھا دیتا ہے؛ اس موقع پر کون اسے واپس بھیج سکتا ہے؟ جو اس کی تلاش میں ہیں وہ خود کو تھکائیں گے نہیں؛ اس کے مہینے میں وہ اسے ڈھونڈ لیں گے۔ {ایک جنگلی...: یا، اے جنگلی گدھا، وغیرہ} {استعمال شدہ: عبرانی۔ سکھایا گیا} {اس کی خوشی: عبرانی۔ اس کے دل کی خواہش} {مڑو...: یا، اسے الٹ دو؟}\n25۔ اپنے پاؤں کو ننگے ہونے سے روکو، اور اپنی گلے کو پیاس سے روکو: لیکن تم نے کہا، کوئی امید نہیں: نہیں؛ کیونکہ میں نے اجنبیوں سے محبت کی ہے، اور ان کے پیچھے جاؤں گا۔ {وہاں...: یا، کیا معاملہ مایوس کن ہے؟}\n26۔ جیسے چور ملنے پر شرمندہ ہوتا ہے، ویسے ہی اسرائیل کا گھر بھی شرمندہ ہوتا ہے؛ وہ، ان کے بادشاہ، ان کے شہزادے، ان کے پادری، اور ان کے نبی،\n27. ایک نسل سے کہا، تو میرے باپ ہو؛ اور تم نے مجھے پتھر تک پہنچایا ہے: کیونکہ انہوں نے [اپنی} میری طرف پلٹ کر دیکھا، نہ کہ [اپنی} چہرے: لیکن اپنی مصیبت کے وقت وہ کہیں گے، اٹھو اور ہمیں بچا لو۔ {لایا...: یا، مجھے پیدا کیا} {ان کی پیٹھ پر: عبرانی۔ گردن کا پچھلا حصہ}\n28. لیکن وہ خدا کہاں ہیں جنہیں تم نے خود بنایا ہے؟ اگر وہ تمہاری مصیبت کے وقت تمہیں بچا سکتے ہیں تو اٹھیں: کیونکہ {مطابق} تیرے شہروں کی تعداد تیرے خدا ہیں، اے یہوداہ۔ {مسئلہ: عبوری۔ برائی}\n29۔ تم مجھ سے کیوں درخواست کرو گے؟ تم سب نے میرے خلاف گناہ کیا ہے، خداوند فرماتا ہے۔\n30۔ میں نے تمہارے بچوں کو بے سود متاثر کیا؛ انہیں کوئی اصلاح نہیں ملی: تمہاری اپنی تلوار نے تمہارے نبیوں کو تباہ کرنے والے شیر کی طرح نگل لیا ہے۔\n31۔ اے نسل، خداوند کے کلام کو دیکھو۔ کیا میں اسرائیل کے لیے بیابان رہا ہوں؟ اندھیرے کی سرزمین؟ اسی لیے میرے لوگ کہتے ہیں، ہم سردار ہیں؛ ہم اب تمہارے پاس نہیں آئیں گے؟ {ہم ہیں...: عبرانی۔ ہمارے پاس ڈومینین ہے}\n32۔ کیا نوکرانی اپنے زیورات بھول سکتی ہے، {یا} دلہن کو اپنا لباس بھول سکتی ہے؟ پھر بھی میرے لوگ مجھے بے شمار دنوں بھول گئے ہیں۔\n33. تم محبت تلاش کرنے کے لیے اپنا راستہ کیوں تراشی؟ اسی لیے تم نے بدکاروں کو بھی اپنے طریقے سکھائے ہیں۔\n34۔ تمہارے لباس میں معصوموں کی روحوں کا خون بھی پایا جاتا ہے: میں نے اسے خفیہ تلاش سے نہیں بلکہ ان سب پر پایا۔ {خفیہ...: عبوری۔ کھودنا}\n35۔ پھر بھی تم کہتے ہو، چونکہ میں بے قصور ہوں، یقینا اس کا غصہ مجھ سے دور ہو جائے گا۔ دیکھو، میں تم سے التجا کروں گا، کیونکہ تم کہتے ہو، میں نے گناہ نہیں کیا۔\n36. تم اتنی چالاکی کیوں کر رہے ہو کہ اپنا راستہ بدل لو؟ تم مصر سے بھی شرمندہ ہو جاؤ گے، جیسے تم آشور سے شرمندہ تھے۔\n37۔ ہاں، تم اس سے نکل جاؤ گے، اور اپنے ہاتھ اپنے سر پر رکھو گے، کیونکہ خداوند نے تمہارے وعدوں کو رد کر دیا ہے، اور تم ان میں کامیاب نہیں ہو گے۔","1۔ کہتے ہیں، اگر کوئی آدمی اپنی بیوی کو چھوڑ دے، اور وہ اس سے چلی جائے، اور دوسرے مرد کی بن جائے، تو کیا وہ دوبارہ اس کے پاس لوٹ جائے گا؟ کیا وہ زمین بہت زیادہ آلودہ نہیں ہوگی؟ لیکن تم نے بہت سے عاشقوں کے ساتھ بدکاری کی ہے؛ پھر بھی دوبارہ میرے پاس لوٹ آؤ، خداوند فرماتا ہے۔ {وہ کہتے ہیں: عبرانی۔ کہہ رہا ہوں}\n2۔ اپنی آنکھیں اونچی جگہوں کی طرف اٹھاؤ، اور دیکھو کہاں تمہیں نہیں ملا۔ جس طرح تم ان کے لیے بیٹھے ہو، جیسے بیابان میں عرب؛ اور تم نے اپنی بدکاری اور بدکاری سے زمین کو آلودہ کر دیا ہے۔\n3۔ لہٰذا بارش روک دی گئی ہے، اور کوئی بارش نہیں ہوئی؛ اور تمہارا ماتھا طوائف جیسا تھا، تم شرمندہ ہونے سے انکار کرتے تھے۔\n4۔ کیا تم اس وقت سے مجھ سے پکار نہیں سکو گے، میرے والد، تو میری جوانی کے رہنما ہو؟\n5. کیا وہ اپنا غصہ ہمیشہ کے لیے محفوظ رکھے گا؟ کیا وہ اسے آخر تک برقرار رکھے گا؟ دیکھو، تم نے اپنی مرضی کے مطابق برے کام کیے اور بات کی۔\n6۔ خداوند نے مجھ سے یوسیاہ بادشاہ کے زمانے میں بھی کہا، کیا تم نے دیکھا کہ اسرائیل نے کیا کیا ہے؟ وہ ہر اونچے پہاڑ اور ہر سبز درخت کے نیچے چڑھ گئی ہے، اور وہاں وہ بدکردار کھیل رہی ہے۔\n7۔ اور میں نے کہا کہ جب وہ یہ سب کچھ کر چکی ہے، تو میری طرف مڑ جاؤ۔ لیکن وہ واپس نہیں آئی۔ اور اس کی دھوکہ باز بہن یہوداہ نے یہ دیکھ لیا۔\n8۔ اور میں نے دیکھا، جب اسرائیل کے پیچھے ہٹنے والے تمام وجوہات کی وجہ سے میں نے اسے قید کر دیا اور طلاق کا نوٹ دیا؛ پھر بھی اس کی غدار بہن یہوداہ کو خوف نہیں تھا، بلکہ وہ بھی بدکردار بننے چلی گئی۔\n9۔ اور اس کی بدکاری کی ہلکی پھلکی وجہ سے اس نے زمین کو ناپاک کیا، اور پتھروں اور مالوں سے زنا کیا۔ {ہلکا پن: یا، شہرت}\n10۔ اور پھر بھی اس سب کے باوجود اس کی غدار بہن یہوداہ نے پورے دل سے مجھ سے رجوع نہیں کیا، بلکہ دکھاوا کر دیکھی ہے، خداوند فرماتا ہے۔ {دکھاوا کرتے ہوئے: عبوری۔ جھوٹ میں}\n11۔ اور خداوند نے مجھ سے کہا، پیچھے ہٹتے ہوئے اسرائیل نے خود کو غدار یہوداہ سے زیادہ جائز قرار دیا ہے۔\n12۔ جاؤ اور یہ الفاظ شمال کی طرف پڑھ کر کہو، اے پیچھے ہٹنے والے اسرائیل، خداوند فرماتا ہے؛ {اور} میں اپنا غصہ تم پر نہیں گراؤں گا: کیونکہ میں رحم دل ہوں، خداوند فرماتا ہے، اور میں ہمیشہ کے لیے غصہ نہیں رکھوں گا۔\n13۔ صرف اپنی گناہ تسلیم کرو کہ تم نے خداوند اپنے خدا کے خلاف سرکشی کی ہے، اور ہر سبز درخت کے نیچے اجنبیوں کے پاس اپنے راستے بکھیر دیے ہیں، اور تم نے میری آواز نہیں مانی، خداوند فرماتا ہے۔\n14. اے پیچھے ہٹنے والے بچوں، مڑو، خداوند فرماتا ہے؛ کیونکہ میں تم سے شادی شدہ ہوں: اور میں تمہیں ایک شہر اور دو خاندان کے ساتھ لے جاؤں گا، اور تمہیں صیون لے آؤں گا:\n15۔ اور میں تمہیں اپنے دل کے مطابق پادری دوں گا، جو تمہیں علم اور سمجھ سے کھلائے گا۔\n16۔ اور یہ ہو جائے گا، جب تم زمین میں بڑھو گے اور بڑھ جاؤ گے، ان دنوں خداوند فرماتا ہے، اور وہ مزید نہیں کہیں گے، خداوند کے عہد کا صندوق: نہ یہ یاد آئے گا، نہ ہی وہ اسے یاد رکھیں گے؛ نہ ہی وہ {اسے} پر جائیں گے؛ اور یہ بھی مزید نہیں کیا جائے گا۔ {ذہن میں آتا ہے: عبرانی۔ دل پر آؤ} {جو...: یا، اسے بڑھا دیا جائے}\n17۔ اس وقت وہ یروشلم کو خداوند کا تخت کہیں گے؛ اور تمام قومیں اس کے لیے جمع ہوں گی، خداوند کے نام پر، یروشلم میں: اور وہ اپنے برے دل کے تصور کے پیچھے مزید نہیں چلیں گی۔ {تخیل: یا، ضد}\n18۔ ان دنوں یہوداہ کا گھر اسرائیل کے گھر کے ساتھ چلے گا، اور وہ شمال کی زمین سے مل کر اس زمین کی طرف آئیں گے جو میں نے تمہارے آباؤ اجداد کو وراثت کے طور پر دی ہے۔ {ساتھ: یا، تو} {دیا گیا...: یا، تمہارے والد کو قبضہ کرنے پر مجبور کیا}\n19۔ لیکن میں نے کہا، میں تمہیں بچوں میں کیسے رکھوں، اور تمہیں ایک خوشگوار زمین دوں، قوموں کے لشکروں کی اچھی وراثت؟ اور میں نے کہا، تو مجھے میرے باپ کہو گا؛ اور مجھ سے منہ نہ موڑنا نہیں ہوگا۔ {میری طرف سے: عبرانی۔ میرے بعد سے} {ایک اچھا...: عبرانی۔ جلال یا خوبصورتی کی وراثت} {خوشگوار...: عبرانی۔ خواہش کی زمین}\n20. جیسا کہ بیوی اپنے شوہر سے غداری کرتی ہے، ویسے ہی تم نے میرے ساتھ دھوکہ کیا ہے، اے بنی اسرائیل، خداوند فرماتا ہے۔ {شوہر: ہیب۔ دوست}\n21۔ اونچی جگہوں پر ایک آواز سنی گئی، جو روتی ہوئی {اور} بنی اسرائیل کی دعائیں سنائی دی: کیونکہ انہوں نے اپنا راستہ بگاڑ دیا ہے، {اور} انہوں نے خداوند اپنے خدا کو بھلا دیا ہے۔\n22. واپس آؤ، اے پیچھے ہٹنے والے بچوں، {اور} میں تمہاری ناکامیوں کو ٹھیک کر دوں گا۔ دیکھو، ہم تمہارے پاس آتے ہیں؛ کیونکہ تو خداوند ہمارے خدا ہو۔\n23. واقعی بے سود نجات کی امید پہاڑوں سے، {اور پہاڑوں کی کثرت سے}: واقعی خداوند ہمارے خدا میں اسرائیل کی نجات ہے۔\n24۔ کیونکہ شرم نے ہمارے باپ اجداد کی جوانی سے محنت کو نگل لیا ہے؛ ان کے ریوڑ اور ریوڑ، ان کے بیٹے اور بیٹیاں۔\n25۔ ہم اپنی شرمندگی میں لیٹتے ہیں، اور ہماری الجھن ہمیں ڈھانپ لیتی ہے: کیونکہ ہم نے خداوند ہمارے خدا، ہم اور اپنے باپوں کے خلاف گناہ کیا ہے، اپنی جوانی سے آج تک، اور خداوند ہمارے خدا کی آواز کی اطاعت نہیں کی۔","1. اے اسرائیل، اگر تم واپس آنا چاہو، اے اسرائیل، خداوند فرماتا ہے، تو میرے پاس واپس آؤ۔ اور اگر تم اپنی گناہوں کو میری نظر سے دور کرنا چاہتے ہو، تو تم ہٹاؤ نہیں۔\n2۔ اور تم قسم کھاؤ کہ خداوند سچائی، انصاف میں اور راستبازی میں زندہ ہے؛ اور قومیں اس میں خود کو برکت دیں گی، اور اس پر فخر کریں گی۔\n3۔ کیونکہ خداوند یہوداہ اور یروشلم کے لوگوں سے یوں فرماتا ہے، اپنی زمین کو توڑو، اور کانٹوں میں نہ بوؤ۔\n4۔ خداوند کے سامنے خود کو ختنہ کرو، اور اپنے دل کی کھالیں ہٹا دو، اے یہوداہ کے لوگ اور یروشلم کے باشندو، ورنہ میرا غصہ آگ کی طرح نکلے گا اور جل جائے گا کہ کوئی اسے بجھا نہ سکے، تمہارے اعمال کی برائی کی وجہ سے۔\n5۔ یہوداہ میں اعلان کرو، اور یروشلم میں شائع کرو؛ اور کہو، تم زمین میں بگل بجاؤ: پکارو، جمع ہو جاؤ، اور کہو، جمع ہو جاؤ، اور ہم محفوظ شہروں میں چلتے ہیں۔\n6۔ صہیون کے لیے معیار قائم کرو: پیچھے ہٹو، نہ رہو: کیونکہ میں شمال سے برائی لاؤں گا، اور عظیم تباہی۔ {ریٹائر: یا، مضبوط کریں} {تباہی: عبرانی۔ بریکنگ}\n7۔ شیر اپنی جھاڑیوں سے نکل آیا ہے، اور غیر قوموں کا تباہ کرنے والا راستے میں ہے؛ وہ اپنی جگہ سے نکل کر تمہاری زمین کو ویران کر رہا ہے؛ {اور} تمہارے شہر تباہ ہو جائیں گے، بغیر کسی باشندے کے۔\n8۔ اس کے لیے تمہیں تھیلی کے کپڑوں سے باندھا، نوحہ اور چیخ و پکار ہے: کیونکہ خداوند کا شدید غضب ہم سے واپس نہیں جاتا۔\n9۔ اور اسی دن یہ عمل ہوگا، خداوند فرماتا ہے، {کہ} بادشاہ کا دل فنا ہو جائے گا، اور شہزادوں کا دل؛ اور کاهن حیران رہ جائیں گے، اور نبی حیران ہوں گے۔\n10۔ پھر میں نے کہا، آہ، خداوند! یقینا تم نے اس قوم اور یروشلم کو بہت دھوکہ دیا ہے، کہہ کر، تم امن پاؤ گے؛ جبکہ تلوار روح تک پہنچتی ہے۔\n11۔ اس وقت اس قوم اور یروشلم سے کہا جائے گا، ویرانے میں اونچی جگہوں کی خشک ہوا میرے قوم کی بیٹی کی طرف، نہ ہوا کے لیے اور نہ صاف کرنے کے لیے،\n12. {حتیٰ کہ} ان {جگہوں} سے ایک مکمل ہوا میرے پاس آئے گی: اب میں ان کے خلاف بھی سزا سناؤں گا۔ {ایک مکمل...: یا، ان سے زیادہ تیز ہوا} {دیں...: عببرانی۔ مکمل فیصلے}\n13۔ دیکھو، وہ بادلوں کی طرح اوپر آئے گا، اور اس کے رتھ ایک طوفان کی طرح ہوں گے: اس کے گھوڑے عقاب سے تیز ہیں۔ ہم پر افسوس ہے! کیونکہ ہم بگڑے ہوئے ہیں۔\n14. اے یروشلم، اپنے دل کو برائی سے دھو تاکہ تم نجات پا سکو۔ تمہارے فضول خیالات کب تک تمہارے اندر رہیں گے؟\n15۔ کیونکہ دان کی طرف سے ایک آواز اعلان کرتی ہے، اور افرائیم پہاڑ سے مصیبت پھیلاتی ہے۔\n16۔ قوموں کو ذکر کرو؛ دیکھو، یروشلم کے خلاف شائع کرو، {کہ} نگرانی کرنے والے دور دراز ملک سے آتے ہیں، اور یہوداہ کے شہروں کے خلاف آواز اٹھاتے ہیں۔\n17۔ کھیت کے محافظ ہونے کے ناطے، کیا وہ اس کے خلاف ہیں؛ کیونکہ وہ میرے خلاف بغاوت کر رہی ہے، خداوند فرماتا ہے۔\n18۔ تمہارے طریقے اور تمہارے اعمال نے یہ {چیزیں} تمہیں عطا کی ہیں؛ یہ تیری برائی ہے، کیونکہ یہ تلخ ہے، کیونکہ یہ تمہارے دل تک پہنچتی ہے۔\n19۔ میری آنتیں، میری آنتیں! میرے دل سے درد ہے؛ میرا دل میرے اندر شور کرتا ہے؛ میں خاموش نہیں رہ سکتا، کیونکہ تم نے، اے میری جان، ترمپٹ کی آواز سنی ہے، جنگ کی خبر۔ {میرا بہت...: عبرانی۔ میرے دل کی دیواریں}\n20. تباہی کے بعد تباہی کا پکار اٹھایا جاتا ہے؛ کیونکہ پوری زمین برباد ہو گئی ہے: اچانک میرے خیمے خراب ہو جاتے ہیں، {اور} میرے پردے بھی ایک لمحے میں۔\n21. میں کتنی دیر تک پرچم دیکھوں گا، {اور} ترمپٹ کی آواز سنوں گا؟\n22۔ کیونکہ میرے لوگ بے وقوف ہیں، انہوں نے مجھے نہیں جانا؛ وہ {سوٹش} بچے ہیں، اور ان میں کوئی سمجھ نہیں: وہ برائی کرنے میں عقلمند ہیں، لیکن نیکی کرنے کے لیے انہیں کوئی علم نہیں۔\n23۔ میں نے زمین کو دیکھا، اور دیکھو، وہ بے شکل اور خالی تھی؛ اور آسمانوں کو، اور ان کے پاس روشنی نہیں تھی۔\n24۔ میں نے پہاڑوں کو دیکھا، اور دیکھو، وہ کانپ رہے تھے، اور تمام پہاڑیاں ہلکی سی حرکت کر رہی تھیں۔\n25۔ میں نے دیکھا، اور دیکھو، کوئی انسان نہیں تھا، اور آسمان کے تمام پرندے بھاگ گئے۔\n26۔ میں نے دیکھا، اور دیکھو، زرخیز جگہ ایک ویران تھی، اور اس کے تمام شہر خداوند کی موجودگی میں تباہ ہو گئے، {اور} اس کے شدید غصے سے۔\n27۔ کیونکہ خداوند نے ایسا فرمایا، پوری زمین ویران ہو جائے گی؛ پھر بھی میں مکمل طور پر ختم نہیں کروں گا۔\n28۔ کیونکہ زمین اس کا سوگ منائے گی، اور آسمان اوپر سیاہ ہو جائیں گے: کیونکہ میں نے کہا ہے، میں نے ارادہ کیا ہے، اور نہ توبہ کروں گا، نہ ہی اس سے پیچھے ہٹوں گا۔\n29۔ پورا شہر گھڑ سواروں اور تیر اندازوں کی آواز کے لیے بھاگ جائے گا؛ وہ جھاڑیوں میں جائیں گے، اور چٹانوں پر چڑھیں گے: ہر شہر کو چھوڑ دیا جائے گا، اور وہاں کوئی انسان نہیں رہتا۔\n30۔ اور جب تم خراب ہو جاؤ گے، تو کیا کرو گے؟ اگر تم اپنے آپ کو سرخ رنگ میں ملبوس کرو، چاہے تم خود کو سونے کے زیورات سے سجا دو، چاہے تم اپنے چہرے کو رنگ سے سجا دو، تو تم خود کو بے سود خوبصورت بنا لو گے؛ تمہارے عاشق تمہیں حقیر سمجھیں گے، وہ تمہاری جان تلاش کریں گے۔ {چہرہ: عبوری۔ آنکھیں}\n31۔ کیونکہ میں نے ایک عورت کی آواز سنی ہے جو مصیبت میں ہے، {اور} اس کی اذیت جو اپنی پہلی اولاد کو جنم دیتی ہے، صیہون کی بیٹی کی آواز، {جو} اپنے آپ پر افسوس کرتی ہے، {جو} اپنے ہاتھ پھیلاتی ہے، {کہتی ہے}، افسوس، اب مجھ پر! کیونکہ میری روح قاتلوں کی وجہ سے تھک چکی ہے۔","1. یروشلم کی گلیوں میں ادھر ادھر دوڑو، اور اب دیکھو، جانو، اور اس کے وسیع مقامات پر تلاش کرو، اگر تمہیں کوئی آدمی مل جائے، اگر کوئی ایسا شخص ہے جو فیصلہ کرتا ہے، جو سچائی تلاش کرتا ہے؛ اور میں اسے معاف کر دوں گا۔\n2۔ اور اگرچہ وہ کہتے ہیں، خداوند زندہ ہے؛ یقینا وہ جھوٹی قسم کھاتے ہیں۔\n3. اے خداوند، کیا تیری آنکھیں سچائی پر نہیں ہیں؟ تم نے انہیں مارا ہے، لیکن وہ غمگین نہیں ہوئے؛ تم نے انہیں کھا لیا، {لیکن} انہوں نے اصلاح قبول کرنے سے انکار کر دیا: انہوں نے اپنے چہرے پتھر سے بھی سخت کر دیے؛ انہوں نے واپس جانے سے انکار کر دیا ہے۔\n4۔ اس لیے میں نے کہا، یقینا یہ غریب ہیں؛ وہ بے وقوف ہیں: کیونکہ وہ خداوند کے راستے کو نہیں جانتے، نہ ہی اپنے خدا کے فیصلے کو۔\n5۔ میں خود کو عظیم لوگوں کے پاس لے جاؤں گا، اور ان سے بات کروں گا؛ کیونکہ انہوں نے خداوند کے راستے کو جانا ہے، {اور} اپنے خدا کے فیصلے کو: لیکن یہ سب بندھن توڑ چکے ہیں، {اور} بندھن توڑ چکے ہیں۔\n6۔ اسی لیے جنگل سے شیر انہیں مار ڈالے گا، اور شام کا بھیڑیا انہیں برباد کرے گا، ایک چیتا ان کے شہروں کی حفاظت کرے گا: جو بھی وہاں سے جائے گا وہ ٹکڑے ٹکڑے ہو جائے گا: کیونکہ ان کی غلطیاں بہت زیادہ ہیں، اور ان کی واپسی بڑھ گئی ہے۔ {شامیں: یا، صحرا} {بڑھا دیا گیا ہے: عبرانی۔ مضبوط ہیں}\n7. میں تمہیں اس کے لیے کیسے معاف کروں؟ تمہارے بچوں نے مجھے چھوڑ دیا ہے، اور ان لوگوں کی قسم کھا لی ہے جو خدا نہیں ہیں: جب میں نے انہیں پورا کھانا کھلایا، تو انہوں نے کیا اور فوج کے ذریعے بدکار عورتوں کے گھروں میں جمع ہو گئے۔\n8۔ انہیں صبح کے وقت گھوڑوں کی طرح کھلایا جاتا تھا: ہر ایک اپنے پڑوسی کی بیوی کے بعد ہنہناتا تھا۔\n9. کیا میں ان {چیزوں} کے لیے نہیں آؤں؟ خداوند فرماتا ہے: اور کیا میری جان کو ایسی قوم سے بدلہ نہیں لیا جائے گا؟\n10۔ تم اس کی دیواروں پر چڑھو اور تباہ کرو؛ لیکن مکمل اختتام نہ کریں: اس کے قلعے ہٹا دیں؛ کیونکہ وہ خدا کے نہیں ہیں۔\n11۔ کیونکہ اسرائیل کے گھر اور یہوداہ کے گھر نے میرے ساتھ بہت غداری کی ہے، خداوند فرماتا ہے۔\n12۔ انہوں نے خداوند کو جھٹلا دیا اور کہا، {یہ وہ نہیں ہے}؛ نہ ہی ہم پر برائی آئے گی؛ نہ تلوار دیکھیں گے نہ قحط:\n13۔ اور نبی ہوا بن جائیں گے، اور کلام ان میں نہیں ہے: اسی طرح ان کے ساتھ کیا جائے گا۔\n14۔ لہٰذا خداوند خدا، لشکروں کا یہی فرماتا ہے، کیونکہ تم یہ کلام بولتے ہو، دیکھو، میں اپنے الفاظ کو تمہارے منہ میں آگ بنا دوں گا، اور اس قوم کو لکڑی بنا دوں گا، اور یہ انہیں نگل جائے گا۔\n15۔ دیکھو، میں دور سے ایک قوم تم پر لاؤں گا، اے بنی اسرائیل، خداوند فرماتا ہے: یہ ایک عظیم قوم ہے، یہ ایک قدیم قوم ہے، ایک ایسی قوم جس کی زبان تم نہیں جانتے اور نہ ہی ان کی باتیں سمجھتے ہو۔\n16۔ ان کا ترکش {ہے} ایک کھلی قبر کی طرح، وہ {ہیں} تمام طاقتور لوگ۔\n17۔ اور وہ تمہاری فصل اور تمہاری روٹی کو کھا جائیں گے، جو تمہارے بیٹے اور بیٹیاں کھائیں گے، وہ تمہارے ریوڑ اور تمہارے ریوڑ کو کھا جائیں گے، وہ تمہارے بیلوں اور انجیر کے درخت کھائیں گے، وہ تمہارے باڑ والے شہروں کو، جن پر تم نے بھروسہ کیا تھا، تلوار سے غریب کر دیں گے۔\n18. پھر بھی، ان دنوں خداوند فرماتا ہے، میں تمہارے ساتھ مکمل طور پر ختم نہیں کروں گا۔\n19۔ اور یہ اس وقت ہوگا جب تم کہو گے، خداوند ہمارے خدا نے یہ سب چیزیں ہمارے لیے کیوں دی؟ پھر تم ان کا جواب دو گے، جیسے تم نے مجھے چھوڑ کر اپنے ملک میں اجنبی دیوتاؤں کی خدمت کی، ویسے ہی تم اجنبیوں کی خدمت کرو گے ایسی زمین میں جو تمہاری نہیں ہے۔\n20۔ اسے یعقوب کے گھرانے میں اعلان کرو، اور یہوداہ میں شائع کرو، کہہ دو،\n21. اے بے وقوف لوگو، اب یہ سنو، اور بے سمجھ؛ جن کی آنکھیں ہیں، اور وہ نہیں دیکھتے؛ جن کے کان ہیں، اور وہ نہیں سنتے: {سمجھ: عبرانی۔ دل}\n22۔ کیا تم مجھ سے نہیں ڈرتے؟ خداوند فرماتا ہے: کیا تم میری موجودگی پر کانپتے نہیں، جس نے ریت کو سمندر کی پابندی کے لیے ہمیشہ کے لیے مقرر کر دیا ہے، کہ وہ اس سے گزر نہیں سکتا؛ اور اگرچہ اس کی لہریں خود بخود اچھلتی ہیں، پھر بھی وہ غالب نہیں آ سکتیں؛ اگرچہ وہ دہاڑتے ہیں، کیا وہ اس کے اوپر سے گزر نہیں سکتے؟\n23۔ لیکن اس قوم کا دل باغی اور باغی ہے؛ وہ بغاوت کر کے چلے جاتے ہیں۔\n24۔ وہ دل سے نہیں کہتے، اب ہم اپنے خداوند خدا سے ڈریں، جو اپنے موسم میں بارش دیتا ہے، پہلا اور دوسرا دونوں: وہ فصل کی مقررہ ہفتوں کو ہمارے لیے محفوظ رکھتا ہے۔\n25. تمہاری گناہوں نے یہ {چیزیں} دور کر دی ہیں، اور تمہارے گناہوں نے تم سے اچھائی چھین لی ہے۔\n26۔ کیونکہ میرے لوگوں میں بدکار پائے گئے {لوگ}: وہ انتظار کرتے ہیں، جیسے وہ جال میں پھنستا ہے؛ وہ جال بچھاتے ہیں، مردوں کو پکڑ لیتے ہیں۔ {وہ لیٹے ہیں...: یا، وہ جھانکتے ہیں جب پرندے انتظار میں بیٹھے ہیں}\n27. جیسے پنجرہ پرندوں سے بھرا ہوتا ہے، ویسے ہی ان کے گھر دھوکہ دہی سے بھرے ہوتے ہیں: اسی لیے وہ بڑے اور امیر ہو جاتے ہیں۔ {پنجرہ: یا، کوپ}\n28۔ وہ موم کے موٹے ہیں، وہ چمکتے ہیں: ہاں، وہ بدکاروں کے اعمال سے آگے نکل جاتے ہیں: وہ یتیم کے مقصد اور مقصد کا فیصلہ نہیں کرتے، پھر بھی وہ خوشحال ہوتے ہیں؛ اور محتاجوں کے حق کا وہ فیصلہ نہیں کرتے۔\n29. کیا میں ان {چیزوں} کے لیے نہیں آؤں؟ خداوند فرماتا ہے: کیا میری روح کو ایسی قوم سے بدلہ نہیں لیا جائے گا؟\n30۔ زمین میں ایک حیرت انگیز اور خوفناک کام ہوتا ہے؛ {ایک شاندار...: یا، حیرت اور گندگی}\n31۔ نبی جھوٹی نبوت کرتے ہیں، اور پادری اپنی مرضی سے حکمرانی کرتے ہیں؛ اور میرے لوگ اسے حاصل کرنا پسند کرتے ہیں: اور آخر میں تم کیا کرو گے؟ {bear...: یا، اپنے ہاتھوں میں لے لیں}","1۔ اے بنیامین کے بچوں، خود کو جمع کرو اور یروشلم کے بیچ سے نکل جاؤ، تیقوع میں بگل بجاؤ، اور بیت ہکریم میں آگ کا نشان قائم کرو، کیونکہ شمال سے برائی نمودار ہوتی ہے اور بڑی تباہی ہوتی ہے۔\n2. میں نے صہیون کی بیٹی کو ایک خوبصورت اور نازک عورت سے تشبیہ دی ہے۔ {خوبصورت: یا، گھر میں رہنا}\n3۔ چرواہے اپنے ریوڑ کے ساتھ اس کے پاس آئیں گے؛ وہ اس کے ارد گرد اپنے خیمے کھڑا کریں گے؛ وہ سب کو اس کی جگہ کھلائیں گے۔\n4۔ اس کے خلاف جنگ کی تیاری کرو؛ اٹھو، اور دوپہر کو اوپر چلیں۔ ہم پر افسوس ہے! کیونکہ دن چلا جاتا ہے، کیونکہ شام کے سائے پھیلے ہوئے ہیں۔\n5۔ اٹھو، اور رات کو چلیں، اور اس کے محل تباہ کر دیں۔\n6۔ کیونکہ لشکروں کے رب نے یہی فرمایا، درخت کاٹ دو اور یروشلم کے خلاف ایک سواری پھینکو: یہ وہ شہر ہے جس کی زیارت کی جانی چاہیے؛ وہ مکمل طور پر ظلم و ستم میں مبتلا ہے۔ {cast...: یا، انجن آف شاٹ نکالو}\n7۔ جیسے چشمہ اپنا پانی بہاتا ہے، ویسے ہی وہ اپنی برائی نکالتی ہے: اس میں تشدد اور لوٹ مار سنائی دیتی ہے؛ میرے سامنے مسلسل غم اور زخم ہیں۔\n8۔ اے یروشلم، تو ہدایت دے کہ میری روح تم سے دور نہ ہو جائے؛ کہیں میں تمہیں ویران نہ کر دوں، ایک ایسی سرزمین جو آباد نہیں۔ {روانگی: عبرانی۔ آزاد ہو جائیں، یا، بے ربط ہو جائیں}\n9۔ لشکروں کے رب نے یوں فرمایا، وہ اسرائیل کے باقیات کو بیل کی طرح اچھی طرح نکالیں گے: اپنا ہاتھ واپس ٹوکریوں میں گھماؤ۔\n10۔ میں کس سے بات کروں اور خبردار کروں تاکہ وہ سن سکیں؟ دیکھو، ان کا کان ختنہ نہیں ہوا اور وہ سن نہیں سکتے: دیکھو، خداوند کا کلام ان کے لیے ملامت ہے؛ انہیں اس میں کوئی خوشی نہیں ہوتی۔\n11۔ اسی لیے میں خداوند کے غضب سے بھرا ہوا ہوں؛ میں برداشت کرنے میں تھک چکا ہوں: میں اسے بیرون ملک بچوں اور نوجوانوں کے اجتماع پر بہاؤں گا: کیونکہ شوہر اور بیوی کو بھی لیا جائے گا، بوڑھا بھی اس کے ساتھ جو دن بھر گیا ہو۔\n12۔ اور ان کے گھر دوسروں کے حوالے کر دیے جائیں گے، {ان کی} کھیتوں اور بیویوں کے ساتھ: کیونکہ میں زمین کے باشندوں پر اپنا ہاتھ بڑھاؤں گا، خداوند فرماتا ہے۔\n13۔ کیونکہ ان میں سے سب سے چھوٹے سے لے کر سب سے بڑے تک ہر کوئی لالچ میں مبتلا ہو جاتا ہے؛ اور نبی سے کاہن تک ہر کوئی جھوٹ بولتا ہے۔\n14۔ انہوں نے میرے لوگوں کی بیٹی کے زخم کو بھی تھوڑا سا ٹھیک کیا ہے، کہتے ہوئے، امن، امن؛ جب {وہاں سکون نہیں ہوتا}۔ {زخمی: عبوری۔ زخم، یا، توڑنا}\n15. کیا وہ شرمندہ تھے جب انہوں نے مکروہ کام کیا؟ نہیں، وہ بالکل شرمندہ نہیں ہوئے، نہ ہی شرمندہ ہو سکتے تھے: اس لیے وہ گرنے والوں کے درمیان گر جائیں گے: جب میں ان سے ملوں گا تو وہ گر جائیں گے، خداوند فرماتا ہے۔\n16۔ خداوند فرماتا ہے، راستوں پر کھڑے رہو، دیکھو، اور پرانے راستوں کے لیے دعا کرو، جہاں {ہے} اچھا راستہ، اور وہاں چلو، اور اپنی روحوں کے لیے سکون پاؤ گے۔ لیکن انہوں نے کہا، ہم وہاں نہیں چلیں گے۔\n17. اور میں تمہارے اوپر پہرہ دار مقرر کرتا ہوں، {کہتا ہوں}، ترمپٹ کی آواز سنو۔ لیکن انہوں نے کہا، ہم نہیں سنیں گے۔\n18. لہٰذا اے قوموں کو سنو اور جانو، اے جماعت، کہ ان میں کیا ہے۔\n19۔ سنو، اے زمین: دیکھو، میں اس قوم پر برائی لاؤں گا، {حتیٰ کہ} ان کے خیالات کا پھل بھی، کیونکہ انہوں نے میرے الفاظ اور میرے قانون کو نہیں سنا، بلکہ اسے رد کر دیا۔\n20۔ میرے لیے سبا سے لوبان اور دور دراز ملک سے میٹھا چھڑی کس مقصد کے لیے آتی ہے؟ تمہاری جلی ہوئی قربانیاں قابل قبول نہیں، اور تمہاری قربانیاں میرے لیے میٹھی نہیں ہیں۔\n21۔ لہٰذا خداوند فرماتا ہے، دیکھو، میں اس قوم کے سامنے رکاوٹیں کھڑا کروں گا، اور باپ اور بیٹے مل کر ان پر گر جائیں گے؛ پڑوسی اور اس کا دوست ہلاک ہو جائیں گے۔\n22۔ خداوند یوں فرماتا ہے، دیکھو، ایک قوم شمالی ملک سے آتی ہے، اور زمین کے کنارے سے ایک عظیم قوم اٹھی گی۔\n23۔ وہ کمان اور نیزے کو مضبوطی سے پکڑیں گے؛ وہ ظالم ہیں، اور ان پر کوئی رحم نہیں؛ ان کی آواز سمندر کی طرح گرجتی ہے؛ اور وہ گھوڑوں پر سوار ہوتے ہیں، جو تیرے خلاف جنگ کے لیے قطار میں کھڑے ہیں، اے صیہون کی بیٹی۔\n24۔ ہم نے اس کی شہرت سنی ہے: ہمارے ہاتھ کمزور ہو گئے ہیں: اذیت نے ہمیں گھیر لیا ہے، {اور} درد، جیسے ایک عورت کی مصیبت۔\n25۔ کھیت میں نہ جاؤ، نہ راستے سے گزرو؛ کیونکہ دشمن کی تلوار {اور} خوف {ہر طرف ہے}۔\n26۔ اے میری قوم کی بیٹی، اپنے آپ کو تھیلے کے کپڑے میں باندھو، اور راکھ میں خود کو ڈبو دے: اپنے اکلوتے بیٹے کے لیے، سب سے تلخ ماتم کرو: کیونکہ خراب کرنے والا اچانک ہم پر آ جائے گا۔\n27. میں نے تمہیں اپنے لوگوں میں ایک مینار اور قلعہ بنایا ہے، تاکہ تم ان کا راستہ جان سکو اور آزما سکو۔\n28۔ وہ سب سخت بغاوت کرنے والے ہیں، بہتان کے ساتھ چل رہے ہیں: وہ پیتل اور لوہے کے ہیں؛ وہ سب بگاڑنے والے ہیں۔\n29۔ بیلوز جل جاتے ہیں، سیسہ آگ سے جل جاتا ہے؛ بانی بے سود پگھلتا ہے: کیونکہ بدکاروں کو نہیں نکالا جاتا۔\n30۔ ناپاک چاندی کو {لوگ} بلائیں گے، کیونکہ خداوند نے انہیں مسترد کر دیا ہے۔ {مذموم...: یا، چاندی سے انکار کرو}","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، اور کہا،\n2۔ خداوند کے گھر کے دروازے پر کھڑے ہو جاؤ، اور وہاں یہ کلام پڑھو، اور کہو، خداوند کا کلام سنو، تمام یہوداہ کے لوگ، جو ان دروازوں سے داخل ہو کر خداوند کی عبادت کرتے ہیں۔\n3۔ یوں لشکروں کے رب، اسرائیل کے خدا فرماتا ہے، اپنے طریقے اور اعمال درست کرو، اور میں تمہیں اس جگہ میں بساؤں گا۔\n4. جھوٹے الفاظ پر بھروسہ نہ کرو، جو کہہ رہے ہو، خداوند کا مندر، خداوند کا مندر، خداوند کا مندر، یہ سب ہیں۔\n5۔ اگر تم اپنے طریقے اور اعمال کو مکمل طور پر بدلو؛ اگر آپ کسی آدمی اور اس کے پڑوسی کے درمیان مکمل طور پر فیصلہ کریں؛\n6. اگر تم اجنبی، یتیم اور بیوہ پر ظلم نہ کرو، اور اس جگہ معصوم خون نہ بہاؤ، نہ ہی دوسرے دیوتاؤں کے پیچھے چل کر اپنی تکلیف پہنچاؤ:\n7۔ پھر میں تمہیں اس جگہ میں بساؤں گا، اس زمین میں جو میں نے تمہارے باپ کو دی ہے، ہمیشہ کے لیے۔\n8۔ دیکھو، تم جھوٹے الفاظ پر بھروسہ کرتے ہو، جو فائدہ نہیں رکھتے۔\n9۔ کیا تم چوری کرو گے، قتل کرو گے، کرو گے، جھوٹ قسم کھاؤ گے، بعل کے لیے لوبان جلاؤ گے، اور ان دیوتاؤں کے پیچھے چلو گے جنہیں تم نہیں جانتے؟\n10۔ اور آؤ اور اس گھر میں میرے سامنے کھڑے ہو جاؤ، جسے میرے نام سے پکارا جاتا ہے، اور کہو، ہم یہ سب گناہ کرنے کے لیے آزاد ہوئے ہیں؟ {جو کہ...: عبرانی جس پر میرا نام پکارا جاتا ہے}\n11. کیا یہ گھر، جو میرے نام سے پکارا جاتا ہے، تمہاری نظر میں ڈاکوؤں کا ٹھکانہ بن گیا ہے؟ دیکھو، میں نے بھی یہ دیکھا ہے، خداوند فرماتا ہے۔\n12۔ لیکن اب میرے مقام پر جاؤ جو شیلوہ میں {تھی}، جہاں میں نے اپنا نام پہلے رکھا تھا، اور دیکھو کہ میں نے اپنے قوم اسرائیل کی برائی کے لیے وہاں کیا کیا۔\n13۔ اور اب، چونکہ تم نے یہ سب کام کیے ہیں، خداوند فرماتا ہے، اور میں نے تم سے کہا، صبح اٹھ کر بولا، لیکن تم نے نہیں سنا؛ اور میں نے تمہیں بلایا، لیکن تم نے جواب نہیں دیا؛\n14۔ اسی لیے میں اس گھر کے ساتھ جو میرے نام سے پکارا جاتا ہے، جس پر تم بھروسہ کرتے ہو، اور اس جگہ کے ساتھ جو میں نے تمہیں اور تمہارے آباؤ اجداد کو دی، جیسا کہ میں نے شیلوہ کو دی ہے۔\n15۔ اور میں تمہیں اپنی نظر سے دور کر دوں گا، جیسے میں نے تمہارے تمام بھائیوں کو، حتیٰ کہ افرائیم کی پوری نسل کو بھی نکال دیا ہے۔\n16۔ اس لیے اس قوم کے لیے دعا نہ کرو، نہ ان کے لیے پکار اٹھاؤ نہ دعا کرو، نہ مجھ سے شفاعت کرو، کیونکہ میں تمہاری بات نہیں سنوں گا۔\n17۔ کیا تم نہیں دیکھتے کہ وہ یہوداہ کے شہروں اور یروشلم کی گلیوں میں کیا کرتے ہیں؟\n18۔ بچے لکڑیاں جمع کرتے ہیں، اور باپ آگ جلاتے ہیں، اور عورتیں [اپنی} آٹا گوندھتی ہیں، تاکہ آسمان کی ملکہ کو کیک بنائی جا سکے، اور دوسرے دیوتاؤں کو شراب کی نذرانہ ڈالیں، تاکہ وہ مجھے غصہ دلا سکیں۔ {ملکہ...: یا، فریم، یا، جنت کی کاری}\n19۔ کیا وہ مجھے غصہ دلانے پر مجبور کرتے ہیں؟ خداوند فرماتا ہے: {کیا وہ خود کو اپنے ہی چہروں کی الجھن میں مبتلا نہیں کرتے؟'\n20۔ لہٰذا خداوند خدا یہ فرماتا ہے؛ دیکھو، میرا غصہ اور غصہ اس جگہ پر، انسان، جانور پر، کھیت کے درختوں پر، اور زمین کے پھل پر بہہ جائے گا؛ اور یہ جل جائے گا، اور بجھا نہیں جائے گا۔\n21۔ یہی فرماتا ہے رب لشکروں، اسرائیل کا خدا؛ اپنی قربانیوں کے لیے اپنی نذرانے پیش کرو، اور گوشت کھاؤ۔\n22۔ کیونکہ میں نے تمہارے آباؤ اجداد سے نہ بات کی، نہ ہی انہیں اس دن حکم دیا جب میں انہیں مصر کی سرزمین سے نکالا تھا، جلانے کی قربانیوں یا قربانیوں کے بارے میں: {متعلق: عبرانی۔ اس معاملے کے بارے میں}\n23۔ لیکن اس چیز نے انہیں حکم دیا، کہا، میری آواز کی اطاعت کرو، اور میں تمہارا خدا بنوں گا، اور تم میرے لوگ بنو گے: اور تم ان تمام راستوں پر چلو، جو میں نے تمہیں حکم دیا ہے، تاکہ یہ تمہارے لیے بھلا ہو۔\n24۔ لیکن انہوں نے نہ سنا، نہ کان جھکایا، بلکہ مشوروں میں چلتے رہے {اور} اپنے برے دل کے تصور میں، اور پیچھے چلے گئے، آگے نہیں۔ {تخیل: یا، ضد} {گیا: ہیب۔ تھے}\n25۔ جب سے تمہارے آباؤ اجداد مصر کی سرزمین سے نکلے ہیں، آج تک میں نے اپنے تمام بندوں کو تم تک بھیجا ہے، جو روزانہ صبح سویرے اٹھتے اور بھیجتے ہیں:\n26۔ پھر بھی انہوں نے میری بات نہیں سنی، نہ کان جھکایا، بلکہ اپنی گردن سخت کر لی: انہوں نے اپنے باپ دادا سے بھی بدتر کیا۔\n27۔ اس لیے تم یہ سب باتیں ان سے کہو۔ لیکن وہ تمہاری بات نہیں سنیں گے: تم انہیں بھی پکارو گے؛ لیکن وہ تمہیں جواب نہیں دیں گے۔\n28۔ لیکن تم ان سے کہو گے، یہ وہ قوم ہے جو خداوند اپنے خدا کی آواز نہیں مانتی اور نہ ہی اصلاح قبول کرتی ہے: سچائی ختم ہو جاتی ہے اور ان کے منہ سے کٹ جاتی ہے۔ {تصحیح: یا، ہدایت}\n29. اپنے بال کاٹ دو، {اے یروشلم}، اور اسے پھینک دو، اور اونچی جگہوں پر ماتم کرو؛ کیونکہ خداوند نے اپنی غضب کی نسل کو رد اور ترک کر دیا ہے۔\n30۔ کیونکہ یہوداہ کے بچوں نے میرے سامنے برائی کی ہے، خداوند فرماتا ہے: انہوں نے اپنے گناہوں کو اس گھر میں رکھا ہے جسے میرے نام سے پکارا جاتا ہے، تاکہ اسے آلودہ کیا جا سکے۔\n31۔ اور انہوں نے توفیت کی اونچی جگہیں تعمیر کیں، جو ہنوم کے بیٹے کی وادی میں ہیں، تاکہ اپنے بیٹوں اور بیٹیوں کو آگ میں جلا سکیں؛ جس کا میں نے حکم دیا تھا، نہ ہی وہ میرے دل میں آیا۔ {آیا...: عبوری۔ یہ میرے دل پر آیا}\n32۔ لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ اسے اب ٹوفیت نہیں کہا جائے گا، نہ ہی ہنوم کے بیٹے کی وادی کہلائی جائے گی، بلکہ ذبح کی وادی کہلائی جائے گی، کیونکہ وہ توپھیت میں دفن ہوں گے، یہاں تک کہ کوئی جگہ باقی نہ رہے۔\n33۔ اور اس قوم کی لاشیں آسمان کے پرندوں اور زمین کے جانوروں کے لیے گوشت ہوں گی؛ اور کوئی بھی انہیں ختم نہیں کرے گا۔\n34۔ پھر میں یہوداہ کے شہروں اور یروشلم کی گلیوں سے خوشی کی آواز، دلہن کی آواز اور دلہن کی آواز کو روک دوں گا: کیونکہ زمین ویران ہو جائے گی۔","1۔ اس وقت، خداوند فرماتا ہے، وہ یہوداہ کے بادشاہوں کی ہڈیاں، اس کے شہزادوں کی ہڈیاں، کاہنوں کی ہڈیاں، انبیاؤں کی ہڈیاں، اور یروشلم کے باشندوں کی ہڈیاں ان کی قبروں سے نکالیں گے:\n2۔ اور وہ انہیں سورج، چاند، اور آسمان کے تمام لشکر کے سامنے پھیلائیں گے، جن سے انہوں نے محبت کی، جن کی انہوں نے عبادت کی، جن کے پیچھے وہ چلے، جن کی تلاش کی، اور جن کی عبادت کی: انہیں جمع نہیں کیا جائے گا، نہ دفن کیا جائے گا؛ وہ زمین پر گوبر کے لیے ہوں گے۔\n3۔ اور موت کو زندگی کے بجائے اس برے خاندان کے باقی ماندہ افراد کے لیے منتخب کیا جائے گا، جو ان تمام جگہوں پر باقی ہیں جہاں میں نے انہیں نکالا ہے، خداوند لشکروں فرماتا ہے۔\n4۔ مزید یہ کہ تم ان سے کہو گے، خداوند یہی فرماتا ہے؛ کیا وہ گریں گے، اور اٹھیں گے نہیں؟ کیا وہ منہ موڑ لے اور واپس نہ آئے؟\n5. پھر، یروشلم کے یہ لوگ ہمیشہ پیچھے ہٹنے کی وجہ سے کیوں پیچھے ہٹ رہے ہیں؟ وہ دھوکہ دہی کو مضبوطی سے تھامے رکھتے ہیں، واپس آنے سے انکار کرتے ہیں۔\n6۔ میں نے سنا اور سنا، {لیکن} انہوں نے صحیح بات نہیں کی: کسی نے اپنی بدکاری پر توبہ نہیں کی، یہ کہتے ہوئے، میں نے کیا کیا؟ ہر کوئی اپنی راہ پر مڑ گیا، جب گھوڑا لڑائی میں دوڑتا ہے۔\n7۔ ہاں، آسمان میں موجود اسٹورک اپنے مقررہ اوقات جانتا ہے؛ اور کچھوا، کرین اور ابابیل ان کے آنے کے وقت کا مشاہدہ کرتے ہیں؛ لیکن میرے لوگ خداوند کے فیصلے کو نہیں جانتے۔\n8. آپ کیسے کہتے ہیں، ہم دانا ہیں، اور خداوند کا قانون ہمارے ساتھ ہے؟ دیکھو، یقینا اس نے {یہ} بنایا؛ کاتبوں کا قلم بے کار ہے۔ {بے سود...: یا، کاتبوں کا جھوٹا قلم جھوٹ کے لیے کام کرتا ہے}\n9۔ عقلمند شرمندہ ہیں، وہ مایوس اور متاثر ہیں: دیکھو، انہوں نے خداوند کے کلام کو رد کر دیا ہے؛ اور ان میں کیا حکمت ہے؟ {عقلمند...: یا، کیا وہ شرمندہ ہوئے ہیں، وغیرہ} {کیا...: عبرانی۔ کس چیز کی حکمت}\n10۔ اسی لیے میں ان کی بیویوں کو دوسروں کو دوں گا، {اور} ان کے کھیت ان کو دوں گا جو {ان} کے وارث ہوں گے: کیونکہ ہر کوئی چھوٹے سے لے کر سب سے بڑے تک لالچ میں مبتلا ہے، نبی سے لے کر پادری تک، ہر کوئی جھوٹ بولتا ہے۔\n11۔ کیونکہ انہوں نے میری قوم کی بیٹی کے زخم کو تھوڑا سا ٹھیک کیا ہے، کہتے ہوئے، امن، امن؛ جب {وہاں سکون نہیں ہوتا}۔\n12. کیا وہ شرمندہ تھے جب انہوں نے کوئی مکروہ کام کیا؟ نہیں، وہ بالکل شرمندہ نہیں ہوئے، نہ ہی شرمندہ ہو سکتے تھے: اس لیے وہ گرنے والوں میں گریں گے: ان کی زیارت کے وقت انہیں گرا دیا جائے گا، خداوند فرماتا ہے۔ {میں کروں گا...: یا، جمع کرتے ہوئے میں کھا جاؤں گا}\n13۔ میں انہیں ضرور کھا جاؤں گا، خداوند فرماتا ہے: {انگور نہیں ہوں گے، نہ انجیر کے درخت پر انجیر، اور پتہ مرجھا جائے گا؛ اور {جو چیزیں} میں نے انہیں دی ہیں وہ ان سے گزر جائیں گی۔\n14. ہم کیوں خاموش بیٹھے ہیں؟ جمع ہو جاؤ، اور محفوظ شہروں میں داخل ہو جاؤ، اور وہاں خاموش رہیں: کیونکہ خداوند ہمارے خدا نے ہمیں خاموش کر دیا ہے، اور ہمیں پینے کے لیے پانی دیا ہے، کیونکہ ہم نے خداوند کے خلاف گناہ کیا ہے۔ {گال: یا، زہر}\n15۔ ہم امن کی تلاش میں تھے، لیکن کوئی اچھا نہیں ملا؛ اور صحت کے وقت کے لیے، اور دیکھو مصیبت!\n16۔ اس کے گھوڑوں کی خراٹے کی آواز دان سے سنائی دی: اس کے طاقتور گھوڑوں کی ہنہناہٹ سن کر پورا ملک کانپ اٹھا؛ کیونکہ وہ آئے ہیں، اور زمین اور اس میں موجود سب کچھ نگل گئے ہیں؛ شہر، اور اس میں رہنے والوں کو۔ {سب...: عبرانی۔ اس کی مکمل شدت}\n17. کیونکہ دیکھو، میں تم میں سانپوں، مرغیوں کو بھیجوں گا، جو مجھ سے متاثر نہیں ہوں گے، اور وہ تمہیں کاٹیں گے، خداوند فرماتا ہے۔\n18۔ {جب} میں غم سے خود کو تسلی دیتا، میرا دل {مجھ میں} بے ہوش ہو جاتا ہے۔ {میں: عبوری۔ upon}\n19۔ میری قوم کی بیٹی کی پکار کی آواز دیکھو، ان لوگوں کی وجہ سے جو دور دراز ملک میں رہتے ہیں: {کیا} صیہون میں خداوند نہیں؟ {کیا} اس میں اس کا بادشاہ نہیں ہے؟ انہوں نے اپنی کندہ شدہ تصاویر {اور} عجیب و غریب غرور سے مجھے کیوں غصہ دلایا؟ {وہ...: عبرانی۔ وہ ملک جو دور ہے}\n20۔ فصل گزر چکی ہے، گرمیوں کا موسم ختم ہو چکا ہے، اور ہم بچائے نہیں گئے۔\n21. اپنی قوم کی بیٹی کے دکھ کے لیے میں زخمی ہوں؛ میں سیاہ فام ہوں؛ حیرت نے مجھ پر قبضہ کر لیا ہے۔\n22. {کیا} گلعاد میں کوئی مرہم نہیں؛ کیا وہاں کوئی معالج نہیں ہے؟ تو پھر میری قوم کی بیٹی کی صحت کیوں نہیں بحال ہوئی؟ {بازیافت شدہ: عبوری۔ اوپر چلا گیا؟}","1. کاش میرا سر پانی ہوتا، اور میری آنکھیں آنسوؤں کا چشمہ ہوتیں، تاکہ میں دن رات اپنی قوم کی بیٹی کے قتل ہونے پر روتا! {اوہ...: عبرانی۔ کون میرا سر دے گا، وغیرہ}\n2. کاش میرے پاس صحرا میں مسافر مردوں کا قیام ہوتا؛ کہ میں اپنے لوگوں کو چھوڑ دوں، اور ان سے دور ہو جاؤں! کیونکہ وہ سب ہیں، غدار لوگوں کا ایک اجتماع۔\n3۔ اور وہ اپنی زبانیں جھوٹ کی طرح موڑتے ہیں: لیکن وہ زمین پر سچائی کے لیے بہادر نہیں ہوتے؛ کیونکہ وہ برائی سے برائی کی طرف جاتے ہیں، اور وہ مجھے نہیں جانتے، خداوند فرماتا ہے۔\n4۔ اس کے ہر پڑوسی کی سنو، اور کسی بھائی پر بھروسہ نہ کرو: کیونکہ ہر بھائی مکمل طور پر جگہ لے لے گا، اور ہر پڑوسی بہتان کے ساتھ چلے گا۔ {پڑوسی: یا، دوست}\n5۔ اور وہ اپنے پڑوسی کو دھوکہ دیں گے، اور سچ نہیں بولیں گے: انہوں نے اپنی زبان کو جھوٹ بولنا سکھایا ہے، {اور} خود کو گناہ کرنے سے روک دیا ہے۔ {دھوکہ: یا، مذاق}\n6۔ تمہاری رہائش دھوکہ دہی کے بیچ میں ہے؛ فریب کے ذریعے وہ مجھے جاننے سے انکار کرتے ہیں، خداوند فرماتا ہے۔\n7۔ لہٰذا لشکروں کے رب فرماتا ہے، دیکھو، میں انہیں پگھلاؤں گا اور آزماؤں گا؛ کیونکہ میں اپنی قوم کی بیٹی کے لیے کیا کروں؟\n8. ان کی زبان تیر کی طرح ہے؛ یہ دھوکہ دہی کہتا ہے: {ایک} اپنے پڑوسی سے اپنے منہ سے سکون سے بات کرتا ہے، لیکن دل میں اپنی انتظار کرتا ہے۔ {دل میں: عبرانی۔ اس کے بیچ میں} {اس کا انتظار: یا، اس کا انتظار کرو}\n9. کیا میں ان {چیزوں} کے لیے ان سے ملنے نہیں جاؤں؟ خداوند فرماتا ہے: کیا میری روح کو ایسی قوم سے بدلہ نہیں لیا جائے گا؟\n10۔ پہاڑوں کے لیے میں رونا اور آہ و بکا اٹھاؤں گا، اور بیابان کے بستیوں کے لیے نوحہ، کیونکہ وہ جل چکے ہیں، یہاں تک کہ کوئی ان سے گزر نہیں سکتا؛ نہ ہی {انسان} مویشیوں کی آواز سن سکتے ہیں؛ آسمان کے پرندے اور درندہ دونوں فرار ہو جاتے ہیں؛ وہ جا چکے ہیں۔ {بستیاں: یا، چراگاہیں} {جل گیا: یا، ویران ہے} {دونوں...: عبرانی۔ پرندے سے لے کر یہاں تک کہ وغیرہ}\n11۔ اور میں یروشلم کو ڈھیر بنا دوں گا، {اور} ڈریگنوں کا گھونسلہ بناؤں گا؛ اور میں یہوداہ کے شہروں کو ویران بنا دوں گا، بغیر کسی باشندے کے۔ {ویران آواز: عبرانی۔ ویرانی}\n12. وہ دانا کون ہے جو اسے سمجھ سکتا ہے؟ اور {وہ کون ہے} جس سے خداوند کے منہ نے بات کی ہے تاکہ وہ یہ اعلان کر سکے، کیونکہ جو زمین تباہ ہو جاتی ہے {اور} صحرا کی طرح جل جاتی ہے، کہ کوئی گزر نہیں سکتا؟\n13۔ اور خداوند فرماتا ہے، کیونکہ انہوں نے میری شریعت کو چھوڑ دیا جو میں نے ان کے سامنے رکھی تھی، اور نہ میری آواز مانے، نہ اس میں داخل ہوئے؛\n14. لیکن انہوں نے اپنے دل کی تخیل اور بعلیم کے پیچھے چلے، جو ان کے آباؤ اجداد نے انہیں سکھایا: {تخیل: یا، ضد}\n15۔ لہٰذا لشکروں کے رب، اسرائیل کے خدا نے یوں فرمایا؛ دیکھو، میں انہیں، حتیٰ کہ اس قوم کو، ورم ووڈ سے کھلاؤں گا، اور انہیں پینے کے لیے گال کا پانی دوں گا۔\n16. میں انہیں بھی کافروں میں بکھیر دوں گا، جنہیں نہ وہ جانتے ہیں اور نہ ان کے باپ جانتے ہیں: اور میں ان کے پیچھے تلوار بھیجوں گا، جب تک کہ میں انہیں نگل نہ جاؤں۔\n17۔ یوں فرماتا ہے رب لشکر، غور کرو اور سوگوار عورتوں کو بلاؤ تاکہ وہ آ سکیں؛ اور چالاک عورتوں کو بھیجو، تاکہ وہ آ سکیں:\n18۔ اور وہ جلدی کریں، اور ہمارے لیے رونا شروع کریں، تاکہ ہماری آنکھیں آنسوؤں سے بہہ جائیں، اور ہماری پلکیں پانی سے بہنے لگیں۔\n19۔ کیونکہ صیون سے چیخنے کی آواز سنائی دیتی ہے، ہم کیسے بگڑے ہوئے ہیں! ہم بہت الجھن میں ہیں، کیونکہ ہم نے زمین کو چھوڑ دیا ہے، کیونکہ ہمارے گھروں نے ہمیں نکال دیا ہے۔\n20۔ پھر بھی اے عورتوں، خداوند کا کلام سنو، اور اپنے کان اس کے منہ کا کلام سنو، اور اپنی بیٹیوں کو رونا سکھاؤ، اور ہر پڑوسی کو نوحہ سکھاؤ۔\n21۔ کیونکہ موت ہماری کھڑکیوں میں آ گئی ہے، {اور} ہمارے محلات میں داخل ہو گئی ہے، تاکہ بچوں کو باہر سے کاٹ دیا جائے، {اور} نوجوانوں کو سڑکوں سے نکال دیا جائے۔\n22۔ خداوند فرماتا ہے کہ انسانوں کی لاشیں کھلے میدان پر گوبر کی طرح گریں گی، اور فصل کاٹنے والے کے پیچھے مٹھی کی طرح، اور کوئی انہیں جمع نہیں کرے گا۔\n23۔ خداوند یوں فرماتا ہے، دانا [انسان} اپنی حکمت پر فخر نہ کرے، نہ ہی طاقتور {انسان} اپنی طاقت پر فخر کرے، امیر {انسان} اپنی دولت میں فخر نہ کرے:\n24۔ لیکن جو اس میں جلال پاتا ہے، وہ مجھے سمجھتا اور جانتا ہے، کہ میں وہ خداوند ہوں جو زمین پر محبت، فیصلہ اور راستبازی کرتا ہے: کیونکہ ان چیزوں میں میں خوشی محسوس کرتا ہوں، خداوند فرماتا ہے۔\n25۔ دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں ان سب کو سزا دوں گا جو ختنہ شدہ لوگوں کے ساتھ ہیں؛ {سزا: عبرانی۔ ملاحظہ کریں}\n26۔ مصر، اور یہوداہ، اور ایڈم، اور آمون اور موآب کی اولاد، اور وہ سب {جو سب سے} کونے میں ہیں، جو بیابان میں رہتے ہیں: کیونکہ تمام {یہ} قومیں {ختنہ} نہیں ہیں، اور اسرائیل کے تمام گھرانے {دل} میں ختنہ نہیں کیے گئے۔ {بالکل زیادہ...: عبرانی۔ کونوں میں کاٹ دیا جائے، یا بالوں کے کنارے کاٹ دیے جائیں}","1. اے بنی اسرائیل کے اس کلام کو سنو جو خداوند تم سے کہتا ہے:\n2۔ خداوند یہ فرماتا ہے: کافروں کا راستہ نہ سیکھو اور آسمان کی نشانیوں سے خوفزدہ نہ ہو؛ کیونکہ کافر ان سے مایوس ہیں۔\n3۔ کیونکہ لوگوں کی رسم و رواج فضول ہیں: کیونکہ {ایک} جنگل سے درخت کاٹتا ہے، مزدور کے ہاتھوں کا کام، کلہاڑی سے۔ {رسم و رواج...: عبرانی۔ قوانین، یا، آرڈیننسز باطل ہیں}\n4۔ وہ اسے چاندی اور سونے سے سجاتے ہیں؛ وہ اسے کیلوں اور ہتھوڑوں سے باندھتے ہیں تاکہ وہ حرکت نہ کرے۔\n5. وہ کھجور کے درخت کی طرح سیدھے کھڑے ہیں، لیکن بولتے نہیں: انہیں برداشت کرنا ضروری ہے، کیونکہ وہ نہیں جا سکتے۔ ان سے نہ ڈریں؛ کیونکہ وہ برائی نہیں کر سکتے، اور نہ ہی ان میں بھلائی کرنے کی صلاحیت ہے۔\n6۔ اگر تجرا جیسا کوئی نہیں، اے خداوند؛ تو عظیم ہو، اور تمہارا نام طاقت میں عظیم ہے۔\n7. اے قوموں کے بادشاہ، تم سے کون نہیں ڈرے گا؟ کیونکہ یہ تمہارے لیے ہے: جیسے قوموں کے تمام دانا لوگوں میں، اور ان کی تمام سلطنتوں میں، تم جیسا کوئی نہیں۔ {تو...: یا، یہ تمہیں پسند کرتا ہے}\n8۔ لیکن وہ بالکل ظالم اور بے وقوف ہیں: اصل {ہے} غرور کا عقیدہ۔ {مجموعی طور پر: عبرانی۔ ایک میں، یا، ایک ساتھ}\n9۔ پلیٹوں میں بچھائی ہوئی چاندی ترشیش سے لائی جاتی ہے، اور سونا اوپاز سے لائی جاتی ہے، جو مزدور اور بانی کے ہاتھوں کا کام ہے: نیلا اور جامنی ان کا لباس ہے: یہ سب چالاک انسانوں کا کام ہے۔\n10۔ لیکن خداوند سچا خدا ہے، وہ زندہ خدا ہے، اور ہمیشہ بادشاہ ہے: اس کے غضب سے زمین لرز جائے گی، اور قومیں اس کے غصے کو برداشت نہیں کر سکیں گی۔ {سچ...: عبرانی سچائی کا خدا} {زندہ خدا: عبرانی۔ زندہ دیوتا} {ہمیشہ کے لیے...: عبرانی۔ بادشاہ ابدیت\n11. یوں تم ان سے کہو گے، وہ دیوتا جنہوں نے آسمان اور زمین نہیں بنائے، {حتیٰ کہ} وہ زمین سے اور ان آسمانوں کے نیچے سے فنا ہو جائیں گے۔\n12۔ اس نے اپنی طاقت سے زمین بنائی، اپنی حکمت سے دنیا کو قائم کیا، اور اپنی مرضی سے آسمان کو پھیلایا۔\n13۔ جب وہ اپنی آواز نکالتا ہے، تو آسمانوں میں پانی کی کثرت ہے، اور وہ زمین کے کناروں سے بخارات کو اوپر اٹھاتا ہے؛ وہ بارش سے بجلی بناتا ہے، اور اپنے خزانے سے ہوا نکالتا ہے۔ {کثیر: یا، شور} {ساتھ: یا، کے لیے}\n14۔ ہر انسان اپنے علم میں وحشی ہے: ہر بانی کندہ شدہ تصویر سے الجھن میں ہے: کیونکہ اس کی پگھلی ہوئی تصویر جھوٹ ہے، اور ان میں کوئی سانس نہیں۔ {اپنے علم میں وحشی: یا، جاننے سے زیادہ وحشی}\n15. وہ باطل ہیں، غلطیوں کا کام: ان کی زیارت کے وقت وہ فنا ہو جائیں گے۔\n16۔ یعقوب کا حصہ {ہے} ان جیسا نہیں: کیونکہ وہ {ہے} تمام {چیز} میں سے پہلا؛ اور اسرائیل اس کی میراث کی چھڑی ہے: لشکروں کا رب اس کا نام ہے۔\n17. اے قلعے کے باشندے، اپنے سامان کو زمین سے جمع کرو۔ {رہائشی: عبرانی۔ آبادکار}\n18۔ کیونکہ خداوند فرماتا ہے، دیکھو، میں اس وقت زمین کے باشندوں کو نکال دوں گا، اور انہیں پریشان کروں گا تاکہ وہ ایسا پائیں۔\n19۔ میری تکلیف پر افسوس ہے! میرا زخم شدید ہے: لیکن میں نے کہا، واقعی یہ ایک غم ہے، اور مجھے اسے برداشت کرنا ہوگا۔\n20۔ میرا خیمہ خراب ہو گیا ہے، اور میری تمام رسیاں ٹوٹ چکی ہیں: میرے بچے مجھ سے نکل چکے ہیں، اور وہ نہیں: اب کوئی نہیں ہے جو میرا خیمہ پھیلا سکے، اور میرے پردے لگا سکے۔\n21۔ کیونکہ پادری ظالم ہو چکے ہیں، اور انہوں نے خداوند کی تلاش نہیں کی، اس لیے وہ خوشحال نہیں ہوں گے، اور ان کے تمام ریوڑ بکھر جائیں گے۔\n22۔ دیکھو، بروئٹ کی آواز آئی ہے، اور شمالی علاقے سے ایک بڑا ہنگامہ برپا ہوا ہے، جس نے یہوداہ کے شہروں کو ویران کر دیا، {اور} ڈریگنوں کا گڑھ بنا دیا۔\n23. اے خداوند، میں جانتا ہوں کہ انسان کا راستہ خود میں نہیں: یہ انسان میں نہیں ہے جو اپنے قدموں کی رہنمائی کے لیے چلتا ہے۔\n24. اے خداوند، مجھے درست فرما، لیکن فیصلے کے ساتھ؛ اپنے غصے میں نہیں، ورنہ تم مجھے کچھ نہیں لے جاؤ گے۔ {لاؤ...: عبرانی مجھے کم تر سمجھو}\n25۔ اپنا غصہ ان کافروں پر نکالو جو تمہیں نہیں جانتے، اور ان خاندانوں پر جو تمہارا نام نہیں پکارتے، کیونکہ انہوں نے یعقوب کو کھا لیا، اسے کھا لیا، اسے کھا لیا، اور اس کا مسکن ویران کر دیا۔","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، اور کہا،\n2۔ اس عہد کے الفاظ سنو، اور یہوداہ کے لوگوں اور یروشلم کے باشندوں سے بات کرو؛\n3۔ اور ان سے کہو، یہی فرماتا ہے اسرائیل کا خداوند خدا؛ لعنت ہو وہ شخص جو اس عہد کے الفاظ کی اطاعت نہیں کرتا،\n4۔ جسے میں نے تمہارے آباؤ اجداد کو حکم دیا تھا جب میں نے انہیں مصر کی زمین سے، لوہے کے بھٹے سے نکالا، کہا، میری آواز مانو اور ان کے مطابق عمل کرو، جیسا کہ میں تمہیں حکم دیتا ہوں: تم میرے لوگ بنو گے، اور میں تمہارا خدا بنوں گا:\n5. تاکہ میں وہ قسم پوری کر سکوں جو میں نے تمہارے آباؤ اجداد سے کیا ہے، کہ انہیں دودھ اور شہد سے بھری زمین دوں، جیسا کہ آج ہے۔ پھر میں نے جواب دیا اور کہا، \"ایسا ہو، اے خداوند۔\" {تو...: عبرانی۔ آمین}\n6۔ پھر خداوند نے مجھ سے کہا، یہوداہ کے شہروں اور یروشلم کی گلیوں میں یہ سب الفاظ بیان کرو، کہ، اس عہد کے الفاظ سنو اور عمل کرو۔\n7۔ کیونکہ میں نے تمہارے آباؤ اجداد سے اس دن دل سے احتجاج کیا جب میں نے انہیں مصر کی سرزمین سے نکالا، {حتیٰ کہ} آج تک، صبح سویرے اٹھ کر احتجاج کیا، کہتا ہوں، میری آواز مانو۔\n8۔ پھر بھی انہوں نے نہ اطاعت کی، نہ کان جھکایا، بلکہ ہر ایک اپنے برے دل کے تصور میں چلتے رہے: اس لیے میں ان پر اس عہد کے تمام الفاظ لاؤں گا، جو میں نے {ان} کو کرنے کا حکم دیا تھا؛ لیکن انہوں نے ایسا نہیں کیا۔ {تخیل: یا، ضد}\n9۔ اور خداوند نے مجھ سے کہا، یہوداہ کے لوگوں اور یروشلم کے باشندوں کے درمیان سازش پائی جاتی ہے۔\n10۔ وہ اپنے آباؤ اجداد کی گناہوں کی طرف لوٹ جاتے ہیں، جنہوں نے میری باتیں سننے سے انکار کیا؛ اور وہ دوسرے دیوتاؤں کے پیچھے گئے تاکہ ان کی خدمت کریں: اسرائیل کے گھر اور یہوداہ کے گھر نے میرا وہ عہد توڑ دیا ہے جو میں نے ان کے باپ دادا سے کیا تھا۔\n11۔ لہٰذا خداوند فرماتا ہے، دیکھو، میں ان پر برائی لاؤں گا جس سے وہ بچ نہیں سکیں گے؛ اور اگرچہ وہ مجھ سے پکاریں گے، میں ان کی بات نہیں سنوں گا۔ {فرار کے لیے: عبرانی۔ آگے بڑھنے کے لیے}\n12۔ پھر یہوداہ کے شہر اور یروشلم کے باشندے جائیں گے اور ان دیوتاؤں سے پکار رہے ہوں گے جنہیں وہ لوبان پیش کرتے ہیں، لیکن وہ اپنی مصیبت کے وقت انہیں بالکل بھی نہیں بچائیں گے۔ {مسئلہ: عبوری۔ برائی}\n13۔ کیونکہ {مطابق} تیرے شہروں کی تعداد تیرے خدا تھے، اے یہودا؛ اور {یروشلم کی گلیوں کے مطابق} تم نے اس شرمناک چیز کے لیے قربان گاہیں لگائی ہیں، {حتیٰ کہ} بعل کے لیے لوبان جلانے کے لیے قربان گاہیں بھی لگائی ہیں۔ {شرمندہ کن...: عبرانی۔ شرم کی بات ہے}\n14۔ لہٰذا اس قوم کے لیے دعا نہ کرو، نہ ان کے لیے کوئی پکار یا دعا کرو، کیونکہ میں ان کی آواز نہیں سنوں گا جب وہ اپنی تکلیف کے لیے مجھ سے پکار رہے ہیں۔ {مسئلہ: عبوری۔ برائی}\n15۔ میری محبوبہ میرے گھر میں کیا کر رہی ہے، {دیکھتے ہوئے} اس نے بہت سے لوگوں کے ساتھ بے حیائی کی ہے، اور مقدس جسم تم سے چھن گیا ہے؟ جب تم برائی کرتے ہو، تو تم خوش ہوتے ہو۔ {کیا...: عبرانی۔ میرے محبوب کے لیے میرے گھر میں کیا ہے} {جب...: یا، جب تیری برائی ہو}\n16۔ خداوند نے تیرا نام پکارا، ایک سبز زیتون کا درخت، خوبصورت اور اچھے پھل والا: ایک بڑے شور کی آواز سے اس پر آگ لگا دی، اور اس کی شاخیں ٹوٹ گئیں۔\n17۔ کیونکہ لشکروں کے رب، جس نے تمہیں لگایا، نے تمہارے خلاف برائی کی ہے، اسرائیل کے گھر اور یہوداہ کے خاندان کی برائی کے لیے، جو انہوں نے خود پر کی تاکہ مجھے بعل کو بخور پیش کرنے میں غصہ دلانے کے لیے کیا جا سکے۔\n18۔ اور خداوند نے مجھے اس کا علم دیا ہے، اور میں جانتا ہوں: پھر تو نے مجھے ان کے اعمال دکھائے۔\n19. لیکن میں {تھا} جیسے ایک بکری {یا} ایک بیل {جو} ذبح کے لیے لایا جاتا ہے؛ اور مجھے معلوم نہیں تھا کہ انہوں نے میرے خلاف سازشیں کی ہیں، {کہہ رہے ہیں}، آؤ درخت کو اس کے پھل سے تباہ کر دیں، اور اسے زندہ لوگوں کی سرزمین سے کاٹ دیں، تاکہ اس کا نام دوبارہ یاد نہ رکھا جائے۔ {درخت...: عبرانی۔ اس کی روٹی کے ساتھ ڈنٹھل}\n20۔ لیکن، اے لشکروں کے رب، جو انصاف سے فیصلہ کرتے ہیں، جو لگام اور دل کو آزماتے ہیں، مجھے ان سے تیرا انتقام دکھاؤ: کیونکہ میں نے اپنی وجہ تیرے سامنے ظاہر کی ہے۔\n21۔ لہٰذا انتھوت کے لوگوں کے رب یہ فرماتے ہیں، جو تیری جان چاہتے ہیں، کہتا ہے: خداوند کے نام پر پیش گوئی نہ کرو، کہ تم ہمارے ہاتھوں نہ مرو:\n22۔ لہٰذا لشکروں کے رب فرماتا ہے، دیکھو، میں انہیں سزا دوں گا: نوجوان تلوار سے مریں گے؛ ان کے بیٹے اور بیٹیاں قحط سے مر جائیں گے: {سزا: عبرانی۔ ملاحظہ کریں}\n23۔ اور ان کی کوئی باقیات باقی نہیں رہیں گی: کیونکہ میں اناتھوت کے لوگوں پر برائی لاؤں گا، حتیٰ کہ ان کی آمد کے سال بھی۔","1. اے خداوند، تو نیک ہو جب میں تجھ سے دعا کرتا ہوں: پھر بھی میں تیری {تمہاری} فیصلوں کے بارے میں بات کرتا ہوں: بدکاروں کا راستہ کیوں کامیاب ہوتا ہے؟ {کیوں} وہ سب خوش ہیں جو بہت دھوکہ دہی کرتے ہیں؟ {بات چیت...: یا، تم سے بات کرو}\n2۔ تم نے انہیں لگایا ہے، ہاں، وہ جڑ پکڑ چکے ہیں: وہ اگتے ہیں، ہاں، وہ پھل دیتے ہیں: تم ان کے منہ کے قریب ہو، اور ان کی لگام سے دور۔ {وہ بڑھتے ہیں: عبرانی۔ وہ چلتے رہتے ہیں}\n3. لیکن تو، اے خداوند، مجھے جانتا ہے: تو نے مجھے دیکھا اور میرا دل اپنے لیے آزمایا: انہیں بھیڑوں کی طرح نکال کر ذبح کے لیے نکالو، اور ذبح کے دن کے لیے تیار کرو۔ {کی طرف...: عبرانی۔ تمہارے ساتھ}\n4. زمین کب تک سوگ منائے گی، اور ہر کھیت کی جڑی بوٹیاں مرجھا جائیں گی، ان لوگوں کی برائی پر جو وہاں بستے ہیں؟ جانور کھا لیے جاتے ہیں، اور پرندے؛ کیونکہ انہوں نے کہا، وہ ہمارا آخری انجام نہیں دیکھے گا۔\n5۔ اگر تم پیدل سپاہیوں کے ساتھ دوڑے اور انہوں نے تمہیں تھکا دیا، تو پھر گھوڑوں سے کیسے مقابلہ کر سکتے ہو؟ اور {اگر} امن کی سرزمین میں، {جہاں تم بھروسہ کرتے ہو}، {انہوں نے تمہیں تھکا دیا}، تو اردن کی افزائش میں تم کیسے کرو گے؟\n6۔ کیونکہ تمہارے بھائیوں اور تمہارے باپ کے گھرانے نے بھی تمہارے ساتھ غداری کی ہے؛ ہاں، انہوں نے تمہارے پیچھے بہت سے لوگوں کو بلایا ہے: ان پر یقین نہ کرو، چاہے وہ تم سے خوبصورت باتیں کرتے ہوں۔ {انہوں نے پکارا...: یا، وہ پوری طرح تمہارے پیچھے پکارے} {منصف...: عبدی۔ اچھی باتیں}\n7۔ میں نے اپنا گھر چھوڑ دیا ہے، میں نے اپنی وراثت چھوڑ دی ہے؛ میں نے اپنی روح کے پیارے کو اس کے دشمنوں کے ہاتھ میں دے دیا ہے۔ {عزیز...: عبرانی۔ محبت}\n8. میری وراثت میرے لیے جنگل میں شیر کی طرح ہے؛ یہ میرے خلاف پکار رہی ہے: اسی لیے میں نے اسے ناپسند کیا۔ {cryeth...: یا، چیختا ہے: عبرانی۔ اپنی آواز دیتا ہے}\n9. میری وراثت {ہے} میرے لیے {ایک دھبے دار پرندہ} کی طرح، ارد گرد کے پرندے {ہیں} اس کے خلاف؛ آؤ، میدان کے تمام جانوروں کو جمع کرو، کھانے کے لیے آؤ۔ {داغدار: یا، پنجہ} {ہوش میں آنا: یا، انہیں ہوش میں لانے پر مجبور کرنا}\n10۔ بہت سے پادریوں نے میرا انگور کا باغ تباہ کر دیا ہے، انہوں نے میرے حصے کو پاؤں تلے روند دیا ہے، انہوں نے میرے خوشگوار حصے کو ویران جنگل بنا دیا ہے۔ {خوشگوار...: عبرانی۔ خواہش کا حصہ}\n11۔ انہوں نے اسے ویران کر دیا ہے، {اور ویران ہونے کی وجہ سے} یہ میرے لیے ماتم کرتا ہے؛ پوری زمین ویران ہو گئی ہے، کیونکہ کوئی اسے دل سے نہیں لگاتا۔\n12۔ بگاڑنے والے تمام اونچی جگہوں پر آ گئے ہیں: کیونکہ خداوند کی تلوار زمین کے {ایک} سرے سے لے کر زمین کے {دوسرے سرے تک} تک نگل جائے گی: کوئی جسم سکون نہیں پا سکتا۔\n13۔ انہوں نے گندم بوئی ہے، لیکن کانٹے کاٹیں گے: انہوں نے خود کو تکلیف دی ہے، {لیکن} فائدہ نہیں اٹھائیں گے: اور وہ آپ کی آمدنی پر شرمندہ ہوں گے کیونکہ خداوند کا شدید غصہ ہے۔ {وہ کریں گے: یا تم کرو گے}\n14. خداوند یہ فرماتا ہے میرے تمام برے پڑوسیوں کے خلاف جو اس وراثت کو چھوتے ہیں جو میں نے اپنے قوم اسرائیل کو وراثت میں دی ہے؛ دیکھو، میں انہیں ان کی زمین سے نکالوں گا، اور یہوداہ کے گھر کو ان میں سے نکالوں گا۔\n15۔ اور یہ ہو جائے گا، جب میں انہیں نکال لوں گا تو واپس آؤں گا، ان پر رحم کروں گا، اور انہیں واپس لاؤں گا، ہر آدمی کو اس کی میراث میں، اور ہر آدمی کو اس کی سرزمین میں۔\n16۔ اور یہ ہو جائے گا، اگر وہ محنت سے میرے لوگوں کے طریقے سیکھیں، میرے نام کی قسم کھائیں کہ خداوند زندہ ہے؛ جیسے انہوں نے میرے لوگوں کو بعل کی قسم سکھائی؛ پھر وہ میرے لوگوں کے درمیان تعمیر ہوں گے۔\n17. لیکن اگر وہ اطاعت نہ کریں تو میں اس قوم کو مکمل طور پر اٹھا کر تباہ کر دوں گا، خداوند فرماتا ہے۔","1۔ خداوند مجھ سے یوں فرماتا ہے، جاؤ اور ایک لینن کی بیلٹ لے آؤ، اسے اپنی کمر پر پہن لو، اور اسے پانی میں نہ ڈالو۔\n2۔ تو میں نے خداوند کے کلام کے مطابق ایک گرڈل لیا، اور اسے اپنی کمر پر ڈال دیا۔\n3۔ اور خداوند کا کلام مجھ پر دوسری بار آیا، اور کہا،\n4۔ وہ بیلٹ جو تمہارے پاس ہے، جو تمہاری کمر پر ہے، اٹھو، فرات کی طرف جاؤ، اور اسے وہاں چٹان کے سوراخ میں چھپا دو۔\n5. تو میں گیا، اور اسے فرات کے پاس چھپا دیا، جیسا کہ خداوند نے مجھے حکم دیا تھا۔\n6۔ اور کئی دنوں بعد ایسا ہوا کہ خداوند نے مجھ سے فرمایا، اٹھو، فرات کی طرف جاؤ، اور وہاں سے وہ بیلٹ لے آؤ، جسے میں نے تمہیں وہاں چھپانے کا حکم دیا تھا۔\n7۔ پھر میں فرات گیا، کھودا اور اس جگہ سے بیلٹ نکالا جہاں میں نے اسے چھپایا تھا: اور دیکھو، بیلٹ خراب ہو چکا تھا، یہ بے فائدہ تھا۔\n8۔ پھر خداوند کا کلام میرے پاس آیا، جس میں کہا،\n9۔ خداوند یوں فرماتا ہے، اسی طرح میں یہوداہ کے غرور اور یروشلم کے عظیم غرور کو نقصان پہنچاؤں گا۔\n10۔ یہ برے لوگ، جو میرے الفاظ سننے سے انکار کرتے ہیں، جو اپنے دل کے تصور میں چلتے ہیں، اور دوسرے دیوتاؤں کے پیچھے چلتے ہیں، ان کی خدمت اور عبادت کرتے ہیں، وہ بھی اس بیلٹ کی طرح ہوں گے، جو کسی کام کا نہیں۔ {تخیل: یا، ضد}\n11۔ جیسے بیلٹ انسان کی کمر سے لپٹتا ہے، ویسے ہی میں نے اسرائیل کے پورے گھر اور یہوداہ کے پورے گھر کو اپنے اوپر لپٹا دیا ہے، خداوند فرماتا ہے؛ تاکہ وہ میرے لیے ایک قوم، ایک نام، تعریف کے لیے، اور شان کے لیے ہوں، لیکن وہ سننا نہیں چاہتے۔\n12۔ لہٰذا تم ان سے یہ لفظ کہہ دو؛ یوں اسرائیل کے خداوند خدا فرماتے ہیں، ہر بوتل شراب سے بھری جائے گی: اور وہ تم سے کہیں گے، کیا ہم نہیں جانتے کہ ہر بوتل شراب سے بھری ہوگی؟\n13۔ پھر تم ان سے کہو گے، خداوند یوں فرماتا ہے، دیکھو، میں اس زمین کے تمام باشندوں، حتیٰ کہ داؤد کے تخت پر بیٹھے بادشاہوں، کاہنوں، انبیوں، اور یروشلم کے تمام باشندوں کو نشے میں بھر دوں گا۔\n14۔ اور میں انہیں ایک دوسرے کے خلاف ماروں گا، حتیٰ کہ باپ اور بیٹے بھی، خداوند فرماتا ہے: میں رحم نہیں کروں گا، نہ بخشوں گا، نہ رحم کروں گا، بلکہ انہیں تباہ کر دوں گا۔ {ایک...: عبرانی۔ ایک آدمی اپنے بھائی کے خلاف} {لیکن...: عبرانی۔ انہیں تباہ کرنے سے}\n15۔ سنو اور سنو؛ غرور نہ کرو: کیونکہ خداوند نے فرمایا ہے۔\n16. اپنے خداوند خدا کو جلال دو، اس سے پہلے کہ وہ تاریکی پھیلائے، اور تمہارے قدم تاریک پہاڑوں پر ٹھوکر کھا جائیں، اور جب تم روشنی کی تلاش میں ہو، وہ اسے موت کے سائے میں بدل دے، {اور} اسے شدید تاریکی بنا دے۔\n17۔ لیکن اگر تم اسے نہیں سنو گے، تو میری روح تمہارے غرور کے لیے خفیہ جگہوں پر روئے گی؛ اور میری آنکھ درد سے روئے گی، اور آنسوؤں سے بہے گی، کیونکہ خداوند کا ریوڑ قید ہو گیا ہے۔\n18۔ بادشاہ اور ملکہ سے کہو، عاجز ہو جاؤ، بیٹھ جاؤ: کیونکہ تمہاری سلطنتیں تمہاری عظمت کا تاج بھی اتریں گی۔ {پرنسپلٹیز: یا، ہیڈ ٹائرز}\n19۔ جنوب کے شہر بند کر دیے جائیں گے، اور کوئی انہیں نہیں کھولے گا: یہوداہ کو سب کچھ قید کر لیا جائے گا، اسے مکمل طور پر قید کر دیا جائے گا۔\n20۔ اپنی آنکھیں اٹھاؤ، اور دیکھو جو شمال سے آتے ہیں: وہ ریوڑ کہاں ہے {جو تمہیں} دیا گیا تھا، تمہارا خوبصورت ریوڑ؟\n21. جب وہ تمہیں سزا دے گا تو تم کیا کہو گے؟ کیونکہ تم نے انہیں سکھایا ہے کہ وہ کپتان بنیں، اور تمہارے سردار بنیں: کیا غم تمہیں ایک مصیبت زدہ عورت کی طرح نہیں لے جائیں گے؟ {سزا: عبرانی دورے پر}\n22۔ اور اگر تم اپنے دل میں کہتی ہو، یہ باتیں مجھ پر کیوں آتی ہیں؟ کیونکہ تیری گناہ کی عظمت تمہارے لباس دریافت ہو گئی ہے، {اور} تمہاری ایڑیاں بے نقاب ہو گئی ہیں۔ {بنایا گیا...: یا، زبردستی لے جایا جائے گا}\n23. کیا ایتھوپین اپنی جلد بدل سکتا ہے، یا چیتا اپنے دھبے بدل سکتا ہے؟ {تو} تم بھی اچھائی کرو جو برے کرنے کے عادی ہو۔ {عادی: عبرانی۔ سکھایا گیا}\n24. اسی لیے میں انہیں صحرا کی ہوا میں اڑتے ہوئے داڑھی کی طرح بکھیر دوں گا۔\n25. یہ {ہے} تیرا قسمت، تیری مقدار کا حصہ جو میرے طرف سے ہے، خداوند فرماتا ہے؛ کیونکہ تم نے مجھے بھلا دیا، اور جھوٹ پر بھروسہ کیا۔\n26. اس لیے میں تمہارے چہرے پر تمہارے کپڑوں کو دریافت کروں گا، تاکہ تمہاری شرمندگی ظاہر ہو۔\n27. میں نے تمہاری زنا دیکھی ہے، تمہاری ہنہناہٹ، تمہاری بدکاری کی بے حیائی، اور تمہاری گناہ کو کھیتوں کے پہاڑوں پر دیکھا ہے۔ اے یروشلم، تم پر افسوس ہے! کیا تم پاک نہیں ہو جاؤ گے؟ {کیا یہ} کب {ہوگا}؟ {جب...: عبرانی۔ کب کے بعد؟}","1۔ خداوند کا کلام جو یرمیاہ کو کمی کے بارے میں آیا۔ {کمی: عبرانی۔ ڈرتھس، یا پابندیوں کے الفاظ}\n2۔ یہوداہ ماتم کرتا ہے، اور اس کے دروازے کمزور پڑ جاتے ہیں؛ وہ زمین تک سیاہ ہیں؛ اور یروشلم کی پکار بلند ہو گئی۔\n3۔ اور ان کے نوابوں نے اپنے بچوں کو پانی میں بھیج دیا: وہ گڑھوں میں آئے، {اور} پانی نہیں پایا؛ وہ اپنے جہاز خالی لے کر واپس آئے؛ وہ شرمندہ اور پریشان تھے، اور اپنے سر ڈھانپ لیے۔\n4۔ کیونکہ زمین خشک ہے، کیونکہ زمین پر بارش نہیں تھی، ہل چلانے والے شرمندہ ہوئے اور اپنے سر ڈھانپ لیے۔\n5۔ ہاں، ہرن بھی کھیت میں بچھڑا گیا، اور اسے چھوڑ دیا، کیونکہ وہاں گھاس نہیں تھی۔\n6۔ اور جنگلی گدھے اونچی جگہوں پر کھڑے تھے، انہوں نے ہوا کو اژدہوں کی طرح بجھا دیا؛ ان کی آنکھیں بند ہو گئیں، کیونکہ وہاں گھاس نہیں تھی۔\n7۔ اے خداوند، اگرچہ ہمارے گناہوں نے ہمارے خلاف گواہی دی، تو یہ اپنے نام کے لیے کرو: کیونکہ ہماری واپسی بہت ہے؛ ہم نے تمہارے خلاف گناہ کیا ہے۔\n8۔ اے اسرائیل کی امید، جو مصیبت کے وقت اس کا نجات دہندہ ہے، تو زمین میں اجنبی کیوں ہو، اور ایک مسافر آدمی جو ایک رات ٹھہرنے کے لیے مڑ جاتا ہے؟\n9. تم کیوں ایک حیران انسان کی طرح ہو، جیسے ایک طاقتور انسان {جو} بچا نہیں سکتا؟ پھر بھی تو، اے خداوند، ہمارے درمیان ہے، اور ہمیں تیرے نام سے پکارا جاتا ہے؛ ہمیں مت چھوڑو۔ {ہم...: عبرانی۔ تیرا نام ہم پر پکارا جاتا ہے}\n10۔ خداوند اس قوم سے یوں فرماتا ہے، جیسے وہ بھٹکنا پسند کرتے ہیں، انہوں نے اپنے قدم نہیں روکے، اس لیے خداوند انہیں قبول نہیں کرتا؛ اب وہ ان کے گناہوں کو یاد رکھے گا، اور ان کے گناہوں کا سامنا کرے گا۔\n11۔ پھر خداوند نے مجھ سے کہا، ان لوگوں کے لیے ان کی بھلائی کے لیے دعا نہ کرو۔\n12۔ جب وہ روزہ رکھیں گے، میں ان کی پکار نہیں سنوں گا؛ اور جب وہ جلانے کی قربانی اور قربانی پیش کریں گے، تو میں انہیں قبول نہیں کروں گا: بلکہ میں انہیں تلوار، قحط اور وبا سے کھا جاؤں گا۔\n13۔ پھر میں نے کہا، آہ، خدا! دیکھو، نبی ان سے کہتے ہیں، تم تلوار نہیں دیکھو گے، نہ قحط آئے گا؛ لیکن میں تمہیں اس جگہ پر سکون دوں گا۔ {یقین دہانی...: عبرانی۔ سچائی کا سکون}\n14۔ پھر خداوند نے مجھ سے کہا، نبی کی نبوت میرے نام پر ہے: میں نے انہیں نہیں بھیجا، نہ حکم دیا، نہ ہی ان سے بات کی: وہ تمہیں جھوٹی پیش گوئی اور فال، ایک بے معنی بات اور ان کے دل کی دھوکہ دہی کی پیش گوئی کرتے ہیں۔\n15۔ لہٰذا خداوند ان نبیوں کے بارے میں یہی فرماتا ہے جو میرے نام پر نبوت کرتے ہیں، اور میں نے انہیں نہیں بھیجا، پھر بھی وہ کہتے ہیں، اس سرزمین میں تلوار اور قحط نہیں ہوں گے؛ وہ نبیوں کو تلوار اور قحط سے ختم کر دیا جائے گا۔\n16۔ اور جن لوگوں کو وہ پیش گوئی کرتے ہیں انہیں قحط اور تلوار کی وجہ سے یروشلم کی گلیوں سے نکال دیا جائے گا؛ اور انہیں دفنانے کے لیے کوئی نہیں ہوگا، نہ ان کی بیویاں، نہ ان کے بیٹے، نہ ان کی بیٹیاں، نہ ان کی بیٹیاں، کیونکہ میں ان پر ان کی برائی انڈیل دوں گا۔\n17۔ اسی لیے تم یہ لفظ ان سے کہہ دینا؛ میری آنکھوں کو دن رات آنسوؤں سے بہنے دو، اور وہ رکنے نہ دو: کیونکہ میری قوم کی کنواری بیٹی ایک بڑی دراڑ کے ساتھ ٹوٹ گئی ہے، ایک بہت شدید ضرب سے۔\n18۔ اگر میں میدان میں جاؤں، تو دیکھو وہ تلوار لے کر مارے گئے ہیں! اور اگر میں شہر میں داخل ہوا تو دیکھوں گا جو قحط سے بیمار ہیں! ہاں، نبی اور پادری دونوں ایک ایسی سرزمین میں جاتے ہیں جسے وہ نہیں جانتے۔ {ادھر ادھر گھومتے ہیں...: یا، کسی زمین کے خلاف تجارت کرتے ہیں، اور لوگ اسے تسلیم نہیں کرتے}\n19۔ کیا تم نے یہوداہ کو مکمل طور پر رد کر دیا ہے؟ کیا تمہاری روح نے صیون سے نفرت کی؟ تم نے ہمیں کیوں مارا اور ہمارے لیے کوئی شفا نہیں؟ ہم امن کی تلاش میں تھے، اور {اچھائی} نہیں ہے؛ اور شفا کے وقت کے لیے، اور دیکھو مصیبت!\n20. اے خداوند، ہم اپنی برائی کو تسلیم کرتے ہیں، {اور} اپنے آباؤ اجداد کی گناہی: کیونکہ ہم نے تیرے خلاف گناہ کیا ہے۔\n21. اپنے نام کے لیے ہم سے نفرت نہ کرو، اپنے جلال کے تخت کو بے عزتی نہ کرو: یاد رکھو، ہمارے ساتھ اپنا عہد نہ توڑو۔\n22. کیا غیر یہودیوں کی فضول باتوں میں سے کوئی ایسی چیز ہے جو بارش کا سبب بن سکے؟ یا آسمان بارش دے سکتا ہے؟ کیا تم نہیں ہو، اے خداوند ہمارے خدا؟ لہٰذا ہم تمہارا انتظار کریں گے: کیونکہ تم نے یہ سب کچھ بنایا ہے۔","1۔ پھر خداوند نے مجھ سے فرمایا، اگرچہ موسیٰ اور سموئیل میرے سامنے کھڑے تھے، {لیکن} میرا دل {اس قوم کی طرف نہیں ہو سکتا تھا}: {ان} کو میری نظر سے دور کر دو، اور انہیں باہر جانے دو۔\n2۔ اور یہ ہو جائے گا، اگر وہ تم سے کہیں، کہاں جائیں گے؟ پھر تم انہیں بتاؤ گے، خداوند یوں فرماتا ہے؛ جیسے {are} کے لیے موت، موت تک؛ اور جیسے {are} تلوار کے لیے، تلوار کے لیے؛ اور وہ جو قحط کے لیے ہیں، قحط کے لیے؛ اور جیسے {are} قید کے لیے، قید کے لیے۔\n3۔ اور میں ان پر چار اقسام مقرر کروں گا، خداوند فرماتا ہے: تلوار مارنے کے لیے، کتے پھاڑنے کے لیے، آسمان کے پرندے اور زمین کے جانور جو کھا کر تباہ کر سکتے ہیں۔ {اقسام: عبدی۔ خاندان}\n4۔ اور میں انہیں زمین کے تمام بادشاہتوں میں منتقل کروں گا، کیونکہ منسیہ، حزقیاہ کا بیٹا، یہوداہ کے بادشاہ کی وجہ سے، جو اس نے یروشلم میں کیا۔ {کیون...: عبرانی۔ انہیں ہٹانے کے لیے دے دو}\n5۔ کیونکہ تم پر کون رحم کرے گا، اے یروشلم؟ یا کون تم پر افسوس کرے گا؟ یا کون کنارے جا کر پوچھے گا کہ تم کیسے ہو؟ {کیسے...: ہیب۔ تمہاری سلامتی کی؟}\n6۔ خداوند فرماتا ہے کہ تو نے مجھے چھوڑ دیا ہے، تو پیچھے جا چکے ہو: اس لیے میں تمہارے خلاف اپنا ہاتھ بڑھاؤں گا اور تمہیں تباہ کر دوں گا؛ میں توبہ کرنے میں تھک چکا ہوں۔\n7۔ اور میں انہیں زمین کے دروازوں پر پنکھا سے پنکھا دوں گا؛ میں ان کے بچوں سے محروم ہو جاؤں گا، میں اپنے لوگوں کو تباہ کر دوں گا، {چونکہ} وہ اپنے راستوں سے واپس نہیں آئیں گے۔ {بچے: یا، جو بھی عزیز ہے}\n8۔ ان کی بیواؤں کو سمندر کی ریت سے اوپر مجھ تک پہنچا دیا گیا ہے: میں نے ان پر نوجوانوں کی ماں کے خلاف دوپہر کے وقت ایک بگاڑ پیدا کر دیا ہے: میں نے اچانک اس پر گروا دیا ہے، اور شہر پر خوف پھیلا دیا ہے۔ {ماں...: یا، ماں شہر ایک نوجوان جو بگاڑ رہا ہے، وغیرہ، یا، ماں اور نوجوان مرد}\n9۔ جس نے سات جنم دیے، وہ کمزور ہو جاتی ہے: اس نے بھوت کو چھوڑ دیا ہے؛ اس کا سورج غروب ہو چکا ہے جبکہ وہ ابھی دن ہے: وہ شرمندہ اور پریشان ہو گئی ہے: اور ان کی باقیات میں ان کے دشمنوں کے سامنے تلوار کے حوالے کر دوں گا، خداوند فرماتا ہے۔\n10۔ افسوس میری ماں، کہ تم نے مجھے ایک لڑاکا اور زمین بھر کے لیے متنازعہ آدمی پیدا کیا! میں نے نہ سود پر قرض دیا، نہ انسانوں نے مجھے سود پر قرض دیا؛ {پھر بھی} ان میں سے ہر ایک مجھے لعنت دیتا ہے۔\n11۔ خداوند نے فرمایا، یقینا یہ تمہارے باقی ماندہ لوگوں کے لیے اچھا ہوگا؛ یقینا میں دشمن کو برائی کے وقت اور مصیبت کے وقت تم سے دعا کرنے پر مجبور کروں گا۔ {وجہ...: یا، دشمن سے تمہارے لیے التجا کرو}\n12. کیا لوہا شمالی لوہا اور فولاد کو توڑے گا؟\n13۔ تیری دولت اور خزانے میں بغیر قیمت کے مال غنیمت کو دوں گا، اور وہ بھی تمہارے تمام گناہوں کے بدلے، حتیٰ کہ تمہاری تمام سرحدوں میں۔\n14۔ اور میں تمہیں تمہارے دشمنوں کے ساتھ اس سرزمین میں لے جاؤں گا {جسے تم نہیں جانتے}: کیونکہ میرے غصے میں آگ جل رہی ہے، {جو} تم پر جل جائے گی۔\n15۔ اے خداوند، تو جانتا ہے: مجھے یاد رکھ، اور مجھے زیارت کر، اور میرے ظلم کرنے والوں سے بدلہ لے؛ اپنی طویل برداشت میں مجھے نہ لے جانا: جان لو کہ تیری خاطر میں نے ملامت برداشت کی ہے۔\n16۔ تیرے الفاظ مل گئے، اور میں نے انہیں کھا لیا؛ اور تیرا کلام میرے لیے میرے دل کی خوشی اور خوشی تھا: کیونکہ مجھے تیرے نام سے پکارا جاتا ہے، اے خداوند، لشکروں کے خدا۔ {میں ہوں...: عبرانی۔ تیرا نام مجھ پر پکارا جاتا ہے}\n17۔ میں مذاق اڑانے والوں کی مجلس میں نہیں بیٹھا، نہ خوش ہوا؛ میں تمہارے ہاتھ کی وجہ سے اکیلا بیٹھا رہا: کیونکہ تم نے مجھے غصے سے بھر دیا ہے۔\n18. میرا درد مستقل کیوں ہے، اور میرا زخم لاعلاج کیوں ہے، {جو} ٹھیک ہونے سے انکار کرتا ہے؟ کیا تم میرے لیے مکمل طور پر جھوٹا رہو گے، {اور} پانی {جو} ناکام ہو جائے گا؟ {ناکام: عبرانی یقین نہیں؟}\n19۔ لہٰذا خداوند فرماتا ہے، اگر تم واپس آؤ گے تو میں تمہیں دوبارہ لاؤں گا، {اور} تم میرے سامنے کھڑے ہو جاؤ گے: اور اگر تم بدکار سے قیمتی چیز نکالو گے، تو تم میرے منہ کی طرح بنو گے: انہیں تمہارے پاس لوٹنے دو؛ لیکن ان کے پاس واپس مت جاؤ۔\n20۔ اور میں تمہیں اس قوم کے لیے ایک باڑ والی دیوار بنا دوں گا: اور وہ تمہارے خلاف لڑیں گے، لیکن وہ تم پر غالب نہیں آ سکیں گے: کیونکہ میں تمہارے ساتھ ہوں تاکہ تمہیں بچا سکوں اور تمہیں بچا سکوں، خداوند فرماتا ہے۔\n21۔ اور میں تمہیں بدکاروں کے ہاتھوں سے نجات دوں گا، اور تمہیں خوفناک کے ہاتھوں سے نجات دوں گا۔","1۔ خداوند کا کلام بھی میرے پاس آیا، جس میں کہا،\n2۔ تم اپنی بیوی نہیں لو گے، نہ ہی اس جگہ تمہارے بیٹے یا بیٹیاں ہوں گی۔\n3۔ کیونکہ خداوند یہ فرماتا ہے ان بیٹوں اور بیٹیوں کے بارے میں جو اس جگہ پیدا ہوتی ہیں، ان کی ماؤں کے بارے میں جو انہیں جنم دیتی ہیں، اور ان کے باپوں کے بارے میں جو انہیں اس زمین میں پیدا کرتے ہیں؛\n4۔ وہ شدید موت سے مر جائیں گے؛ انہیں افسوس نہیں کیا جائے گا؛ نہ ہی انہیں دفن کیا جائے گا؛ {لیکن} وہ زمین پر گوبر کی طرح ہوں گے: اور تلوار اور قحط سے نگل جائیں گے؛ اور ان کی لاشیں آسمان کے پرندوں اور زمین کے جانوروں کے لیے گوشت ہوں گی۔\n5۔ کیونکہ خداوند یوں فرماتا ہے، نہ ماتم کے گھر میں داخل ہو، نہ ماتم کرو اور نہ ہی ان پر افسوس کرو، کیونکہ میں نے اس قوم سے اپنا سکون چھین لیا ہے، خداوند فرماتا ہے، محبت اور رحمت بھی۔ {سوگ: یا، سوگ کی ضیافت}\n6۔ بڑے اور چھوٹے دونوں اس زمین میں مر جائیں گے: انہیں دفن نہیں کیا جائے گا، نہ لوگ ان کے لیے ماتم کریں گے، نہ خود کو کاٹیں گے، نہ گنجے ہو جائیں گے:\n7. نہ ہی {لوگ} ان کے لیے اپنے آپ کو ماتم میں پھاڑیں گے، تاکہ انہیں مردوں کے لیے تسلی دے سکیں؛ نہ ہی {مرد} انہیں اپنے والد یا ماں کے لیے تسلی کا پیالہ دیں گے۔ {پھاڑو...: یا، ان کے لیے روٹی توڑو}\n8۔ تم دعوت کے گھر میں بھی نہیں جا کر ان کے ساتھ بیٹھ کر کھانا اور پینا نہیں چاہتے۔\n9۔ کیونکہ لشکروں کا رب، اسرائیل کا خدا یہی فرماتا ہے؛ دیکھو، میں اس جگہ سے تمہاری آنکھوں میں، اور تمہارے دنوں میں، خوشی کی آواز، دولہا کی آواز، اور دلہن کی آواز کو ختم کر دوں گا۔\n10۔ اور یہ تب ہوگا جب تم ان لوگوں کو یہ سب الفاظ دکھاؤ گے، اور وہ تم سے کہیں گے، خدا نے ہمارے خلاف یہ سب برا کیوں سنایا؟ یا ہماری گناہ کیا ہے؟ یا وہ کیا گناہ ہے جو ہم نے خداوند ہمارے خدا کے خلاف کیا ہے؟\n11۔ پھر تو تم ان سے کہو گے، کیونکہ تمہارے آباؤ اجداد نے مجھے چھوڑ دیا، خداوند فرماتا ہے، اور دوسرے دیوتاؤں کے پیچھے چلے، ان کی خدمت کی، ان کی عبادت کی، مجھے چھوڑ دیا، اور میرے قانون کی پاسداری نہیں کی؛\n12۔ اور تم نے اپنے باپ دادا سے بھی بدتر کیا ہے؛ کیونکہ دیکھو، تم ہر ایک کو اس کے برے دل کے تصور کے پیچھے چلتے ہو، تاکہ وہ میری بات نہ سنیں: {خیال: یا، ضد}\n13۔ اسی لیے میں تمہیں اس زمین سے نکال دوں گا ایک ایسی زمین میں جسے تم نہیں جانتے، نہ تم اور نہ تمہارے باپ دادا؛ اور وہاں تم دن رات دوسرے دیوتاؤں کی عبادت کرو گے؛ جہاں میں تم پر احسان نہیں کروں گا۔\n14۔ لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ اب یہ نہ کہا جائے گا، خداوند زندہ ہے، جس نے اسرائیل کے بچوں کو مصر کی سرزمین سے نکالا؛\n15۔ لیکن، خداوند زندہ ہے، جس نے اسرائیل کے بچوں کو شمال کی زمین سے اور ان تمام زمینوں سے پروان چڑھایا جہاں سے اس نے انہیں نکالا: اور میں انہیں ان کی زمین میں واپس لاؤں گا جو میں نے ان کے باپ کو دی تھی۔\n16. دیکھو، میں بہت سے ماہی گیروں کو بلاتا ہوں، خداوند فرماتا ہے، اور وہ انہیں مچھلی پکڑیں گے؛ اور اس کے بعد میں بہت سے شکاری بھیجوں گا، جو ہر پہاڑ، ہر پہاڑ سے، اور چٹانوں کے سوراخوں سے انہیں شکار کریں گے۔\n17. کیونکہ میری آنکھیں ان کے تمام راستوں پر ہیں: وہ میرے چہرے سے چھپی نہیں، نہ ہی ان کی گناہی میری آنکھوں سے چھپی ہے۔\n18۔ اور سب سے پہلے میں ان کے گناہوں اور گناہوں کا دوگنا بدلہ دوں گا؛ کیونکہ انہوں نے میری زمین کو آلودہ کیا، انہوں نے میری وراثت کو اپنی نفرت انگیز اور گھناونے چیزوں کی لاشوں سے بھر دیا ہے۔\n19۔ اے خداوند، میری طاقت، میرا قلعہ، اور مصیبت کے دن میری پناہ گاہ، غیر یہودی زمین کے کونے سے تیرے پاس آئیں گے اور کہیں گے، یقینا ہمارے آباؤ اجداد نے جھوٹ، فضول اور ایسی چیزیں وراثت میں پائی ہیں جن میں کوئی فائدہ نہیں۔\n20. کیا انسان اپنے لیے دیوتا بنائے گا، اور وہ خدا نہیں ہیں؟\n21. لہٰذا، دیکھو، میں ایک بار انہیں بتاؤں گا، میں انہیں اپنا ہاتھ اور طاقت جاننے دوں گا؛ اور وہ جان لیں گے کہ میرا نام {ہے} خداوند ہے۔ {خداوند: یا، یہووا}","1۔ یہوداہ کا گناہ {ہے} لوہے کے قلم سے لکھا گیا، {اور} ہیرے کی نوک سے: {یہ} ان کے دل کی میز پر کندہ ہے، اور تمہارے قربان گاہوں کے سینگوں پر؛ {نقطہ: عبرانی۔ ناخن}\n2۔ جب ان کے بچے اپنے قربان گاہوں اور اونچے پہاڑوں پر سبز درختوں کے کنارے اپنے باغات کو یاد کرتے ہیں۔\n3۔ اے میرے میدان میں پہاڑ، میں تیرا مال {اور} تمہارے تمام خزانے غنیمت کو دوں گا، {اور} تیری تمام سرحدوں پر گناہ کے لیے بلند مقامات۔\n4۔ اور تم، حتیٰ کہ تم خود بھی، اپنی وراثت کو ختم کر دو جو میں نے تمہیں دی ہے؛ اور میں تمہیں اپنے دشمنوں کی خدمت کروں گا اس سرزمین میں جسے تم نہیں جانتے: کیونکہ تم نے میرے غصے میں آگ جلا دی ہے، جو ہمیشہ کے لیے جلتی رہے گی۔ {آپ خود: عبرانی۔ اپنے آپ میں}\n5۔ خداوند یہ فرماتا ہے؛ لعنت زدہ {ہو} وہ شخص جو انسان پر بھروسہ کرتا ہے، اپنا بازو گوشت دیتا ہے، اور جس کا دل خداوند سے جدا ہوتا ہے۔\n6۔ کیونکہ وہ صحرا کی زمین کی طرح ہوگا، اور نہیں دیکھے گا کہ کب اچھائی آئے گی؛ بلکہ وہ ویران علاقوں میں خشک جگہوں پر رہیں گے، جو ایک نمکین زمین میں ہے اور آباد نہیں۔\n7۔ مبارک وہ شخص ہے جو خداوند پر بھروسہ کرتا ہے، اور جس کی امید خداوند ہے۔\n8۔ کیونکہ وہ ایسے درخت کی طرح ہوگا جو پانی کے کنارے لگایا گیا ہو، اور جو دریا کے کنارے اپنی جڑیں پھیلاتا ہے، اور گرمی آنے پر نہیں دیکھے گا، بلکہ اس کا پتا سبز ہوگا؛ اور خشک سالی کے سال میں محتاط نہیں رہیں گے، نہ ہی پھل دینا بند ہوں گے۔ {خشک سالی: یا، تحمل}\n9. دل {ہے} سب سے زیادہ دھوکہ باز اور انتہائی بدکار: کون اسے جان سکتا ہے؟\n10. میں، خداوند، دل کی تلاش کرتا ہوں، {میں} لگام کو آزماتا ہوں، یہاں تک کہ ہر انسان کو اس کے طریقوں کے مطابق دوں، {اور} اس کے اعمال کے پھل کے مطابق۔\n11۔ {جیسا کہ تیتر انڈوں پر بیٹھا ہے}، اور انڈے نہیں نکالتا؛ {یوں} جو دولت حاصل کرتا ہے، اور حق سے نہیں، وہ اپنی زندگی کے بیچ میں انہیں چھوڑ دے گا، اور آخر میں بیوقوف ہوگا۔ {بیٹھتی ہے...: یا، وہ بچے جمع کرتی ہے جو اس نے پیدا نہیں کیے}\n12۔ ابتدا سے ہی ایک شاندار بلند تخت {ہے} ہماری پناہ گاہ کی جگہ۔\n13۔ اے خداوند، اسرائیل کی امید، جو بھی تجھ سے رخصت ہو جائے گا وہ شرمندہ ہوگا، {اور} جو مجھ سے جدا ہوں گے وہ زمین پر لکھے جائیں گے، کیونکہ انہوں نے زندہ پانیوں کے چشمے کو چھوڑ دیا ہے۔\n14. اے خداوند، مجھے شفا دے، اور میں شفا پا جاؤں گا؛ مجھے بچا لو، اور میں نجات پا جاؤں گا: کیونکہ تو میری تعریف ہو۔\n15۔ دیکھو، وہ مجھ سے کہتے ہیں، خداوند کا کلام کہاں ہے؟ اب آنے دو۔\n16۔ جہاں تک میرا تعلق ہے، میں نے پادری بننے سے جلدی نہیں کی کہ تمہاری پیروی کروں: نہ ہی میں نے اس افسوسناک دن کی خواہش کی؛ تم جانتی ہو: جو کچھ میرے ہونٹوں سے نکلا وہ تمہارے سامنے {درست} تھا۔ {تو...: عبرانی تمہارے بعد}\n17۔ میرے لیے خوف نہ بنو: تم برائی کے دن میری امید ہو۔\n18۔ جو مجھے ستاتے ہیں وہ الجھن میں پڑ جائیں، لیکن مجھے پریشان نہ ہونے دیں: انہیں خوفزدہ ہونا چاہیے، لیکن مجھے بھی ڈرنے نہ دیں: ان پر برائی کا دن لے آؤ، اور انہیں دوہری تباہی سے تباہ کر دے۔ {تباہ کریں...: عببرانی۔ انہیں ڈبل بریچ سے توڑو}\n19۔ خداوند نے مجھ سے یوں فرمایا؛ جاؤ اور قوم کے بچوں کے دروازے پر کھڑے ہو جاؤ، جہاں سے یہوداہ کے بادشاہ آتے ہیں، اور جس سے وہ باہر جاتے ہیں، اور یروشلم کے تمام دروازوں پر؛\n20۔ اور ان سے کہو، اے یہوداہ کے بادشاہوں، اور تمام یہوداہ، اور یروشلم کے تمام باشندے، جو ان دروازوں سے داخل ہوتے ہیں، خداوند کا کلام سنو:\n21. خداوند فرماتا ہے؛ ہوشیار رہو، اور ہفتہ کے دن بوجھ نہ اٹھاؤ، نہ یروشلم کے دروازے سے اندر آؤ؛\n22۔ سبت کے دن اپنے گھروں سے بوجھ نہ اٹھاؤ، نہ ہی کوئی کام کرو، بلکہ سبت کے دن کو مقدس سمجھو، جیسا کہ میں نے تمہارے آباؤ اجداد کو حکم دیا تھا۔\n23۔ لیکن انہوں نے نہ فرمانبردار ہوئے، نہ کان جھکایا، بلکہ اپنی گردن سخت کر لی تاکہ وہ نہ سن سکیں اور نہ ہی ہدایت حاصل کر سکیں۔\n24۔ اور یہ ہو جائے گا، اگر تم پوری توجہ سے میری بات سنو، خداوند فرماتا ہے، کہ اس شہر کے دروازوں سے سبت کے دن کوئی بوجھ نہ لانا، بلکہ سبت کے دن کو مقدس رکھو، اس میں کوئی کام نہ کرنا؛\n25۔ پھر اس شہر کے دروازے میں بادشاہ اور شہزادے داخل ہوں گے، جو داؤد کے تخت پر بیٹھے ہوں گے، رتھ اور گھوڑوں پر سوار ہوں گے، وہ، ان کے شہزادے، یہوداہ کے لوگ اور یروشلم کے باشندے: اور یہ شہر ہمیشہ کے لیے قائم رہے گا۔\n26۔ اور وہ یہوداہ کے شہروں سے، یروشلم کے آس پاس کے علاقوں سے، بنیامین کی زمین، میدان، پہاڑوں اور جنوب سے آئیں گے، سلائی کی قربانیاں، قربانیاں، گوشت کی قربانیاں، لوبان اور تعریف کی قربانیاں لائیں گے، خداوند کے گھر کے لیے۔\n27۔ لیکن اگر تم میری بات نہیں سنتے کہ سبت کا دن مقدس مانوں، اور بوجھ نہ اٹھاؤ، حتیٰ کہ ہفتہ کے دن یروشلم کے دروازے سے داخل ہو؛ پھر میں اس کے دروازوں میں آگ جلاؤں گا، اور وہ یروشلم کے محلات کو نگل جائے گی، اور کبھی بجھے نہیں گی۔","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا ہے، جس میں کہا گیا ہے،\n2۔ اٹھو، اور کمہار کے گھر جاؤ، وہاں میں تمہیں اپنی باتیں سناؤں گا۔\n3۔ پھر میں کمہار کے گھر گیا، اور دیکھو، اس نے پہیوں پر کام کیا۔ {پہیے: یا، فریم، یا، سیٹیں}\n4۔ اور جو برتن اس نے مٹی سے بنایا وہ کمہار کے ہاتھ میں خراب ہو گیا: تو اس نے اسے دوبارہ ایک اور برتن بنایا، جیسا کہ کومہارہ کو اچھا لگا کہ وہ اسے بنائے۔ {مٹی...: یا، خراب ہو چکی تھی، جیسے مٹی کمہار کے ہاتھ میں} {بنایا...: عببرانی۔ واپس کیا گیا اور بنایا گیا، وغیرہ}\n5۔ پھر خداوند کا کلام میرے پاس آیا، جس نے کہا،\n6۔ اے اسرائیل کے گھر، کیا میں تمہارے ساتھ یہ کمہار بن سکتا ہوں؟ خداوند فرماتا ہے۔ دیکھو، جیسے مٹی مٹی کمہار کے ہاتھ میں ہے، ویسے ہی تم میرے ہاتھ میں ہو، اے اسرائیل کے گھرانے پر۔\n7. {کب} لمحے میں کسی قوم، اور ایک بادشاہت کے بارے میں بات کروں گا، جو اسے توڑنے، گرانے اور تباہ کرنے کے لیے ہے؛\n8۔ اگر وہ قوم، جس کے خلاف میں نے حکم دیا ہے، اپنی برائی سے منہ موڑ لے، تو میں اس برائی سے توبہ کروں گا جو میں نے ان کے ساتھ کرنے کا سوچا تھا۔\n9. اور {کب} میں ایک قوم کے بارے میں بات کروں گا، اور ایک بادشاہت کے بارے میں، جو اسے تعمیر اور آباد کرے گی؛\n10۔ اگر وہ میرے سامنے برا کرے اور میری آواز نہ مانے، تو میں ان اچھائیوں سے توبہ کروں گا جس سے میں نے کہا تھا کہ میں ان کے لیے فائدہ مند ہوں گا۔\n11۔ اب جاؤ، یہوداہ کے لوگوں اور یروشلم کے باشندوں سے بات کرو، کہو، خداوند یہ فرماتا ہے؛ دیکھو، میں تمہارے خلاف برائی کا الزام لگاتا ہوں، اور تمہارے خلاف ایک چال بناتا ہوں: اب تم سب کو اس کے برے راستے سے واپس لوٹاؤ، اور اپنے طریقے اور اعمال کو اچھے بناؤ۔\n12۔ اور انہوں نے کہا، کوئی امید نہیں: لیکن ہم اپنی مرضی سے چلیں گے، اور ہر ایک اپنے برے دل کی تخیل کرے گا۔\n13۔ لہٰذا خداوند فرماتا ہے؛ اب ان کافروں میں سے پوچھو جنہوں نے ایسی باتیں سنی ہیں: اسرائیل کی کنواری نے بہت خوفناک کام کیا ہے۔\n14. کیا {ایک انسان} لبنان کی برف {جو آتی ہے} میدان کی چٹان سے نکلے گا؟ {یا} کیا وہ سرد بہتا ہوا پانی جو کہیں اور سے آتا ہے، چھوڑ دیا جائے گا؟ {برف...: یا، میرے کھیتوں کے لیے ایک چٹان کے لیے، یا لبنان کی برف کے لیے؟ کیا بہتے پانی کو چھوڑ کر عجیب سرد پانیوں کے لیے چھوڑ دیا جائے گا؟}\n15۔ کیونکہ میرے لوگ مجھے بھول گئے ہیں، انہوں نے دھوپ کو باطل کر دیا، اور انہیں قدیم راستوں سے اپنے راستوں پر چلنے پر مجبور کیا، ایسے راستوں پر چلنے پر مجبور کیا جو چھوڑے نہیں گئے؛\n16۔ اپنی زمین کو ویران بنانا، {اور} مسلسل سیسہ دار بنانا؛ جو بھی وہاں سے گزرے گا وہ حیران رہ جائے گا، اور سر ہلائے گا۔\n17. میں انہیں دشمن کے سامنے مشرقی ہوا کی طرح بکھیر دوں گا؛ میں انہیں ان کی مصیبت کے دن چہرہ نہیں بلکہ پشت دکھاؤں گا۔\n18۔ پھر انہوں نے کہا، آؤ اور یرمیاہ کے خلاف سازشیں کریں؛ کیونکہ قانون نہ کاہن سے فنا ہوگا، نہ دانا کی نصیحت، نہ نبی کا کلام۔ آؤ، اور اسے زبان سے ماریں، اور اس کی کسی بات کی پرواہ نہ کریں۔ {ساتھ...: یا، زبان کے لیے}\n19۔ اے خداوند، میری بات سنو اور ان کی آواز سنو جو میرے خلاف ہیں۔\n20. کیا برائی کا بدلہ اچھائی کا بدلہ ملے گا؟ کیونکہ انہوں نے میری روح کے لیے گڑھا کھود دیا ہے۔ یاد رکھو کہ میں تمہارے سامنے کھڑا تھا تاکہ ان کے لیے اچھی بات کروں، {اور} تیرا غصہ ان سے دور کر سکوں۔\n21۔ اس لیے اپنے بچوں کو قحط کے حوالے کرو، اور تلوار کی طاقت سے ان کا خون بہاؤ؛ اور ان کی بیویوں کو ان کے بچوں سے محروم کر دیا جائے، اور وہ بیوہ بن جائیں؛ اور ان کے آدمیوں کو موت کے گھاٹ اتار دیا جائے؛ ان کے نوجوانوں کو جنگ میں تلوار سے مارے جانے دو۔ {ڈال...: عببرانی۔ انہیں نکال دو}\n22۔ جب تم اچانک ان پر فوج لاؤ گے تو ان کے گھروں سے ایک چیخ سنائی دے گی، کیونکہ انہوں نے مجھے لینے کے لیے ایک گڑھا کھود دیا ہے، اور میرے قدموں کے لیے جال چھپا دیے ہیں۔\n23۔ پھر بھی، اے خداوند، تو جانتے ہو کہ ان کی میرے خلاف تمام نصیحتیں مجھے قتل کرنے کے لیے: ان کے گناہوں کو معاف نہ کر، نہ ان کے گناہ کو اپنی نظر سے مٹا دے، بلکہ انہیں تیرے سامنے گرا دے؛ اپنے غصے کے وقت ان سے معاملہ کرو۔ {مارنے کے لیے...: عببرانی۔ موت کے لیے}","1۔ خداوند فرماتا ہے، جاؤ اور مٹی کی بوتل لے آؤ، اور قدیم لوگوں اور قدیم کاہنوں کی بوتل لے لو؛\n2۔ اور ہنوم کے بیٹے کی وادی کی طرف جاؤ، جو مشرقی دروازے کے دروازے کے قریب ہے، اور وہاں وہ الفاظ پڑھو جو میں تمہیں بتاؤں گا، {مشرقی...: عبرانی۔ سن گیٹ}\n3۔ اور کہو، اے یہوداہ کے بادشاہوں اور یروشلم کے باشندوں، خداوند کا کلام سنو؛ یوں لشکروں کے رب، اسرائیل کے خدا فرماتا ہے؛ دیکھو، میں اس جگہ پر برائی لاؤں گا، جس کی سننے والی اس کے کان سنسناہٹ محسوس کریں گے۔\n4۔ کیونکہ انہوں نے مجھے چھوڑ دیا ہے، اس جگہ کو دور کر دیا ہے، اور اس میں دوسرے دیوتاؤں کے لیے خوشبو جلا دی ہے، جنہیں نہ وہ جانتے ہیں، نہ ان کے باپوں نے، نہ یہوداہ کے بادشاہوں کو، اور اس جگہ کو معصوموں کے خون سے بھر دیا ہے؛\n5۔ انہوں نے بعل کی اونچی جگہیں بھی بنائی ہیں، تاکہ اپنے بیٹوں کو آگ سے جلا سکیں {کیونکہ بعل کو جلانے والی قربانیاں} تھیں، جن کا میں نے حکم نہیں دیا، نہ کہا تھا، نہ ہی میرے ذہن میں آیا:\n6۔ لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ اس جگہ کو اب ٹوفیت نہیں کہا جائے گا، نہ ہی ہنم کے بیٹے کی وادی، بلکہ قتل عام کی وادی کہلائی جائے گی۔\n7۔ اور میں اس جگہ پر یہوداہ اور یروشلم کی نصیحت کو منسوخ کر دوں گا؛ اور میں انہیں تلوار کے ذریعے ان کے دشمنوں کے سامنے، اور ان کے ہاتھوں جو اپنی جان چاہتے ہیں، گرا دوں گا: اور ان کی لاشیں آسمان کے پرندوں اور زمین کے جانوروں کے لیے گوشت بناؤں گا۔\n8۔ اور میں اس شہر کو ویران کر دوں گا، اور ایک سرسراہٹ بھی؛ جو بھی وہاں سے گزرے گا وہ حیران ہوگا اور اس کی تمام آفتوں کی وجہ سے سیسکاری کرے گا۔\n9۔ اور میں انہیں ان کے بیٹوں کا گوشت اور اپنی بیٹیوں کا گوشت کھلاؤں گا، اور وہ ہر ایک کو اس کے دوست کا گوشت کھائیں گے، محاصرے اور سختی میں، جس سے ان کے دشمن اور جو اپنی جان چاہتے ہیں، انہیں پابند کریں گے۔\n10۔ پھر تم بوتل توڑ دو ان لوگوں کے سامنے جو تمہارے ساتھ جائیں گے،\n11۔ اور ان سے کہے گا، یہی فرماتا ہے رب لشکر؛ اسی طرح میں اس قوم اور اس شہر کو توڑوں گا، جیسے {ایک} کومھار کے برتن کو توڑتا ہے، جو دوبارہ مکمل نہیں ہو سکتا: اور وہ {ان} توفیت میں دفن کر دیں گے، جب تک {دفنانے} کی جگہ نہ رہے۔ {be made...: عبرانی۔ شفا پانا}\n12. خداوند فرماتا ہے، میں اس جگہ اور اس کے باشندوں کے ساتھ ایسا ہی کروں گا، اور {حتیٰ کہ} اس شہر کو توفیت بنا دوں گا:\n13۔ اور یروشلم کے گھر، اور یہوداہ کے بادشاہوں کے گھر، توپھیت کی جگہ کی طرح ناپاک ہو جائیں گے، کیونکہ ان تمام گھروں کی چھتوں پر آسمان کے تمام لشکر کو لوبان جلایا گیا ہے، اور دوسرے دیوتاؤں کو شراب کی قربانیاں دی گئی ہیں۔\n14۔ پھر یرمیاہ توفیت سے آیا، جہاں خداوند نے اسے نبوت کے لیے بھیجا تھا؛ اور وہ لارڈز ہاؤس کے دربار میں کھڑے ہوئے؛ اور سب لوگوں سے کہا،\n15۔ لشکروں کے رب، اسرائیل کے خدا نے یوں فرمایا؛ دیکھو، میں اس شہر اور اس کے تمام قصبوں پر وہ تمام برائی لاؤں گا جو میں نے اس کے خلاف سنائی ہے، کیونکہ انہوں نے اپنی گردن سخت کر لی ہے تاکہ وہ میرے الفاظ نہ سن سکیں۔","1۔ اب پاشور، جو ایمر کاهن کا بیٹا تھا، اور جو خداوند کے گھر میں بھی چیف گورنر تھا، نے سنا کہ یرمیاہ نے ان باتوں کی پیش گوئی کی تھی۔\n2۔ پھر پاشور نے یرمیاہ نبی کو مارا، اور اسے بنیامین کے اونچے دروازے میں جو {تھا} کے ذخائر میں ڈال دیا، جو {تھا} خداوند کے گھر کے قریب۔\n3۔ اور کل ایسا ہوا کہ پاشور نے یرمیاہ کو اسٹاک سے باہر نکالا۔ پھر یرمیاہ نے اس سے کہا، خداوند نے تیرے نام کو پاشور نہیں بلکہ ماگورمیسابیب کہا۔ {Magormissabib: یعنی خوف کا دور}\n4۔ کیونکہ خداوند فرماتا ہے، دیکھو، میں تمہیں اپنے اور تمہارے تمام دوستوں کے لیے دہشت پیدا کروں گا، اور وہ اپنے دشمنوں کی تلوار سے گریں گے، اور تمہاری آنکھیں اسے دیکھیں گی: اور میں تمام یہوداہ کو بابل کے بادشاہ کے ہاتھ میں دوں گا، اور وہ انہیں قیدی بنا کر بابل لے جائے گا،  اور انہیں تلوار سے مار ڈالوں گا۔\n5۔ مزید برآں، میں اس شہر کی تمام طاقت، اس کی تمام محنت، اس کی قیمتی چیزیں، اور یہوداہ کے بادشاہوں کے تمام خزانے ان کے دشمنوں کے ہاتھ میں دوں گا، جو انہیں برباد کریں گے، لے جائیں گے، اور بابل لے جائیں گے۔\n6۔ اور تم، پاشور، اور تمہارے گھر میں رہنے والے سب قید میں چلے جاؤ گے: اور تم بابل آؤ گے، وہاں مرو گے، اور وہاں دفن ہو گے، اور تمہارے تمام دوست جن سے تم نے جھوٹ کی پیش گوئی کی ہے۔\n7۔ اے خداوند، تو نے مجھے دھوکہ دیا، اور میں دھوکہ کھا گیا: تو مجھ سے زیادہ طاقتور ہے، اور کامیاب ہو گیا ہے: میں روزانہ مذاق اڑاتا ہوں، ہر کوئی میرا مذاق اڑاتا ہے۔ {دھوکہ کھایا گیا: یا، بہکایا گیا}\n8. کیونکہ جب سے میں نے بولا، میں نے پکارا، میں نے تشدد اور بگاڑ رویا؛ کیونکہ خداوند کا کلام میرے لیے روزانہ ملامت اور طنز بن گیا۔\n9۔ پھر میں نے کہا، میں اس کا ذکر نہیں کروں گا، اور اس کے نام پر مزید بات نہیں کروں گا۔ لیکن {اس کا لفظ} میرے دل میں ایسے تھا جیسے میری ہڈیوں میں جلتی ہوئی آگ، اور میں برداشت سے تھکا ہوا تھا، اور میں رک نہیں سکا۔\n10۔ کیونکہ میں نے بہت سے لوگوں کی بدنامی سنی ہے، ہر طرف خوف ہے۔ رپورٹ کریں، {کہیں وہ}، اور ہم رپورٹ کریں گے۔ میرے تمام ساتھی میرے رکنے کا انتظار کر رہے تھے، {کہہ رہے تھے}، شاید وہ بہکایا جائے گا، اور ہم اس پر غالب آئیں گے، اور ہم اس سے انتقام لیں گے۔ {سب...: عبرانی۔ میرے امن کے ہر آدمی}\n11. لیکن خداوند میرے ساتھ ایک بہت خوفناک شخص ہے: اس لیے میرے ستانے والے لڑکھڑائیں گے، اور وہ کامیاب نہیں ہوں گے: وہ بہت شرمندہ ہوں گے؛ کیونکہ وہ ترقی نہیں کریں گے: ان کی دائمی الجھن کبھی نہیں بھولی جائے گی۔\n12. لیکن، اے رب لشکروں، جو راستبازوں کو آزمائش دیتا ہے، {اور لگام اور دل دیکھتا ہے، مجھے ان سے تیرا انتقام دکھاؤ: کیونکہ میں نے اپنا مقصد تیرے لیے کھول دیا ہے۔\n13۔ خداوند کو گاؤ، خداوند کی تعریف کرو، کیونکہ اس نے غریبوں کی جان کو بدکاروں کے ہاتھوں سے بچا لیا ہے۔\n14. لعنت زدہ {ہو} وہ دن جس میں میں پیدا ہوا: وہ دن جب میری ماں مجھے جنم دے برکت نہ دے۔\n15. لعنت پر {} وہ شخص جس نے میرے والد کو خبر دی اور کہا، تمہارے لیے ایک مرد بچہ پیدا ہوا ہے؛ جس سے وہ بہت خوش ہوا۔\n16۔ اور وہ آدمی ان شہروں کی طرح ہو جنہیں خداوند نے گرا دیا اور توبہ نہ کی؛ اور اسے صبح کی پکار اور دوپہر کے وقت شور سننے دو؛\n17. کیونکہ اس نے مجھے رحم سے نہیں مارا؛ یا یہ کہ میری ماں شاید میری قبر ہوتی، اور اس کا رحم {آنے والا} ہمیشہ میرے ساتھ عظیم رہتا۔\n18۔ میں رحم سے کیوں نکلا تاکہ محنت اور غم دیکھ سکوں، تاکہ میرے دن شرمندگی میں گزر جائیں؟","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، جب بادشاہ صدقیاہ نے اس کے پاس ملخیاہ کے بیٹے پاشور اور معسیاہ کاهن کے بیٹے زفانیاہ کو بھیجا، اور کہا،\n2. میں تم سے دعا کرتا ہوں کہ ہمارے لیے خداوند سے پوچھو؛ کیونکہ بابل کا بادشاہ نبوکدرز ہمارے خلاف جنگ کرتا ہے؛ اگر ایسا ہے تو خداوند ہمارے ساتھ اپنے تمام حیرت انگیز اعمال کے مطابق سلوک کرے گا، تاکہ وہ ہم سے اوپر چلا جائے۔\n3۔ پھر یرمیاہ نے ان سے کہا، یوں تم صدقیاہ سے کہو گے:\n4۔ یہی فرماتا ہے خداوند اسرائیل کے خدا؛ دیکھو، میں وہ جنگی ہتھیار واپس کر دوں گا جو تمہارے ہاتھ میں ہیں، جن سے تم بابل کے بادشاہ اور کلدانیوں کے خلاف لڑ رہے ہو، جو تمہارے محاصرے میں ہیں بغیر دیواروں کے، اور میں انہیں اس شہر کے بیچ میں جمع کروں گا۔\n5۔ اور میں خود تمہارے خلاف ہاتھ بڑھا کر اور مضبوط بازو کے ساتھ لڑوں گا، حتیٰ کہ غصے میں، غصے میں، اور شدید غصے میں۔\n6۔ اور میں اس شہر کے باشندوں کو، انسان اور جانور دونوں، مار ڈالوں گا: وہ ایک بڑی وبا سے مر جائیں گے۔\n7۔ اور اس کے بعد، خداوند فرماتا ہے، میں یہوداہ کے بادشاہ زدقیاہ اور اس کے خادموں، اور لوگوں کو، اور جو لوگ اس شہر میں بچا ہیں، وبا، تلوار اور قحط سے، بابل کے بادشاہ نبوکدرز کے ہاتھ میں، ان کے دشمنوں کے ہاتھوں، اور ان کے جانوں کے ہاتھوں میں بچا دوں گا:  اور وہ انہیں تلوار کی نوک سے مارے گا؛ وہ انہیں معاف نہیں کرے گا، نہ رحم کرے گا، نہ رحم کرے گا۔\n8۔ اور اس قوم سے تم کہو گے، خداوند یہی فرماتا ہے؛ دیکھو، میں تمہارے سامنے زندگی کا راستہ اور موت کا راستہ پیش کرتا ہوں۔\n9۔ جو اس شہر میں رہے گا وہ تلوار، قحط اور وبا سے مرے گا، لیکن جو باہر جائے گا اور کلدانیوں کے ہاتھوں مارا جائے گا جو تمہیں گھیر رہے ہیں، وہ زندہ رہے گا اور اس کی جان اس کے لیے شکار کے طور پر ہوگی۔\n10۔ کیونکہ میں نے اس شہر کے خلاف برائی کے لیے رخ کیا ہے، نہ کہ بھلائی کے لیے، خداوند فرماتا ہے: یہ بابل کے بادشاہ کے ہاتھ میں دیا جائے گا، اور وہ اسے آگ سے جلا دے گا۔\n11۔ اور یہوداہ کے بادشاہ کے گھر کو چھوتے ہوئے، {کہیں}، خداوند کا کلام سنو؛\n12۔ اے داؤد کے گھرانہ، خداوند فرماتا ہے؛ صبح فیصلہ کرو، اور جو ظالم کے ہاتھوں بگڑا ہوا ہے اسے آزاد کر دو، ورنہ میرا غصہ آگ کی طرح بجھ جائے گا، اور تمہارے اعمال کی برائی کی وجہ سے کوئی اسے بجھا نہیں سکتا۔ {ایگزیکیوٹ: ہیب۔ جج}\n13. دیکھو، میں تیرے خلاف ہوں، اے وادی کے باشندے، {اور} میدان کی چٹان پر، خداوند فرماتا ہے؛ جو کہتے ہیں، کون ہمارے خلاف آئے گا؟ یا کون ہمارے گھروں میں داخل ہوگا؟ {رہائشی: عبرانی۔ آبادکار}\n14۔ لیکن میں تمہیں تمہارے اعمال کے پھل کے مطابق سزا دوں گا، خداوند فرماتا ہے: اور میں اس کے جنگل میں آگ جلاؤں گا، جو اس کے ارد گرد کی ہر چیز کو نگل جائے گی۔ {سزا: عبرانی۔ ملاحظہ کریں}","1۔ خداوند فرماتا ہے؛ یہوداہ کے بادشاہ کے گھر نیچے جاؤ، اور وہاں یہ لفظ کہو۔\n2۔ اور کہو، اے یہوداہ کے بادشاہ خداوند کا کلام سنو، جو داؤد کے تخت پر بیٹھا ہے، تو اور تمہارے بندوں اور اپنے لوگوں کے جو ان دروازوں سے داخل ہوتے ہیں:\n3۔ خداوند یہ فرماتا ہے؛ فیصلہ اور راستبازی انجام دو، اور ظلم کرنے والے کے ہاتھ سے بگڑے ہوئے کو آزاد کرو: اور نہ ظلم کرو، نہ اجنبی، نہ باپ کے یتیم پر، نہ بیوہ پر ظلم کرو، نہ اس جگہ پر معصوم خون بہاؤ۔\n4۔ اگر تم واقعی یہ کام کرو گے، تو وہاں اس گھر کے دروازے سے بادشاہ داؤد کے تخت پر بیٹھے ہوں گے، رتھ اور گھوڑوں پر سوار ہوں گے، وہ، اس کے خادم اور اس کے لوگ۔ {اوپر...: عبرانی کیونکہ داؤد اپنے تخت پر ہے}\n5۔ لیکن اگر تم یہ الفاظ نہیں سننا چاہتے، تو میں خود قسم کھاتا ہوں، خداوند فرماتا ہے، کہ یہ گھر ویران ہو جائے گا۔\n6۔ کیونکہ خداوند یہوداہ کے بادشاہ کے گھرانے سے یوں فرماتا ہے؛ تو میرے لیے گلعاد ہو، لبنان کا سربراہ ہو: یقینا میں تمہیں بیابان بنا دوں گا، اور وہ شہر جو آباد نہیں ہیں۔\n7۔ اور میں تمہارے خلاف تباہ کرنے والے تیار کروں گا، ہر ایک اپنے ہتھیار کے ساتھ: اور وہ تمہارے منتخب دیودار کاٹیں گے، اور انہیں آگ میں پھینک دیں گے۔\n8۔ اور بہت سی قومیں اس شہر سے گزریں گی، اور ہر آدمی اپنے پڑوسی سے کہیں گی، خداوند نے اس عظیم شہر کے ساتھ ایسا کیوں کیا؟\n9۔ پھر وہ جواب دیں گے، کیونکہ انہوں نے خداوند اپنے خدا کے عہد کو چھوڑ دیا ہے، دوسرے دیوتاؤں کی عبادت کی ہے، اور ان کی خدمت کی ہے۔\n10۔ مردوں کے لیے نہ روؤ، نہ اس پر افسوس کرو۔ {بلکہ} اس کے لیے روؤ جو چلا جاتا ہے: کیونکہ وہ دوبارہ نہیں آئے گا، نہ اپنے وطن کو دیکھے گا۔\n11۔ کیونکہ خداوند یہوداہ کے بادشاہ یوشیا کے بیٹے شلم کے بارے میں یہی فرماتا ہے، جو یوسیاہ کے باپ کی جگہ حکومت کرتا تھا، جو اس جگہ سے نکلا تھا؛ وہ اب وہاں واپس نہیں جائے گا:\n12۔ لیکن وہ اس جگہ مر جائے گا جہاں اسے قید کیا گیا ہے، اور وہ اس زمین کو دوبارہ نہیں دیکھے گا۔\n13۔ اس پر افسوس جو اپنا گھر ناانصافی سے بناتا ہے، اور اپنے کمرے ظلم سے؛ {جو} اپنے پڑوسی کی خدمت کو بغیر اجرت کے استعمال کرتا ہے، اور اسے اس کے کام کے بدلے نہیں دیتا؛\n14۔ جو کہتا ہے، میں اپنے لیے ایک چوڑا گھر اور بڑے کمرے بناؤں گا، اور اس کی کھڑکیاں کاٹ دوں گا؛ اور {یہ} دیودار کے ساتھ سیئل کیا گیا ہے، اور سرخ رنگ سے رنگا گیا ہے۔ {بڑا: عبوری۔ تھرو ایئرڈ} {کھڑکیاں: یا، میری کھڑکیاں}\n15. کیا تم حکومت کرو گے، کیونکہ تم دیودار کے سب سے قریب ہو؟ کیا تمہارے والد نے کھایا، پیا، اور فیصلہ اور انصاف نہیں کیا، {اور} پھر {یہ اس کے لیے ٹھیک تھا}؟\n16۔ انہوں نے غریبوں اور محتاجوں کے معاملے کا فیصلہ کیا؛ تو {یہ تھا} اچھا، {اس کے ساتھ: کیا} مجھے جاننا نہیں تھا؟ خداوند فرماتا ہے۔\n17. لیکن تمہاری آنکھیں اور دل صرف تمہاری لالچ کے لیے ہیں، اور معصوم خون بہانے کے لیے، ظلم اور تشدد کے لیے، یہ سب کرنے کے لیے۔ {تشدد: یا، درانداز}\n18۔ لہٰذا خداوند یہوداہ کے بادشاہ یوسیاہ کے بیٹے یہویاکیم کے بارے میں یوں فرماتا ہے؛ وہ اس کے لیے افسوس نہیں کریں گے، {کہیں}، آہ میرے بھائی! یا، آہ بہن! وہ اس کے لیے افسوس نہیں کریں گے، {کہیں}، اے خداوند! یا، آہ اس کی جلال!\n19۔ اسے گدھے کی تدفین کے ساتھ دفن کیا جائے گا، اسے کھینچا جائے گا اور یروشلم کے دروازوں سے باہر پھینک دیا جائے گا۔\n20۔ لبنان جاؤ اور رو لو؛ اور باشان میں اپنی آواز بلند کرو، اور آیت سے پکارو: کیونکہ تمہارے تمام محبوب تباہ ہو چکے ہیں۔\n21۔ میں نے تم سے تیری خوشحالی میں کہا؛ {لیکن} تم نے کہا، میں سنوں گا نہیں۔ یہ تمہاری جوانی سے تمہاری عادت رہی ہے، کہ تم میری آواز نہیں مانتے۔ {خوشحالی: عبرانی۔ خوشحالی}\n22۔ ہوا تمہارے تمام پادریوں کو کھا جائے گی، اور تمہارے محبوب قید میں چلے جائیں گے: تب تم اپنی تمام برائیوں پر شرمندہ اور پریشان ہو جاؤ گے۔\n23. اے لبنان کے باشندے، جو دیودار کے درختوں میں اپنا گھونسلہ بناتا ہے، تو تم کتنی مہربان ہو گی جب تمہیں تکلیف پہنچے، جیسے ایک عورت کی تکلیف میں! {رہائشی: عبرانی۔ آبادکار}\n24. {جیسا کہ} میں زندہ ہوں، خداوند فرماتا ہے، اگرچہ کونیاہ یہویاکیم بادشاہ یہوداہ کا بیٹا میرے دائیں ہاتھ پر نشان تھا، پھر بھی میں تمہیں وہاں سے نکالنا چاہتا ہوں؛\n25۔ اور میں تمہیں ان کے ہاتھ میں دے دوں گا جو تیری جان چاہتے ہیں، اور ان کے ہاتھ میں جن کے چہرے سے تم ڈرتے ہو، حتیٰ کہ بابل کے بادشاہ نبوکدرززار کے ہاتھ میں، اور کلدانیوں کے ہاتھ میں۔\n26۔ اور میں تمہیں اور تمہاری ماں کو جو تمہیں جنم دیتی ہے، نکال دوں گا، دوسرے ملک میں، جہاں تم پیدا نہیں ہوئے؛ اور وہیں تم مر جاؤ گے۔\n27۔ لیکن اس زمین کی طرف جہاں وہ واپس جانا چاہتے ہیں، وہاں واپس نہیں جائیں گے۔ {خواہش: عبرانی۔ ان کا ذہن بلند کریں}\n28۔ {کیا} یہ آدمی کونیاہ ایک حقیر ٹوٹا ہوا بت ہے؟ {کیا وہ} ایک ایسا برتن ہے جس میں {ہے} کوئی خوشی نہیں؟ کیوں انہیں نکال دیا جاتا ہے، وہ اور اس کی نسل، اور ایک ایسی زمین میں پھینک دیے جاتے ہیں جسے وہ نہیں جانتے؟\n29۔ اے زمین، زمین، زمین، خداوند کا کلام سنو۔\n30۔ خداوند یوں فرماتا ہے، اس بے اولاد آدمی کو لکھو {جو} اپنے زمانے میں کامیاب نہیں ہوگا: کیونکہ اس کی نسل کا کوئی آدمی داؤد کے تخت پر بیٹھا اور یہوداہ میں مزید حکومت کرے گا خوشحال نہیں ہوگا۔","1. ان پادریوں پر افسوس جو میری چراگاہ کی بھیڑوں کو تباہ اور بکھیر دیتے ہیں! خداوند فرماتا ہے۔\n2۔ لہٰذا اسرائیل کے خداوند خدا نے ان پادریوں کے خلاف فرمایا ہے جو میری قوم کو کھانا دیتے ہیں؛ تم نے میرا ریوڑ بکھیر دیا، انہیں بھگا دیا، اور ان سے ملاقات نہیں کی: دیکھو، میں تم پر تمہارے اعمال کی برائی نازل کروں گا، خداوند فرماتا ہے۔\n3۔ اور میں اپنے ریوڑ کے باقیات کو ان تمام ملکوں سے جمع کروں گا جہاں میں نے انہیں نکالا ہے، اور انہیں دوبارہ ان کے گودے میں لے آؤں گا؛ اور وہ پھلدار اور بڑھیں گے۔\n4۔ اور میں ان کے اوپر چرواہے مقرر کروں گا جو انہیں کھلائیں گے، اور وہ مزید خوفزدہ نہیں ہوں گے، نہ خوفزدہ ہوں گے، نہ ہی کمی محسوس کریں گے، خداوند فرماتا ہے۔\n5۔ دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں داؤد کے لیے ایک نیک شاخ اٹھاؤں گا، اور ایک بادشاہ حکومت کرے گا اور خوشحال ہوگا، اور زمین پر فیصلہ اور انصاف کرے گا۔\n6۔ اس کے زمانے میں یہوداہ نجات پائے گا، اور اسرائیل محفوظ رہے گا: اور یہی اس کا نام ہے جس سے اسے کہا جائے گا، خداوند ہماری راستبازی۔ {خداوند...: عبرانی۔ یہوواہتسیدکینو}\n7۔ لہٰذا دیکھو، وہ دن آتے ہیں، خداوند فرماتا ہے، کہ وہ دوبارہ نہیں کہیں گے، خداوند زندہ ہے، جس نے بنی اسرائیل کو مصر کی سرزمین سے نکالا؛\n8۔ لیکن خداوند زندہ ہے، جس نے اسرائیل کے خاندان کی نسل کو شمالی علاقے سے اور ان تمام ملکوں سے نکالا جہاں سے میں نے انہیں نکالا؛ اور وہ اپنے ہی ملک میں رہیں گے۔\n9۔ میرے اندر میرا دل انبیاء کی وجہ سے ٹوٹ گیا ہے؛ میری ساری ہڈیاں کانپ رہی ہیں؛ میں ایک نشے میں دھت آدمی کی طرح ہوں، اور ایک ایسے آدمی کی طرح ہوں جسے شراب نے مغلوب کر دیا ہے، خداوند کی وجہ سے، اور اس کی پاکیزگی کے الفاظ کی وجہ سے۔\n10۔ کیونکہ زمین سے بھری ہوئی ہے؛ کیونکہ قسم کھانے کی وجہ سے زمین سوگ مناتی ہے؛ جنگل کی خوشگوار جگہیں خشک ہو چکی ہیں، ان کا راستہ برا ہے، اور ان کی طاقت درست نہیں ہے۔ {گالی دیتے ہوئے: یا، گالی دیتے ہوئے} {یقینا: یا، تشدد}\n11. کیونکہ نبی اور پادری دونوں گناہ ہیں؛ ہاں، میں نے اپنے گھر میں ان کی برائی دیکھی ہے، خداوند فرماتا ہے۔\n12۔ اسی لیے ان کا راستہ ان کے لیے اندھیرے میں پھسلتے ہوئے راستوں کی طرح ہوگا: انہیں دھکیل دیا جائے گا اور وہاں گر جائیں گے: کیونکہ میں ان پر برائی لاؤں گا، حتیٰ کہ ان کی زیارت کے سال بھی، خداوند فرماتا ہے۔\n13۔ اور میں نے سامریہ کے نبیوں میں حماقت دیکھی ہے؛ انہوں نے بعل میں پیش گوئی کی، اور میرے لوگوں کو اسرائیل کو گمراہ کیا۔ {حماقت: یا، ایک مضحکہ خیز بات: عبرانی۔ ناپسندیدہ}\n14۔ میں نے یروشلم کے نبیوں میں بھی ایک خوفناک چیز دیکھی ہے: وہ کرتے ہیں اور جھوٹ بولتے ہیں: وہ بدکاروں کے ہاتھوں کو بھی مضبوط کرتے ہیں کہ کوئی اس کی برائی سے واپس نہیں جاتا: وہ سب میرے لیے سدوم کی طرح ہیں، اور اس کے باشندے عمورہ کی طرح ہیں۔ {an...: یا، گندگی}\n15۔ لہٰذا خداوند لشکروں نے انبیاء کے بارے میں یوں فرمایا؛ دیکھو، میں انہیں ورم ووڈ کھلاؤں گا، اور انہیں گال کا پانی پلاؤں گا: کیونکہ یروشلم کے نبیوں سے گستاخی پورے ملک میں پھیلی ہوئی ہے۔ {گالیاں: یا، منافقت}\n16۔ یوں لشکروں کے رب فرماتا ہے، ان نبیوں کی باتوں کو نہ سنو جو تمہیں پیش گوئی کرتے ہیں: وہ تمہیں خود غرور بناتے ہیں: وہ اپنے دل کا خواب بولتے ہیں، {اور} خداوند کے منہ سے نہیں۔\n17۔ وہ اب بھی ان لوگوں سے کہتے ہیں جو مجھے حقیر سمجھتے ہیں، خداوند نے فرمایا، تم امن پاؤ گے؛ اور وہ ہر اس شخص سے کہتے ہیں جو اپنے دل کے تصور کے پیچھے چلتا ہے، تم پر کوئی برائی نہیں آئے گی۔ {تخیل: یا، ضد}\n18. کیونکہ کون خداوند کی نصیحت میں کھڑا ہوا اور اس کا کلام سنا اور محسوس کیا؟ جس نے اپنا کلام نشان زد کیا اور سنا؟ {وکیل: یا، خفیہ}\n19۔ دیکھو، خداوند کا ایک طوفان غصے میں باہر نکلا، بلکہ ایک شدید طوفان: یہ بدکاروں کے سر پر شدید گرے گا۔\n20۔ خداوند کا غصہ واپس نہیں آئے گا، جب تک کہ وہ عمل نہ کرے، اور جب تک وہ اپنے دل کے خیالات پورے نہ کر لے: آخری دنوں میں آپ اسے مکمل طور پر غور کریں گے۔\n21۔ میں نے ان نبیوں کو نہیں بھیجا، پھر بھی وہ بھاگے: میں نے ان سے بات نہیں کی، پھر بھی انہوں نے پیش گوئی کی۔\n22۔ لیکن اگر وہ میرے مشورے میں کھڑے ہوتے، اور میرے لوگوں کو میرے الفاظ سنوا دیتے، تو انہیں ان کے برے راستے اور ان کے اعمال کی برائی سے روکنا چاہیے تھا۔\n23. کیا میں ایک خدا ہوں، خداوند فرماتا ہے، اور دور خدا نہیں؟\n24۔ کیا کوئی خفیہ جگہوں پر چھپ سکتا ہے جہاں میں اسے نہ دیکھوں؟ خداوند فرماتا ہے۔ کیا میں آسمان اور زمین کو نہیں بھرتا؟ خداوند فرماتا ہے۔\n25۔ میں نے وہ سنا جو نبیوں نے کہا، کہ نبوت میرے نام پر ہے، کہ میں نے خواب دیکھا، میں نے خواب دیکھا۔\n26. یہ کب تک ان نبیوں کے دل میں رہے گا جو جھوٹ بولتے ہیں؟ ہاں، {وہ} اپنے دل کی فریب کے نبی ہیں؛\n27۔ جو سوچتے ہیں کہ میرے لوگ اپنے خوابوں سے میرا نام بھلا دیں گے جو وہ ہر آدمی کو اس کے پڑوسی کو بتاتے ہیں، جیسے ان کے باپ میرے نام کو بعل کے لیے بھول گئے ہیں۔\n28۔ جو نبی خواب دیکھتا ہے، وہ خواب سنائے؛ اور جس کے پاس میرا کلام ہے، وہ میرا کلام ایمانداری سے کہے۔ گندم کے مقابلے میں چاف کیا ہے؟ خداوند فرماتا ہے۔ {جس کا خواب ہے: عبرانی۔ کس کے ساتھ ہے، وغیرہ}\n29۔ {کیا} میرا لفظ آگ کی طرح نہیں ہے؟ خداوند فرماتا ہے؛ اور جیسے کوئی ہتھوڑا {جو} پتھر کو ٹکڑوں میں توڑ دے؟\n30۔ لہٰذا، دیکھو، میں انبیاء کے خلاف ہوں، خداوند فرماتا ہے، جو ہر ایک کو اپنے پڑوسی سے میرے کلام چرا لیتے ہیں۔\n31۔ دیکھو، میں انبیاء کے خلاف ہوں، خداوند فرماتا ہے، جو اپنی زبانیں استعمال کرتے ہیں اور کہتے ہیں، وہ فرماتا ہے۔ {وہ...: یا، جو ان کی زبانیں ہموار کرتا ہے}\n32۔ دیکھو، میں ان لوگوں کے خلاف ہوں جو جھوٹے خوابوں کی نبوت کرتے ہیں، خداوند فرماتا ہے، اور انہیں بتاتے ہیں، اور اپنی قوم کو ان کے جھوٹ اور ہلکے پن سے گمراہ کرتے ہیں؛ پھر بھی میں نے انہیں نہیں بھیجا اور نہ ہی حکم دیا: اس لیے وہ اس قوم کے کسی بھی فائدے کے نہیں ہوں گے، خداوند فرماتا ہے۔\n33۔ اور جب یہ لوگ، یا نبی، یا کوئی پادری، تم سے پوچھے گا، کہ خداوند کا بوجھ کیا ہے؟ تو پھر تم ان سے کہو گے، کون سا بوجھ؟ میں تمہیں چھوڑ بھی دوں گا، خداوند فرماتا ہے۔\n34۔ اور جہاں تک نبی اور پادری اور لوگوں کا تعلق ہے جو کہیں گے، خداوند کا بوجھ ہے، میں اس آدمی اور اس کے گھر کو بھی سزا دوں گا۔ {سزا: عبرانی۔ ملاحظہ کریں}\n35۔ یوں تم ہر ایک کو اپنے پڑوسی سے اور ہر ایک اپنے بھائی سے کہو۔ خداوند نے کیا جواب دیا ہے؟ اور، خداوند نے کیا کہا ہے؟\n36۔ اور خداوند کا بوجھ مزید ذکر نہ کرنا، کیونکہ ہر انسان کا کلام اس کا بوجھ ہوگا؛ کیونکہ تم نے زندہ خدا کے الفاظ کو بگاڑ دیا ہے، جو ہمارے خدا، لشکروں کے خداوند کا ہے۔\n37۔ یوں تم نبی سے کہو گے، خداوند نے تمہیں کیا جواب دیا؟ اور، خداوند نے کیا کہا ہے؟\n38۔ لیکن چونکہ آپ کہتے ہیں، خداوند کا بوجھ ہے؛ لہٰذا خداوند فرماتا ہے؛ کیونکہ تم یہ کلام کہتے ہو، خداوند کا بوجھ، اور میں نے تمہیں بھیجا ہے، کہتا ہوں، تم یہ نہیں کہو گے، خداوند کا بوجھ؛\n39۔ لہٰذا، دیکھو، میں، خود میں بھی، تمہیں مکمل طور پر بھول جاؤں گا، اور تمہیں اور اس شہر کو چھوڑ دوں گا جو میں نے تمہیں اور تمہارے باپ و اجداد کو دیا ہے، {اور تمہیں اپنی موجودگی سے نکال دوں گا}:\n40۔ اور میں تم پر ایک دائمی ملامت اور ایک دائمی شرمندگی لاؤں گا، جو کبھی نہیں بھولی جائے گی۔","1۔ خداوند نے مجھے دکھایا، اور دیکھو، دو انجیر کی ٹوکریاں خداوند کے مندر کے سامنے رکھی گئیں، جب کہ بابل کے بادشاہ نبوکدرز نے یہوداہ کے بادشاہ یہویاکیم کے بیٹے یکونیاہ اور یہوداہ کے شہزادوں کو یروشلم سے بڑھئیوں اور لوہاروں کے ساتھ قید کر کے بابل لے آیا۔\n2۔ ایک ٹوکری میں بہت اچھے انجیر تھے، {حتیٰ کہ} جیسے انجیر {جو پہلے پکے} تھے: اور دوسری ٹوکری میں {تھا} بہت شرارتی انجیر، جو کھایا نہیں جا سکتا تھا، وہ بہت خراب تھے۔ {وہ...: عبرانی۔ بردی کے لیے}\n3۔ پھر خداوند نے مجھ سے فرمایا، کیا دیکھا، یرمیاہ؟ اور میں نے کہا، انجیر؛ اچھے انجیر، بہت اچھے؛ اور وہ برائی، بہت برائی، جو نہیں کھائی جا سکتی، وہ بہت برے ہیں۔\n4. پھر خداوند کا کلام میرے پاس آیا، جس میں کہا گیا،\n5. یہی فرماتا ہے، خداوند اسرائیل کا خدا؛ ان اچھے انجیر کی طرح، میں ان کو بھی تسلیم کروں گا جو یہوداہ کے قید میں لے جایا گیا ہے، جنہیں میں نے اس جگہ سے کلدانیوں کی زمین میں بھیجا ہے {ان} بھلائی کے لیے۔ {وہ...: عبرانی۔ قید}\n6۔ کیونکہ میں انہیں اچھائی کے لیے دیکھوں گا، اور انہیں اس زمین پر واپس لاؤں گا: اور میں انہیں تعمیر کروں گا، نہ کہ انہیں گرا دوں گا؛ اور میں انہیں لگاؤں گا، نہ کہ توڑوں گا۔\n7۔ اور میں انہیں دل دوں گا کہ وہ مجھے جانیں، کہ میں خداوند ہوں: اور وہ میرے لوگ ہوں گے، اور میں ان کا خدا بنوں گا: کیونکہ وہ پورے دل سے میرے پاس واپس آئیں گے۔\n8۔ اور جیسے برے انجیر جو کھائے نہیں جا سکتے، وہ بہت برے ہیں؛ یقینا خداوند فرماتا ہے، تو میں یہوداہ کے بادشاہ سدقیاہ کو، اس کے شہزادوں، اور یروشلم کے باقیات کو جو اس سرزمین میں باقی ہیں، اور جو مصر کی سرزمین میں بستے ہیں، دوں گا:\n9۔ اور میں انہیں زمین کے تمام بادشاہتوں میں منتقل کر دوں گا کیونکہ ان کی تکلیف ہوگی، ملامت اور کہاوت، طعنہ اور لعنت بن جائے، ہر جگہ جہاں میں انہیں نکالوں گا۔ {ہٹانے کے لیے: عبرانی۔ یا پریشانی کو ختم کرنے کے لیے}\n10۔ اور میں تلوار، قحط اور وبا کو ان کے درمیان بھیجوں گا، یہاں تک کہ وہ اس زمین سے ختم ہو جائیں جو میں نے انہیں اور ان کے باپوں کو دی ہے۔","1۔ وہ کلام جو یرمیاہ کو یہوداہ کے تمام لوگوں کے بارے میں پہنچا، چوتھے سال میں یہویاکیم، یسوعیہ بادشاہ یوسیاہ کے بیٹے، میں، وہ {تھا} جو بابل کے بادشاہ نبوکدرز کا پہلا سال تھا؛\n2۔ وہ جو یرمیاہ نبی نے یہوداہ کے تمام لوگوں اور یروشلم کے تمام باشندوں سے کہا،\n3۔ یوشیا کے تیرہویں سال سے، جو یہوداہ کے بادشاہ آمون کا بیٹا تھا، آج تک، یعنی تیسویں اور بیسواں سال، خداوند کا کلام میرے پاس آیا ہے، اور میں نے تم سے بات کی ہے، صبح سویرے اٹھ کر بولتے ہوئے؛ لیکن تم نے سنا نہیں۔\n4۔ اور خداوند نے آپ کے پاس اپنے تمام بندوں کو نبی بھیجے ہیں، جو صبح سویرے اٹھ کر بھیجتے ہیں؛ لیکن تم نے نہ سنا ہے، نہ ہی اپنی کان سننے کی کوشش کی۔\n5۔ انہوں نے کہا، اب ہر ایک کو اس کے برے راستے سے اور اپنے اعمال کی برائی سے منہ موڑ لو، اور اس زمین میں رہو جو خداوند نے تمہیں اور تمہارے آباؤ اجداد کو ہمیشہ کے لیے دی ہے:\n6۔ اور دوسرے دیوتاؤں کے پیچھے نہ جاؤ کہ ان کی خدمت کرو اور ان کی عبادت کرو، اور مجھے اپنے ہاتھوں کے اعمال سے ناراض نہ کرو؛ اور میں تمہیں کوئی نقصان نہیں پہنچاؤں گا۔\n7. پھر بھی تم نے میری بات نہیں مانی، خداوند فرماتا ہے؛ تاکہ تم مجھے اپنے ہاتھوں کے کاموں سے غصہ دلا سکو۔\n8۔ لہٰذا لشکروں کے رب نے یوں فرمایا؛ کیونکہ تم نے میرے الفاظ نہیں سنے،\n9۔ دیکھو، میں شمال کے تمام خاندانوں کو بھیجوں گا اور لے جاؤں گا، خداوند فرماتا ہے، اور بابل کے بادشاہ نبوکدرز کو اپنے بندے کے خلاف لے آؤں گا اور انہیں اس زمین، اس کے باشندوں کے خلاف، اور ان تمام قوموں کے خلاف لاؤں گا اور انہیں مکمل طور پر تباہ کر دوں گا، اور انہیں حیران اور غصہ دوں گا،  اور ہمیشہ کی ویرانی بھی۔\n10۔ مزید برآں، میں ان سے خوشی کی آواز، خوشی کی آواز، دولہے کی آواز، دلہن کی آواز، چکی کے پتھروں کی آواز، اور موم بتی کی روشنی حاصل کروں گا۔ {میں کروں گا...: عبرانی۔ میں ان سے فنا ہو جاؤں گا}\n11۔ اور یہ پوری زمین ویرانی ہوگی، {اور} حیرت ہوگی؛ اور یہ قومیں بابل کے بادشاہ کی ستر سال خدمت کریں گی۔\n12۔ اور جب ستر سال مکمل ہو جائیں گے، میں بابل کے بادشاہ اور اس قوم کو سزا دوں گا، خداوند فرماتا ہے، ان کی بدکاری اور کلدانیوں کی زمین کو، اور اسے ہمیشہ کے لیے ویرانی بنا دوں گا۔ {سزا: عبرانی۔ ملاحظہ کریں}\n13۔ اور میں اس زمین پر اپنے تمام الفاظ لاؤں گا جو میں نے اس کے خلاف کہے ہیں، {حتیٰ کہ} اس کتاب میں جو کچھ بھی لکھا ہے، جو یرمیاہ نے تمام قوموں کے خلاف پیش گوئی کی ہے۔\n14۔ کیونکہ بہت سی قومیں اور عظیم بادشاہ بھی ان کی خدمت کریں گے: اور میں انہیں ان کے اعمال اور اپنے ہاتھوں کے کاموں کے مطابق بدلہ دوں گا۔\n15۔ کیونکہ یہی فرماتا ہے خداوند اسرائیل کا خدا؛ اس غصے کا شراب کا پیالہ میرے ہاتھ سے لے لو، اور ان تمام قوموں کو، جن کے پاس میں تمہیں بھیجتا ہوں، اسے پی لو۔\n16۔ اور وہ پیئیں گے، جذباتی ہوں گے، اور پاگل ہوں گے، اس تلوار کی وجہ سے جو میں ان کے درمیان بھیجوں گا۔\n17۔ پھر میں نے خداوند کے ہاتھ سے پیالہ لیا، اور تمام قوموں کو پانی پلایا، جن کے پاس خداوند نے مجھے بھیجا تھا:\n18۔ {یعنی} یروشلم، یہوداہ کے شہروں، اور ان کے بادشاہوں، اور اس کے بادشاہوں کو، انہیں ویرانی، حیرت، سرسراہٹ اور لعنت بنانے کے لیے؛ جیسا کہ آج ہے؛\n19۔ مصر کے بادشاہ فرعون، اس کے خادم، اس کے شہزادے، اور اس کے تمام لوگ؛\n20۔ اور تمام مخلوط لوگ، اور عوز کی زمین کے تمام بادشاہ، اور فلسطینیوں کی سرزمین کے تمام بادشاہ، اشکلون، عزا، عکرون، اور اشدود کے باقیات کے تمام بادشاہ،\n21۔ ایڈوم، موآب، اور آمون کے اولاد،\n22۔ اور ٹائرس کے تمام بادشاہ، اور زیدون کے تمام بادشاہ، اور ان جزائر کے بادشاہ جو سمندر کے پار ہیں، {جزیرے: یا، سمندر کے کنارے علاقہ}\n23. دیدان، اور تیما، اور بوز، اور سب {جو ہیں} سب سے کونے میں، {وہ...: عبرانی۔ کونوں میں کاٹ دیا جائے، یا بالوں کے کونوں کو الگ کر دیا جائے}\n24۔ اور عرب کے تمام بادشاہ، اور صحرا میں رہنے والے مخلوط قوم کے تمام بادشاہ،\n25۔ اور زمری کے تمام بادشاہ، اور ایلام کے تمام بادشاہ، اور میڈیس کے تمام بادشاہ،\n26۔ اور شمال کے تمام بادشاہ، دور اور قریب، ایک دوسرے کے ساتھ، اور دنیا کی تمام بادشاہتیں جو زمین پر ہیں: اور شیشاخ کا بادشاہ ان کے بعد پیے گا۔\n27۔ اسی لیے تم ان سے کہو گے، یہی فرماتا ہے لشکروں کا رب، اسرائیل کا خدا؛ پیو، اور نشے میں رہو، تھوک دو، گرج، اور دوبارہ نہ اٹھو، اس تلوار کی وجہ سے جو میں تمہارے درمیان بھیجوں گا۔\n28۔ اور اگر وہ تمہارے ہاتھ سے پیالہ لینے سے انکار کریں تو تم ان سے کہو گے، یہی فرماتا ہے رب لشکر؛ تم ضرور پیو گے۔\n29۔ کیونکہ دیکھو، میں اس شہر پر برائی لا رہا ہوں جسے میرے نام سے پکارا جاتا ہے، اور کیا تمہیں بالکل سزا نہیں ملنی چاہیے؟ تم بے سزا نہیں رہو گے: کیونکہ میں زمین کے تمام باشندوں پر تلوار کا مطالبہ کروں گا، لشکروں کے رب فرماتا ہے۔ {جو کہ...: عبرانی جس پر میرا نام پکارا جاتا ہے}\n30۔ لہٰذا ان سب کے خلاف یہ سب نبوت کرو اور ان سے کہو، خداوند اوپر سے دہاڑے گا، اور اپنی مقدس جگہ سے اپنی آواز نکلے گا؛ وہ اپنی رہائش گاہ پر زور سے دھاڑ مارے گا؛ وہ زمین کے تمام باشندوں کے خلاف نعرہ لگائے گا، جیسے وہ لوگ جو {انگور} کے قدموں پر چلتے ہیں۔\n31۔ ایک شور زمین کے کناروں تک پہنچے گا؛ کیونکہ خداوند قوموں کے ساتھ جھگڑا کرتا ہے، وہ تمام جسم سے دعا کرے گا؛ خداوند فرماتا ہے کہ وہ ان لوگوں کو جو تلوار کے ساتھ بدکار ہیں، دے گا۔\n32. یوں لشکروں کے رب فرماتا ہے، دیکھو، برائی قوم سے قوم تک پھیلے گی، اور زمین کے کنارے سے ایک بڑا طوفان اٹھے گا۔\n33۔ اور خداوند کا قتل اس دن زمین کے {ایک} سرے سے زمین کے دوسرے سرے تک ہوگا: انہیں نہ ماتم کیا جائے گا، نہ جمع کیا جائے گا، نہ دفن کیا جائے گا؛ وہ زمین پر گوبر ڈال دیے جائیں گے۔\n34۔ اے چرواہوں کو چیخنا اور چیخنا؛ اور اپنے آپ کو راکھ میں ڈوبو، اے ریوڑ کے اصول: کیونکہ تمہارے قتل اور انتشار کے دن مکمل ہو چکے ہیں؛ اور تم ایک خوشگوار برتن کی طرح گر جاؤ گے۔ {دن...: عبرانی۔ تمہارے قتل کے دن} {ایک خوشگوار...: عبرانی خواہش کا برتن}\n35۔ اور چرواہوں کے پاس بھاگنے کا کوئی راستہ نہیں ہوگا، نہ ہی ریوڑ کا اصل بچ نکلنے کا۔ {چرواہے...: عبرانی۔ چرواہوں سے فرار ختم ہو جائے گا، اور فرار ہو جائے گا، وغیرہ}\n36۔ چرواہوں کی پکار کی آواز، اور ریوڑ کے سردار کی چیخ، {سنی جائے گی}: کیونکہ خداوند نے ان کی چراگاہ خراب کر دی ہے۔\n37۔ اور پرامن رہائش گاہیں خداوند کے شدید غضب کی وجہ سے ختم ہو جاتی ہیں۔\n38۔ اس نے شیر کی طرح اپنی چھپائی چھوڑ دی ہے: کیونکہ ان کی زمین ظالم کی شدت اور شدید غصے کی وجہ سے ویران ہے۔ {ویران آواز: عبرانی۔ ایک ویرانی}","1۔ یہویاکیم، یہوداہ کے بادشاہ یوشیا کے بیٹے کی بادشاہت کے آغاز میں خداوند کی طرف سے یہ کلام آیا، جس میں کہا گیا،\n2۔ خداوند یوں فرماتا ہے؛ خداوند کے گھر کے صحن میں کھڑے ہو جاؤ، اور یہوداہ کے تمام شہروں سے، جو خداوند کے گھر میں عبادت کے لیے آتے ہیں، وہ تمام الفاظ کہو جو میں تمہیں ان سے کہنے کا حکم دیتا ہوں؛ ایک لفظ بھی کم نہ کریں:\n3۔ اگر ایسا ہوا تو وہ سنیں گے، اور ہر انسان کو اس کے برے راستے سے روکیں گے، تاکہ میں اس برائی سے توبہ کر سکوں جو میں ان کے اعمال کی برائیوں کی وجہ سے ان کے ساتھ کرنے کا ارادہ رکھتا ہوں۔\n4۔ اور تم ان سے کہو گے، خداوند یہ فرماتا ہے؛ اگر تم میری بات نہیں سنو گے، تو میرے قانون کے مطابق چلو جو میں نے تمہارے سامنے رکھا ہے،\n5۔ اپنے بندوں کے انبیاء کی باتیں سننے کے لیے، جنہیں میں نے آپ کے پاس بھیجا تھا، دونوں صبح سویرے اٹھ کر بھیجے، لیکن آپ نے نہیں سنا؛\n6۔ پھر میں اس گھر کو شیلوہ کی طرح بنا دوں گا، اور اس شہر کو زمین کی تمام قوموں کے لیے لعنت بنا دوں گا۔\n7۔ تو کاہنوں، انبیاء اور سب لوگوں نے یرمیاہ کو خداوند کے گھر میں یہ الفاظ کہتے سنا۔\n8۔ اب ایسا ہوا جب یرمیاہ نے وہ سب کچھ بولنا بند کر دیا جو خداوند نے سب لوگوں سے کہنے کا حکم دیا تھا، کہ کاہنوں، نبیوں اور سب لوگوں نے اسے لے لیا اور کہا، تم ضرور مر جاؤ گے۔\n9۔ تم نے خداوند کے نام پر نبوت کیوں کی، کہ یہ گھر شیلوہ کی طرح ہوگا، اور یہ شہر بغیر کسی باشندے کے ویران ہو جائے گا؟ اور تمام لوگ یرمیاہ کے خلاف خداوند کے گھر میں جمع ہو گئے۔\n10۔ جب یہوداہ کے شہزادوں نے یہ باتیں سنیں، تو وہ بادشاہ کے گھر سے خداوند کے گھر آئے اور خداوند کے نئے دروازے کے دروازے پر بیٹھ گئے۔ {دروازے پر...: یا، دروازے پر}\n11۔ پھر کاہنوں اور نبیوں نے شہزادوں اور تمام لوگوں سے کہا، یہ آدمی مرنے کے لائق ہے؛ کیونکہ اس نے اس شہر کے خلاف پیش گوئی کی ہے، جیسا کہ تم نے اپنے کانوں سے سنا ہے۔ {یہ آدمی...: عبرانی۔ موت کا فیصلہ اس آدمی کے لیے ہے}\n12۔ پھر یرمیاہ نے تمام شہزادوں اور سب لوگوں سے کہا، \"خداوند نے مجھے بھیجا ہے تاکہ اس گھر اور اس شہر کے خلاف وہ تمام الفاظ پیش گوئی کروں جو تم نے سنے ہیں۔\n13۔ لہٰذا اب اپنے طریقے اور اعمال درست کرو، اور خداوند تمہارے خدا کی آواز کی اطاعت کرو؛ اور خداوند اسے اس برائی سے توبہ کرے گا جو اس نے تمہارے خلاف کی ہے۔\n14۔ جہاں تک میرا تعلق ہے، دیکھو، میں تمہارے ہاتھ میں ہوں: میرے ساتھ جیسا اچھا لگے وہ کرو اور تم سے ملوں۔ {یعنی...: عبرانی کیونکہ یہ آپ کی نظر میں اچھا اور درست ہے}\n15۔ لیکن تم یقین رکھو کہ اگر تم مجھے مار دو گے تو تم اپنے اوپر، اس شہر پر، اور اس کے باشندوں پر معصوم خون لاؤ گے، کیونکہ سچ میں خداوند نے مجھے تمہارے پاس بھیجا ہے تاکہ یہ سب باتیں تمہارے کانوں میں کہہ سکوں۔\n16۔ پھر شہزادوں اور تمام لوگوں نے کاہنوں اور نبیوں سے کہا؛ یہ آدمی مرنے کے لائق نہیں: کیونکہ اس نے ہم سے خداوند ہمارے خدا کے نام پر بات کی ہے۔\n17۔ پھر ملک کے کچھ بزرگوں نے کھڑے ہو کر سب لوگوں کی جماعت سے کہا،\n18. میکاہ موراستی نے یہوداہ کے بادشاہ حزقیاہ کے زمانے میں پیش گوئی کی اور یہوداہ کے تمام لوگوں سے کہا، \"یہی فرماتا ہے رب لشکر؛ صیون کو کھیت کی طرح جوتا جائے گا، اور یروشلم ڈھیر بن جائے گا، اور گھر کا پہاڑ جنگل کی اونچی جگہوں کی طرح ہوگا۔\n19۔ کیا یہوداہ اور تمام یہوداہ کے بادشاہ حزقیاہ نے اسے قتل کر دیا؟ کیا اس نے خداوند سے نہیں ڈرا، اور خداوند سے دعا نہیں کی، اور خداوند نے اس برائی سے توبہ کی جو اس نے ان کے خلاف کی تھی؟ اسی طرح ہم اپنی روحوں کے خلاف بڑی برائی حاصل کر سکتے ہیں۔ {خداوند، اور: عبرانی خداوند کا چہرہ، وغیرہ}\n20۔ اور ایک شخص بھی تھا جس نے خداوند کے نام سے نبوت کی تھی، یوریاہ جو شمعیہ کا بیٹا کیرجاتجاریم تھا، جس نے یرمیاہ کے تمام الفاظ کے مطابق اس شہر اور اس زمین کے خلاف نبوت کی:\n21۔ اور جب یہویاکیم بادشاہ، اپنے تمام طاقتور آدمیوں اور تمام شہزادوں کے ساتھ، اس کے الفاظ سنے، تو بادشاہ نے اسے قتل کرنے کی کوشش کی، لیکن جب یوریاہ نے یہ سنا تو وہ ڈر گیا، بھاگ گیا اور مصر میں چلا گیا؛\n22۔ اور یہویاکیم بادشاہ نے مصر میں آدمیوں کو بھیجا، {یعنی} الناتھن ابن اخبور، اور {کچھ لوگ} اس کے ساتھ مصر بھیجے۔\n23۔ اور انہوں نے یوریاہ کو مصر سے نکالا اور اسے یہویاقیم بادشاہ کے پاس لے گئے؛ جس نے اسے تلوار سے مارا اور اس کی لاش عام لوگوں کی قبروں میں پھینک دی۔ {عام...: عبرانی۔ سنز آف دی پیپل}\n24۔ پھر بھی، شافان کے بیٹے احیکم کا ہاتھ یرمیاہ کے پاس تھا، تاکہ اسے لوگوں کے ہاتھ میں نہ دے کر اسے قتل کر دیں۔","1۔ یہویاکیم، یہوداہ کے بادشاہ یوسیاہ کے بیٹے کی بادشاہت کے آغاز میں یرمیاہ کو خداوند کی طرف سے یہ پیغام آیا، جس میں کہا گیا،\n2۔ خداوند مجھ سے یوں فرماتا ہے؛ اپنے بندھن اور جوتے بنو، اور انہیں اپنی گردن پر باندھو، {فرماتا ہے...: یا، خداوند نے فرمایا}\n3۔ اور انہیں ادوم کے بادشاہ، موآب کے بادشاہ، عمونیوں کے بادشاہ، اور تیروس کے بادشاہ کو، اور زیدون کے بادشاہ کے پاس بھیجو، ان رسولوں کے ہاتھوں جو یروشلم آتے ہیں، زدقیاہ بادشاہ یہوداہ کے پاس بھیجو؛\n4۔ اور انہیں حکم دو کہ وہ اپنے آقاؤں سے کہیں، یہی فرماتا ہے لشکروں کا رب، اسرائیل کا خدا؛ اسی طرح تم اپنے آقاؤں سے کہو گے؛ {کہنے کے لیے...: یا، اپنے آقاؤں کے بارے میں، کہنا}\n5. میں نے زمین، وہ انسان اور جانور جو زمین پر ہیں، اپنی عظیم طاقت اور اپنے پھیلائے ہوئے بازو سے بنایا ہے، اور اسے دیا ہے جسے وہ مجھے ملتا لگا۔\n6۔ اور اب میں نے یہ تمام زمینیں بابل کے بادشاہ نبوکدنضر کے ہاتھ میں دے دی ہیں، جو میرا خادم ہے؛ اور میدان کے جانوروں کو بھی میں نے اسے اس کی خدمت کے لیے دیا ہے۔\n7۔ اور تمام قومیں اس کی اور اس کے بیٹے اور اس کے بیٹے کی خدمت کریں گی، یہاں تک کہ اس کی سرزمین کا وقت آ جائے: اور پھر بہت سی قومیں اور عظیم بادشاہ اس کی خدمت کریں گے۔\n8۔ اور یہ ہو جائے گا کہ وہ قوم اور بادشاہت جو اسی نبوکدنضر بابل کے بادشاہ کی خدمت نہیں کرے گی، اور جو اپنی گردن بابل کے بادشاہ کے جوے کے نیچے نہیں ڈالے گی، اس قوم کو میں سزا دوں گا، خداوند فرماتا ہے، تلوار سے، قحط سے، اور وبا سے،  جب تک میں انہیں اس کے ہاتھ سے نگل نہ لوں۔\n9۔ لہٰذا اپنے نبیوں، غیب گوؤں، خواب دیکھنے والوں، جادوگروں، جادوگروں کی بات نہ سنو، جو تم سے بات کرتے ہیں، کہ تم بابل کے بادشاہ کی خدمت نہیں کرو گے: {خواب دیکھنے والے: عبرانی۔ خواب}\n10۔ کیونکہ وہ تم سے جھوٹ بولتے ہیں، تاکہ تمہیں تمہاری سرزمین سے دور لے جایا جائے؛ اور کہ میں تمہیں نکال دوں، اور تم مر جاؤ گے۔\n11۔ لیکن وہ قومیں جو بابل کے بادشاہ کے جوڑے میں اپنی گردن لگا کر اس کی خدمت کرتی ہیں، انہیں میں ان کی اپنی زمین میں ساکت چھوڑ دوں گا، خداوند فرماتا ہے؛ اور وہ اسے جوتیں گے، اور اس میں رہیں گے۔\n12۔ میں نے یہوداہ کے بادشاہ زدقیاہ سے بھی ان تمام الفاظ کے مطابق کہا، \"اپنی گردنیں بابل کے بادشاہ کے جولے کے نیچے لے آؤ، اس کی اور اس کی قوم کی خدمت کرو اور زندہ رہو۔\n13. تم اور تمہارے لوگ تلوار سے، قحط اور وبا سے کیوں مرو گے، جیسا کہ خداوند نے اس قوم کے خلاف کہا ہے جو بابل کے بادشاہ کی خدمت نہیں کرتی؟\n14۔ لہٰذا ان نبیوں کی باتوں کو نہ سنو جو تم سے بات کرتے ہیں، کہ تم بابل کے بادشاہ کی خدمت نہیں کرو گے، کیونکہ وہ تم سے جھوٹ بولتے ہیں۔\n15۔ کیونکہ میں نے انہیں نہیں بھیجا، خداوند فرماتا ہے، پھر بھی وہ میرے نام پر جھوٹ کی پیش گوئی کرتے ہیں؛ تاکہ میں تمہیں نکال دوں، اور تم اور وہ نبی جو تمہیں نبوت کرتے ہیں، ہلاک ہو جاؤ۔ {ایک جھوٹ: عبوری۔ جھوٹ میں، یا جھوٹ میں}\n16۔ میں نے کاہنوں اور اس سب قوم سے کہا، خداوند نے ایسا فرمایا؛ اپنے نبیوں کی باتوں کو نہ سنو جو تمہیں پیش گوئی کرتے ہیں، کہتے ہیں، دیکھو، خداوند کے گھر کے برتن جلد ہی بابل سے واپس لائے جائیں گے: کیونکہ وہ تم سے جھوٹ کی پیش گوئی کرتے ہیں۔\n17۔ ان کی بات نہ سنو؛ بابل کے بادشاہ کی خدمت کرو، اور زندہ رہو: یہ شہر کیوں تباہ ہو جائے؟\n18۔ لیکن اگر وہ نبی ہیں، اور اگر خداوند کا کلام ان کے ساتھ ہے، تو اب وہ خداوند لشکروں کے سامنے شفاعت کریں، کہ خداوند کے گھر اور یہوداہ کے بادشاہ کے گھر، اور یروشلم میں جو برتن باقی ہیں، وہ بابل نہ جائیں۔\n19۔ کیونکہ لشکروں کے رب نے ستونوں، سمندر کے بارے میں، بنیادوں کے بارے میں، اور اس شہر میں باقی ماندہ برتنوں کے باقیات کے بارے میں یوں فرمایا،\n20۔ جسے بابل کے بادشاہ نبوکدنصر نے قبول نہیں کیا، جب اس نے یہوداہ کے بادشاہ یہویاکیم کے بیٹے جیکونیا کو یروشلم سے بابل قید کر لیا، اور یہوداہ و یروشلم کے تمام اشرافیہ کو قید کر لیا؛\n21. جی ہاں، یہ فرماتا ہے لشکروں کے رب، اسرائیل کے خدا، ان برتنوں کے بارے میں جو خداوند کے گھر میں اور یہوداہ اور یروشلم کے بادشاہ کے گھر میں باقی ہیں؛\n22. انہیں بابل لے جایا جائے گا، اور وہ وہاں رہیں گے جب تک میں ان سے ملنے نہ جاؤں، خداوند فرماتا ہے؛ پھر میں انہیں اوپر لے آؤں گا، اور اسے اس جگہ واپس لاؤں گا۔","1۔ اور اسی سال، یہوداہ کے بادشاہ صدقیہ کی حکومت کے آغاز میں، چوتھے سال میں، اور پانچویں مہینے میں، {کہ} حنانیاہ عزور کے نبی کے بیٹے، جو {گبعون} کا تھا، نے خداوند کے گھر میں، کاہنوں اور تمام لوگوں کی موجودگی میں مجھ سے کہا،  کہتا ہے،\n2. یوں لشکروں کے رب، اسرائیل کے خدا فرماتے ہیں، میں نے بابل کے بادشاہ کا جوا توڑ دیا ہے۔\n3۔ دو پورے سال کے اندر میں خداوند کے گھر کے تمام برتن دوبارہ اس جگہ لے آؤں گا، جنہیں بابل کے بادشاہ نبوکدنضر نے یہاں سے لے کر بابل لے جایا تھا: {دو...: عبرانی۔ دو سال کے دن}\n4۔ اور میں یہوداہ کے یہوداہ کے بادشاہ یہویاکیم کے بیٹے یکونیاہ کو دوبارہ اس جگہ لے آؤں گا، اور یہوداہ کے تمام قیدیوں کے ساتھ، جو بابل میں گئے، خداوند فرماتا ہے: کیونکہ میں بابل کے بادشاہ کا جوا توڑ دوں گا۔ {قیدی: عبرانی۔ قید}\n5۔ پھر نبی یرمیاہ نے نبی حنانیاہ سے کہا، کاہنوں کی موجودگی میں، اور خداوند کے گھر میں کھڑے تمام لوگوں کی موجودگی میں،\n6۔ حتیٰ کہ نبی یرمیاہ نے کہا، آمین: خداوند ایسا فرما: خداوند اپنے وہ الفاظ پورا کرے جو تم نے پیش گوئی کی ہیں، تاکہ خداوند کے گھر کے برتن اور جو بھی قید کیا گیا ہے، اسے بابل سے اس جگہ واپس لے آؤ۔\n7۔ پھر بھی اب یہ لفظ سنو جو میں تمہارے کانوں میں اور تمام لوگوں کے کانوں میں کہتا ہوں؛\n8۔ وہ نبی جو میرے اور تم سے پہلے قدیم تھے، نے کئی ملکوں، عظیم سلطنتوں، جنگ، برائی، اور وبا کے خلاف نبوت کی ہے۔\n9۔ وہ نبی جو امن کی پیش گوئی کرتا ہے، جب نبی کا کلام پورا ہوگا، {تب} نبی کو معلوم ہوگا کہ خداوند نے واقعی اسے بھیجا ہے۔\n10۔ پھر حنانیاہ نبی نے نبی یرمیاہ کی گردن سے جوا اتار کر توڑ دیا۔\n11۔ اور حنانیاہ نے سب لوگوں کے حضور فرمایا، خداوند نے ایسا فرمایا؛ اسی طرح میں بابل کے بادشاہ نبوکدنصر کا جوا تمام قوموں کی گردن سے دو سال کے اندر توڑ دوں گا۔ اور نبی یرمیاہ نے اپنی راہ چلائی۔\n12۔ پھر خداوند کا کلام یرمیاہ {نبی} تک پہنچا، جس کے بعد حنانیاہ نبی نے نبی یرمیاہ کی گردن سے جوا توڑ دیا اور کہا،\n13۔ جاؤ اور حنانیاہ کو بتاؤ، کہو، خداوند یہ فرماتا ہے؛ تو نے لکڑی کے جوتے توڑے؛ لیکن تم ان کے لیے لوہے کے جولے بناؤ گے۔\n14۔ کیونکہ لشکروں کا رب، اسرائیل کا خدا یہی فرماتا ہے؛ میں نے ان تمام قوموں کی گردن پر لوہے کا جوا لگا دیا ہے تاکہ وہ بابل کے بادشاہ نبوکدنصر کی خدمت کر سکیں؛ اور وہ اس کی خدمت کریں گے: اور میں نے اسے میدان کے جانور بھی دیے ہیں۔\n15۔ پھر نبی یرمیاہ نے حنانیاہ نبی سے کہا، اب سنو، حنانیا؛ خداوند نے تمہیں نہیں بھیجا؛ لیکن تم اس قوم کو جھوٹ پر بھروسہ کرنے پر مجبور کرتے ہو۔\n16۔ لہٰذا خداوند فرماتا ہے؛ دیکھو، میں تمہیں زمین سے نکال دوں گا: اس سال تم مر جاؤ گے، کیونکہ تم نے خداوند کے خلاف بغاوت سکھائی ہے۔ {بغاوت: عبرانی۔ بغاوت}\n17۔ تو حنانیاہ نبی اسی سال ساتویں مہینے میں وفات پا گئے۔","1۔ اب یہ وہ الفاظ ہیں جو یرمیاہ نبی نے یروشلم سے بزرگوں کی باقیات کے لیے بھیجے جو قیدیوں میں لے جایا گیا تھا، اور کاہنوں، انبیاء کو، اور ان تمام لوگوں کے لیے جنہیں نبوکدنصر نے یروشلم سے بابل قید کیا تھا؛\n2۔ (اس کے بعد یقونیاہ بادشاہ، ملکہ، خواجہ سرا صاحب، یہوداہ اور یروشلم کے شہزادے، بڑھئی اور لوہار یروشلم سے روانہ ہو گئے؛) {خواجہ سرا: یا، چیمبرلین}\n3۔ شافان کے بیٹے ایلاساہ، اور ہلکیا کے بیٹے جماریاہ کے ہاتھوں (جسے یہوداہ کے بادشاہ زدقیاہ نے بابل بھیجا اور بابل کے بادشاہ نبوکدنصر کے پاس بھیجا) کہا،\n4. یوں فرماتا ہے لشکروں کے رب، اسرائیل کا خدا، ان سب قیدیوں کو جنہیں میں نے یروشلم سے بابل لے جایا ہے؛\n5. گھر بناؤ، اور ان میں رہو؛ اور باغات لگائیں، اور ان کے پھل کھائیں؛\n6۔ بیویاں لو، اور بیٹے اور بیٹیاں پیدا کرو؛ اور اپنے بیٹوں کے لیے بیویاں لو، اور اپنی بیٹیوں کو شوہروں کو دے دو تاکہ وہ بیٹے اور بیٹیاں پیدا کر سکیں؛ تاکہ تم وہاں بڑھ جاؤ، نہ کہ کم کیے جاؤ۔\n7۔ اور اس شہر کی امن کی تلاش کرو جہاں میں نے تمہیں قیدی بنا کر لے جایا ہے، اور اس کے لیے خداوند سے دعا کرو: کیونکہ اس میں سکون ملے گا۔\n8۔ کیونکہ ایسا فرماتا ہے لشکروں کے رب، اسرائیل کے خدا؛ تمہارے نبی اور غیب گو، جو تمہارے درمیان ہیں، تمہیں دھوکہ نہ دیں، نہ تمہارے خوابوں کو سنیں جنہیں تم خواب دیکھتے ہو۔\n9۔ کیونکہ وہ میرے نام پر جھوٹی نبوت کرتے ہیں: میں نے انہیں نہیں بھیجا، خداوند فرماتا ہے۔ {غلط طور پر: عبوری۔ جھوٹ میں}\n10۔ کیونکہ خداوند یوں فرماتا ہے، کہ بابل میں ستر سال مکمل ہونے کے بعد میں تم سے ملوں گا، اور تمہارے لیے اپنی نیک دعا ادا کروں گا، تاکہ تمہیں اس جگہ واپس لے جاؤں۔\n11. کیونکہ میں جانتا ہوں کہ میں آپ کے بارے میں جو خیالات رکھتا ہوں، خداوند فرماتا ہے، امن کے خیالات ہیں، نہ کہ برائی کے، تاکہ آپ کو متوقع انجام دیا جا سکے۔ {متوقع...: عبرانی۔ اختتام اور توقع}\n12۔ پھر تم مجھے پکارو گے، اور جاؤ گے اور مجھ سے دعا کرو گے، اور میں تمہاری بات سنوں گا۔\n13۔ اور تم مجھے تلاش کرو گے، اور مجھے پاؤ گے، جب تم پورے دل سے مجھے تلاش کرو گے۔\n14۔ اور میں تم سے پایا جاؤں گا، خداوند فرماتا ہے: اور میں تمہاری قید کو دور کر دوں گا، اور تمہیں تمام قوموں اور ہر جگہ سے جمع کروں گا جہاں میں نے تمہیں نکالا ہے، خداوند فرماتا ہے؛ اور میں تمہیں دوبارہ اس جگہ لے جاؤں گا جہاں سے میں نے تمہیں قید میں لے جایا تھا۔\n15. کیونکہ تم نے کہا ہے، خداوند نے ہمیں بابل میں نبیوں کو زندہ کیا؛\n16. {جان لو} کہ اس بادشاہ کے رب جو داؤد کے تخت پر بیٹھا ہے، اور اس شہر میں بسنے والے تمام لوگوں کے بارے میں، {اور} تمہارے بھائیوں کا جو تمہارے ساتھ قید میں نہیں گئے، یہ فرماتا ہے؛\n17۔ ایسا فرماتا ہے رب لشکر؛ دیکھو، میں ان پر تلوار، قحط اور وبا بھیجوں گا، اور انہیں گندے انجیر کی طرح بنا دوں گا، جو کھائے نہیں جا سکتے، وہ بہت برے ہیں۔\n18۔ اور میں انہیں تلوار، قحط اور وبا سے ستاوں گا، اور انہیں زمین کی تمام سلطنتوں میں منتقل کر دوں گا، تاکہ وہ ان تمام قوموں میں لعنت، حیرت، اور سرسراہٹ اور ملامت بن جائیں جہاں میں نے انہیں نکالا ہے: {لعنت بننے کے لیے:  عبرانی۔ ایک لعنت کے لیے}\n19۔ کیونکہ انہوں نے میرے الفاظ نہیں سنے، خداوند فرماتا ہے، جو میں نے اپنے بندوں کے ذریعے ان کے لیے بھیجا ہے، نبیوں نے، صبح اٹھ کر انہیں بھیجا؛ لیکن تم سننا نہیں چاہتے، خداوند فرماتا ہے۔\n20. لہٰذا خداوند کا کلام سنو، اے سب قید والوں، جنہیں میں نے یروشلم سے بابل بھیجا ہے:\n21. یوں فرماتا ہے لشکروں کے رب، اسرائیل کا خدا، کلایاہ کا بیٹا اہاب، اور ماسیہ کے بیٹے زدقیاہ کا، جو میرے نام پر تم سے جھوٹ کی پیش گوئی کرتے ہیں؛ دیکھو، میں انہیں بابل کے بادشاہ نبوکدرز کے ہاتھ میں دوں گا؛ اور وہ انہیں تمہاری آنکھوں کے سامنے مار ڈالے گا؛\n22۔ اور ان میں سے یہوداہ کی تمام قید کی لعنت اٹھائی جائے گی جو بابل میں ہیں، اور کہا جائے گا، خداوند تمہیں زدیقیاہ کی مانند اور اخاب جیسا بنا دے، جسے بابل کے بادشاہ نے آگ میں بھنا تھا؛\n23۔ کیونکہ انہوں نے اسرائیل میں بدعنوانی کی، اپنے پڑوسیوں کی بیویوں کے ساتھ کیا، اور میرے نام پر جھوٹ بولے جو میں نے انہیں حکم نہیں دیا؛ یہاں تک کہ میں بھی جانتا ہوں، اور {میں} گواہ ہوں، خداوند فرماتا ہے۔\n24. {یوں} تم شمعیاہ نحلمی سے بھی بات کرو گے، کہو، {نحلامی: یا، خواب دیکھنے والا}\n25۔ یوں لشکروں کے رب، اسرائیل کے خدا نے فرمایا، کیونکہ تو نے اپنے نام پر یروشلم میں موجود تمام لوگوں کو، اور عسیعیاہ کے بیٹے زفانیاہ کو اور تمام کاہنوں کو خطوط بھیجے ہیں،\n26۔ خداوند نے تمہیں یہوعیادا کاہن کی جگہ پادری بنایا ہے، تاکہ تم خداوند کے گھر میں افسر بنو، کیونکہ ہر پاگل شخص اور خود کو نبی بناتا ہے، تاکہ تم اسے قید اور محفظے میں ڈال دو۔\n27۔ تو پھر تم نے انتھوت کے یرمیاہ کو کیوں نہیں ڈانٹا، جو خود کو تمہارے لیے نبی بناتا ہے؟\n28۔ اسی لیے اس نے ہمیں بابل میں بھیجا، کہا، یہ قید طویل ہے: گھر بناؤ اور ان میں رہو؛ اور باغات لگاتے ہیں اور ان کے پھل کھاتے ہیں۔\n29۔ اور زفانیاہ کاهن نے یہ خط یرمیاہ نبی کے کانوں میں پڑھا۔\n30۔ پھر خداوند کا کلام یرمیاہ کو آیا، جس میں کہا،\n31۔ قید میں موجود سب کو بھیج دو اور کہو، خداوند نے شمعیہ نحلمی کے بارے میں یہی فرمایا؛ کیونکہ اس شمعیہ نے تم سے پیش گوئی کی ہے، اور میں نے اسے نہیں بھیجا، اور اس نے تمہیں جھوٹ پر بھروسہ کروایا:\n32۔ لہٰذا خداوند فرماتا ہے؛ دیکھو، میں شمعیاہ نحلمی اور اس کی نسل کو سزا دوں گا: اس کے پاس اس قوم میں رہنے کے لیے کوئی آدمی نہیں ہوگا؛ نہ ہی وہ وہ نیکی دیکھے گا جو میں اپنے لوگوں کے لیے کروں گا، خداوند فرماتا ہے؛ کیونکہ اس نے خداوند کے خلاف بغاوت سکھائی ہے۔ {بغاوت: عبرانی۔ بغاوت}","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، اور کہا،\n2۔ یوں اسرائیل کے خداوند خدا فرماتے ہیں، کہتی ہیں: وہ تمام الفاظ جو میں نے تم سے کہے ہیں، وہ سب کتاب میں لکھو۔\n3۔ خداوند فرماتا ہے، دیکھو، دن آتے ہیں کہ میں اپنے قوم اسرائیل اور یہوداہ کی قید کو دوبارہ لاؤں گا، خداوند فرماتا ہے: اور میں انہیں اس زمین میں واپس لے آؤں گا جو میں نے ان کے باپوں کو دی تھی، اور وہ اس پر قبضہ کریں گے۔\n4۔ اور یہ وہ الفاظ ہیں جو خداوند نے اسرائیل اور یہوداہ کے بارے میں کہے۔\n5۔ کیونکہ خداوند یہ فرماتا ہے؛ ہم نے ایک لرزتی ہوئی آواز سنی ہے، خوف کی، اور امن کی نہیں۔ {خوف کا...: یا، خوف ہے، امن نہیں}\n6۔ اب پوچھو اور دیکھو کیا آدمی بچے کے ساتھ تکلیف اٹھاتا ہے؟ کیوں میں ہر مرد کو اپنے ہاتھ کمر پر دیکھتا ہوں، ایک عورت کی طرح جو مصیبت میں ہے، اور تمام چہرے سفید پڑ جاتے ہیں؟ {ایک آدمی: عبرانی۔ ایک مرد}\n7. افسوس! کیونکہ وہ دن {ہے} عظیم ہے، تاکہ کوئی {نہیں} جیسا ہو: یہ {ہے} یہاں تک کہ یعقوب کی مصیبت کا وقت بھی؛ لیکن وہ اس سے بچایا جائے گا۔\n8۔ کیونکہ اسی دن ہو جائے گا، لشکروں کے رب فرماتا ہے، {کہ} میں اس کا جوا تمہاری گردن سے توڑ دوں گا، اور تمہاری بندھن توڑ دوں گا، اور اجنبی اس کی خدمت نہیں کریں گے:\n9۔ لیکن وہ خداوند اپنے خدا کی عبادت کریں گے، اور اپنے بادشاہ داؤد کی بھی، جسے میں ان کے پاس اٹھاؤں گا۔\n10۔ لہٰذا اے میرے بندے یعقوب، خوفزدہ نہ ہو، خداوند فرماتا ہے؛ اے اسرائیل، ڈر نہ جانا، کیونکہ دیکھو، میں تمہیں دور سے اور تیری نسل کو ان کی قید کی سرزمین سے بچاؤں گا؛ اور یعقوب واپس آئے گا، آرام کرے گا، خاموش رہے گا، اور کوئی اسے خوفزدہ نہیں کرے گا۔\n11۔ کیونکہ میں تمہارے ساتھ ہوں، خداوند فرماتا ہے، تاکہ تمہیں بچا سکوں: اگرچہ میں ان تمام قوموں کا خاتمہ کر دوں جہاں میں نے تمہیں بکھیر دیا ہے، پھر بھی میں تمہیں مکمل طور پر ختم نہیں کروں گا: لیکن میں تمہیں درست کروں گا، اور تمہیں مکمل طور پر سزا سے محروم نہیں چھوڑوں گا۔\n12۔ کیونکہ خداوند یوں فرماتا ہے، تیرا زخم لاعلاج ہے، اور تیرا زخم شدید ہے۔\n13. کوئی نہیں جو تمہاری دلیل کا دفاع کرے، تاکہ تم جکڑ جاؤ: تمہارے پاس کوئی شفا بخش دوا نہیں۔ {وہ...: عببرانی۔ باندھنے کے لیے، یا، دباؤ ڈالنے کے لیے}\n14. تمہارے تمام عاشق تمہیں بھول گئے ہیں؛ وہ تمہیں تلاش نہیں کرتے؛ کیونکہ میں نے تمہیں دشمن کے زخم سے زخمی کیا ہے، ظالم کی سزا سے، تیری بے گناهی کی کثرت کے لیے؛ {کیونکہ} تمہارے گناہ بڑھ گئے۔\n15۔ تم اپنی تکلیف پر کیوں پکار رہے ہو؟ تمہارا غم تمہارے گناہوں کی کثرت کے لیے لاعلاج ہے: {کیونکہ} کہ تمہارے گناہ بڑھ گئے، میں نے یہ سب تمہارے ساتھ کیا۔\n16۔ لہٰذا جو تمہیں کھا جائے گا وہ سب نگل جائیں گے؛ اور تمہارے تمام دشمن، ان میں سے ہر ایک، قید میں چلے جائیں گے؛ اور جو تمہیں بگاڑیں گے وہ مال لوٹ جائیں گے، اور جو بھی تم پر حملہ کرے گا وہ میں شکار کے بدلے دوں گا۔\n17۔ کیونکہ میں تمہیں صحت بخشوں گا، اور تمہارے زخموں سے شفا دوں گا، خداوند فرماتا ہے؛ کیونکہ انہوں نے تمہیں بے گھر کہا، {کہا}، یہ {ہے} صیون ہے، جس کی کوئی تلاش نہیں کرتا۔\n18۔ خداوند فرماتا ہے؛ دیکھو، میں یعقوب کے خیموں کی قید دوبارہ لاؤں گا، اور اس کے گھروں پر رحم کروں گا؛ اور شہر اس کے اپنے ڈھیر پر تعمیر کیا جائے گا، اور محل اسی طرح قائم رہے گا۔ {ہیپ: یا، لٹل ہل}\n19۔ اور ان میں سے شکرگزاری اور خوش ہونے والوں کی آواز نکلے گی: اور میں انہیں بڑھاؤں گا، اور وہ کم نہیں ہوں گے؛ میں انہیں بھی جلال بخشوں گا، اور وہ چھوٹے نہیں ہوں گے۔\n20۔ ان کے بچے بھی پہلے کی طرح ہوں گے، اور ان کی جماعت میرے سامنے قائم ہوگی، اور میں ان سب کو سزا دوں گا جو ان پر ظلم کریں گے۔\n21۔ اور ان کے اشرافیہ خود سے ہوں گے، اور ان کا گورنر ان کے درمیان سے نکلے گا؛ اور میں اسے قریب لے آؤں گا، اور وہ میرے قریب آئے گا: کیونکہ یہ کون ہے جس نے اپنے دل کو میرے قریب آنے پر مجبور کیا؟ خداوند فرماتا ہے۔\n22۔ اور تم میرے لوگ بنو گے، اور میں تمہارا خدا بنوں گا۔\n23۔ دیکھو، خداوند کا طوفان غصے کے ساتھ باہر نکلتا ہے، ایک مسلسل طوفان: یہ بدکاروں کے سر پر درد کے ساتھ گرے گا۔ {جاری ہے: عبرانی۔ کاٹنا} {گرنا...: یا، باقی رہنا}\n24۔ خداوند کا شدید غضب واپس نہیں آئے گا، جب تک کہ وہ یہ نہ کر لے، اور جب تک وہ اپنے دل کے ارادے پورے نہ کر لے: آخری دنوں میں تم اس پر غور کرو گے۔","1۔ اسی وقت، خداوند فرماتا ہے، کیا میں اسرائیل کے تمام خاندانوں کا خدا بنوں گا، اور وہ میرے لوگ ہوں گے۔\n2۔ خداوند فرماتا ہے، وہ لوگ جو تلوار سے بچ گئے تھے، صحرا میں فضل پائے گئے؛ {حتی} اسرائیل، جب میں اسے آرام دینے گیا تھا۔\n3۔ خداوند نے میرے سامنے قدیم زمانے سے ظاہر کیا ہے، {کہتا ہے}، ہاں، میں نے تمہیں ہمیشہ کی محبت سے محبت دی ہے؛ اسی لیے میں نے تمہیں محبت سے اپنی طرف کھینچا ہے۔ {of...: عبرانی۔ دور سے} {محبت بھری مہربانی کے ساتھ...: میں نے تم پر محبت کی مہربانی کی ہے}\n4۔ میں دوبارہ تمہیں تعمیر کروں گا، اور تم تعمیر ہو گے، اے اسرائیل کی کنواری: تم دوبارہ اپنے تابرات سے سجے جاؤ گے، اور خوش ہونے والوں کے رقص میں آگے بڑھو گے۔ {ٹیبریٹس: اور، ٹمبرلز}\n5۔ تم اب بھی سامریہ کے پہاڑوں پر بیلیں لگاؤ گے: کاشتکار بوئیں گے اور عام چیزوں کی طرح کھائیں گے۔ {کھاؤ...: عبوری۔ ان کی بے حرمتی کریں}\n6۔ کیونکہ ایک دن آئے گا، {جب} افرایم کے پہاڑ پر موجود پہرے دار پکاریں گے، اٹھو، اور ہم صیون کی طرف چلیں جو ہمارے خداوند ہمارے خدا کے پاس ہے۔\n7۔ کیونکہ خداوند یہ فرماتا ہے؛ یعقوب کے لیے خوشی سے گاؤ، اور قوموں کے سرداروں میں پکارو: اعلان کرو، تعریف کرو، اور کہو، اے خداوند، اپنے لوگ، اسرائیل کے باقیات کو بچا۔\n8۔ دیکھو، میں انہیں شمالی ملک سے لے آؤں گا، اور زمین کے کناروں سے لے آؤں گا، اور ان کے ساتھ اندھے اور لنگڑے، حاملہ عورت اور جو بچے کے ساتھ جدوجہد کرے گا، ایک بڑی جماعت وہاں واپس آئے گی۔\n9۔ وہ روتے ہوئے آئیں گے، اور میں دعاؤں کے ساتھ ان کی رہنمائی کروں گا: میں انہیں پانی کی ندیوں کے کنارے سیدھا چلاؤں گا، جہاں وہ لڑکھڑائیں نہیں: کیونکہ میں اسرائیل کا باپ ہوں، اور افرائیم میرا پہلا بیٹا ہے۔ {درخواستیں: یا، احسان}\n10۔ اے قوموں، خداوند کا کلام سنو اور دور دراز جزیروں میں اعلان کرو، اور کہو، جس نے اسرائیل کو بکھیر دیا وہ اسے جمع کرے گا اور اس کی حفاظت کرے گا، جیسے چرواہا اپنے ریوڑ کو کرتا ہے۔\n11۔ کیونکہ خداوند نے یعقوب کو نجات دی ہے، اور اسے اس کے ہاتھ سے چھڑا دیا ہے جو اس سے زیادہ طاقتور تھا۔\n12۔ لہٰذا وہ آئیں گے اور صیون کی بلندی پر گائیں گے، اور خداوند کی بھلائی کے لیے، گندم، شراب، تیل کے لیے، اور ریوڑ اور ریوڑ کے بچوں کے لیے ایک ساتھ بہیں گے؛ اور ان کی روح ایک پانی والے باغ کی مانند ہوگی؛ اور وہ اب مزید غمگین نہیں ہوں گے۔\n13۔ پھر کنواری رقص میں خوش ہوگی، جوان اور بوڑھے دونوں ساتھ: کیونکہ میں ان کے غم کو خوشی میں بدل دوں گا، انہیں تسلی دوں گا، اور ان کے غم سے خوش کروں گا۔\n14. اور میں کاہنوں کی روح کو موٹاپے سے تسکین دوں گا، اور میرے لوگ میری نیکی سے مطمئن ہوں گے، خداوند فرماتا ہے۔\n15۔ خداوند فرماتا ہے؛ رامہ میں ایک آواز سنائی دی، نوحہ، {اور} تلخ رونا؛ راحیل، جو اپنے بچوں کے لیے رو رہی تھی، اپنے بچوں کے لیے تسلی پانے سے انکار کرتی تھی، کیونکہ وہ نہیں تھے۔\n16۔ خداوند یہ فرماتا ہے؛ اپنی آواز کو رونے سے روکو، اور آنکھوں کو آنسوؤں سے روک: کیونکہ تمہارا کام انعام پائے گا، خداوند فرماتا ہے؛ اور وہ دشمن کی سرزمین سے دوبارہ آئیں گے۔\n17۔ اور تیری طرف امید ہے، خداوند فرماتا ہے، کہ تمہارے بچے دوبارہ اپنی سرحد پر آئیں گے۔\n18۔ میں نے یقینا افرائیم کو اپنے آپ پر افسوس کرتے سنا ہے؛ تم نے مجھے ڈانٹا ہے، اور مجھے سزا دی گئی، جیسے کوئی بیل جو جولے کا عادی نہ ہو: مجھے بدل دو، تو میں بدل جاؤں گا؛ کیونکہ تو خداوند میرے خدا ہو۔\n19۔ یقینا جب میں بدل گیا تو میں نے توبہ کی؛ اور اس کے بعد مجھے ہدایت ملی، میں نے اپنی ران پر مارا: میں شرمندہ ہوا، ہاں، حتیٰ کہ حیران بھی، کیونکہ میں نے اپنی جوانی کی ملامت برداشت کی۔\n20۔ {کیا} ایفریم میرا پیارا بیٹا ہے؟ {کیا وہ} ایک خوشگوار بچہ ہے؟ کیونکہ چونکہ میں نے اس کے خلاف بات کی ہے، میں اسے اب بھی مخلصانہ طور پر یاد کرتا ہوں: اس لیے میری آنتیں اس کے لیے پریشان ہیں؛ خداوند فرماتا ہے کہ میں اس پر ضرور رحم کروں گا۔ {آر...: عبرانی آواز}\n21۔ اپنے راستے بنا، اپنے اوپر ڈھیر بنو، اپنے دل کو سڑک کی طرف رکھو، {حتی} اس راہ کی طرف جو تم نے دیکھا: اے اسرائیل کی کنواری، دوبارہ ان شہروں کی طرف مڑو۔\n22. اے پیچھے ہٹنے والی بیٹی، تم کتنی دیر تک گھومتی رہو گی؟ کیونکہ خداوند نے زمین میں ایک نئی چیز پیدا کی ہے، ایک عورت مرد کے گرد گھیرے گی۔\n23. یوں فرماتا ہے رب لشکروں، اسرائیل کا خدا؛ اب بھی وہ یہوداہ کی سرزمین اور اس کے شہروں میں یہ بات استعمال کریں گے، جب میں ان کی قید دوبارہ لاؤں گا؛ خداوند تمہیں برکت دے، اے انصاف کی رہائش گاہ، {اور} پاکیزگی کے پہاڑ۔\n24۔ اور یہوداہ میں اور اس کے تمام شہروں میں کسان اکٹھے رہیں گے، اور وہ ریوڑ لے کر نکلیں گے۔\n25۔ کیونکہ میں نے تھکی ہوئی روح کو تسکین دی ہے، اور ہر غمزدہ روح کو تازہ کر دیا ہے۔\n26۔ اس پر میں جاگا، اور دیکھا؛ اور میری نیند میرے لیے میٹھی تھی۔\n27۔ دیکھو، وہ دن آتے ہیں، خداوند فرماتا ہے، کہ میں اسرائیل کے گھر اور یہوداہ کے گھر کو انسان کی نسل اور جانور کی نسل سے بوؤں گا۔\n28۔ اور یہ ہوگا، {جیسا کہ میں نے ان کی نگرانی کی ہے} ویسے ہی جیسے میں نے ان کی حفاظت کی ہے، توڑنا، توڑنا، گرانا، تباہ کرنا، اور تکلیف دینا؛ اسی طرح میں ان کی حفاظت کروں گا، تعمیر کروں گا، اور لگاؤں گا، خداوند فرماتا ہے۔\n29۔ ان دنوں وہ مزید کچھ نہیں کہیں گے، باپوں نے کھٹا انگور کھا لیا ہے، اور بچوں کے دانت کھڑے ہو گئے ہیں۔\n30۔ لیکن ہر کوئی اپنی غلطی کے لیے مرے گا: جو بھی کھٹا انگور کھائے گا، اس کے دانت کھڑے ہو جائیں گے۔\n31. دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں اسرائیل کے گھر اور یہوداہ کے گھر کے ساتھ نیا عہد کروں گا:\n32۔ اس عہد کے مطابق نہیں جو میں نے ان کے آباؤ اجداد سے اس دن کیا تھا {جب میں نے انہیں ہاتھ پکڑ کر مصر کی سرزمین سے نکالا تھا؛ جسے وہ میرا عہد توڑتے ہیں، حالانکہ میں ان کا شوہر تھا، خداوند فرماتا ہے: {اگرچہ...: یا کیا مجھے ان کے لیے شوہر رکھنا چاہیے تھا؟}\n33. لیکن یہ وہ عہد ہوگا جو میں اسرائیل کے گھر کے ساتھ کروں گا؛ ان دنوں کے بعد، خداوند فرماتا ہے، میں اپنا قانون ان کے اندرونی حصے میں رکھوں گا، اور اسے ان کے دلوں میں لکھوں گا؛ اور وہ ان کے خدا ہوں گے، اور وہ میرے لوگ ہوں گے۔\n34۔ اور وہ ہر آدمی کو اس کے پڑوسی اور ہر بھائی کو مزید نہیں سکھائیں گے، یہ کہتے ہوئے: خداوند کو جانو، کیونکہ وہ سب مجھے جانیں گے، ان میں سے چھوٹے سے لے کر سب سے بڑے تک، خداوند فرماتا ہے: کیونکہ میں ان کے گناہوں کو معاف کروں گا، اور ان کے گناہ کو مزید یاد نہیں رکھوں گا۔\n35. خداوند یہی فرماتا ہے، جو دن میں سورج کو روشنی دیتا ہے، {اور} چاند اور ستاروں کی رسومات رات کی روشنی کے لیے، جو سمندر کو تقسیم کرتے ہیں جب اس کی لہریں گرجتی ہیں؛ لشکروں کا رب اس کا نام ہے:\n36۔ اگر یہ احکامات میرے سامنے سے ہٹ جائیں، خداوند فرماتا ہے، {تو} اسرائیل کی نسل بھی ہمیشہ کے لیے میرے سامنے قوم نہیں رہے گی۔\n37۔ خداوند یہ فرماتا ہے؛ اگر اوپر آسمان کو ناپا جا سکتا ہے، اور زمین کی بنیادیں نیچے تلاش کی جائیں، تو میں اسرائیل کے تمام بیج کو بھی ان سب کے اعمال کے لیے پھینک دوں گا، خداوند فرماتا ہے۔\n38۔ دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ شہر خداوند کے لیے حنانیل کے مینار سے کونے کے دروازے تک تعمیر کیا جائے گا۔\n39۔ اور پیمائش کی لکیر اب بھی اس کے خلاف پہاڑی گاریب پر جائے گی، اور گوتھ کے گرد گھومے گی۔\n40۔ اور مردہ لاشوں کی پوری وادی، راکھ کی، اور تمام کھیت، جو کیدرون کے ندی تک، گھوڑے کے دروازے کے کونے تک، مشرق کی طرف ہے، خداوند کے لیے مقدس ہوگی؛ اسے نہ تو اٹھایا جائے گا، نہ ہی ہمیشہ کے لیے پھینکا جائے گا۔","1۔ وہ کلام جو خداوند کی طرف سے یرمیاہ کو یہوداہ کے بادشاہ زدقیاہ کے دسویں سال میں آیا، جو کہ نبوکدرز کا اٹھارہویں سال تھا۔\n2۔ تب بابل کے بادشاہ کی فوج نے یروشلم کا محاصرہ کر لیا: اور یرمیاہ نبی کو جیل کے صحن میں بند کر دیا گیا، جو یہوداہ کے بادشاہ کے گھر میں تھا۔\n3۔ کیونکہ یہوداہ کے بادشاہ زدقیاہ نے اسے خاموش کر دیا تھا، کہتے ہوئے، کیوں تم نبوت کرتے ہو، اور کہتے ہو، خداوند نے یوں فرمایا، دیکھو، میں اس شہر کو بابل کے بادشاہ کے ہاتھ میں دوں گا، اور وہ اسے لے لے گا؛\n4۔ اور یہوداہ کا بادشاہ صدقیہ کلدانیوں کے ہاتھ سے نہیں نکل سکے گا، بلکہ یقینا بابل کے بادشاہ کے ہاتھ میں دے دیا جائے گا، اور اس سے منہ بہ منہ بات کرے گا، اور اس کی آنکھیں اس کی آنکھوں کو دیکھیں گی؛\n5۔ اور وہ زدیقیاہ کو بابل لے جائے گا، اور وہیں رہے گا جب تک میں اس سے نہ ملوں، خداوند فرماتا ہے: چاہے تم کلدانیوں سے لڑو، تم کامیاب نہیں ہو گے۔\n6۔ اور یرمیاہ نے کہا، خداوند کا کلام میرے پاس آیا، اور کہا،\n7۔ دیکھو، شلم کا بیٹا ہنامیل، تمہارا چچا تمہارے پاس آئے گا اور کہتا ہے، میرا کھیت جو انتھوتھ میں ہے، تمہیں خرید لو، کیونکہ نجات کا حق تمہیں خریدنے کا حق ہے۔\n8۔ تو ہنامیل میرے چچا کا بیٹا میرے پاس قید خانے کے دربار میں خداوند کے کلام کے مطابق آیا، اور مجھ سے کہا، میرا کھیت خریدو، میں تم سے دعا کرتا ہوں، جو انتھوت میں ہے، جو بنیامین کے ملک میں ہے: کیونکہ وراثت کا حق تمہارا ہے، اور نجات تمہارا ہے؛ اپنے لیے {یہ} خرید لو۔ تب مجھے معلوم ہوا کہ یہ {تھا} خداوند کا کلام ہے۔\n9۔ اور میں نے اپنے چچا کے بیٹے حنامیل کا کھیت خریدا، جو انتھوتھ میں تھا، اور اس کے پیسے {حتیٰ کہ} سترہ شیکل چاندی کے برابر تولے۔ {سترہ...: یا، سات شیکل اور دس چاندی کے سکے}\n10۔ اور میں نے ثبوت کو سبسکرائب کیا، سیل کیا، گواہوں کو لیا، اور بیلنس میں پیسے تولے۔ {سبسکرائب کیا...: عبرانی۔ کتاب میں لکھا}\n11۔ تو میں نے خریداری کے ثبوت لیے، {دونوں} وہ جو قانون اور رسم و رواج کے مطابق مہر بند تھے، اور جو کھلا تھا:\n12۔ اور میں نے خریداری کی گواہی باروخ، نیریاہ کے بیٹے، ماسیہ کے بیٹے کو حنامیل میرے چچا کے {بیٹے} کے سامنے اور ان گواہوں کی موجودگی میں پیش کی جنہوں نے خریداری کی کتاب پر دستخط کیے، ان تمام یہودیوں کے سامنے جو قید خانے کے دربار میں بیٹھے تھے۔\n13۔ اور میں نے باروخ پر ان کے سامنے حملہ کیا، کہا،\n14. یوں فرماتا ہے رب لشکروں، اسرائیل کا خدا؛ ان شواہد کو لیں، خریداری کے یہ شواہد، جو دونوں مہر بند ہیں، اور یہ ثبوت جو کھلا ہے؛ اور انہیں مٹی کے برتن میں رکھ دیں، تاکہ وہ کئی دن زندہ رہ سکیں۔\n15۔ کیونکہ ایسا فرماتا ہے لشکروں کے رب، اسرائیل کے خدا؛ اس زمین میں گھر، کھیت اور انگور کے باغات دوبارہ قابض ہوں گے۔\n16۔ اب جب میں نے خریداری کی گواہی باروخ، نیریاہ کے بیٹے کو دی، تو میں نے خداوند سے دعا کی، کہا،\n17. اے خداوند! دیکھو، تم نے اپنی عظیم طاقت سے آسمان اور زمین بنا دی ہے اور بازو پھیلا دیا ہے، {اور} تمہارے لیے کچھ بھی زیادہ مشکل نہیں: {بہت...: یا تم سے چھپا ہوا}\n18۔ تو ہزاروں لوگوں کے ساتھ محبت دکھاتی ہو، اور ان کے بعد آنے والے باپ کی بدکاری کا بدلہ ان کے بعد آنے والے بچوں کے گود میں دیتی ہو: عظیم، طاقتور خدا، لشکروں کا رب، {ہے} اس کا نام،\n19۔ مشورے میں بڑا، اور کام میں طاقتور: کیونکہ تمہاری آنکھیں انسانوں کے بیٹوں کے تمام راستوں پر کھل رہی ہیں: ہر ایک کو اس کے طریقوں اور اس کے اعمال کے پھل کے مطابق دینے کے لیے: {کام: عبرانی۔ کر رہا ہوں}\n20۔ جس نے مصر کی سرزمین میں آج تک اور اسرائیل میں اور {دیگر} لوگوں میں بھی نشانیاں اور عجائبات قائم کیے ہیں؛ اور تمہیں آج کی طرح ایک نام دیا ہے؛\n21۔ اور اس نے اپنے لوگوں کو اسرائیل کو مصر کی سرزمین سے نشانوں، عجائباتوں، مضبوط ہاتھوں، پھیلائے ہوئے بازو اور بڑی دہشت کے ساتھ نکالا؛\n22۔ اور انہوں نے انہیں یہ زمین دی، جو تم نے ان کے باپ اجداد سے قسم کھائی تھی، ایک ایسی زمین جو دودھ اور شہد سے بہتی ہو؛\n23۔ اور وہ اندر آئے، اور اس پر قبضہ کر لیا؛ لیکن انہوں نے تمہاری آواز نہیں مانی، نہ ہی تمہارے قانون میں چلے؛ انہوں نے وہ سب کچھ نہیں کیا جو تم نے انہیں حکم دیا تھا، اس لیے تم نے ان پر یہ ساری برائی مسلط کر دی:\n24۔ دیکھو سوار، وہ شہر میں آئے ہیں تاکہ اسے حاصل کریں؛ اور شہر کلدانیوں کے ہاتھ میں دے دیا جاتا ہے، جو اس کے خلاف لڑتے ہیں، تلوار، قحط اور وبا کی وجہ سے: اور جو تم نے کہا وہ ہو گیا؛ اور دیکھو، تم اسے دیکھتے ہو۔ {ماؤنٹس: یا، انجن آف شاٹ}\n25۔ اور تو نے مجھ سے کہا، اے خداوند خدا، پیسوں کے بدلے زمین خرید کر اور گواہ لے لو؛ کیونکہ شہر کلدانیوں کے حوالے کر دیا گیا ہے۔ {اس کے لیے: یا، اس کے خلاف}\n26۔ پھر خداوند کا کلام یرمیاہ کو آیا، جس نے کہا،\n27۔ دیکھو، میں خداوند ہوں، تمام جسم کا خدا: کیا میرے لیے کوئی چیز بہت مشکل ہے؟\n28۔ لہٰذا خداوند فرماتا ہے؛ دیکھو، میں اس شہر کو کلدانیوں کے ہاتھ میں اور بابل کے بادشاہ نبوکدرز کے ہاتھ میں دوں گا، اور وہ اسے لے گا:\n29۔ اور کلدانی جو اس شہر کے خلاف لڑ رہے ہیں، آئیں گے اور اس شہر کو آگ لگا دیں گے، اور اسے ان گھروں کے ساتھ جلا دیں گے، جن کی چھتوں پر انہوں نے بعل کو لوبان پیش کیا ہے، اور دوسرے دیوتاؤں کو شراب کی قربانیاں دی ہیں، تاکہ مجھے غصہ دلا سکیں۔\n30۔ کیونکہ بنی اسرائیل اور یہوداہ کی اولاد نے اپنی جوانی سے ہی میرے سامنے صرف برا کیا ہے: کیونکہ بنی اسرائیل نے صرف اپنے ہاتھوں کے کام سے مجھے غصہ دلایا ہے، خداوند فرماتا ہے۔\n31۔ کیونکہ یہ شہر میرے لیے میرے غصے اور غصے کا باعث رہا ہے، جس دن سے انہوں نے اسے تعمیر کیا ہے، آج تک؛ کہ میں اسے اپنے چہرے کے سامنے سے ہٹا دوں، {ایک اشتعال...: عبرانی۔ میرے غصے کے لیے}\n32۔ بنی اسرائیل اور یہوداہ کے بچوں کی تمام برائی کی وجہ سے، جو انہوں نے مجھے غصہ دلایا ہے، وہ، ان کے بادشاہوں، ان کے شہزادے، ان کے کاہن، ان کے نبی، یہوداہ کے لوگ، اور یروشلم کے باشندے۔\n33۔ اور انہوں نے میری طرف پیٹھ کی، چہرہ نہیں، حالانکہ میں نے انہیں سکھایا، صبح اٹھ کر انہیں سکھایا، پھر بھی انہوں نے سبق نہیں سنا۔ {واپس: عبوری۔ گردن}\n34۔ لیکن انہوں نے اپنے مکروہ جسم کو میرے نام سے پکارا جانے والے گھر میں لگا دیا تاکہ اسے ناپاک کیا جا سکے۔\n35۔ اور انہوں نے بعل کی اونچی جگہیں تعمیر کیں، جو ہنوم کے بیٹے کی وادی میں ہیں، تاکہ اپنے بیٹوں اور بیٹیوں کو آگ سے گزر کر مولخ تک پہنچایا جا سکے؛ جس کا میں نے انہیں حکم نہیں دیا، نہ ہی میرے ذہن میں آیا کہ وہ یہ مکروہ کام کریں، تاکہ یہوداہ کو گناہ کروائے۔\n36۔ اور اب یہ فرماتا ہے کہ خداوند، اسرائیل کا خدا، اس شہر کے بارے میں جس کے بارے میں تم کہتے ہو: یہ بابل کے بادشاہ کے ہاتھ میں تلوار، قحط اور وبا کے ذریعے دیا جائے گا؛\n37۔ دیکھو، میں انہیں تمام ملکوں سے جمع کروں گا، جہاں میں نے انہیں اپنے غصے، غصے اور شدید غصے میں بھگا دیا ہے؛ اور میں انہیں دوبارہ اس جگہ لے آؤں گا، اور انہیں محفوظ رہنے دوں گا:\n38۔ اور وہ میرے لوگ ہوں گے، اور میں ان کا خدا بنوں گا:\n39۔ اور میں انہیں ایک دل اور ایک راستہ دوں گا، تاکہ وہ ہمیشہ کے لیے مجھ سے ڈریں، ان کی بھلائی کے لیے، اور ان کے بعد اپنے بچوں کے لیے: {ہمیشہ کے لیے: عبرانی۔ تمام دن}\n40۔ اور میں ان سے ایک دائمی عہد کروں گا کہ میں ان سے منہ موڑوں گا نہیں، ان کے لیے بھلائی نہیں کروں گا؛ لیکن میں ان کے دلوں میں خوف ڈالوں گا کہ وہ مجھ سے جدا نہ ہوں۔ {ان سے: عبرانی۔ ان کے بعد سے}\n41. ہاں، میں ان پر خوشی مناؤں گا تاکہ ان کے لیے بھلائی کروں، اور میں انہیں پورے دل اور جان سے اس زمین میں ضرور لگاؤں گا۔ {یقینا: عبوری۔ سچ میں، یا استحکام میں}\n42۔ کیونکہ خداوند یہ فرماتا ہے؛ جیسے میں نے اس قوم پر یہ ساری بڑی برائی لائی ہے، ویسے ہی میں ان پر وہ سب بھلائی لاؤں گی جو میں نے ان سے وعدہ کی ہے۔\n43۔ اور اس زمین میں کھیت خریدے جائیں گے، جس کے بارے میں تم کہتے ہو، {یہ ویران ہے} بغیر انسان اور جانور کے؛ یہ کلدانیوں کے ہاتھ میں دیا جاتا ہے۔\n44۔ لوگ پیسے کے بدلے کھیت خریدیں گے، شواہد جمع کریں گے، انہیں مہر لگائیں گے، اور بنیامین کی سرزمین میں، یروشلم کے آس پاس، یہوداہ کے شہروں میں، پہاڑوں کے شہروں میں، وادی کے شہروں میں، اور جنوب کے شہروں میں گواہ لیں گے، کیونکہ میں ان کی قید واپس لاؤں گا،  خداوند فرماتا ہے۔","1۔ مزید یہ کہ خداوند کا کلام یرمیاہ کو دوسری بار آیا، جب وہ ابھی قید کی عدالت میں قید تھا، اور کہا،\n2۔ یہی فرماتا ہے خداوند جو اس کا خالق ہے، وہ خداوند جس نے اسے بنایا، تاکہ اسے قائم کیا جائے؛ خداوند اس کا نام ہے؛ {خداوند ہے: یا، یہووا، وغیرہ}\n3. مجھے پکارو، اور میں تمہیں جواب دوں گا، اور تمہیں عظیم اور عظیم چیزیں دکھاؤں گا، جو تم نہیں جانتے۔ {طاقتور: یا، چھپی ہوئی}\n4۔ کیونکہ یہی فرماتا ہے، خداوند اسرائیل کے اس شہر کے گھروں اور یہوداہ کے بادشاہوں کے گھروں کے بارے میں، جو پہاڑوں اور تلوار سے گرا دیے گئے ہیں؛\n5۔ وہ کلدانیوں سے لڑنے آتے ہیں، لیکن یہ ان لوگوں کی لاشوں سے بھرنے کے لیے ہے، جنہیں میں نے اپنے غصے اور غصے میں مارا ہے، اور ان سب کی برائیوں کے لیے میں نے اس شہر سے اپنا چہرہ چھپا لیا ہے۔\n6۔ دیکھو، میں اسے صحت اور شفا دوں گا، اور انہیں شفا دوں گا، اور انہیں سکون اور سچائی کی فراوانی دکھاؤں گا۔\n7۔ اور میں یہوداہ کی قید اور اسرائیل کی قید کو واپس لاؤں گا، اور انہیں پہلے کی طرح تعمیر کروں گا۔\n8۔ اور میں انہیں ان کے تمام گناہوں سے پاک کروں گا جو انہوں نے میرے خلاف گناہ کیے ہیں؛ اور میں ان کے تمام گناہوں کو معاف کر دوں گا، جن سے انہوں نے گناہ کیا ہے، اور جن سے انہوں نے میرے خلاف زیادتی کی ہے۔\n9۔ اور یہ میرے لیے خوشی کا نام ہوگا، زمین کی تمام قوموں کے سامنے ایک تعریف اور عزت ہوگی، جو میری ان کے لیے کی گئی تمام نیکی سنیں گی: اور وہ اس نیکی اور خوشحالی کے لیے ڈریں گے جو میں اس کے لیے لاؤں گا۔\n10۔ خداوند فرماتا ہے؛ پھر اس جگہ پر سنائی دے گا، جو تم کہتے ہو {بے انسان} اور بغیر جانور کے، {حتیٰ کہ} یہوداہ کے شہروں میں، اور یروشلم کی گلیوں میں، جو ویران ہیں، بے انسان، بے بسکین، اور بغیر جانور کے،\n11۔ خوشی کی آواز، اور خوشی کی آواز، دولہا کی آواز، اور دلہن کی آواز، ان لوگوں کی آواز جو کہیں گے، خداوند کی تعریف کرو، کیونکہ خداوند بھلا ہے؛ اس کی رحمت {ہمیشہ قائم ہے} کے لیے: {اور} ان میں سے جو خداوند کے گھر میں حمد کی قربانی لائیں گے۔ کیونکہ میں زمین کی قید کو واپس لاؤں گا، جیسا کہ پہلی بار فرماتا ہے، خداوند فرماتا ہے۔\n12۔ خداوند لشکروں نے یوں فرمایا؛ اس جگہ میں، جو انسان اور جانور کے بغیر ویران ہے، اور اس کے تمام شہروں میں، چرواہوں کی رہائش گاہ ہوگی جو اپنے ریوڑ کو آرام دے رہے ہیں۔\n13۔ پہاڑوں کے شہروں میں، وادی کے شہروں میں، جنوب کے شہروں میں، اور بنیامین کی سرزمین میں، یروشلم کے آس پاس کے علاقوں میں، اور یہوداہ کے شہروں میں، ریوڑ دوبارہ اس کے ہاتھوں سے گزریں گے جو انہیں بتاتا ہے، خداوند فرماتا ہے۔\n14. دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں وہ نیکی پوری کروں گا جو میں نے اسرائیل کے گھر اور یہوداہ کے گھر سے وعدہ کی ہے۔\n15۔ ان دنوں میں، اور اس وقت، میں راستبازی کی شاخ کو داؤد تک بڑھاؤں گا؛ اور وہ زمین میں انصاف اور راستبازی انجام دے گا۔\n16۔ ان دنوں یہوداہ نجات پائے گا، اور یروشلم محفوظ رہے گا: اور یہی نام ہے جس سے اسے کہا جائے گا، خداوند ہماری راستبازی۔ {خداوند...: عبرانی۔ یہوواہتسیدکینو}\n17۔ کیونکہ خداوند یہ فرماتا ہے؛ داؤد کبھی نہیں چاہے گا کہ کوئی آدمی اسرائیل کے گھر کے تخت پر بیٹھے؛ {ڈیوڈ...: عبرانی۔ داؤد سے کوئی کٹ نہیں جائے گا}\n18. نہ ہی کاہن، لاوی میرے سامنے کسی ایسے آدمی کو چاہیں گے جو جلنے کی قربانیاں پیش کرے، گوشت کی قربانیاں جلائے اور مسلسل قربانی دے۔\n19۔ اور خداوند کا کلام یرمیاہ کے پاس آیا، جس میں کہا،\n20۔ خداوند فرماتا ہے؛ اگر تم میرے دن کے عہد اور رات کے عہد کو توڑ سکتے ہو، اور ان کے موسم میں دن اور رات نہ ہوں؛\n21۔ {پھر} میرا عہد میرے خادم داؤد کے ساتھ بھی توڑ سکتا ہے کہ اس کا تخت پر حکمرانی کرنے والا بیٹا نہ ہو؛ اور لاویوں کے ساتھ کاہن، میرے وزیر۔\n22۔ جیسے آسمان کی فوج گنی نہیں جا سکتی، نہ ہی سمندر کی ریت ناپی جا سکتی ہے: اسی طرح میں اپنے خادم داؤد کی نسل اور میرے خدمت کرنے والے لاویوں کی نسل کو بڑھاؤں گا۔\n23۔ مزید یہ کہ خداوند کا کلام یرمیاہ تک پہنچا، جس میں کہا،\n24۔ کیا تم نے یہ نہیں سنا کہ یہ قوم کیا کہہ رہی ہے، کہ خداوند نے جو دو خاندان چنے ہیں، انہوں نے انہیں بھی چھوڑ دیا ہے؟ اسی لیے انہوں نے میرے لوگوں سے نفرت کی ہے، کہ وہ ان کے سامنے ایک قوم نہ رہیں۔\n25۔ خداوند فرماتا ہے؛ اگر میرا عہد {دن} اور رات کے ساتھ نہ ہو، {اور اگر} میں نے آسمان اور زمین کے احکامات مقرر نہ کیے ہوں؛\n26۔ پھر میں یعقوب کی نسل اور اپنے خادم داؤد کو پھینک دوں گا، {تاکہ} میں اس کی نسل میں سے {کسی بھی} کو ابراہیم، اسحاق اور یعقوب کی نسل پر حکمران نہ بنا سکوں: کیونکہ میں ان کی قید واپس لاؤں گا اور ان پر رحم کروں گا۔","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، جب نبوکدنضر، بابل کے بادشاہ، اور اس کی تمام فوج، اور اس کی سلطنت کی تمام بادشاہتیں، اور تمام لوگ، یروشلم اور اس کے تمام شہروں کے خلاف لڑے، اور کہا، {اس کی...: عبرانی۔ اس کے ہاتھ کی حکمرانی}\n2. یہی فرماتا ہے، خداوند اسرائیل کا خدا؛ جاؤ اور یہوداہ کے بادشاہ زدقیاہ سے بات کرو، اور اسے بتاؤ، خداوند یوں فرماتا ہے؛ دیکھو، میں اس شہر کو بابل کے بادشاہ کے ہاتھ میں دوں گا، اور وہ اسے آگ سے جلا دے گا:\n3۔ اور تم اس کے ہاتھ سے نہیں نکل سکتے، بلکہ ضرور پکڑے جاؤ گے اور اس کے ہاتھ میں دے دیے جاؤ گے؛ اور تمہاری آنکھیں بابل کے بادشاہ کی آنکھوں کو دیکھیں گی، اور وہ تم سے منہ بہ منہ بات کرے گا، اور تم بابل جاؤ گے۔ {وہ کرے گا...: عبرانی۔ اس کا منہ تمہارے منہ سے بات کرے گا}\n4۔ پھر بھی خداوند کا کلام سنو، اے یہوداہ کے بادشاہ صدقیا؛ یوں تیرے خداوند فرماتا ہے، تو تلوار سے نہیں مرا جانا:\n5. {لیکن} تم سکون سے مرو گے: اور تمہارے باپوں کی آگ کے ساتھ، جو تمہارے پہلے بادشاہ تھے، وہ بھی تمہارے لیے [خوشبو} جلائیں گے؛ اور وہ آپ پر افسوس کریں گے، {کہیں}، اے خداوند! کیونکہ میں نے کلام پڑھا ہے، خداوند فرماتا ہے۔\n6۔ پھر یرمیاہ نبی نے یروشلم میں یہوداہ کے بادشاہ زدقیاہ سے یہ تمام الفاظ کہے،\n7۔ جب بابل کے بادشاہ کی فوج نے یروشلم، اور یہوداہ کے باقی تمام شہروں کے خلاف، لاخیش کے خلاف، اور عزیقہ کے خلاف لڑائی کی، کیونکہ یہ محفوظ شہر یہوداہ کے شہروں میں سے باقی رہ گئے۔\n8۔ {یہ} وہ کلام ہے جو خداوند کی طرف سے یرمیاہ کو آیا، اس کے بعد بادشاہ صدقیاہ نے یروشلم میں موجود تمام لوگوں سے عہد کیا کہ انہیں آزادی کا اعلان کیا جائے؛\n9۔ کہ ہر آدمی اپنے نوکر اور ہر خادم، چاہے وہ عبرانی ہو یا عبرانی عورت، کو آزاد کرے؛ کہ کوئی بھی ان کی خدمت خود نہ کرے، {یعنی}، ایک یہودی کا بھائی۔\n10۔ اب جب تمام شہزادے، اور تمام لوگ، جنہوں نے عہد کیا تھا، سنا کہ ہر ایک کو اپنے خادم اور ہر نوکر کو آزاد کر دینا چاہیے، تاکہ کوئی بھی ان کی خدمت نہ کرے، تو انہوں نے اطاعت کی، اور انہیں جانے دیا۔\n11۔ لیکن بعد میں انہوں نے رخ موڑ لیا، اور نوکروں اور خادماؤں کو، جنہیں انہوں نے آزاد کیا تھا، واپس لے آئے اور انہیں نوکروں اور خادماؤں کے لیے تابع کر دیا۔\n12۔ لہٰذا خداوند کا کلام یرمیاہ تک خداوند کی طرف سے آیا، جس میں کہا گیا،\n13. خداوند اسرائیل کے خدا نے یوں فرمایا؛ میں نے تمہارے آباؤ اجداد سے عہد کیا تھا جب میں نے انہیں مصر کی زمین سے، غلاموں کے گھر سے نکالا، اور کہا،\n14۔ سات سال کے آخر میں تم ہر آدمی، اس کا بھائی، ایک عبرانی کو جانے دو، جو تمہیں بیچ دیا گیا ہے؛ اور جب وہ تمہاری چھ سال خدمت کرے گا، تو اسے تم سے آزاد کر دو گے: لیکن تمہارے آباؤ اجداد نے میری بات نہیں سنی، نہ ہی ان کی کان مانی۔ {رہا ہے...: یا، اس نے خود کو بیچ دیا}\n15۔ اور تم اب مڑ چکے تھے، اور میری نظر میں ہر آدمی کو اس کے پڑوسی کی آزادی کا اعلان کر کے؛ اور تم نے میرے سامنے اس گھر میں عہد کیا تھا جسے میرے نام سے پکارا جاتا ہے: {اب: عبرانی۔ آج کے لیے} {جو...: عبرانی۔ جس پر میرا نام پکارا جاتا ہے}\n16۔ لیکن تم نے میرا نام بدنام کیا، اور ہر آدمی کو اس کے خادم اور ہر اس خادمہ کو، جسے تم نے اپنی مرضی سے آزاد کیا تھا، واپس لے آئے، اور انہیں غلام بنا دیا، تاکہ وہ تمہارے لیے خادم اور خادمہ بن جائیں۔\n17۔ لہٰذا خداوند فرماتا ہے؛ تم نے میری بات نہیں سنی، آزادی کا اعلان کرتے ہوئے، ہر ایک اپنے بھائی کو، اور ہر آدمی اپنے پڑوسی کو: دیکھو، میں تمہارے لیے آزادی کا اعلان کرتا ہوں، خداوند فرماتا ہے، تلوار، وبا اور قحط کے لیے؛ اور میں تمہیں زمین کی تمام سلطنتوں میں لے جاؤں گا۔ {ہونے والا...: عببرانی۔ ایک ہٹانے کے لیے}\n18۔ اور میں ان لوگوں کو دوں گا جنہوں نے میرا عہد توڑا، جنہوں نے میرے سامنے کیے گئے عہد کے الفاظ پورے نہیں کیے، جب انہوں نے بچھڑے کو دو حصوں میں کاٹا اور اس کے حصوں کے درمیان سے گزرا،\n19۔ یہوداہ کے شہزادے، اور یروشلم کے شہزادے، خواجہ سرا، کاہن، اور زمین کے تمام لوگ جو بچھڑے کے حصوں کے درمیان سے گزرتے تھے؛\n20۔ میں انہیں ان کے دشمنوں کے ہاتھ میں دے دوں گا، اور ان کے ہاتھ میں جو ان کی جان چاہتے ہیں: اور ان کے مردہ جسم آسمان کے پرندوں اور زمین کے جانوروں کے لیے گوشت کے لیے ہوں گے۔\n21. اور یدقیاہ بادشاہ یہوداہ اور اس کے شہزادوں کو ان کے دشمنوں کے ہاتھ میں دے دوں گا، اور ان کے ہاتھ میں جو اپنی جان چاہتے ہیں، اور بابل کے بادشاہ کی فوج کے ہاتھ میں، جو تم سے نکل چکی ہے۔\n22. دیکھو، میں حکم دوں گا، خداوند فرماتا ہے، اور انہیں اس شہر واپس لے آتا ہوں؛ اور وہ اس کے خلاف لڑیں گے، اسے قبضے میں لیں گے، اور آگ سے جلا دیں گے: اور میں یہوداہ کے شہروں کو ایک ویران بنا دوں گا جہاں کوئی آباد نہیں۔","1۔ وہ کلام جو یرمیاہ کو خداوند کی طرف سے آیا، یہویاکیم، یہوداہ کے بادشاہ یوسیاہ کے بیٹے کے زمانے میں، کہتا ہے،\n2۔ ریکابیٹیز کے گھر جاؤ، ان سے بات کرو، اور انہیں خداوند کے گھر میں لے آؤ، ایک کمرے میں، اور انہیں شراب پلانا۔\n3۔ پھر میں نے یعقوبیا، یرمیاہ کا بیٹا، حبازنیا کا بیٹا، اور اس کے بھائیوں کو، اس کے تمام بیٹوں کو، اور پورے ریخابیوں کے گھرانے کو لے لیا؛\n4۔ اور میں نے انہیں خداوند کے گھر میں لے آیا، حنان کے بیٹوں کے کمرے میں، جو اگدلیہ کا بیٹا تھا، خدا کا بندہ تھا، جو شہزادوں کے کمرے کے پاس تھا، جو معسیاہ کے کمرے کے اوپر تھا، شالوم کے بیٹے، دروازے کا محافظ: {دروازہ: عبرانی۔ تھریشولڈ، یا، ویسل}\n5۔ اور میں نے ریکابیٹیس خاندان کے بیٹوں کے سامنے شراب اور جام سے بھرے برتن رکھے، اور ان سے کہا، \"شراب پیو۔\n6۔ لیکن انہوں نے کہا، ہم شراب نہیں پئیں گے: کیونکہ ہمارے باپ نے ہمیں حکم دیا تھا کہ نہ تم شراب پیو گے، نہ تم اور نہ تمہارے بیٹے ہمیشہ کے لیے:\n7۔ نہ گھر بناؤ گے، نہ بیج بوؤ گے، نہ انگور کے باغ لگاؤ گے، نہ کوئی ہوگا، بلکہ اپنے تمام دن خیموں میں رہو گے؛ تاکہ تم اس سرزمین میں کئی دن گزار سکو جہاں تم اجنبی ہو۔\n8۔ یوں ہم نے ہمارے باپ ریچاب کے بیٹے جوناداب کی آواز کی اطاعت کی ہے جو اس نے ہمیں حکم دیا ہے کہ ہم اپنی بیویوں، بیٹوں اور بیٹیوں کو سارا دن شراب نہ پئیں؛\n9۔ نہ ہی ہمارے لیے گھر بنائیں جہاں ہم رہ سکیں: نہ ہمارے پاس انگور کا باغ ہے، نہ کھیت ہے، نہ بیج:\n10۔ لیکن ہم خیموں میں رہے، اور اطاعت کی، اور وہ سب کچھ کیا جو ہمارے والد جوناداب نے ہمیں حکم دیا تھا۔\n11۔ لیکن جب بابل کا بادشاہ نبوکدرز زمین پر آیا، تو ہم نے کہا، آؤ، اور یروشلم چلیں، کلدانیوں کی فوج اور شامیوں کی فوج کے خوف سے: یوں ہم یروشلم میں رہتے ہیں۔\n12۔ پھر خداوند کا کلام یرمیاہ کو آیا، جس میں کہا گیا،\n13. ایسا فرماتا ہے لشکروں کے رب، اسرائیل کے خدا؛ جاؤ اور یہوداہ کے لوگوں اور یروشلم کے باشندوں کو بتاؤ، کیا تمہیں میری بات سننے کی ہدایت نہیں ملے گی؟ خداوند فرماتا ہے۔\n14۔ ریچاب کے بیٹے جوناداب کے الفاظ ادا کیے گئے کہ اس نے اپنے بیٹوں کو شراب نہ پینے کا حکم دیا؛ کیونکہ آج تک وہ کوئی شراب نہیں پیتے، لیکن اپنے باپ کے حکم کی پیروی کرتے ہیں: حالانکہ میں نے تم سے بات کی ہے، صبح سویرے اٹھ کر بات کی؛ لیکن تم نے میری بات نہیں مانی۔\n15۔ میں نے تم کے پاس اپنے تمام بندوں کو نبی بھیجے ہیں، جو صبح سویرے اٹھ کر بھیج رہے ہیں، کہہ رہے ہیں، اب ہر انسان کو اس کے برے راستے سے واپس لوٹاؤ، اپنے اعمال درست کرو، اور دوسرے دیوتاؤں کے پیچھے نہ جاؤ تاکہ ان کی خدمت کرے، اور تم اس زمین میں رہو جو میں نے تمہیں اور تمہارے آباؤ اجداد کو دی ہے:  لیکن تم نے اپنی کان نہیں مانی، نہ ہی میری بات سنی۔\n16۔ کیونکہ جوناداب کے بیٹوں نے اپنے والد کا حکم پورا کیا ہے، جس کا اس نے انہیں حکم دیا تھا؛ لیکن اس قوم نے میری بات نہیں سنی:\n17. لہٰذا لشکروں کے خداوند خدا اسرائیل کے خدا نے یوں فرمایا؛ دیکھو، میں یہوداہ اور یروشلم کے تمام باشندوں پر وہ تمام برائی لاؤں گا جو میں نے ان کے خلاف سنا: کیونکہ میں نے ان سے بات کی ہے، لیکن انہوں نے نہیں سنا؛ اور میں نے انہیں پکارا ہے، لیکن انہوں نے جواب نہیں دیا۔\n18۔ اور یرمیاہ نے ریخابیتس کے گھر سے کہا، یوں فرماتا ہے لشکروں کے رب، اسرائیل کا خدا؛ کیونکہ تم نے اپنے والد جوناداب کے حکم کی پیروی کی، اس کے تمام احکامات پورے کیے، اور اس کے حکم کے مطابق عمل کیا:\n19۔ لہٰذا لشکروں کے رب، اسرائیل کے خدا نے یوں فرمایا؛ ریچاب کا بیٹا جوناداب کبھی نہیں چاہے گا کہ کوئی آدمی ہمیشہ میرے سامنے کھڑا رہے۔ {یونادب...: عبرانی۔ کوئی بھی آدمی جوناداب بیٹے رچاب سے کھڑا ہونے کے لیے نہیں روکا جائے گا، وغیرہ۔","1۔ اور یہ یہویاکیم، یہوداہ کے بادشاہ یوسیاہ کے بیٹے کے چوتھے سال میں ہوا، {کہ} یہ کلام یرمیاہ کو خداوند کی طرف سے آیا، جس میں کہا گیا،\n2۔ اپنے لیے ایک کتاب کا رول لے لو، اور اس میں وہ تمام الفاظ لکھو جو میں نے تم سے اسرائیل، یہوداہ کے خلاف، اور تمام قوموں کے خلاف کہے ہیں، جس دن میں نے تم سے بات کی، یوشیا کے دنوں سے لے کر آج تک۔\n3۔ ممکن ہے کہ یہوداہ کا گھر وہ تمام برائیاں سن لے جو میں ان کے ساتھ کرنا چاہتا ہوں؛ تاکہ وہ ہر انسان کو اس کے برے راستے سے واپس لوٹیں؛ تاکہ میں ان کے گناہوں اور گناہوں کو معاف کر سکوں۔\n4۔ پھر یرمیاہ نے باروخ کو نریاہ کا بیٹا کہا: اور باروخ نے یرمیاہ کے منہ سے خداوند کے تمام الفاظ جو اس نے اس سے کہے تھے، ایک کتاب کے رول پر لکھے۔\n5۔ اور یرمیاہ نے باروخ کو حکم دیا، کہا، میں خاموش ہو جاؤ؛ میں خداوند کے گھر میں نہیں جا سکتا:\n6۔ تو جاؤ، اور اس فہرست میں پڑھو جو تم نے میرے منہ سے لکھا ہے، خداوند کے الفاظ لوگوں کے کانوں میں خداوند کے گھر میں روزے کے دن پڑھو، اور انہیں تمام یہوداہ کے کانوں میں پڑھو جو اپنے شہروں سے نکلتے ہیں۔\n7. ممکن ہے وہ اپنی دعا خداوند کے سامنے پیش کریں، اور ہر ایک کو اس کے برے راستے سے واپس لوٹیں: کیونکہ خداوند نے اس قوم کے خلاف جو غصہ اور غصہ نازل کیا ہے وہ بہت بڑا ہے۔ {وہ...: عبرانی۔ ان کی دعا ناکام ہو جائے گی}\n8۔ اور باروخ، نیریاہ کا بیٹا، نے یرمیاہ نبی کے حکم کے مطابق سب کچھ کیا، اور کتاب میں خداوند کے کلام کو خداوند کے گھر میں پڑھا۔\n9۔ اور یہویاکیم، یہوداہ کے بادشاہ یوسیاہ کے بیٹے کے پانچویں سال میں نویں مہینے میں یہ ہوا کہ انہوں نے خداوند کے حضور یروشلم کے تمام لوگوں اور یہوداہ کے شہروں سے یروشلم آنے والے تمام لوگوں کے سامنے روزہ رکھا۔\n10۔ پھر باروخ کو کتاب میں یرمیاہ کے الفاظ پڑھیں جو خداوند کے گھر میں، جماریاہ بیٹے شافان کاتب کے کمرے میں، اعلیٰ صحن میں، خداوند کے گھر کے نئے دروازے کے داخلے پر، تمام لوگوں کے کانوں میں۔ {اندراج: یا، دروازہ}\n11۔ جب میخایا، جماریاہ کا بیٹا، شافان کا بیٹا، نے کتاب سے خداوند کے تمام الفاظ سنے،\n12۔ پھر وہ بادشاہ کے گھر میں نیچے گیا، کاتب کے کمرے میں: اور دیکھو، تمام شہزادے وہاں بیٹھ گئے، حتیٰ کہ الیشاما کاتب، دلایا شمعیہ کا بیٹا، اور الناتھن ابن اخبور، جماریاہ شافان کا بیٹا، زدیقیاہ حنانیاہ کا بیٹا، اور تمام شہزادے۔\n13۔ پھر میکائیا نے انہیں وہ تمام الفاظ سنائے جو اس نے سنے تھے، جب باروخ نے لوگوں کے کانوں میں کتاب پڑھی۔\n14۔ اسی لیے تمام شہزادوں نے یہودی، نیتانیاہ کے بیٹے، شلیمیاہ کے بیٹے، کوشی کے بیٹے، باروخ کے پاس بھیجا، اور کہا، وہ رول اپنے ہاتھ میں لے لو جو تم نے لوگوں کے کانوں میں پڑھا ہے، اور آ جاؤ۔ تو باروخ، نیریاہ کے بیٹے، نے رول اپنے ہاتھ میں لیا اور ان کے پاس آیا۔\n15۔ اور انہوں نے اسے کہا، اب بیٹھ جاؤ اور ہمارے کانوں میں پڑھو۔ لہٰذا باروخ نے ان کے کانوں میں پڑھا۔\n16۔ اب ایسا ہوا، جب انہوں نے تمام الفاظ سن لیے، تو وہ ایک اور دوسرے سے ڈر گئے، اور باروخ سے کہا، ہم بادشاہ کو یہ سب باتیں ضرور بتائیں گے۔\n17۔ اور انہوں نے باروخ سے پوچھا، کہا، اب بتاؤ، تم نے یہ سب الفاظ اس کے منہ پر کیسے لکھے؟\n18۔ پھر باروخ نے ان کے جواب دیے، اس نے یہ سب الفاظ اپنے منہ سے مجھ سے کہے، اور میں نے انہیں کتاب میں سیاہی سے لکھا۔\n19۔ پھر شہزادوں نے باروخ سے کہا، جاؤ، تم اور یرمیاہ چھپ جاؤ؛ اور کسی کو معلوم نہ ہو کہ تم کہاں ہو۔\n20۔ اور وہ بادشاہ کے پاس دربار میں گئے، لیکن انہوں نے کاغذات الیشاما کاتب کے کمرے میں رکھ دیے، اور بادشاہ کے کانوں میں سب باتیں سنائیں۔\n21۔ تو بادشاہ نے جہودی کو رول لانے بھیجا: اور اس نے اسے الیشاما کاتب کے کمرے سے نکالا۔ اور یہودی نے اسے بادشاہ کے کانوں میں پڑھا، اور ان تمام شہزادوں کے کانوں میں جو بادشاہ کے ساتھ کھڑے تھے۔\n22۔ بادشاہ نویں مہینے میں ونٹر ہاؤس میں بیٹھا تھا: اور اس کے سامنے آگ جل رہی تھی۔\n23۔ اور ایسا ہوا کہ جب یہودی نے تین یا چار پتے پڑھے، تو اس نے قلم کی چھری سے اسے کاٹ کر آگ میں ڈال دیا جو آگ پر تھی، یہاں تک کہ سارا رول آگ میں جل گیا جو آگ پر تھی۔\n24۔ پھر بھی وہ خوفزدہ نہیں ہوئے، نہ ہی اپنے کپڑے پھاڑے، نہ بادشاہ، نہ ہی اس کے خادموں میں سے کوئی جس نے یہ سب باتیں سنیں۔\n25۔ پھر بھی ایلناتھن، دلایاہ اور جماریاہ نے بادشاہ سے سفارش کی کہ وہ رول نہ جلائے گا: لیکن وہ ان کی بات سننے کو تیار نہیں تھا۔\n26۔ لیکن بادشاہ نے حملیک کے بیٹے یرحمیل، عزریئل کے بیٹے سریعہ اور عبدیل کے بیٹے شلیمیاہ کو حکم دیا کہ وہ باروخ کاتب اور یرمیاہ نبی کو لے جائیں: لیکن خداوند نے انہیں چھپا لیا۔ {حملیک کا: یا، بادشاہ کا}\n27۔ پھر خداوند کا کلام یرمیاہ تک پہنچا، اس کے بعد بادشاہ نے رول جلا دیا، اور وہ الفاظ جو باروخ نے یرمیاہ کے منہ پر لکھے تھے، کہا،\n28۔ ایک اور رول لے لو، اور اس میں وہ تمام پہلے الفاظ لکھو جو پہلے رول میں تھے، جنہیں یہویاکیم، بادشاہ یہوداہ نے جلا دیا ہے۔\n29۔ اور تم یہوداہ کے بادشاہ یہویاکیم سے کہو گے، خداوند یوں فرماتا ہے؛ تم نے یہ رول جلا دیا ہے، اور کہا، تم نے اس میں کیوں لکھا ہے، کہ بابل کا بادشاہ ضرور آئے گا اور اس سرزمین کو تباہ کرے گا، اور وہاں سے انسان اور جانور کو روک دے گا؟\n30۔ لہٰذا یہوداہ کے بادشاہ یہویاکیم کے خداوند نے یوں فرمایا؛ اس کے پاس داؤد کے تخت پر بیٹھنے کے لیے کوئی نہیں ہوگا: اور اس کی لاش دن میں گرمی میں اور رات کو برف میں پھینکی جائے گی۔\n31۔ اور میں اسے، اس کی نسل اور اس کے خادموں کو ان کی بدکاری کی سزا دوں گا؛ اور میں ان پر، یروشلم کے باشندوں اور یہوداہ کے لوگوں پر وہ تمام برائی لاؤں گا جو میں نے ان کے خلاف سنا ہے؛ لیکن انہوں نے نہیں سنا۔ {سزا: عبرانی۔ ملاحظہ کریں}\n32۔ پھر اس نے یرمیاہ کو ایک اور رول لیا، اور اسے باروخ کاتب، نیریاہ کے بیٹے کو دے دیا؛ جس نے اس میں یرمیاہ کے منہ سے اس کتاب کے تمام الفاظ لکھے جو یہوداہ کے بادشاہ یہویاکیم نے آگ میں جلا دیے تھے: اور ان کے علاوہ کئی ایسے الفاظ بھی شامل کیے گئے۔ {جیسے: عبرانی۔ جیسا کہ وہ}","1۔ اور یوشیا کے بیٹے بادشاہ صدقیہ نے یہویاقیم کے بیٹے کونیاہ کی جگہ حکومت کی، جسے بابل کے بادشاہ نبوکدرز نے یہوداہ کی سرزمین میں بادشاہ بنایا۔\n2۔ لیکن نہ وہ، نہ اس کے بندوں نے، اور نہ ہی زمین کے لوگوں نے خداوند کے اس کلام کو سنا جو اس نے نبی یرمیاہ کے ذریعے کہے۔ {بذریعہ...: عبرانی۔ نبی کے ہاتھوں سے}\n3۔ اور صدقیہ بادشاہ نے یہوقال شلیمیاہ کے بیٹے اور زفانیاہ جو ماسیہ کا بیٹا کاہن تھا، نبی یرمیاہ کے پاس بھیجا، اور کہا، اب ہمارے لیے خداوند سے دعا کرو۔\n4۔ اب یرمیاہ لوگوں کے درمیان آیا اور باہر گیا، کیونکہ انہوں نے اسے قید میں نہیں ڈالا تھا۔\n5۔ پھر فرعون کی فوج مصر سے باہر آئی: اور جب کلدانی جو یروشلم کا محاصرہ کر رہے تھے ان کی خبر سنی، تو وہ یروشلم سے روانہ ہو گئے۔\n6۔ پھر خداوند کا کلام نبی یرمیاہ کو آیا، جس میں کہا گیا،\n7۔ خداوند اسرائیل کے خدا نے یوں فرمایا؛ اسی طرح تم یہوداہ کے بادشاہ سے کہو گے، جس نے تمہیں میرے پاس بھیجا ہے تاکہ مجھ سے پوچھو؛ دیکھو، فرعون کی فوج، جو تمہاری مدد کے لیے آئی ہے، مصر واپس آ رہی ہے، اپنے ملک میں۔\n8۔ اور کلدانی دوبارہ آئیں گے، اس شہر کے خلاف لڑیں گے، اسے فتح کریں گے، اور آگ سے جلا دیں گے۔\n9۔ خداوند یہ فرماتا ہے؛ اپنے آپ کو دھوکہ نہ دو، یہ نہ کہو، کلدانی ضرور ہم سے چلے جائیں گے، کیونکہ وہ نہیں جائیں گے۔ {آپ سب لوگ: عبوری۔ تمہاری روحیں}\n10۔ اگرچہ تم نے کلدانیوں کی پوری فوج کو مار دیا جو تم سے لڑ رہی تھی، اور ان میں زخمی لوگ باقی تھے، پھر بھی وہ اپنے خیمے میں موجود ہر آدمی کو اٹھا کر اس شہر کو آگ سے جلا دیں۔ {زخمی: عبرانی۔ تھرسٹ تھرو تھرو}\n11۔ اور ایسا ہوا کہ جب کلدانیوں کی فوج فرعون کی فوج کے خوف سے یروشلم سے توڑ دی گئی، {ٹوٹ گیا...: عبرانی۔ اوپر جانے کے لیے بنایا گیا}\n12۔ پھر یرمیاہ یروشلم سے نکل کر بنیامین کی سرزمین میں گیا، تاکہ وہاں سے لوگوں کے درمیان الگ ہو جائے۔ {الگ...: یا، لوگوں کے درمیان وہاں سے نکل جانا}\n13۔ اور جب وہ بنیامین کے دروازے پر تھا، تو وارڈ کا ایک کپتان وہاں تھا، جس کا نام اریاہ تھا، جو شلیمیاہ کا بیٹا تھا، حنانیاہ کا بیٹا؛ اور اس نے یرمیاہ نبی کو لے کر کہا، \"تو کلدانیوں کے ہاتھوں گر گیا ہے۔\"\n14۔ پھر یرمیاہ نے کہا، {یہ} جھوٹا ہے؛ میں کلدانیوں کے ہاتھوں نہیں گرتا۔ لیکن اس نے اس کی بات نہیں مانی: تو اریاہ نے یرمیاہ کو لے کر اسے شہزادوں کے پاس لے آیا۔ {غلط: عبوری۔ جھوٹ، یا، ایک جھوٹ}\n15۔ اسی لیے شہزادے یرمیاہ پر غصے میں آ گئے، اسے مارا اور یوناتھن کاتب کے گھر میں قید کر دیا، کیونکہ انہوں نے اسے قید خانہ بنا دیا تھا۔\n16۔ جب یرمیاہ کو تہہ خانے اور کیبنوں میں داخل کیا گیا، اور یرمیاہ وہاں کئی دن رہا؛ {کیبن: یا، سیلز}\n17۔ پھر صدقیہ بادشاہ نے بھیجا اور اسے باہر لے گیا، اور بادشاہ نے اپنے گھر میں چپکے سے پوچھا اور کہا، کیا خداوند کی طرف سے کوئی لفظ ہے؟ اور یرمیاہ نے کہا، ایک ہے: کیونکہ اس نے کہا، تم بابل کے بادشاہ کے ہاتھ میں دیے جاؤ گے۔\n18۔ مزید یہ کہ یرمیاہ نے بادشاہ صدقیاہ سے کہا، میں نے تمہارے خلاف، تمہارے بندوں کے خلاف یا اس قوم کے خلاف کیا جرم کیا ہے کہ تم نے مجھے قید میں ڈال دیا ہے؟\n19۔ اب کہاں ہیں تمہارے وہ نبی جنہوں نے تمہیں پیش گوئی کی تھی کہ بابل کا بادشاہ تمہارے خلاف نہیں آئے گا، نہ اس سرزمین پر؟\n20۔ لہٰذا اب سنو، اے میرے رب بادشاہ، میری التجا کو قبول کرے، میں دعا کرتا ہوں؛ کہ تم مجھے جوناتھن کاتب کے گھر واپس جانے سے روک دو، ورنہ میں وہاں مر جاؤں گا۔ {لیٹ...: عبوری۔ میری دعا کو گرا دو}\n21۔ پھر بادشاہ صدقیہ نے حکم دیا کہ وہ یرمیاہ کو قید خانے کے دربار میں بند کریں، اور روزانہ بیکرز کی گلی سے اسے روٹی کا ایک ٹکڑا دیں، جب تک کہ شہر کی ساری روٹی ختم نہ ہو جائے۔ یوں یرمیاہ قید خانے کے دربار میں ہی رہا۔","1۔ پھر شیفتیا، متان کا بیٹا، اور جدلیاہ پاشور کا بیٹا، اور یوکال شلیمیاہ کا بیٹا، اور پاشور ملکیا کا بیٹا، نے وہ الفاظ سنے جو یرمیاہ نے سب لوگوں سے کہے تھے، کہہ رہے تھے،\n2۔ خداوند یوں فرماتا ہے، جو اس شہر میں رہ جائے گا وہ تلوار، قحط اور وبا سے مرے گا؛ لیکن جو کلدانیوں کے پاس جائے گا وہ زندہ رہے گا؛ کیونکہ وہ اپنی جان شکار کے لیے رکھے گا، اور زندہ رہے گا۔\n3۔ خداوند یوں فرماتا ہے، یہ شہر یقینا بابل کے بادشاہ کی فوج کے ہاتھ میں دے دیا جائے گا، جو اسے لے گی۔\n4۔ لہٰذا شہزادوں نے بادشاہ سے کہا، ہم تم سے التجا کرتے ہیں کہ اس آدمی کو قتل کر دو، کیونکہ اس طرح وہ اس شہر میں باقی جنگجوؤں کے ہاتھ کمزور کر دیتا ہے، اور تمام لوگوں کے ہاتھوں کو بھی، جب وہ ان سے ایسی باتیں کرتے ہیں: کیونکہ یہ آدمی اس قوم کی بھلائی نہیں چاہتا،  لیکن تکلیف سے۔ {ویلفیئر: عبرانی۔ امن}\n5۔ پھر صدقیہ بادشاہ نے کہا، دیکھو، وہ تمہارے ہاتھ میں ہے: کیونکہ بادشاہ وہ تمہارے خلاف کچھ نہیں کر سکتا۔\n6۔ پھر انہوں نے یرمیاہ کو لے کر اسے ملکیا کے قید خانے میں پھینک دیا، جو ہملک کے بیٹے تھا، جو قید خانے کے صحن میں تھا، اور انہوں نے یرمیاہ کو رسیوں سے نیچے اتار دیا۔ اور قید خانے میں پانی نہیں تھا، صرف کیچڑ تھا: یوں یرمیاہ کیچڑ میں ڈوب گیا۔ {حملیک کا: یا، بادشاہ کا}\n7۔ اب جب ایبڈمیلخ، جو بادشاہ کے گھر میں ایک ایونک تھا، نے سنا کہ انہوں نے یرمیاہ کو قید خانے میں ڈال دیا ہے؛ بادشاہ جو اس وقت بنیامین کے دروازے پر بیٹھا تھا؛\n8۔ ایبیدملک بادشاہ کے گھر سے باہر نکلا اور بادشاہ سے کہا،\n9۔ میرے آقا بادشاہ، ان لوگوں نے یرمیاہ نبی کے ساتھ جو کچھ بھی کیا اس میں برا کیا ہے، جسے انہوں نے قید خانے میں پھینک دیا ہے؛ اور وہ اس جگہ بھوک کے لیے مرنے جیسا ہے: کیونکہ شہر میں اب روٹی نہیں رہی۔ {وہ کہتا ہے...: عببرانی۔ وہ مر جائے گا}\n10۔ پھر بادشاہ نے ایبڈمیلک ایتھوپین کو حکم دیا، کہا، یہاں سے تیس آدمیوں کو اپنے ساتھ لے آؤ، اور یرمیاہ نبی کو قید خانے سے نکال لو، اس سے پہلے کہ وہ مر جائے۔ {تمہارے ساتھ: عبرانی۔ تمہارے ہاتھ میں}\n11۔ تو ایبدمیلخ اپنے ساتھ مردوں کو لے گیا، اور خزانے کے نیچے بادشاہ کے گھر گیا، اور وہاں سے پرانے کاسٹ شدہ کپڑے اور پرانے سڑے ہوئے کپڑے لے کر انہیں رسیوں کے ذریعے قید خانے میں یرمیاہ کے پاس چھوڑ دیا۔\n12۔ اور ایبدملک حبوشی نے یرمیاہ سے کہا، اب یہ پرانے پھٹے ہوئے کپڑے اور سڑے ہوئے کپڑے اپنے بازوؤں کے نیچے رسیوں کے نیچے رکھ دو۔ اور جیریمیاہ نے ایسا ہی کیا۔\n13۔ تو انہوں نے یرمیاہ کو رسیوں سے باندھ کر قید خانے سے باہر نکالا، اور یرمیاہ قید خانے کے دربار میں ہی رہا۔\n14۔ پھر زدیقیاہ بادشاہ نے بھیجا، اور یرمیاہ نبی کو اپنے پاس لے گیا جو خداوند کے گھر میں تیسرے اندراج میں ہے: اور بادشاہ نے یرمیاہ سے کہا، میں تم سے ایک بات پوچھوں گا؛ مجھ سے کچھ نہ چھپاؤ۔ {تیسرا: یا، پرنسپل}\n15۔ پھر یرمیاہ نے صدقیاہ سے کہا، اگر میں تمہیں یہ اعلان کروں تو کیا تم مجھے قتل نہیں کرو گے؟ اور اگر میں تمہیں مشورہ دوں تو کیا تم میری بات نہیں سنو گے؟\n16۔ لہٰذا صدقیہ بادشاہ نے خفیہ طور پر یرمیاہ سے قسم کھائی، کہ {جیسا کہ خداوند زندہ ہے، جس نے ہمیں یہ روح بنائی، میں تمہیں موت نہیں دوں گا، نہ ہی تمہیں ان لوگوں کے ہاتھ میں دوں گا جو تیری جان چاہتے ہیں۔\n17۔ پھر یرمیاہ نے صدقیاہ سے کہا، خداوند فرماتا ہے، لشکروں کا خدا، اسرائیل کا خدا؛ اگر تم یقینی طور پر بابل کے بادشاہ کے شہزادوں کے پاس جاؤ گے، تو تمہاری روح زندہ رہے گی، اور یہ شہر آگ سے نہیں جلائے گا؛ اور تم زندہ رہو گے، اور تمہارا گھر:\n18۔ لیکن اگر تم بابل کے بادشاہ کے شہزادوں کے پاس نہیں جاؤ گے، تو یہ شہر کلدانیوں کے ہاتھ میں دے دیا جائے گا، اور وہ اسے آگ سے جلا دیں گے، اور تم ان کے ہاتھوں سے نہیں بچ سکو گے۔\n19۔ اور زدیقیاہ بادشاہ نے یرمیاہ سے کہا، میں ان یہودیوں سے ڈرتا ہوں جو کلدانیوں کے ہاتھوں گرے ہیں، ورنہ وہ مجھے اپنے ہاتھ میں دے دیں گے اور میرا مذاق اڑائیں گے۔\n20۔ لیکن یرمیاہ نے کہا، وہ تمہیں نجات نہیں دیں گے۔ خدا کی آواز مانو، جو میں تم سے کہتا ہوں: تاکہ وہ تمہارے لیے بھلائی ہو، اور تمہاری جان زندہ ہو۔\n21. لیکن اگر تم باہر جانے سے انکار کرو تو یہی وہ کلام ہے جو خداوند نے مجھے دکھایا ہے:\n22۔ اور دیکھو، یہوداہ کے بادشاہ کے گھرانے میں باقی تمام عورتیں بابل کے بادشاہ کے شہزادوں کے پاس لائی جائیں گی، اور وہ عورتیں کہیں گی، تمہارے دوستوں نے تمہیں چڑھایا اور تم پر غالب آ گئے: تمہارے قدم کیچڑ میں دھنس گئے ہیں، اور وہ پیچھے ہٹ گئے ہیں۔ {تمہارے دوست: عبرانی۔ تیرے امن کے مردو}\n23۔ تو وہ تمہاری تمام بیویوں اور بچوں کو کلدانیوں کے پاس لے آئیں گے: اور تم ان کے ہاتھوں سے نہیں نکل سکو گے، بلکہ بابل کے بادشاہ کے ہاتھوں پکڑے جاؤ گے: اور تم اس شہر کو آگ سے جلا دو گے۔ {تو وجہ بناؤ گے...: عبرانی۔ تم جلاؤ گے، وغیرہ}\n24۔ پھر صدقیاہ نے یرمیاہ سے کہا، کوئی ان باتوں کو نہ جانے، ورنہ تم نہیں مرو گے۔\n25۔ لیکن اگر شہزادے سن لیں کہ میں نے تم سے بات کی ہے، اور وہ تمہارے پاس آ کر کہیں، اب ہمیں وہ بتاؤ جو تم نے بادشاہ سے کہی ہے، ہم سے نہ چھپاؤ، اور ہم تمہیں قتل نہیں کریں گے؛ اور بادشاہ نے تم سے کیا کہا:\n26۔ پھر تم ان سے کہو گے، میں نے بادشاہ کے سامنے اپنی دعا پیش کی ہے کہ وہ مجھے جوناتھن کے گھر واپس جانے اور وہاں مرنے پر مجبور نہیں کرے گا۔\n27۔ پھر تمام شہزادے یرمیاہ کے پاس آئے اور اس سے پوچھا: اور اس نے بادشاہ کے حکم کردہ تمام الفاظ کے مطابق انہیں بتایا۔ لہٰذا انہوں نے اس سے بات کرنا چھوڑ دیا؛ کیونکہ معاملہ سمجھا نہیں گیا۔ {وہ...: عبرانی۔ وہ اس سے خاموش تھے}\n28۔ تو یرمیاہ قید خانے کے دربار میں اس دن تک مقیم رہا جب یروشلم پر قبضہ کیا گیا: اور وہ {وہاں} تھا جب یروشلم پر قبضہ کیا گیا۔","1۔ یہوداہ کے بادشاہ زدقیاہ کے نویں سال میں، دسویں مہینے میں، بابل کا بادشاہ نبوکدرز اور اس کی تمام فوج یروشلم کے خلاف آیا، اور انہوں نے اسے محاصرہ کر لیا۔\n2. {اور} صدقیاہ کے گیارہویں سال میں، چوتھے مہینے، مہینے کے نویں {دن} میں، شہر کو تقسیم کر دیا گیا۔\n3۔ اور بابل کے بادشاہ کے تمام شہزادے اندر آئے، اور درمیان کے دروازے میں بیٹھ گئے، حتیٰ کہ نرگلشارزر، سمگارنیبو، سرسیخم، ربساریس، نرگلشارزر، ربماگ، بابل کے بادشاہ کے تمام باقیات کے ساتھ۔\n4۔ اور ایسا ہوا کہ جب یہوداہ کے بادشاہ زدقیاہ نے انہیں اور تمام جنگجوؤں کو دیکھا، تو وہ بھاگ گئے، اور رات کو شہر سے باہر نکل گئے، بادشاہ کے باغ کے راستے، دو دیواروں کے درمیان دروازے سے، اور وہ میدان کے راستے سے نکل گیا۔\n5۔ لیکن کلدانیوں کی فوج نے ان کا پیچھا کیا اور یریحو کے میدانوں میں زدقیاہ کو پکڑ لیا: اور جب انہوں نے اسے پکڑ لیا تو اسے بابل کے بادشاہ نبوکدنضر کے پاس لے گئے، جو ہامات کی سرزمین میں ربلہ میں تھا، جہاں اس نے اس پر فیصلہ سنایا۔ {دیا گیا...: عببرانی۔ اس سے بات کی، فیصلے}\n6۔ پھر بابل کے بادشاہ نے ربلہ میں زدقیاہ کے بیٹوں کو اپنی آنکھوں کے سامنے قتل کر دیا: اور بابل کے بادشاہ نے یہوداہ کے تمام اشرافیہ کو بھی قتل کر دیا۔\n7۔ اس کے علاوہ اس نے زدیقیاہ کی آنکھیں نکال دیں اور اسے زنجیروں سے باندھ کر بابل لے گیا۔ {ساتھ...: عبوری۔ دو بریزن چینز، یا بیٹرز کے ساتھ}\n8۔ اور کلدانیوں نے بادشاہ کے گھر اور لوگوں کے گھروں کو آگ سے جلا دیا اور یروشلم کی دیواریں توڑ دیں۔\n9۔ پھر محافظوں کے کپتان نبوزاردان نے شہر میں باقی ماندہ لوگوں کے باقیات کو قیدی میں بابل لے آیا، اور جو لوگ گر گئے، وہ بھی اس کے ہاتھوں گرے، باقی باقی لوگوں کے ساتھ۔ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف دی ایگزیکیوشنرز، یا سلاٹرمین}\n10۔ لیکن نبوزاردان محافظ نے غریبوں کو چھوڑ دیا، جن کے پاس کچھ نہیں تھا، یہوداہ کی سرزمین میں، اور انہیں ایک ہی وقت میں انگور کے باغات اور کھیت دیے۔ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف دی ایگزیکیوشنرز، یا، سلاٹرمین} {پر...: عبرانی اس دن}\n11۔ اب بابل کے بادشاہ نبوکدرز نے یرمیاہ کے بارے میں گارڈ کے کپتان نبوزارادان کو ذمہ داری دی اور کہا، {عبرانی۔ {کپتان...: یا، چیف مارشل: عبرانی کے ہاتھوں چیف آف دی ایگزیکیوشنرز، یا سلاٹرمین}\n12۔ اسے پکڑو، اس پر غور کرو، اور اسے نقصان نہ پہنچاؤ؛ بلکہ اس کے ساتھ ویسا ہی کرو جیسا وہ تمہیں کہے گا۔ {دیکھیں...: عبوری۔ اپنی نظریں اس پر مرکوز کرو}\n13۔ تو نبوزارادان گارڈ کے کپتان نے بھیجا، اور نیبوشاسبان، ربساریس، نرگلشارزر، ربماگ، اور بابل کے تمام بادشاہ شہزادے؛ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف دی ایگزیکیوشنرز، یا سلاٹرمین}\n14۔ انہوں نے بھی بھیجا اور یرمیاہ کو قید خانے کے دربار سے باہر نکالا، اور اسے گڈالیا، جو احیقام کے بیٹے شافان کا بیٹا تھا، کے حوالے کر دیا تاکہ وہ اسے گھر لے جائے: یوں وہ لوگوں کے درمیان رہا۔\n15۔ اب خداوند کا کلام یرمیاہ کے پاس آیا، جب وہ قید خانے کی عدالت میں بند تھا، اور کہا،\n16۔ جاؤ اور ایبدیملک ایتھوپین سے بات کرو، کہو، یوں فرماتا ہے لشکروں کے رب، اسرائیل کا خدا؛ دیکھو، میں اپنے الفاظ اس شہر پر برائی کے لیے لاؤں گا، بھلائی کے لیے نہیں؛ اور وہ اس دن تمہارے سامنے {کامیاب} ہوں گے۔\n17. لیکن میں اسی دن تمہیں نجات دوں گا، خداوند فرماتا ہے: اور تم ان لوگوں کے ہاتھ میں نہیں دیے جاؤ گے جن سے تم ڈرتے ہو۔\n18۔ کیونکہ میں ضرور تمہیں نجات دوں گا، اور تم تلوار سے نہیں گرو گے، بلکہ تمہاری جان تمہارے لیے شکار ہوگی: کیونکہ تم نے مجھ پر بھروسہ کیا ہے، خداوند فرماتا ہے۔","1۔ وہ کلام جو خداوند کی طرف سے یرمیاہ کو آیا، اس کے بعد کہ نبوزارادان محافظ نے اسے رامہ سے آزاد کر دیا، جب اس نے اسے زنجیروں میں باندھ کر یروشلم اور یہوداہ کے قیدیوں میں باندھ کر بابل لے جایا گیا۔ {زنجیریں: یا، منیکلز}\n2۔ اور محافظوں کے کپتان نے یرمیاہ کو لے کر کہا، خداوند تیرے خدا نے یہ برائی اس جگہ پر نازل کی ہے۔\n3۔ اب خداوند نے اسے لایا ہے، اور جیسا کہ اس نے کہا ویسا ہی کیا: کیونکہ تم نے خداوند کے خلاف گناہ کیا اور اس کی آواز نہیں مانی، اس لیے یہ چیز تم پر آ گئی ہے۔\n4. اور اب، دیکھو، میں آج تمہیں ان زنجیروں سے آزاد کرتا ہوں جو {تمہارے} ہاتھ پر تھیں۔ اگر تمہیں اچھا لگے کہ میرے ساتھ بابل آؤ، تو آؤ؛ اور میں تمہیں اچھی طرح دیکھوں گا: لیکن اگر تمہیں میرے ساتھ بابل میں آنا برا لگے تو صبر کرو: دیکھو، ساری زمین تمہارے سامنے ہے: جہاں تمہارے لیے جانا اچھا اور موزوں لگے، وہاں جاؤ۔ {تھے...: یا، تمہارے ہاتھ پر ہیں} {میں کروں گا...: عبرانی۔ میں اپنی نظر تم پر ڈالوں گا}\n5۔ اب جب وہ ابھی واپس نہیں گیا، {اس نے کہا}، تو پھر واپس جدلیاہ کے پاس جاؤ، جو احیکم کا بیٹا ہے، شافان کا بیٹا، جسے بابل کے بادشاہ نے یہوداہ کے شہروں کا گورنر بنایا ہے، اور اس کے ساتھ لوگوں کے درمیان رہو: یا جہاں چاہو وہاں جاؤ۔ تو گارڈ کے کپتان نے اسے خوراک اور انعام دیا، اور اسے جانے دیا۔\n6۔ پھر یرمیاہ احیکم کے بیٹے گدلیاہ کے پاس مزپا گیا؛ اور اس کے ساتھ ان لوگوں کے درمیان رہا جو زمین میں رہ گئے۔\n7۔ اب جب کھیتوں میں موجود تمام فوجوں کے کپتان، حتیٰ کہ وہ اور ان کے آدمی بھی، نے سنا کہ بابل کے بادشاہ نے جیڈالیا کو احیکم کے بیٹے کو زمین کا گورنر بنا دیا ہے، اور اس کے پاس مردوں، عورتوں، بچوں اور زمین کے غریبوں کو، جو نہیں لے جائے، انہیں بابل قید کر دیا ہے؛\n8۔ پھر وہ گدالیہ کے پاس مزپا کے پاس آئے، یہاں تک کہ نیثنیا کا بیٹا اسماعیل، اور کاریہ کے بیٹے یوحنان اور یوناتھن، اور تنہومیت کے بیٹے سریاہ، اور ایفائی نیتوفحیوں کے بیٹے، اور یزانیا جو ایک ماحاتی کا بیٹا تھا، وہ اور ان کے لوگ آئے۔\n9۔ اور گڈالیا، احیکم کا بیٹا، شافان کا بیٹا، ان سے اور ان کے آدمیوں سے قسم کھاتا ہے، کہتا ہے: کلدانیوں کی خدمت سے نہ ڈرو، زمین میں رہو اور بابل کے بادشاہ کی خدمت کرو، اور یہ تمہارے لیے خوش ہوگا۔\n10۔ جہاں تک میرا تعلق ہے، دیکھو، میں مزپا میں رہوں گا تاکہ کلدانیوں کی خدمت کروں، جو ہمارے پاس آئیں گے: لیکن تم شراب، گرمیوں کے پھل، تیل جمع کرو، اور انہیں اپنے برتنوں میں ڈالو، اور اپنے قبضے کے اپنے شہروں میں رہو۔ {خدمت کرنے کے لیے: عبرانی۔ سامنے کھڑے ہونے کے لیے}\n11۔ اسی طرح جب موآب، عمونیوں میں، اور ایڈوم میں، اور تمام ملکوں میں موجود تمام یہودیوں نے سنا کہ بابل کے بادشاہ نے یہوداہ کی باقیات چھوڑ دی ہیں، اور اس نے ان پر احیکم کے بیٹے شافان کے بیٹے گدلیاہ کو مقرر کر دیا ہے؛\n12۔ یہاں تک کہ تمام یہودی بھی ہر جگہ سے واپس آئے جہاں انہیں نکالا گیا تھا، اور یہوداہ کی زمین، جدلیہ، مزپا آئے، اور شراب اور گرمیوں کے پھل بہت جمع کیے۔\n13۔ مزید برآں، کریہ کا بیٹا یوحنان، اور کھیتوں میں موجود تمام فوجوں کے کپتان گدلیاہ کے پاس مزپا آئے،\n14۔ اور اس سے کہا، کیا تم جانتے ہو کہ عمونیوں کے بادشاہ بعلس نے تمہیں قتل کرنے کے لیے اسماعیل بھیجا ہے؟ لیکن گدالیا، احیکم کا بیٹا، ان پر یقین نہ کر سکا۔ {قتل کرنے کے لیے...: عبرانی۔ تمہیں روح میں مارنے کے لیے؟}\n15۔ پھر یوحنان نے قریع کے بیٹے گدلیاہ سے مزپا میں خفیہ طور پر کہا، \"مجھے جانے دو، میں تم سے دعا کرتا ہوں، اور میں نیتھنیا کے بیٹے اسماعیل کو قتل کر دوں گا، اور کوئی نہیں جانے گا: وہ تمہیں کیوں مارے، تاکہ تمہارے پاس جمع ہونے والے تمام یہودی بکھر جائیں اور یہوداہ میں باقی ماندہ لوگ ہلاک ہو جائیں؟\n16۔ لیکن گدلیاہ ابن احیکام نے یوحنان کے کاریہ کے بیٹے سے کہا، تم یہ کام نہ کرو گے، کیونکہ تم اسماعیل کے بارے میں جھوٹ بولتے ہو۔","1۔ ساتویں مہینے میں یہ ہوا کہ} اسماعیل نیثنیا کا بیٹا الیشامہ کا بیٹا، جو بادشاہ کی نسل سے تھا، اور بادشاہ کے شہزادے، حتیٰ کہ دس آدمی اس کے ساتھ تھے، احیکم کے بیٹے گدلیاہ کے پاس مزپا آئے؛ اور وہاں وہ مزپا میں اکٹھے روٹی کھاتے تھے۔\n2۔ پھر اسماعیل نیثانیاہ کا بیٹا اور اس کے ساتھ موجود دس آدمی اٹھے اور خاہیکم کے بیٹے گدالیاہ کو تلوار سے مارا اور اسے قتل کر دیا، جسے بابل کے بادشاہ نے زمین کا گورنر بنایا تھا۔\n3۔ اسماعیل نے اپنے ساتھ موجود تمام یہودیوں کو بھی مار ڈالا، {حتیٰ کہ} جدلیاہ کے ساتھ، مزپا میں، اور وہاں پائے جانے والے کلدانیوں کو، {اور} جنگی مردوں کو۔\n4۔ اور یہ واقعہ اس دن ہوا جب اس نے گدلیاہ کو قتل کیا، اور کسی کو معلوم نہ ہوا،\n5۔ کہ شیخم، شیلوہ، اور سامریہ سے یقینا چالیس آدمی آئے، اپنی داڑھیاں منڈوا کر، کپڑے پھاڑ کر، اور خود کو کاٹ کر، ہاتھ میں نذرانے اور لوبان لے کر، تاکہ انہیں خداوند کے گھر لے آئیں۔\n6۔ اور اسماعیل نیتانیاہ کا بیٹا مزپا سے ان سے ملنے نکلا، راستے میں روتا رہا: اور جب اس نے ان سے ملاقات کی تو اس نے کہا، \"آؤ گدلیاہ کے پاس آؤ، جو احیکم کا بیٹا ہے۔ {روتے ہوئے...: عبرانی ان گو اینڈ ویپنگ}\n7۔ اور جب وہ شہر کے بیچ میں پہنچے، تو نیتھنیا کے بیٹے اسماعیل نے انہیں قتل کر دیا، {اور انہیں گڑھے کے بیچ میں پھینک دیا}، وہ اور اس کے ساتھ موجود لوگ بھی۔\n8۔ لیکن ان میں سے دس آدمی ملے جنہوں نے اسماعیل سے کہا، 'ہمیں مت مارو'، کیونکہ ہمارے پاس کھیت میں گندم، جو، تیل اور شہد کے خزانے ہیں۔ لہٰذا اس نے انہیں ان کے بھائیوں میں سے نہیں مارا۔\n9۔ اب وہ گڑھا جس میں اسماعیل نے ان مردوں کی تمام لاشیں پھینکی تھیں، جنہیں اس نے گدلیاہ کی وجہ سے مارا تھا، وہی تھا جو بادشاہ آسا نے اسرائیل کے بادشاہ بعشا سے ڈرنے کے لیے بنایا تھا: اور نیتانیاہ کے بیٹے اسماعیل نے اسے ان لوگوں سے بھر دیا جو مارے گئے تھے۔ {کیونکہ...: یا، گدالیا کے قریب: عبرانی۔ ہاتھ سے، یا، گدالیاہ کے پہلو سے}\n10۔ پھر اسماعیل نے مزپا میں موجود تمام لوگوں کی باقیات کو قید کر لیا، حتیٰ کہ بادشاہ کی بیٹیاں، اور وہ سب لوگ جو مزپا میں باقی تھے، جنہیں نبوزارادان نے محافظوں کے سردار نے احیکم کے بیٹے گدالیا کے حوالے کیا تھا: اور اسماعیل نیثانیاہ کے بیٹے نے انہیں قید کر لیا اور عمونیوں کے پاس روانہ ہو گیا۔\n11۔ لیکن جب یوحنان، کاریاہ کا بیٹا، اور اس کے ساتھ موجود تمام فوجوں کے کپتانوں نے سنا کہ نیتھنیا کے بیٹے اسماعیل نے کتنی برائیاں کی تھیں،\n12۔ پھر انہوں نے تمام آدمیوں کو لے کر نیتھانیا کے بیٹے اسماعیل کے ساتھ لڑائی کے لیے نکلے، اور اسے گبعون کے عظیم پانیوں کے کنارے پایا۔\n13۔ اب یہ ہوا کہ {وہ} جب تمام لوگ جو اسماعیل کے ساتھ تھے، انہوں نے یوحنان کاریہ کے بیٹے اور اس کے ساتھ موجود تمام فوجوں کے کپتانوں کو دیکھا، تو وہ خوش ہوئے۔\n14۔ تو وہ تمام لوگ جنہیں اسماعیل نے مزپا سے قید کیا تھا، ادھر ادھر بھاگ گئے اور واپس لوٹ آئے اور یوحنان کے بیٹے کاریہ کے پاس چلے گئے۔\n15۔ لیکن اسماعیل نیتانیاہ کا بیٹا آٹھ آدمیوں کے ساتھ یوحنان سے فرار ہو کر عمونیوں کے پاس گیا۔\n16۔ پھر اس نے یوحنان، کاریاہ کا بیٹا، اور اس کے ساتھ موجود تمام فوجوں کے کپتانوں کو لے لیا، تمام باقیات جو اس نے نیتھنیا کے بیٹے اسماعیل سے حاصل کی تھیں، مزپا سے، اس کے بعد اس نے احیکم کے بیٹے گڈالیا، حتیٰ کہ طاقتور جنگجوؤں، عورتوں اور بچوں کو قتل کر دیا،  اور خواجہ سرا، جنہیں وہ دوبارہ گبعون سے لایا تھا:\n17۔ اور وہ روانہ ہو گئے، اور بیت لحم کے قریب چمہام کی بستی میں بس گئے تاکہ مصر میں داخل ہو سکیں،\n18۔ کلدانیوں کی وجہ سے: کیونکہ وہ ان سے ڈرتے تھے، کیونکہ نیتھنیا کے بیٹے اسماعیل نے احیکم کے بیٹے گدلیاہ کو قتل کر دیا تھا، جسے بابل کے بادشاہ نے زمین کا گورنر بنایا تھا۔","1۔ پھر فوجوں کے تمام کپتان، یوحنان کریہ کا بیٹا، اور یزانیا ہوشیا کا بیٹا، اور سب سے چھوٹے سے لے کر سب سے بڑے تک، قریب آئے،\n2۔ اور یرمیاہ نبی سے کہا، ہم آپ سے التجا کرتے ہیں کہ ہماری دعا آپ کے سامنے قبول کی جائے، اور ہمارے لیے خداوند اپنے خدا سے دعا کریں، {حتیٰ کہ} کہ یہ سب باقی ماندہ ہے؛ (کیونکہ ہم رہ گئے ہیں {لیکن} بہت سے میں سے چند ہیں، جیسا کہ تیری آنکھیں ہمیں دیکھتی ہیں :) {آؤ...: یا، ہماری دعا تمہارے سامنے آ جائے}\n3. تاکہ خداوند تیرا خدا ہمیں راستہ دکھائے جس میں ہم چل سکتے ہیں، اور وہ کام جو ہم کر سکتے ہیں۔\n4۔ پھر یرمیاہ نبی نے ان سے کہا، میں نے آپ کو سنا ہے؛ دیکھو، میں تمہارے خدا سے تمہارے الفاظ کے مطابق دعا کروں گا؛ اور یہ ہو جائے گا، {کہ} خداوند جو بھی جواب دے گا، میں تمہیں اس کا اعلان کروں گا؛ میں تم سے کچھ بھی نہیں چھپاؤں گا۔\n5۔ پھر انہوں نے یرمیاہ سے کہا، خداوند ہمارے درمیان سچا اور وفادار گواہ بنو، اگر ہم ان تمام چیزوں کے مطابق نہ بھی ہوں جن کے لیے خداوند تیرا خدا تمہیں ہمارے پاس بھیجے گا۔\n6۔ چاہے وہ اچھا ہو یا برا، ہم خداوند ہمارے خدا کی آواز کی اطاعت کریں گے، جس کے پاس ہم تمہیں بھیجتے ہیں؛ تاکہ جب ہم خداوند اپنے خدا کی آواز کی اطاعت کریں تو ہمارے ساتھ اچھا ہو۔\n7۔ اور دس دن بعد ہوا کہ خداوند کا کلام یرمیاہ تک پہنچا۔\n8۔ پھر اس نے یوحنان کو کاریاہ کا بیٹا کہا، اور ان تمام فوجوں کے کپتانوں کو جو اس کے ساتھ تھے، اور تمام لوگ چھوٹے سے بڑے تک،\n9۔ اور میں نے ان سے کہا، یہی فرماتا ہے، خداوند اسرائیل کا خدا، جس کے سامنے تم نے مجھے اپنی دعا پیش کرنے کے لیے بھیجا ہے؛\n10۔ اگر تم اب بھی اس زمین میں رہو گے، تو میں تمہیں تعمیر کروں گا، اور تمہیں نیچے نہیں کھینچوں گا، اور تمہیں نہیں نکالوں گا: کیونکہ میں اس برائی پر توبہ کرتا ہوں جو میں نے تمہارے ساتھ کی ہے۔\n11۔ بابل کے بادشاہ سے مت ڈرو، جس سے تم ڈرتے ہو؛ اس سے مت ڈرو، خداوند فرماتا ہے: کیونکہ میں تمہارے ساتھ ہوں تاکہ تمہیں بچا سکوں، اور تمہیں اس کے ہاتھ سے نجات دوں۔\n12۔ اور میں تم پر رحم کروں گا تاکہ وہ تم پر رحم کرے اور تمہیں تمہاری سرزمین واپس لے جائے۔\n13۔ لیکن اگر تم کہو کہ ہم اس زمین میں نہیں رہیں گے، نہ ہی خداوند تمہارے خدا کی آواز کی اطاعت کریں گے،\n14۔ کہانی، نہیں؛ لیکن ہم مصر کی سرزمین میں جائیں گے، جہاں نہ جنگ دیکھیں گے، نہ بگل کی آواز سنیں گے، نہ روٹی کی بھوک ہوگی۔ اور وہیں ہم رہیں گے:\n15۔ اور اب خداوند کا کلام سنو، اے یہوداہ کے باقیات؛ یوں لشکروں کے رب، اسرائیل کے خدا فرماتا ہے؛ اگر آپ مکمل طور پر مصر میں داخل ہونے کے لیے اپنے چہرے لگا دیں، اور وہاں قیام کے لیے جائیں؛\n16۔ پھر یہ ہو جائے گا کہ وہ تلوار، جس سے تم ڈرتے تھے، تمہیں مصر کی سرزمین میں پکڑ لے گی، اور قحط، جس سے تم ڈرتے تھے، تمہارے پیچھے مصر میں آئے گا؛ اور وہیں تم مر جاؤ گے۔ {بعد میں آئے گا...: عبرانی۔ تمہارے پیچھے چڑھ جائے گا}\n17. اسی طرح ان تمام مردوں کے ساتھ جو اپنا چہرہ لگا کر مصر میں قیام کے لیے جائیں گے؛ وہ تلوار، قحط اور وبا سے مر جائیں گے: اور ان میں سے کوئی بھی اس برائی سے بچ نہیں پائے گا جو میں ان پر لاؤں گا۔ {تو...: عبرانی۔ تمام مرد بھی ایسا ہی کریں گے}\n18۔ کیونکہ ایسا فرماتا ہے لشکروں کے رب، اسرائیل کے خدا؛ جیسے میرا غصہ اور غصہ یروشلم کے باشندوں پر بہہ گیا ہے؛ اسی طرح میرا غصہ تم پر نازل ہوگا، جب تم مصر میں داخل ہو گے: اور تم ایک ذلیل، حیرت، لعنت اور ملامت بنو گے؛ اور تم اس جگہ کو دوبارہ نہیں دیکھو گے۔\n19۔ خداوند نے تمہارے بارے میں کہا ہے، اے یہوداہ کے باقیات؛ تم مصر میں مت جاؤ: جان لو کہ میں نے آج تمہیں نصیحت کی ہے۔ {تنبیہ...: عبرانی۔ تمہارے خلاف گواہی دی}\n20۔ کیونکہ تم نے اپنے دلوں میں دھوکہ دیا جب تم نے مجھے اپنے خداوند خدا کے پاس بھیجا، اور کہا، ہمارے لیے خداوند ہمارے خدا سے دعا کرو؛ اور جیسا کہ خداوند ہمارے خدا کہے گا، اس کے مطابق ہمیں اعلان کرو، اور ہم یہ کریں گے۔ {تم نے دھوکہ دیا...: یا، تم نے اپنی روحوں کے خلاف دھوکہ دیا ہے}\n21. اور {اب} میں نے یہ دن آپ کے سامنے اعلان کیا ہے؛ لیکن تم نے خداوند تمہارے خدا کی آواز نہیں مانی، اور نہ ہی کسی بھی چیز کی جس کے لیے اس نے مجھے تمہارے پاس بھیجا ہے۔\n22۔ اب جان لو کہ تم تلوار، قحط اور وبا سے مر جاؤ گے، اس جگہ جہاں تم جانا چاہتے ہو {اور} قیام کے لیے۔ {جانے کے لیے...: یا، سفر پر جانے کے لیے}","1۔ اور ایسا ہوا، {کہ} جب یرمیاہ نے تمام لوگوں سے خداوند ان کے خدا کے تمام الفاظ بولنا بند کر دیا، جن کے لیے خداوند ان کے خدا نے انہیں بھیجا تھا، {حتیٰ کہ} یہ تمام الفاظ،\n2۔ پھر عزریاہ ہوشایا کا بیٹا، یوحنان کاریہ کا بیٹا، اور تمام مغرور لوگوں نے یرمیاہ سے کہا، تو جھوٹ بولتے ہو: خداوند ہمارے خدا نے تمہیں یہ کہنے کے لیے نہیں بھیجا، مصر میں مت جا کر وہاں قیام کرو:\n3۔ لیکن باروخ نیریاہ کا بیٹا تمہیں ہمارے خلاف بٹھاتا ہے، تاکہ ہمیں کلدانیوں کے ہاتھ میں دے دے، تاکہ وہ ہمیں قتل کر دیں اور قیدیوں کو بابل لے جائیں۔\n4۔ یوں یوحنان کاریاہ کا بیٹا، اور فوج کے تمام کپتان اور تمام لوگ، خداوند کی آواز کی اطاعت نہیں کرتے کہ وہ یہوداہ کی سرزمین میں بسیں۔\n5۔ لیکن یوحنان کاریاہ کا بیٹا اور فوج کے تمام کپتانوں نے یہوداہ کے تمام باقیات کو جو تمام قوموں سے واپس آئے تھے، جہاں سے نکالا گیا تھا، یہوداہ کی سرزمین میں بسنے کے لیے لے گئے؛\n6۔ حتیٰ کہ مرد، عورتیں، بچے، بادشاہ کی بیٹیاں، اور ہر وہ شخص جو نبوزاردان محافظ کے پاس گیا تھا، اس کے ساتھ گدلیاہ بیٹا احیکم کا بیٹا، شافان کا بیٹا، یرمیاہ نبی، اور باروخ نیریاہ کا بیٹا تھا۔\n7۔ تو وہ مصر کی سرزمین میں آئے: کیونکہ انہوں نے خداوند کی آواز نہیں مانی: یوں وہ تہپانس تک پہنچے۔\n8۔ پھر خداوند کا کلام یرمیاہ کو تہپانس میں آیا، جس میں کہا گیا،\n9۔ اپنے ہاتھ میں بڑے پتھر پکڑو، اور انہیں مٹی میں بھٹی میں چھپا دو، جو فرعون کے گھر کے دروازے پر تہپانیس میں ہے، یہوداہ کے لوگوں کی نظر میں؛\n10۔ اور ان سے کہو، یہی فرماتا ہے لشکروں کے رب، اسرائیل کا خدا؛ دیکھو، میں بابل کے بادشاہ نبوکدرز کو بھیجوں گا اور لے جاؤں گا، جو میرا خادم ہے، اور اس کا تخت ان پتھروں پر رکھوں گا جو میں نے چھپائے ہیں؛ اور وہ ان پر اپنا شاہی پویلین پھیلائے گا۔\n11۔ اور جب وہ آئے گا، تو وہ مصر کی سرزمین کو مارے گا، {اور جو موت کے لیے ہیں} کو موت کے لیے آزاد کرے گا؛ اور ایسے {جو ہیں} قید سے قید کے لیے؛ اور وہ {جو ہیں} تلوار سے تلوار کے لیے۔\n12۔ اور میں مصر کے دیوتاؤں کے گھروں میں آگ جلاؤں گا؛ اور وہ انہیں جلا دے گا، اور قیدی لے جائے گا: اور وہ مصر کی سرزمین کے ساتھ صف بندی کرے گا، جیسے چرواہا اپنے لباس پر پہنتا ہے؛ اور وہ وہاں سے امن کے ساتھ باہر جائے گا۔\n13۔ وہ بیت شمش کی تصاویر بھی توڑے گا، جو مصر کی سرزمین میں ہے؛ اور مصریوں کے دیوتاؤں کے گھروں کو آگ سے جلایا جائے گا۔ {تصاویر: عبرانی۔ مجسمے، یا، کھڑے ہوئے مجسمے} {بیت شمش: یا، سورج کا گھر}","1۔ وہ کلام جو یرمیاہ کو آیا، ان تمام یہودیوں کے بارے میں جو مصر کی سرزمین میں رہتے ہیں، جو مگدول، تہپانس، نوف اور پاتھروس کے ملک میں رہتے ہیں، اور کہا،\n2. ایسا فرماتا ہے رب لشکروں، اسرائیل کا خدا؛ تم نے وہ تمام برائی دیکھی ہے جو میں نے یروشلم اور یہوداہ کے تمام شہروں پر لائی ہے؛ اور دیکھو، آج وہ ویران ہیں، اور کوئی انسان وہاں نہیں رہتا،\n3۔ ان کی بدکاری کی وجہ سے جو انہوں نے مجھے غصہ دلانے کے لیے کی ہے، کہ وہ لوبان جلانے گئے، {اور} دوسرے دیوتاؤں کی خدمت کرنے گئے، جنہیں وہ نہیں جانتے تھے، نہ وہ، نہ تم، نہ تمہارے باپ اجداد۔\n4۔ تاہم میں نے تم کے پاس اپنے تمام بندوں کو نبی بھیجے، جو صبح سویرے اٹھ کر بھیجے اور کہا، اوہ، یہ مکروہ کام نہ کرو جس سے میں نفرت کرتا ہوں۔\n5۔ لیکن انہوں نے اپنی برائی سے منہ موڑنے کے لیے کان نہیں سنے، اور دوسرے دیوتاؤں کو دھوپ نہ جلانے کی کوشش کی۔\n6۔ اسی لیے میرا غصہ اور غصہ یہوداہ کے شہروں اور یروشلم کی گلیوں میں بھڑک اٹھا؛ اور وہ ضائع ہو چکے ہیں {اور} ویران، جیسا کہ آج کے دن ہے۔\n7۔ لہٰذا اب خداوند یہی فرماتا ہے، لشکروں کا خدا، اسرائیل کا خدا؛ اسی لیے تم اپنی روحوں پر یہ عظیم برائی کرتے ہو، کہ تم سے مرد و عورت، بچے اور دودھ پلانے والے کو یہوداہ سے الگ کر دو، اور تمہیں کوئی باقی نہ رہے؛ {باہر...: عببرانی۔ یہوداہ کے درمیان سے باہر}\n8۔ کہ تم مجھے اپنے ہاتھوں کے اعمال سے غصہ دلاتے ہو، مصر کی سرزمین میں دوسرے دیوتاؤں کے لیے خوشبو جلاتے ہو، جہاں تم چلے جاتے ہو، تاکہ تم خود کو کاٹ سکو، اور زمین کی تمام قوموں میں لعنت اور ملامت بن سکو؟\n9۔ کیا تم اپنے باپ اجداد کی برائی، یہوداہ کے بادشاہوں کی بدکاری، ان کی بیویوں کی بدکاری، اپنی بدکاری، اور اپنی بیویوں کی بدکاری کو بھول گئے ہو، جو انہوں نے یہوداہ کی سرزمین اور یروشلم کی گلیوں میں کی ہیں؟ {برائی...: عبرانی۔ برائیاں، یا، سزائیں وغیرہ}\n10۔ وہ آج تک عاجز نہیں ہوئے، نہ ہی میرے قانون اور نہ ہی میرے قوانین میں چلے، جو میں نے آپ اور آپ کے آباؤ اجداد کے سامنے رکھے۔ {عاجزی کے ساتھ: عبرانی۔ پچھتاو}\n11۔ لہٰذا لشکروں کے رب، اسرائیل کے خدا نے یوں فرمایا؛ دیکھو، میں تمہارے خلاف برائی کے لیے اپنا چہرہ لگا دوں گا، اور یہوداہ کو کاٹنے کے لیے۔\n12۔ اور میں یہوداہ کے باقیات کو، جنہوں نے مصر کی سرزمین میں قیام کے لیے رخ کیا ہے، لے جاؤں گا، اور وہ سب نگل جائیں گے، {اور} مصر کی سرزمین میں گر جائیں گے؛ وہ تلوار سے اور قحط سے بھی ختم ہو جائیں گے: وہ مریں گے، سب سے چھوٹے سے لے کر سب سے بڑے تک، تلوار اور قحط سے: اور وہ ایک ذلیل، حیرت، لعنت، اور ملامت ہوں گے۔\n13۔ کیونکہ میں ان لوگوں کو سزا دوں گا جو مصر کی سرزمین میں بستے ہیں، جیسے میں نے یروشلم کو تلوار، قحط اور وبا سے سزا دی ہے:\n14۔ تاکہ یہوداہ کے باقیات میں سے کوئی بھی، جو مصر کی سرزمین میں وہاں قیام کے لیے گئے ہیں، فرار نہ ہو سکیں اور نہ ہی رک سکیں، تاکہ وہ یہوداہ کی سرزمین میں واپس جائیں، جہاں وہ واپس جانا چاہتے ہیں، کیونکہ کوئی واپس نہیں جائے گا سوائے ان کے جو بچ نکلے۔ {have...: عبرانی ان کی روح کو اٹھاؤ}\n15۔ پھر وہ تمام مرد جو جانتے تھے کہ ان کی بیویوں نے دوسرے دیوتاؤں کے لیے لوبان جلا دیا ہے، اور تمام عورتیں جو کھڑی تھیں، ایک بڑی تعداد میں، حتیٰ کہ مصر کی سرزمین پاتھروس میں رہنے والے تمام لوگ، یرمیاہ نے جواب دیا،\n16. {جہاں تک} وہ کلام ہے جو تم نے خداوند کے نام پر ہم سے کہا ہے، ہم تمہاری بات نہیں سنیں گے۔\n17۔ لیکن ہم یقینا جو کچھ بھی اپنے منہ سے نکلے گا، کریں گے، آسمان کی ملکہ کو خوشبو جلانا، اور اس کے لیے شراب کی قربانیاں ڈالنا، جیسا کہ ہم نے، اپنے باپ-اجداد، بادشاہوں، اور اپنے شہزادوں، یہوداہ کے شہروں اور یروشلم کی گلیوں میں کیا: کیونکہ {تب} ہمارے پاس کافی خوراک تھی،  اور وہ ٹھیک تھے، اور کوئی برائی نہیں دیکھی۔ {ملکہ...: یا، آسمان کا فریم} {ویچوئلز: عبرانی۔ روٹی}\n18. لیکن جب سے ہم نے آسمان کی ملکہ کو لوبان جلانے اور اس پر شراب ڈالنے کے لیے روانہ ہوئے، ہم نے سب کچھ چاہا، اور تلوار اور قحط نے نگل لیے ہیں۔\n19۔ اور جب ہم نے آسمان کی ملکہ کے لیے خوشبو جلائی، اور اس کے لیے شراب کی نذرانہ ڈالی، کیا ہم نے اس کی عبادت کے لیے کیک بنائے اور اپنے مردوں کے بغیر اس کے لیے شراب کی قربانیاں نذرانے پیش کیں؟ {مرد: یا، شوہر؟}\n20۔ پھر یرمیاہ نے سب لوگوں، مردوں، عورتوں اور ان سب لوگوں سے کہا جنہوں نے اسے یہ جواب دیا تھا، کہا،\n21۔ وہ لوبان جو تم نے یہوداہ کے شہروں اور یروشلم کی گلیوں میں جلایا، تم، تمہارے باپ، بادشاہوں، شہزادوں، اور اس ملک کے لوگ، کیا خداوند نے انہیں یاد نہیں رکھا اور اسے اپنے ذہن میں نہیں لایا؟\n22. تاکہ خداوند تمہارے اعمال کی برائیوں کی وجہ سے مزید برداشت نہ کر سکے، {اور} ان گناہوں کی وجہ سے جو تم نے کی ہیں؛ لہٰذا تمہاری زمین ویرانی، حیرت اور لعنت ہے، بغیر کسی باشندے کے، جیسا کہ آج ہے۔\n23۔ کیونکہ تم نے لوبان جلائی، اور خدا کے خلاف گناہ کیا، اور نہ تو خدا کی آواز مانی، نہ اس کے قانون میں، نہ اس کے قوانین میں، نہ اس کی گواہوں میں چلے؛ لہٰذا یہ برائی آپ کے ساتھ ہوئی ہے، جیسا کہ آج کے دن ہے۔\n24۔ مزید یہ کہ یرمیاہ نے تمام لوگوں اور تمام عورتوں سے کہا، خداوند کا کلام سنو، تمام یہوداہ جو مصر کی سرزمین میں ہیں:\n25۔ یوں لشکروں کے رب، اسرائیل کے خدا فرماتے ہیں؛ تم اور تمہاری بیویوں نے دونوں نے اپنے منہ سے بات کی، اور اپنے ہاتھ سے پورا کیا، کہا، ہم ضرور اپنے وعدے پورے کریں گے جو ہم نے عہد کیے ہیں، آسمان کی ملکہ کو لوبان جلائیں گے، اور اس پر شراب کی نذریں ڈالیں گے: تم یقینا اپنی قسمیں پوری کرو گے، اور اپنی قسمیں پوری کرو گے۔\n26۔ لہٰذا خداوند کا کلام سنو، تمام یہوداہ جو مصر کی سرزمین میں بستے ہیں؛ دیکھو، میں نے اپنے عظیم نام کی قسم کھائی ہے، خداوند فرماتا ہے، کہ میرا نام اب یہوداہ کے کسی بھی آدمی کے منہ میں پورے مصر کی سرزمین میں نہیں رکھا جائے گا، اور کہا، خداوند خدا زندہ ہے۔\n27۔ دیکھو، میں ان کی حفاظت برائی کے لیے کروں گا، نہ کہ بھلائی کے لیے: اور یہوداہ کے تمام لوگ جو مصر کی سرزمین میں ہیں، تلوار اور قحط سے نگل جائیں گے، یہاں تک کہ ان کا خاتمہ ہو جائے۔\n28۔ لیکن جو چند لوگ تلوار سے بچ نکلیں گے وہ مصر کی سرزمین سے یہوداہ کی سرزمین میں واپس جائیں گے، اور یہوداہ کے تمام باقیات جو مصر کی سرزمین میں قیام کے لیے گئے ہیں، جان جائیں گے کہ کس کے الفاظ قائم ہوں گے، میرے یا ان کے۔ {میرا...: عبرانی۔ مجھ سے، یا ان سے}\n29۔ اور یہ تمہارے لیے ایک نشانی ہوگی، خداوند فرماتا ہے، کہ میں تمہیں اس جگہ سزا دوں گا، تاکہ تم جان سکو کہ میرے الفاظ تمہارے خلاف برائی کے لیے کھڑے ہوں گے:\n30. خداوند یہ فرماتا ہے؛ دیکھو، میں مصر کے بادشاہ فرعون ہوفرا کو اس کے دشمنوں کے ہاتھ میں اور ان کے ہاتھ میں دوں گا جو اس کی جان چاہتے ہیں؛ جیسے میں نے یہوداہ کے بادشاہ زدقیاہ کو بابل کے بادشاہ نبوکدرز کے ہاتھ میں دیا، جو اس کا دشمن تھا، اور جس نے اس کی جان مانگی۔","1۔ وہ کلام جو یرمیاہ نبی نے باروخ، نیریاہ کے بیٹے سے کہے، جب اس نے یہ الفاظ یرمیاہ کے منہ پر ایک کتاب میں لکھا، یہویاقیم کے چوتھے سال میں یہوداہ کے بادشاہ یوسیاہ کے بیٹے، اور کہا،\n2. ایسا فرماتا ہے، اے باروخ، خداوند اسرائیل کے خدا، تجھے کہتا ہے؛\n3. تم نے کہا، اب میری حالت ہائ! کیونکہ خداوند نے میرے غم میں غم بھی شامل کر دیا ہے؛ میں آہ بھرتے ہوئے بے ہوش ہو گیا، اور مجھے سکون نہیں ملا۔\n4. تو تو اس سے یوں کہنا ہے، خداوند فرماتا ہے؛ دیکھو، {وہ} جو میں نے بنایا ہے، وہ میں ٹوٹ جائے گا، اور جو میں نے لگایا ہے اسے میں اٹھاؤں گا، یہاں تک کہ یہ پوری زمین بھی۔\n5۔ اور کیا تم اپنے لیے بڑی چیزیں تلاش کرتے ہو؟ ان کی تلاش نہ کرو، کیونکہ دیکھو، میں ہر انسان پر برائی لاؤں گا، خداوند فرماتا ہے: لیکن تمہاری جان میں تمہیں شکار کے طور پر ہر جگہ دوں گا جہاں تم جاؤ گے۔","1۔ خداوند کا کلام جو یرمیاہ نبی کو غیر یہودیوں کے خلاف آیا؛\n2۔ مصر کے خلاف، مصر کے بادشاہ فرعون نیکو کی فوج کے خلاف، جو دریائے فرات کے کنارے کارشمش میں تھی، جسے بابل کے بادشاہ نبوکدرز نے یہویا بادشاہ یوشع کے بیٹے کے چوتھے سال میں مارا تھا۔\n3۔ بکلر اور ڈھال کا حکم دو، اور جنگ کے قریب آؤ۔\n4۔ گھوڑوں کو ہارنس کرنا؛ اور اٹھو، اے گھڑ سواروں کو، اور اپنے ہیلمٹ کے ساتھ آگے بڑھو؛ نیزے تیار کرو، {اور} بریگنڈائنز پہناؤ۔\n5. میں نے انہیں مایوس کیوں دیکھا ہے {اور} واپس موڑ لیا گیا ہے؟ اور ان کے طاقتور لوگ شکست کھا جاتے ہیں، تیزی سے بھاگ جاتے ہیں، اور پیچھے مت دیکھتے ہیں: {کیونکہ} خوف کے ارد گرد تھا، خداوند فرماتا ہے۔ {شکست خوردہ...: عبرانی۔ ٹکڑوں میں ٹوٹا ہوا} {فرار ہو گیا...: عبرانی۔ ایک فلائٹ سے فرار ہو گیا}\n6. تیز رفتار کو بھاگنے نہ دو، نہ ہی طاقتور آدمی کو بھاگنے دو؛ وہ لڑکھڑائیں گے، اور دریائے فرات کے کنارے شمال کی طرف گریں گے۔\n7. یہ کون ہے جو سیلاب کی طرح آتا ہے، جس کے پانی دریا کی طرح بہتے ہیں؟\n8۔ مصر سیلاب کی طرح اٹھتا ہے، اور اس کے پانی دریاؤں کی طرح بہتے ہیں؛ اور وہ کہتا ہے، میں اوپر جاؤں گا، {اور} زمین کو ڈھانپ دوں گا؛ میں شہر اور اس کے باشندوں کو تباہ کر دوں گا۔\n9. اوپر آؤ، اے گھوڑے؛ اور غصہ، اے رتھیں؛ اور طاقتور لوگ باہر آ جائیں؛ ایتھوپین اور لیبیائی، جو ڈھال سنبھالتے ہیں؛ اور لیدیئنز، جو کمان کو موڑتے ہیں۔ {ایتھوپینز: عبرانی۔ کش} {لیبیائی: عبرانی۔ Put}\n10۔ کیونکہ یہ خداوند خدا لشکروں کا دن ہے، انتقام کا دن، تاکہ وہ اپنے دشمنوں کا بدلہ لے سکے: اور تلوار کھا جائے گی، اور ان کے خون سے سیر اور مست ہو جائے گی: کیونکہ لشکروں کے خداوند خدا نے شمالی علاقے میں دریائے فرات کے کنارے قربانی دی ہے۔\n11۔ گلیڈ میں چڑھ جاؤ، اور مرہم لو، اے کنواری مصر کی بیٹی: تم بہت سی دوائیں بے سود استعمال کرو گی؛ {کیونکہ} تم شفا نہیں پاؤ گے۔ {تم چاہو گے...: عبرانی۔ تمہیں کوئی علاج نہیں ملے گا}\n12۔ قوموں نے تمہاری شرمندگی سن لی ہے، اور تمہاری پکار زمین کو بھر گئی ہے: کیونکہ طاقتور آدمی طاقتوروں کے خلاف ٹھوکر کھا گیا، {اور} دونوں ایک ساتھ گر گئے۔\n13۔ وہ کلام جو خداوند نے یرمیاہ نبی سے کہا، کہ بابل کا بادشاہ نبوکدرز آئے گا {اور} مصر کی سرزمین پر حملہ کرے گا۔\n14. مصر میں اعلان کرو، میگدول میں شائع کرو، اور نوف اور تہپانس میں شائع کرو: کہو، مضبوط رہو اور تیار رہو؛ کیونکہ تلوار تمہارے گرد کھا جائے گی۔\n15. تمہارے بہادر {مرد} کیوں بہہ گئے؟ وہ کھڑے نہیں ہوئے، کیونکہ خداوند نے انہیں مجبور کیا۔\n16۔ اس نے بہت سے لوگوں کو گرایا، ہاں، ایک دوسرے پر گرا: اور انہوں نے کہا، اٹھو، اور ہم اپنے لوگوں کے پاس واپس جائیں، اور اپنی پیدائش کی سرزمین پر، ظالم تلوار سے۔ {بنا...: عبرانی گرنے والوں کو ضرب دی گئی}\n17۔ انہوں نے وہاں پکارا، فرعون مصر کا بادشاہ {یہ صرف ایک آواز ہے}؛ اس نے مقررہ وقت گزار لیا ہے۔\n18. {جیسا کہ میں زندہ ہوں}، بادشاہ فرماتا ہے، جس کا نام {ہے} رب لشکروں کا، یقینا جیسے تابور {ہے} پہاڑوں میں اور سمندر کے کنارے کرمل کی طرح، {ویسے} وہ آئے گا۔\n19۔ اے مصر میں رہنے والی بیٹی، خود کو قید میں جانے کے لیے تیار کرو: کیونکہ نوف ویران اور ویران ہو جائے گا بغیر کسی باشندے کے۔ {فرنش...: عبرانی۔ قید کے اوزار بناؤ}\n20. مصر {ایک بہت خوبصورت گائے کی طرح} ہے، {لیکن} تباہی آتی ہے؛ یہ شمال سے آتا ہے۔\n21۔ اس کے کرائے کے آدمی بھی اس کے درمیان موٹے بیلوں کی طرح ہیں؛ کیونکہ وہ بھی واپس پلٹ گئے، {اور} ایک ساتھ بھاگ گئے: وہ کھڑے نہیں ہوئے، کیونکہ ان کی آفت کا دن ان پر آ گیا، {اور} ان کی آمد کا وقت۔ {موٹا...: عبرانی۔ اسٹال کے بیلے}\n22۔ اس کی آواز سانپ کی طرح جائے گی؛ کیونکہ وہ فوج کے ساتھ مارچ کریں گے، اور کلہاڑیوں کے ساتھ اس کے خلاف آئیں گے، جیسے لکڑی کاٹنے والے۔\n23. وہ اس کا جنگل کاٹ دیں گے، خداوند فرماتا ہے، اگرچہ اسے تلاش نہیں کیا جا سکتا؛ کیونکہ وہ صرف ٹڈیوں سے بڑھ کر ہیں، اور {ہیں} بے شمار ہیں۔\n24۔ مصر کی بیٹی کو الجھا دیا جائے گا؛ اسے شمال کے لوگوں کے ہاتھ میں دے دیا جائے گا۔\n25۔ لشکروں کا رب، اسرائیل کا خدا، فرماتا ہے؛ دیکھو، میں نو، فرعون، اور مصر کی اکثریت کو ان کے دیوتاؤں اور بادشاہوں کے ساتھ سزا دوں گا؛ یہاں تک کہ فرعون بھی، اور {تمام} وہ لوگ جو اس پر بھروسہ کرتے ہیں: {کثرت: یا، پرورش دینے والا: عبرانی۔ امون}\n26۔ اور میں انہیں ان لوگوں کے ہاتھ میں دوں گا جو اپنی جان چاہتے ہیں، اور بابل کے بادشاہ نبوکدرز کے ہاتھ میں، اور اس کے بندوں کے ہاتھ میں: اور بعد میں یہ آباد ہوگا، جیسا کہ پرانے زمانے میں تھا، خداوند فرماتا ہے۔\n27۔ لیکن اے میرے خادم یعقوب، ڈرو مت، اور اے اسرائیل، خوفزدہ نہ ہو، کیونکہ دیکھو، میں تمہیں دور سے اور تیری نسل کو ان کی قید کی سرزمین سے بچاؤں گا؛ اور یعقوب واپس آئے گا، آرام کرے گا، اور کوئی اسے خوفزدہ نہیں کرے گا۔\n28. اے یعقوب میرے بندے، ڈر مت، خداوند فرماتا ہے: کیونکہ میں تیرے ساتھ ہوں؛ کیونکہ میں ان تمام قوموں کا مکمل خاتمہ کروں گا جہاں میں نے تمہیں نکالا ہے: لیکن میں تمہیں مکمل انجام نہیں دوں گا، بلکہ تمہیں درست کروں گا؛ پھر بھی میں تمہیں مکمل طور پر بغیر سزا کے نہیں چھوڑوں گا۔ {نہ چھوڑیں...: یا، مکمل طور پر آپ کو کاٹ نہ دیں}","1۔ خداوند کا کلام جو یرمیاہ نبی کو فلسطینیوں کے خلاف آیا، اس سے پہلے کہ فرعون غزہ پر حملہ کرے۔ {غزہ: عبرانی۔ عزا}\n2۔ خداوند یوں فرماتا ہے؛ دیکھو، شمال سے پانی اٹھتا ہے، اور ایک سیلاب بہہ جاتا ہے، جو زمین اور اس میں موجود سب کچھ بہہ جاتا ہے؛ شہر، اور اس میں رہنے والے لوگ: تب لوگ چیخیں گے، اور زمین کے تمام باشندے چیخیں گے۔ {یہ سب...: عبرانی۔ اس کی مکمل شدت}\n3۔ اس کے مضبوط گھوڑوں کے کھروں کی ٹھوکر کی آواز، اس کے رتھوں کی دوڑ، اور اس کے پہیوں کی گڑگڑاہٹ پر، باپ اپنے بچوں کی کمزوریوں کی وجہ سے پیچھے نہیں دیکھیں گے؛\n4۔ اس دن کی وجہ سے جو تمام فلسطینیوں کو برباد کرے گا، {اور} ٹائرس اور زیدون سے باقی بچا ہوا ہر مددگار کو کاٹ دے گا: کیونکہ خداوند فلسطینیوں کو، جو کفتور کے ملک کے باقیات ہیں، لوٹ کرے گا۔ {ملک: عبرانی دی آئل}\n5. گنج پن غزہ پر آ گیا؛ اشکلون ان کی وادی کے باقیات سے کٹ گیا ہے: کتنی دیر تک تم خود کو کاٹتے رہو گے؟\n6. اے خداوند کی تلوار، کب تک خاموش رہو گے؟ اپنے غلاف میں خود کو رکھو، آرام کرو، اور خاموش رہو۔ {put...: عبدی۔ اپنے آپ کو سنبھالو}\n7۔ یہ کیسے خاموش ہو سکتا ہے، جب کہ خداوند نے اسے اشکلون اور سمندر کے کنارے پر الزام دیا ہے؟ وہیں اس نے اسے مقرر کیا ہے۔ {کیسے...: عبرانی تم کیسے کر سکتے ہو}","1. موآب کے خلاف یوں فرماتا ہے رب لشکروں، اسرائیل کا خدا؛ نیبو پر افسوس! کیونکہ یہ خراب ہو چکا ہے: کریاتھائم حیران ہے {اور} پکڑا گیا ہے: مسگاب حیران اور پریشان ہے۔ {مسگاب: یا، اونچی جگہ}\n2. {موآب کی مزید تعریف نہیں ہوگی}: ہیشبون میں انہوں نے اس کے خلاف برائی کی سازش کی؛ آؤ، اور اسے قوم بننے سے کاٹ دیں۔ اور تم بھی مارے جاؤ گے، اے پاگلوں؛ تلوار تمہارا پیچھا کرے گی۔ {کٹ جائیں...: یا، خاموش ہو جاؤ} {تعاقب...: عبرانی تمہارے پیچھے جاؤ}\n3۔ ہورنائم سے ایک چیخ و پکار کی آواز، برباد کرنے والی اور بڑی تباہی۔\n4. موآب تباہ ہو جاتا ہے؛ اس کے ننھے بچوں نے ایک چیخ سنائی دی ہے۔\n5۔ کیونکہ لوہیت کی چڑھائی میں مسلسل رونا اوپر جائے گا؛ کیونکہ ہورونائم کے زوال کے دوران دشمنوں نے تباہی کی چیخ سنی ہے۔ {مسلسل...: عبرانی۔ روتے ہوئے رونا}\n6. بھاگ جاؤ، اپنی جان بچاؤ، اور جنگل کی زمین کی طرح بنو۔ {دی ہیتھ: یا، ایک ننگا درخت}\n7۔ کیونکہ چونکہ تم نے اپنے اعمال اور خزانے پر بھروسہ کیا ہے، تم بھی پکڑے جاؤ گے: اور کیموش اپنے پادریوں اور شہزادوں کے ساتھ قید میں جائے گا۔\n8۔ اور برباد کرنے والا ہر شہر پر آئے گا، اور کوئی شہر بچ نہیں پائے گا: وادی بھی تباہ ہو جائے گی، اور میدان تباہ ہو جائے گا، جیسا کہ خداوند نے فرمایا۔\n9۔ موآب کو پر دے دو، تاکہ وہ بھاگ جائے اور بھاگ جائے: کیونکہ اس کے شہر ویران ہو جائیں گے، وہاں رہنے والا کوئی نہیں ہوگا۔\n10۔ لعنت زدہ {ہو} جو خداوند کے کام کو دھوکہ دے کر کرتا ہے، اور لعنت زدہ {ہو} وہ جو اپنی تلوار کو خون سے بچاتا ہے۔ {دھوکہ دہی: یا، لاپرواہی سے}\n11۔ موآب اپنی جوانی سے ہی پرسکون ہے، اور اس نے اپنی لیز پر سکون حاصل کیا ہے، نہ ایک برتن سے دوسرے برتن میں خالی ہوا، نہ ہی قید میں گیا؛ اس لیے اس کا ذائقہ اس میں رہا، اور اس کی خوشبو نہیں بدلی۔ {باقی ماندہ: عبوری۔ کھڑا ہوا}\n12۔ لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں اس کے پاس آوارہ بھیجوں گا، جو اسے بھٹکنے پر مجبور کریں گے، اس کے برتن خالی کریں گے، اور ان کی بوتلیں توڑ دیں گے۔\n13۔ اور موآب کموش سے شرمندہ ہوگا، جیسے اسرائیل کے گھر کو بیت ال کے اعتماد پر شرمندہ تھا۔\n14. آپ کیا کہتے ہیں، ہم جنگ کے لیے طاقتور اور طاقتور لوگ ہیں؟\n15۔ موآب خراب ہو چکا ہے، اور اس کے شہروں سے اوپر چلا گیا ہے، اور اس کے منتخب نوجوان قتل عام کے لیے نیچے جا چکے ہیں، بادشاہ کہتا ہے، جس کا نام لشکروں کا رب ہے۔ {اس کا...: عبرانی دی چوائس}\n16۔ موآب کی آفت قریب ہے، اور اس کی مصیبت تیزی سے آتی ہے۔\n17۔ جو بھی اس کے گرد ہے، اس پر افسوس کرو؛ اور جو سب اس کا نام جانتے ہیں، کہو، مضبوط عصا کیسے ٹوٹ گئی، {اور} خوبصورت چھڑی!\n18۔ اے بیٹی جو دیبون میں رہتی ہے، اپنی شان سے اتر آؤ اور پیاس میں بیٹھو؛ کیونکہ موآب کا بگاڑنے والا تم پر آئے گا، {اور} وہ تمہارے مضبوط قلعے تباہ کر دے گا۔\n19۔ اے آروئر کے باشندے، راستے پر کھڑے ہو جاؤ اور جاسوسی کرو؛ اس سے پوچھو جو بھاگتی ہے، اور جو بھاگتی ہے، {اور} پوچھو، کیا ہوا؟ {رہائشی: عبرانی۔ آبادکار}\n20۔ موآب الجھن میں ہے؛ کیونکہ یہ ٹوٹ چکا ہے: چیخنا اور چیخنا؛ آرنون میں بتاؤ کہ موآب خراب ہو چکا ہے،\n21۔ اور فیصلہ میدان پر آتا ہے؛ ہولون پر، اور جہازہ پر، اور میفاتھ پر،\n22۔ اور دیبون پر، نیبو پر، اور بیت دیبلتھیم پر،\n23۔ اور کریاتایم، بیت گمول پر، اور بیت میون پر،\n24۔ اور کیریوت پر، بوزرہ پر، اور موآب کی سرزمین کے تمام شہروں پر، دور یا قریب۔\n25. موآب کا سینگ کاٹ دیا جاتا ہے، اور اس کا بازو ٹوٹ جاتا ہے، خداوند فرماتا ہے۔\n26۔ اسے نشے میں ڈال دو: کیونکہ اس نے خود کو خداوند کے خلاف بڑایا: موآب بھی اپنی قے میں ڈوب جائے گا، اور وہ بھی مذاق میں ہوگا۔\n27۔ کیا اسرائیل تمہارے لیے مذاق نہیں تھا؟ کیا وہ چوروں کے درمیان پایا گیا؟ کیونکہ جب سے تم نے اس کے بارے میں بات کی، خوشی سے چھلانگ لگائی۔ {skippedst...: یا، خود کو حرکت دی}\n28. اے موآب میں رہنے والو، شہروں کو چھوڑ دو، اور چٹان میں بسو اور اس کبوتر کی طرح بنو جو گڑھے کے منہ کے کناروں میں اپنا گھونسلہ بناتی ہے۔\n29۔ ہم نے موآب کے غرور کو سنا ہے، (وہ حد سے زیادہ مغرور ہے)، اس کی بلندی، اس کی تکبر، اس کی تکبر، اور اس کے دل کی تکبر۔\n30. میں اس کے غضب کو جانتا ہوں، خداوند فرماتا ہے؛ لیکن {ایسا نہیں ہوگا}؛ اس کے جھوٹ اس پر اثر نہیں کریں گے۔ {اس کے جھوٹ...: یا، وہ جن پر وہ رہتا ہے (عبرانی۔ اس کی بارز) صحیح نہیں ہوتی}\n31۔ لہٰذا میں موآب کے لیے چیخ پکاروں گا، اور تمام موآب کے لیے پکاروں گا؛ {میرا دل} کرہیرس کے لوگوں کے لیے سوگ منائے گا۔\n32۔ اے سبمہ کی بیل، میں یازر کے رونے سے تیرے لیے روؤں گا: تیرے پودے سمندر کے پار جا چکے ہیں، وہ یازر کے سمندر تک پہنچ گئے ہیں: خراب کرنے والا تمہارے موسم گرما کے پھلوں اور تمہاری شکار پر گر گیا ہے۔\n33۔ اور خوشی اور خوشی فراوان کھیت اور موآب کی زمین سے لی جاتی ہے؛ اور میں نے شراب کو شراب کے پریس سے گرا دیا ہے: کوئی چیخ و پکار کے ساتھ قدم نہیں رکھے گا؛ ان کی چیخ و پکار نہیں ہوگی۔\n34۔ ہیشبون کی پکار {حتی} سے لے کر ایلعلہ تک، {اور حتیٰ کہ} جہاز تک، انہوں نے اپنی آواز نکالی، زوار {حتی} سے حتیٰ کہ ہورونایم تک، {جیسے} تین سالہ گائے کی طرح: کیونکہ نمرم کے پانی بھی ویران ہوں گے۔ {ویران آواز: عبرانی۔ ویرانی}\n35. مزید برآں، میں موآب میں رک جاؤں گا، خداوند فرماتا ہے، جو اونچی جگہوں پر پیش کرتا ہے، اور جو اپنے دیوتاؤں کے لیے لوبان جلاتا ہے۔\n36۔ اسی لیے میرا دل موآب کے لیے پائپ کی طرح بجے گا، اور میرا دل کیرہیرس کے لوگوں کے لیے پائپوں کی طرح بجے گا: کیونکہ جو دولت اس نے حاصل کی ہے وہ ختم ہو گئی۔\n37۔ ہر سر گنجا ہوگا، اور ہر داڑھی کٹی ہوگی: تمام ہاتھوں پر کٹائی اور کمر پر تھیلی کے کپڑے ہوں گے۔ {کٹا ہوا: ہیب۔ کم ہو گیا}\n38. {موآب کے تمام گھروں کی چھتوں اور ان کی گلیوں پر عمومی طور پر نوحہ ہوگا} کیونکہ میں نے موآب کو ایسے توڑ دیا ہے جیسے کوئی برتن جس میں کوئی خوشی نہیں، خداوند فرماتا ہے۔\n39۔ وہ چیخیں گے، {کہیں}، یہ کیسے ٹوٹا ہوا ہے! موآب نے شرمندگی سے کیسے پیٹھ موڑی! اسی طرح موآب ان سب کے لیے مذاق اور مایوسی کا باعث بنے گا۔ {واپس: عبوری۔ گردن}\n40۔ کیونکہ خداوند یہ فرماتا ہے؛ دیکھو، وہ عقاب کی طرح اڑے گا، اور موآب پر اپنے پر پھیلائے گا۔\n41۔ کیریوت پر قبضہ ہو جاتا ہے، اور قلعے حیران رہ جاتے ہیں، اور اس دن موآب میں طاقتور مردوں کے دل ایک عورت کے درد میں دل کی طرح ہوں گے۔ {کیریوتھ: یا، شہر}\n42. اور موآب کو قوم بننے سے تباہ کر دیا جائے گا، کیونکہ اس نے خود کو خداوند کے خلاف بڑھا دیا ہے۔\n43. خوف، اور گڑھا اور جال، تم پر ہوں گے، اے موآب کے باشندے، خداوند فرماتا ہے۔\n44۔ جو خوف سے بھاگے گا وہ گڑھے میں گر جائے گا؛ اور جو گڑھے سے نکلے گا اسے جال میں لے جایا جائے گا: کیونکہ میں موآب پر ان کی آمد کا سال بھی لاؤں گا، خداوند فرماتا ہے۔\n45۔ جو لوگ بھاگے وہ ہشبون کے سائے تلے کھڑے رہے کیونکہ وہ طاقت کی وجہ سے کھڑے رہے: لیکن ہیشبون سے آگ نکلے گی، اور سیہون کے بیچ سے شعلہ نکلے گا، جو موآب کے کونے اور ہنگامہ آرائی کرنے والوں کے سر کے تاج کو نگل جائے گی۔ {ہنگامہ خیز...: عبرانی۔ شور کے بچے}\n46. اے موآب، تم پر افسوس ہو! کیموش کے لوگ ہلاک ہو جاتے ہیں: کیونکہ تمہارے بیٹے قید ہو جاتے ہیں اور تمہاری بیٹیاں قید ہو جاتی ہیں۔ {قیدی، اور: عبرانی۔ قید میں، وغیرہ}\n47. پھر بھی میں موآب کی قید کو آخری دنوں میں دوبارہ لاؤں گا، خداوند فرماتا ہے۔ اب تک {یہ} موآب کا فیصلہ ہے۔","1۔ عمونیوں کے بارے میں، خداوند فرماتا ہے؛ کیا اسرائیل کے کوئی بیٹے نہیں؟ کیا اس کا کوئی وارث نہیں؟ تو پھر ان کا بادشاہ گاد کا وارث کیوں ہے، اور اس کے لوگ اس کے شہروں میں کیوں رہتے ہیں؟ {تشویشناک: یا، خلاف} {ان کا بادشاہ: یا، میلکوم}\n2. لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں عمونیوں کے ربا میں جنگ کی خبر سناؤں گا؛ اور یہ ایک ویران ڈھیر ہوگا، اور اس کی بیٹیاں آگ میں جل جائیں گی: پھر اسرائیل ان وارثوں کا وارث ہوگا جو اس کے وارث تھے، خداوند فرماتا ہے۔\n3. اے ہیشبون، چیخ کر چلاؤ، کیونکہ عائی خراب ہو چکا ہے: اے رباح کی بیٹیاں، پکار جاؤ، تمہیں بور کے کپڑے سے باندھو؛ افسوس کرتا ہے، اور جھاڑیوں کے کنارے ادھر ادھر بھاگتا ہے؛ کیونکہ ان کا بادشاہ قید میں جائے گا، {اور} اس کے پادری اور اس کے شہزادے مل کر۔ {ان کا بادشاہ: یا، میلکوم}\n4. کیوں تم وادیوں میں سب سے زیادہ جلال پاتی ہو، اپنی بہتی ہوئی وادی، اے پیچھے ہٹنے والی بیٹی؟ جس نے اپنے خزانے پر بھروسہ کیا، {کہا}، کون میرے پاس آئے گا؟ {تمہارا...: یا، تیری وادی بہہ جاتی ہے}\n5۔ دیکھو، میں تم پر خوف لاؤں گا، خداوند خدا، لشکروں کے سب سے جو تیرے ارد گرد ہیں، فرماتا ہے؛ اور تم ہر آدمی کو سیدھا نکال دیا جائے گا؛ اور جو بھٹکتا ہے اسے کوئی جمع نہیں کرے گا۔\n6۔ اور اس کے بعد میں آمون کے بچوں کی قید دوبارہ لاؤں گا، خداوند فرماتا ہے۔\n7۔ ایڈوم کے بارے میں، رب لشکروں نے یوں فرمایا؛ {کیا} تیمان میں اب حکمت نہیں رہی؟ کیا مشاورت محتاط لوگوں سے ختم ہو جاتی ہے؟ کیا ان کی حکمت ختم ہو گئی ہے؟\n8. بھاگ جاؤ، پیچھے ہٹو، گہرائی میں رہو، اے دیدان کے باشندو؛ کیونکہ میں عیسو کی آفت اس پر لاؤں گا، جب {جب} میں اس سے ملنے جاؤں گا۔ {مڑو...: یا، وہ واپس پلٹ چکے ہیں}\n9۔ اگر گرپیگیتھررز آپ کے پاس آئیں تو کیا وہ {کچھ} انگور جمع کرنے والے نہیں چھوڑیں گے؟ اگر رات کو چور ہوں تو وہ تباہ کر دیں گے جب تک کہ ان کے پاس کافی نہ ہو۔ {تک...: عبرانی۔ ان کی کفایت شعاری}\n10۔ لیکن میں نے عیسو کو بے نقاب کر دیا ہے، اس کے خفیہ مقامات بے نقاب کر دیے ہیں، اور وہ خود کو چھپا نہیں سکے گا: اس کی نسل خراب ہو چکی ہے، اس کے بھائی اور اس کے پڑوسی خراب ہو چکے ہیں، اور وہ نہیں ہے۔\n11۔ اپنے یتیم بچوں کو چھوڑ دو، میں انہیں زندہ رکھوں گا؛ اور تمہاری بیواؤں کو مجھ پر بھروسہ کرنے دو۔\n12۔ کیونکہ خداوند یہ فرماتا ہے؛ دیکھو، جن کا فیصلہ پیالہ نہ پینا تھا، وہ یقینا پی چکے ہیں؛ اور کیا تم وہ ہو جو مکمل طور پر بغیر سزا کے بچ جائے گا؟ تم بغیر سزا کے نہیں رہو گے، لیکن ضرور پیو گے۔\n13۔ کیونکہ میں نے خود سے قسم کھائی ہے، خداوند فرماتا ہے، کہ بوزراہ ویرانی، ملامت اور بربادی بن جائے گا؛ اور اس کے تمام شہر ہمیشہ کے لیے ویران رہیں گے۔\n14۔ میں نے خداوند کی طرف سے ایک افواہ سنی ہے، اور ایک سفیر کافروں کے پاس بھیجا گیا ہے، {کہ}، سب اکٹھے ہو جاؤ، اس کے خلاف آؤ، اور جنگ کے لیے اٹھ کھڑے ہو جاؤ۔\n15۔ کیونکہ میں تمہیں کافروں میں چھوٹا کر دوں گا، {اور} انسانوں میں حقیر کر دوں گا۔\n16. تیری ہولناکی نے تمہیں دھوکہ دیا ہے، {اور} تمہارے دل کے غرور کو، اے وہ جو چٹان کی دراڑوں میں رہتی ہے، جو پہاڑی کی بلندی پر ہے: اگر تم اپنا گھونسلا عقاب جتنا اونچا بنا لو، تو میں تمہیں وہاں سے نیچے اتاروں گا، خداوند فرماتا ہے۔\n17۔ ایڈم بھی ویران ہوگا: جو بھی اس کے پاس سے گزرے گا وہ حیران رہ جائے گا، اور اس کی تمام آفتوں پر سیسکاری کرے گا۔\n18۔ جیسے سدوم اور عمورہ اور ان کے پڑوسی شہروں کے تختہ الٹنے پر، خداوند فرماتا ہے، وہاں کوئی انسان نہیں رہے گا، اور نہ ہی کوئی انسان کا بیٹا وہاں رہے گا۔\n19۔ دیکھو، وہ اردن کے پھول سے شیر کی طرح طاقتور لوگوں کے مسکن کے خلاف اٹھے گا: لیکن میں اچانک اسے اس سے دور لے جاؤں گا: اور کون {ہے} منتخب {آدمی} جسے میں اس پر مقرر کر سکوں؟ کیونکہ میرے جیسا کون ہے؟ اور مجھے وقت کون مقرر کرے گا؟ اور وہ چرواہا کون ہے جو میرے سامنے کھڑا ہوگا؟ {مجھے مقرر کریں...: یا، مجھے فیصلہ میں مقرر کریں؟}\n20۔ لہٰذا خداوند کی وہ نصیحت سنو جو اس نے ایڈوم کے خلاف لی ہے؛ اور اس کے مقاصد جو اس نے تیمان کے باشندوں کے خلاف کیے ہیں: یقینا ریوڑ کا سب سے چھوٹا حصہ انہیں باہر نکالے گا: یقینا وہ ان کی رہائش گاہوں کو ان کے ساتھ ویران کر دے گا۔\n21۔ زمین ان کے گرنے کی آواز پر ہل جاتی ہے، اس چیخ پر جو آواز بحیرہ احمر میں سنائی دیتی ہے۔ {بحر احمرانی: عبرانی۔ گھاس بھرا سمندر}\n22۔ دیکھو، وہ عقاب کی طرح اوپر آئے گا اور اپنے پروں کو بوزارت پر پھیلائے گا: اور اس دن ایڈوم کے طاقتور مردوں کا دل ایک عورت کے درد میں دل کی طرح ہوگا۔\n23۔ دمشق کے بارے میں۔ حمتھ حیران ہے، اور آرپاد: کیونکہ انہوں نے بری خبر سنی ہے: وہ دل کمزور ہیں؛ {سمندر پر غم ہے}؛ یہ خاموش نہیں ہو سکتا۔ {کمزور دل: عبوری۔ پگھلا ہوا} {پر...: یا، جیسے سمندر پر}\n24۔ دمشق کمزور ہو جاتی ہے، {اور} خود کو بھاگنے کے لیے موڑ دیتی ہے، اور خوف نے {اسے} پر قبضہ کر لیا ہے: غم اور غم نے اسے اپنی لپیٹ میں لے لیا ہے، جیسے ایک عورت جو مصیبت میں ہے۔\n25. تعریف کا شہر کیسے باقی نہیں رہا، جو میری خوشی کا شہر ہے!\n26۔ اس لیے اس کے نوجوان اس کی گلیوں میں گر جائیں گے، اور اس دن تمام جنگجو کاٹ دیے جائیں گے، خداوند لشکروں کا فرماتا ہے۔\n27۔ اور میں دمشق کی دیوار میں آگ جلاؤں گا، جو بن حداد کے محلات کو جلا دے گی۔\n28۔ قدار کے بارے میں، اور حزور کی بادشاہتوں کے بارے میں، جنہیں بابل کا بادشاہ نبوکدرز مار دے گا، خداوند یوں فرماتا ہے؛ اٹھو، کیدار جاؤ، اور مشرق کے لوگوں کو لوٹ لو۔\n29۔ اپنے خیمے اور اپنے ریوڑ لے جائیں گے: وہ اپنے پردے، تمام برتن اور اونٹ اپنے لیے لے جائیں گے؛ اور وہ انہیں پکاریں گے، خوف ہر طرف ہے۔\n30. بھاگو، دور جاؤ، گہرائی میں رہو، اے حزور کے باشندو، خداوند فرماتا ہے؛ کیونکہ بابل کے بادشاہ نبوکدرز نے تمہارے خلاف مشورہ کیا ہے، اور تمہارے خلاف کوئی مقصد بنا لیا ہے۔ {حاصل کرو...: عبوری۔ بہت زیادہ فلٹ کریں}\n31. اٹھو، اس امیر قوم کے پاس چڑھو جو بے فکری سے رہتی ہے، خداوند فرماتا ہے، جس کے نہ دروازے ہیں نہ بندیں، {جو} صرف رہتی ہے۔ {امیر: یا، یہ آرام دہ ہے}\n32۔ اور ان کے اونٹ مال غنیمت ہوں گے، اور ان کے مویشی مال غنیمت ہوں گے: اور میں انہیں ہر طرف سے بکھیر دوں گا؛ اور میں ان کی آفت ہر طرف سے لاؤں گا، خداوند فرماتا ہے۔ {میں...: عبرانی کونوں میں کاٹ دیا جائے، یا ایسے کنارے جن کے بالوں کے کونوں پر کٹے ہوئے ہوں}\n33۔ اور ہازور ڈریگنوں کا مسکن ہوگا، {اور} ہمیشہ کے لیے ویران رہے گا: وہاں کوئی انسان نہیں رہے گا، نہ ہی کوئی انسان کا بیٹا وہاں رہے گا۔\n34۔ خداوند کا وہ کلام جو یرمیاہ نبی کو ایلام کے خلاف آیا، زدقیاہ بادشاہ یہوداہ کی حکومت کے آغاز میں، اور کہا،\n35۔ خداوند لشکروں نے یوں فرمایا؛ دیکھو، میں ایلام کی کمان توڑوں گا، جو ان کی طاقت کا سردار ہے۔\n36۔ اور ایلام پر میں آسمان کے چاروں حصوں سے چار ہوائیں لاؤں گا، اور انہیں ان تمام ہواؤں کی طرف بکھیر دوں گا؛ اور کوئی قوم نہیں ہوگی جہاں ایلام کے بے دخل لوگ نہ آئیں۔\n37۔ کیونکہ میں ایلام کو ان کے دشمنوں کے سامنے اور ان کے جانوں کے سامنے مایوس کروں گا: اور میں ان پر برائی لاؤں گا، {حتیٰ کہ} میرا شدید غصہ، خداوند فرماتا ہے؛ اور میں تلوار ان کے پیچھے بھیجوں گا، جب تک کہ میں انہیں نگل نہ جاؤں:\n38۔ اور میں اپنا تخت ایلام میں بٹھاؤں گا، اور وہاں سے بادشاہ اور شہزادوں کو تباہ کر دوں گا، خداوند فرماتا ہے۔\n39۔ لیکن یہ آخری دنوں میں ہو جائے گا، {کہ} میں ایلام کی قید کو دوبارہ لاؤں گا، خداوند فرماتا ہے۔","1۔ وہ کلام جو خداوند نے بابل کے خلاف {اور} کلدانیوں کی زمین کے خلاف یرمیاہ نبی کے ذریعے بیان کیا۔ {بذریعہ...: عبرانی۔ یرمیاہ کے ہاتھوں\n2. قوموں میں اعلان کریں، شائع کریں، اور ایک معیار قائم کریں؛ شائع کریں، {اور} نہ چھپائیں: فرض کریں، بابل پر قبضہ ہو گیا، بیل الجھن میں ہے، میروڈاچ ٹکڑوں میں ٹوٹ گیا ہے؛ اس کے آئیڈیلز الجھے ہوئے ہیں، اس کی تصویریں ٹکڑوں میں ٹوٹ چکی ہیں۔ {سیٹ اپ: عبوری۔ اٹھاؤ}\n3۔ کیونکہ شمال سے ایک قوم اس کے خلاف آتی ہے، جو اس کی زمین کو ویران کر دے گی، اور وہاں کوئی نہیں رہے گا: وہ انسان اور جانور دونوں کو ہٹا دیں گے، چلے جائیں گے۔\n4۔ ان دنوں میں، اور اس وقت، خداوند فرماتا ہے، بنی اسرائیل آئیں گے، وہ اور یہوداہ کے بچے مل کر جائیں گے اور روئیں گے: وہ جائیں گے، اور اپنے خدا کو تلاش کریں گے۔\n5۔ وہ اپنے چہروں کے ساتھ صہیون کا راستہ پوچھیں گے، {کہیں}، آؤ، اور ہم خداوند کے ساتھ ایک دائمی عہد میں شامل ہو جائیں {جو کبھی نہ بھلایا جائے۔''\n6۔ میرے لوگ گمشدہ بھیڑیں بن گئے ہیں: ان کے چرواہوں نے انہیں گمراہ کیا ہے، انہوں نے انہیں پہاڑوں پر بھگا دیا ہے: وہ پہاڑوں سے پہاڑوں تک گئے ہیں، وہ اپنی آرام گاہ بھول گئے ہیں۔ {آرام کی جگہ: عبرانی۔ لیٹنے کی جگہ}\n7۔ جو بھی انہیں پایا اس نے انہیں نگل لیا: اور ان کے مخالفین نے کہا، ہم گناہ نہیں کرتے کیونکہ انہوں نے خداوند کے خلاف گناہ کیا ہے، جو انصاف کا گھر ہے، حتیٰ کہ خداوند کے خلاف بھی، جو ان کے باپ اجداد کی امید ہے۔\n8۔ بابل کے بیچ سے نکل جاؤ، اور کلدانیوں کی زمین سے باہر نکل جاؤ، اور ریوڑوں کے سامنے بکریوں کی طرح بنو۔\n9۔ دیکھو، میں بابل کے خلاف شمالی ملک سے بڑی قوموں کی ایک مجلس کھڑا کروں گا، اور وہ اس کے خلاف صف بندی میں کھڑے ہوں گے؛ وہاں سے اسے لے جایا جائے گا: ان کے تیر {ایک طاقتور ماہر آدمی کے ہوں گے}؛ کوئی بھی رائیگاں واپس نہیں آئے گا۔ {ماہر...: یا، ڈسٹرائر}\n10. اور کلدیہ غنیمت ہوگی: جو بھی اسے خراب کرے گا وہ مطمئن ہو جائے گا، خداوند فرماتا ہے۔\n11. کیونکہ تم خوش تھے، کیونکہ تم خوش ہوئے، اے میرے ورثے کو تباہ کرنے والوں، کیونکہ تم گھاس کی گائے کی طرح موٹے ہو گئے ہو، اور بیلوں کی طرح دہاڑتے ہو؛ {موٹا: عبوری۔ بڑے، یا موٹے} {دھاڑ...: یا، گھوڑوں کی طرح ہنکار}\n12۔ تمہاری ماں بہت پریشان ہوگی؛ جو تمہیں نکالے گی وہ شرمندہ ہوگی: دیکھو، قوموں میں سب سے پیچھے ایک بیابان، ایک خشک زمین، اور ایک صحرا ہوگا۔\n13۔ خداوند کے غضب کی وجہ سے یہ آباد نہیں ہوگا، بلکہ مکمل طور پر ویران ہو جائے گا: جو بھی بابل کے پاس جائے گا وہ حیران رہ جائے گا اور اس کی تمام آفتوں پر پھنکار کرے گا۔\n14۔ اپنے آپ کو بابل کے ارد گرد کے خلاف صف بندی میں کھڑا کر دو: جو بھی کمان موڑتا ہے، اس پر تیر چلاؤ، تیر نہ چھوڑو: کیونکہ اس نے خداوند کے خلاف گناہ کیا ہے۔\n15۔ اس کے گرد چیخ کر پکارو: اس نے اپنا ہاتھ دے دیا ہے: اس کی بنیادیں گر گئی ہیں، اس کی دیواریں گر گئی ہیں: کیونکہ یہ خداوند کا انتقام ہے: اس سے انتقام لو؛ جیسے اس نے کیا، اس کے ساتھ بھی کرو۔\n16۔ بابل کے بیج بونے والے کو اور جو فصل کے وقت درانتی سنبھالتا ہے اسے کاٹ دو: ظالم تلوار کے خوف سے وہ سب کو اس کی قوم کے حوالے کر دیں گے، اور ہر ایک اپنی سرزمین کی طرف بھاگ جائیں گے۔ {درانتی؛ یا، درانت}\n17۔ اسرائیل ایک بکھری ہوئی بھیڑ ہے؛ شیروں نے {اسے} کو بھگا دیا ہے: پہلے آشور کے بادشاہ نے اسے نگل لیا ہے؛ اور آخر میں یہ نبوکدرز بادشاہ بابل نے اپنی ہڈیاں توڑ دی ہیں۔\n18۔ لہٰذا لشکروں کے رب، اسرائیل کے خدا نے یوں فرمایا؛ دیکھو، میں بابل کے بادشاہ اور اس کی سرزمین کو سزا دوں گا، جیسے میں نے آشور کے بادشاہ کو سزا دی ہے۔\n19۔ اور میں اسرائیل کو اس کے گھر واپس لے آؤں گا، اور وہ کرمل اور باشان پر کھائے گا، اور اس کی روح کوہ افرائیم اور جلعاد پر مطمئن ہو جائے گی۔\n20۔ ان دنوں میں، اور اس وقت، خداوند فرماتا ہے، اسرائیل کی بدکاری کی تلاش کی جائے گی، اور {کوئی نہیں ہوگا}؛ اور یہوداہ کے گناہ بھی، اور وہ نہیں پائے جائیں گے: کیونکہ میں ان لوگوں کو معاف کر دوں گا جنہیں میں محفوظ رکھتا ہوں۔\n21. میراتھائم کی سرزمین کے خلاف بھی آگے بڑھو، {حتی} اس کے خلاف بھی، اور پیکوڈ کے باشندوں کے خلاف: ان کے پیچھے ضائع ہو جاؤ اور مکمل طور پر تباہ ہو جاؤ، خداوند فرماتا ہے، اور جو کچھ میں نے تمہیں حکم دیا ہے اس کے مطابق کرو۔ {مراتھائم: یا، باغیوں کی} {پیکوڈ: یا، ملاقات}\n22۔ زمین میں جنگ کی آواز ہے، اور بڑی تباہی کی بھی۔\n23. پوری زمین کا ہتھوڑا کیسے کاٹا اور ٹوٹا گیا! بابل قوموں کے درمیان ویرانی کیسے بن گیا!\n24۔ میں نے تمہارے لیے جال بچھا دیا ہے، اور تم بھی پکڑے گئے ہو، اے بابل، اور تم نہیں جانتے تھے: تم مل گئے ہو، اور پکڑے گئے ہو، کیونکہ تم نے خداوند کے خلاف لڑائی کی۔\n25۔ خداوند نے اپنا اسلحہ کھولا ہے، اور اپنے غصے کے ہتھیار نکال لیے ہیں: کیونکہ یہ خداوند خدا کا کام ہے جو کلدانیوں کی سرزمین میں لشکروں کا ہے۔\n26. اس کے خلاف انتہائی سرحد سے آؤ، اس کے گوداموں کو کھولو: اسے ڈھیر کی طرح پھینک دو، اور مکمل طور پر تباہ کر دو: اس میں سے کچھ بھی باقی نہ رہے۔ {سے...: عبرانی آخر سے} {cast...: or, tred her}\n27۔ اس کے تمام بیل ذبح کرنا؛ انہیں ذبح کی طرف جانے دو: ان پر افسوس! کیونکہ ان کا دن آ گیا ہے، ان کی آمد کا وقت۔\n28۔ ان لوگوں کی آواز جو بابل کی سرزمین سے بھاگ کر بھاگ جاتے ہیں، تاکہ صیون میں خداوند ہمارے خدا کا انتقام، اس کے مندر کا انتقام، اعلان کریں۔\n29۔ تیر اندازوں کو بابل کے خلاف اکٹھا کرو: جو بھی کمان جھکاؤ، اس کے خلاف ارد گرد کیمپ لگاؤ؛ کوئی بھی اس سے بچ نہ جائے: اسے اس کے کام کے مطابق بدلہ دو؛ جو کچھ اس نے کیا ہے اس کے مطابق اس کے ساتھ کرو، کیونکہ وہ خداوند کے خلاف، اسرائیل کے مقدس ہستی کے خلاف مغرور رہی ہے۔\n30. اسی لیے اس کے نوجوان سڑکوں پر گر جائیں گے، اور اس کے تمام جنگجو اسی دن کاٹ دیے جائیں گے، خداوند فرماتا ہے۔\n31۔ دیکھو، میں تمہارے خلاف ہوں، {اے تو} سب سے زیادہ مغرور، خداوند خدا لشکروں کا فرماتا ہے: کیونکہ تیرا دن آ گیا ہے، وہ وقت {جو} میں تجھ سے ملنے آؤں گا۔ {زیادہ تر...: عبرانی۔ فخر}\n32۔ اور سب سے مغرور لڑکھڑا کر گر جائے گا، اور کوئی اسے اٹھا نہیں سکے گا: اور میں اس کے شہروں میں آگ جلاؤں گا، جو اس کے ارد گرد جل جائے گی۔ {the...: عبرانی فخر}\n33۔ ایسا فرماتا ہے رب لشکر؛ بنی اسرائیل اور یہوداہ کے بچے ایک ساتھ ظلم کیے گئے: اور جو بھی انہیں قید میں لے گیا، اس نے انہیں مضبوطی سے تھام لیا؛ انہوں نے انہیں جانے سے انکار کر دیا۔\n34۔ ان کا نجات دہندہ {ہے} طاقتور؛ لشکروں کا رب اس کا نام ہے: وہ ان کے مقصد کی بھرپور حمایت کرے گا، تاکہ وہ زمین کو سکون دے سکے، اور بابل کے باشندوں کو پریشان کر سکے۔\n35. تلوار {ہے} کلدانیوں پر، خداوند فرماتا ہے، اور بابل کے باشندوں، اس کے شہزادوں پر، اور اس کے عقلمندوں پر۔\n36۔ جھوٹوں پر تلوار {ہے}؛ اور وہ محبت کریں گے: ایک تلوار اس کے طاقتور آدمیوں پر ہے؛ اور وہ مایوس ہوں گے۔ {جھوٹے: یا، چیف رہتا ہے: عبرانی۔ بارز}\n37. ایک تلوار ان کے گھوڑوں، ان کے رتھوں پر، اور ان تمام مخلوط لوگوں پر جو اس کے درمیان ہیں؛ اور وہ عورتوں کی طرح بن جائیں گی: ایک تلوار اس کے خزانے پر ہے؛ اور انہیں لوٹا جائے گا۔\n38۔ اس کے پانیوں پر خشک سالی ہے؛ اور وہ خشک ہو جائیں گے: کیونکہ یہ زمین تراشے گئے مجسموں کی ہے، اور وہ اپنے بتوں پر پاگل ہیں۔\n39۔ لہٰذا صحرا کے جنگلی جانور اور جزیروں کے جنگلی جانور وہاں رہیں گے، اور الو وہاں رہیں گے: اور یہ ہمیشہ کے لیے آباد نہیں رہے گا؛ اور نہ ہی یہ نسل در نسل بیان کیا جائے گا۔\n40۔ جیسے خدا نے سدوم اور عمورہ اور ان کے پڑوسی شہروں کو گرا دیا، خداوند فرماتا ہے؛ {یوں} کوئی انسان وہاں نہیں رہے گا، اور نہ ہی کوئی انسان کا بیٹا وہاں رہے گا۔\n41۔ دیکھو، شمال سے ایک قوم آئے گی، اور ایک عظیم قوم، اور زمین کے کناروں سے کئی بادشاہ اٹھے گا۔\n42. وہ کمان اور نیزہ پکڑیں گے: وہ ظالم ہوں گے، اور رحم نہیں کریں گے: ان کی آواز سمندر کی طرح دہاڑے گی، اور وہ گھوڑوں پر سوار ہوں گے، {ہر ایک} قطار میں کھڑے ہوں گے، جیسے کوئی آدمی لڑائی میں لڑتا ہے، اے بابل کی بیٹی۔\n43۔ بابل کے بادشاہ نے ان کی خبر سنی ہے، اور اس کے ہاتھ کمزور ہو گئے: درد نے اسے جکڑ لیا، {اور} ایک عورت کی طرح تکلیف میں درد محسوس کیا۔\n44۔ دیکھو، وہ شیر کی طرح اردن کے پھول سے طاقتوروں کی رہائش گاہ تک پہنچے گا: لیکن میں انہیں اچانک اس سے دور کر دوں گا: اور کون {ہے} منتخب {آدمی} جسے میں اس پر مقرر کر سکوں؟ کیونکہ میرے جیسا کون ہے؟ اور مجھے وقت کون مقرر کرے گا؟ اور وہ چرواہا کون ہے جو میرے سامنے کھڑا ہوگا؟ {مجھے مقرر کریں...: یا، مجھے درخواست کرنے کے لیے کہیں گے؟}\n45۔ لہٰذا خداوند کی نصیحت سنو، جو اس نے بابل کے خلاف لی ہے؛ اور اس کے مقاصد جو اس نے کلدانیوں کی زمین کے خلاف بنائے ہیں: یقینا سب سے چھوٹا ریوڑ انہیں باہر نکالے گا: یقینا وہ ان کے ساتھ ان کی رہائش کو ویران کر دے گا۔\n46۔ بابل کے قبضے کی آواز پر زمین ہلتی ہے، اور قوموں میں پکار سنائی دیتی ہے۔","1۔ خداوند فرماتا ہے؛ دیکھو، میں بابل کے خلاف اٹھوں گا، اور ان لوگوں کے خلاف جو میرے خلاف اٹھتے ہیں، ایک تباہ کن ہوا؛ {درمیان: عبوری۔ دل}\n2۔ اور بابل کے شائقین بھیجوں گا، جو اسے پنکھا دیں گے، اور اس کی زمین خالی کریں گے، کیونکہ مصیبت کے دن وہ اس کے خلاف ہوں گے۔\n3۔ جس کے خلاف جھکتا ہے، تیر انداز اپنی کمان جھکائے، اور جو اپنے ڈاکو میں اٹھتا ہے، اس کے خلاف خود کو اوپر اٹھائے: اور اس کے نوجوانوں کو نہ بخشو؛ تم اس کے تمام لشکروں کو مکمل طور پر تباہ کر دو۔\n4. یوں مارے جانے والے کلدانیوں کی زمین میں گرے جائیں گے، اور جو لوگ اس کی گلیوں میں پھینکے جائیں گے۔\n5۔ کیونکہ اسرائیل {چھوڑا} نہیں گیا، نہ یہوداہ اپنے خدا سے، جو لشکروں کے رب کا ہے؛ اگرچہ ان کی زمین اسرائیل کے مقدس ہستی کے خلاف گناہ سے بھری ہوئی تھی۔\n6۔ بابل کے بیچ سے بھاگ جاؤ، اور ہر انسان کی جان کو آزاد کرو: اس کی گناہ میں کٹ نہ جانا؛ کیونکہ یہ خداوند کے انتقام کا وقت ہے؛ وہ اسے بدلہ دے گا۔\n7۔ بابل {تھا} خداوند کے ہاتھ میں ایک سنہری پیالہ تھا، جس نے ساری زمین کو مست کر دیا: قوموں نے اس کی شراب پی لی ہے؛ اسی لیے قومیں پاگل ہیں۔\n8۔ بابل اچانک گر کر تباہ ہو جاتا ہے: اس کے لیے چیخیں؛ اس کے درد کے لیے مرہم لیں، اگر ایسا ہوا تو شاید وہ ٹھیک ہو جائے۔\n9۔ ہم بابل کو شفا دینا چاہتے تھے، لیکن وہ شفا یافتہ نہیں ہوئی: اسے چھوڑ دو، اور ہر ایک کو اس کے اپنے ملک میں لے جائے: کیونکہ اس کا فیصلہ آسمان تک پہنچتا ہے، اور آسمان تک بلند ہو جاتا ہے۔\n10۔ خداوند نے ہماری راستبازی کو جنم دیا ہے: آؤ، اور ہم صیون میں خداوند ہمارے خدا کے کام کا اعلان کریں۔\n11۔ تیر روشن کرو؛ ڈھالیں جمع کرو: خداوند نے میڈز کے بادشاہوں کی روح کو اٹھایا ہے: کیونکہ اس کا چال بابل کے خلاف ہے، اسے تباہ کرنا؛ کیونکہ یہ خداوند کا انتقام ہے، اس کے مندر کا انتقام۔ {روشن: عبوری۔ پیور}\n12۔ بابل کی دیواروں پر پرچم نصب کرو، پہرے دار مضبوط کرو، پہرے دار کھڑے کرو، گھات لگانے کی تیاری کرو: کیونکہ خداوند نے وہ سب کچھ بنایا اور کیا جو اس نے بابل کے باشندوں کے خلاف کہا۔ {گھات لگائے: عبرانی۔ جھوٹے انتظار میں}\n13۔ اے تم جو بے شمار پانیوں پر رہتی ہو، خزانے سے بھرپور، تمہارا انجام آ چکا ہے، {اور} تیری لالچ کی پیمائش۔\n14۔ رب لشکروں نے خود سے قسم کھائی ہے، {کہ}، یقینا میں تمہیں مردوں سے بھر دوں گا، جیسے کہ کیٹرپلرز سے؛ اور وہ تمہارے خلاف چیخ اٹھائیں گے۔ {اکیلے: عبرانی۔ اس کی روح سے} {اوپر: عبرانی۔ مکمل طور پر}\n15۔ اس نے اپنی طاقت سے زمین بنائی، اپنی حکمت سے دنیا کو قائم کیا، اور اپنی سمجھ سے آسمان کو پھیلایا۔\n16۔ جب وہ اپنی آواز نکالتا ہے، {آسمانوں میں پانی کی کثرت ہے}؛ اور وہ زمین کے کناروں سے بھاپ اٹھاتا ہے، بارش سے بجلی بناتا ہے، اور اپنے خزانے سے ہوا نکالتا ہے۔ {کثیر: یا، شور}\n17۔ ہر انسان اپنے علم سے وحشی ہوتا ہے؛ ہر بانی کندہ شدہ تصویر سے الجھن میں ہے: کیونکہ اس کی پگھلی ہوئی تصویر {ہے} جھوٹ ہے، اور {اس میں کوئی سانس نہیں}۔ {کیا یہ سخت ہے...: یا، جاننے سے زیادہ وحشیانہ ہے}\n18. وہ خود غرض ہیں، غلطیوں کا کام: ان کی زیارت کے وقت وہ فنا ہو جائیں گے۔\n19۔ یعقوب کا حصہ {ہے} ان جیسا نہیں؛ کیونکہ وہ سب چیزوں میں سے پہلا ہے: اور اسرائیل اس کی میراث کی چھڑی ہے: لشکروں کا رب اس کا نام ہے۔\n20۔ تو میری جنگی کلہاڑی ہو اور جنگ کے ہتھیار ہو: کیونکہ تیرے ساتھ میں قوموں کو ٹکڑے ٹکڑے کروں گا، اور تیرے ساتھ سلطنتیں تباہ کروں گا؛ {تمہارے ساتھ: یا، تمہارے ساتھ، یا، تمہارے ذریعے}\n21۔ اور تمہارے ساتھ میں گھوڑے اور اس کے سوار کو ٹکڑوں میں توڑوں گا؛ اور تمہارے ساتھ میں رتھ اور اس کے سوار کو ٹکڑوں میں توڑوں گا؛\n22. تمہارے ساتھ میں مرد اور عورت کو بھی ٹکڑوں میں توڑوں گا؛ اور تمہارے ساتھ میں پرانے اور جوان ٹکڑوں میں ٹوٹوں گا؛ اور تمہارے ساتھ میں نوجوان اور لڑکی کو ٹکڑوں میں توڑوں گا؛\n23۔ میں بھی تیرے چرواہے اور اس کے ریوڑ کے ساتھ ٹکڑے ٹکڑے کر دوں گا؛ اور تمہارے ساتھ میں کسان اور اس کے بیلوں کے جوتے کو ٹکڑوں میں توڑوں گا؛ اور تمہارے ساتھ میں کپتان اور حکمرانوں کو ٹکڑوں میں توڑوں گا۔\n24۔ اور میں بابل اور کلدیا کے تمام باشندوں کو ان کی تمام برائی جو انہوں نے صہیون میں تمہارے سامنے کی ہے، تمہارے سامنے دوں گا، خداوند فرماتا ہے۔\n25۔ دیکھو، میں تیرے خلاف ہوں، اے تباہ کن پہاڑ، خداوند فرماتا ہے، جو ساری زمین کو تباہ کر دیتا ہے: اور میں اپنا ہاتھ تیرے اوپر بڑھاؤں گا، تمہیں چٹانوں سے نیچے لاؤں گا، اور تمہیں جلا ہوا پہاڑ بنا دوں گا۔\n26۔ اور وہ تم سے کونے کے لیے پتھر یا بنیاد کے لیے پتھر نہیں لیں گے؛ لیکن تم ہمیشہ کے لیے ویران رہو گے، خداوند فرماتا ہے۔ {مایوس کن...: عبرانی۔ ابدی ویرانیاں}\n27۔ تم زمین میں ایک جھنڈا قائم کرو، قوموں کے درمیان بگل بجائے، قوموں کو اس کے خلاف تیار کرو، اور ارارات، منی اور اشچناز کی سلطنتوں کو اس کے خلاف متحد کرو؛ اس کے خلاف ایک کپتان مقرر کرنا؛ گھوڑوں کو کھردرے کیٹرپلرز کے طور پر اوپر لے آئیں۔\n28۔ اس کے خلاف قوموں کو تیار کرو جن میں مید کے بادشاہ، ان کے کپتان، اور ان کے تمام حکمران شامل ہیں، اور اس کی سلطنت کی تمام زمین۔\n29۔ اور زمین لرزے گی اور غمگین ہو گی: کیونکہ خداوند کا ہر مقصد بابل کے خلاف انجام دیا جائے گا، تاکہ بابل کی زمین کو ویرانی بنا دیا جائے اور کوئی باشندہ نہ ہو۔\n30۔ بابل کے طاقتور آدمیوں نے لڑائی چھوڑ دی ہے، وہ اپنے قبضے میں رہ گئے ہیں: ان کی طاقت ناکام ہو گئی ہے؛ وہ عورتوں کی طرح بن گئیں: انہوں نے اس کے گھروں کو جلا دیا؛ اس کے سلاخیں ٹوٹ چکی ہیں۔\n31۔ ایک پوسٹ دوسرے سے ملنے جائے گا، اور ایک پیغامبر دوسرے سے ملنے جائے گا، تاکہ بابل کے بادشاہ کو دکھائے کہ اس کا شہر {ایک} سرے پر قبضہ کر لیا گیا ہے،\n32۔ اور راستے بند کر دیے گئے، اور سرکنڈے آگ میں جل گئے، اور جنگجو خوفزدہ ہو گئے۔\n33۔ کیونکہ ایسا ہی فرماتا ہے لشکروں کے رب، اسرائیل کے خدا؛ بابل کی بیٹی {ہے} ایک تھریشنگ فلور کی طرح، {یہ} وقت ہے کہ اسے کوٹھا جائے: ابھی تھوڑی دیر باقی ہے، اور اس کی فصل کا وقت آئے گا۔ {یہ ہے...: یا، اس وقت جب وہ اسے تھری کرتا ہے}\n34۔ بابل کے بادشاہ نبوکدرز نے مجھے نگل لیا، اس نے مجھے کچل دیا، اس نے مجھے خالی برتن بنایا، اس نے مجھے ڈریگن کی طرح نگل لیا، اس نے اپنے پیٹ کو میری نازک کپڑوں سے بھر دیا، اس نے مجھے نکال دیا۔\n35. جو ظلم میرے اور میرے جسم پر بابل پر کیا گیا، صیون کے باشندے کہیں گے؛ اور یروشلم کہے گا کہ میرا خون کلدیہ کے باشندوں پر ہے۔ {تشدد...: عبرانی۔ میرا تشدد} {گوشت: یا، باقی} {رہائشی: عبرانی۔ آبادکار}\n36۔ لہٰذا خداوند فرماتا ہے؛ دیکھو، میں تمہارے حق کی وکالت کروں گا، اور تمہارے لیے انتقام لوں گا؛ اور میں اس کے سمندر کو خشک کروں گا، اور اس کے چشمے خشک کر دوں گا۔\n37۔ اور بابل ڈھیر بن جائے گا، ڈریگنوں کے لیے رہائش گا، حیرت اور سرسراہٹ، بغیر کسی باشندے کے۔\n38۔ وہ شیر کی طرح ایک ساتھ دھاڑیں گے: وہ شیر کے بچوں کی طرح چیخیں گے۔ {چیخ: یا، خود کو ہلا دیں}\n39۔ ان کی گرمی میں میں ان کی ضیافت کروں گا، اور انہیں نشے میں ڈالوں گا تاکہ وہ خوش رہیں، اور ہمیشہ کی نیند میں رہیں، اور جاگیں نہیں، خداوند فرماتا ہے۔\n40۔ میں انہیں بھیڑوں کی طرح ذبح کے لیے لے آؤں گا، جیسے بکریوں کے ساتھ مینڈھ۔\n41۔ شیشاک کو کیسے لے جایا گیا ہے! اور پوری زمین کی تعریف کیسے حیران ہے! بابل قوموں میں کیسے حیران کن بن گیا!\n42۔ سمندر بابل پر آ رہا ہے: وہ اس کی لہروں کی کثرت سے ڈھکا ہوا ہے۔\n43. اس کے شہر ویران، خشک زمین اور بیابان ہیں، ایسی زمین جہاں کوئی انسان نہیں رہتا، اور نہ ہی کوئی انسان کا بیٹا وہاں سے گزرتا ہے۔\n44۔ اور میں بیل کو بابل میں سزا دوں گا، اور اس کے منہ سے وہ سب نکالوں گا جو اس نے نگل لیا ہے: اور قومیں اس کی طرف مزید نہیں آئیں گی: ہاں، بابل کی دیوار گر جائے گی۔\n45۔ میرے لوگو، اس کے بیچ سے نکل جاؤ، اور ہر انسان کی جان کو خداوند کے شدید غضب سے بچاؤ۔\n46۔ اور کہیں تمہارا دل بے ہوش نہ ہو جائے، اور اس افواہ سے ڈرو جو زمین میں سنائی دے گی؛ ایک افواہ {ایک} سال آئے گی، اور اس کے بعد {ایک اور} سال میں ایک افواہ آئے گی، اور زمین میں تشدد، حکمران کے خلاف حکمران۔ {ورنہ: یا، نہ ہونے دو}\n47۔ لہٰذا، دیکھو، دن آتے ہیں کہ میں بابل کی کندہ شدہ تصاویر پر فیصلہ کروں گا: اور اس کی پوری زمین برباد ہو جائے گی، اور اس کے تمام مارے گئے اس کے بیچ میں گر جائیں گے۔ {do...: عبرانی۔ ملاحظہ کریں}\n48۔ پھر آسمان اور زمین اور اس میں جو کچھ بھی ہے، بابل کے لیے گائیں گے: کیونکہ بگاڑنے والے شمال سے اس کے پاس آئیں گے، خداوند فرماتا ہے۔\n49۔ جیسے بابل نے اسرائیل کے مارے گئے لوگوں کو گرا دیا، ویسے ہی بابل میں زمین کے تمام مارے گئے ہوں گے۔ {جیسا کہ...: یا، دونوں بابل گر جائیں گے، اے اسرائیل کے مقتولوں، اور بابل کے ساتھ، وغیرہ} {زمین: یا، دیہ}\n50۔ جو تلوار سے بچ نکلے، چلے جاؤ، رک جاؤ: دور خداوند کو یاد کرو، اور یروشلم کو اپنے ذہن میں آنے دو۔\n51. ہم حیران ہیں، کیونکہ ہم نے ملامت سنی ہے: شرم نے ہمارے چہروں پر چھا لیا ہے: کیونکہ اجنبی خداوند کے گھر کے مقدس مقامات میں داخل ہوئے ہیں۔\n52۔ لہٰذا، دیکھو، دن آتے ہیں، خداوند فرماتا ہے، کہ میں اس کی کندہ شدہ تصویروں پر فیصلہ کروں گا: اور اس کی زمین کے تمام حصے میں زخمی کراہوں گے۔\n53. اگرچہ بابل آسمان تک چڑھ جائے، اور اپنی طاقت کی بلندی کو مضبوط کرے، {لیکن} مجھ سے اس کے پاس کچھ خرابیاں آئیں گی، خداوند فرماتا ہے۔\n54۔ بابل سے ایک چیخ کی آواز آتی ہے، اور کلدانیوں کی زمین سے بڑی تباہی:\n55۔ کیونکہ خداوند نے بابل کو برباد کیا ہے، اور اس میں سے عظیم آواز کو تباہ کر دیا ہے؛ جب اس کی لہریں عظیم پانیوں کی طرح گرجتی ہیں، تو ان کی آواز کی آواز نکلتی ہے:\n56. چونکہ اس پر برباد کرنے والا آ گیا، {حتیٰ کہ} بابل پر بھی، اور اس کے طاقتور آدمی لے لیے گئے، ان کے ہر کمان ٹوٹ جاتے ہیں: کیونکہ خداوند خدا بدلہ ضرور دے گا۔\n57. اور میں اس کے شہزادوں، اس کے دانا، اس کے کپتانوں، حکمرانوں اور اس کے طاقتور لوگوں کو نشے میں ڈالوں گا: اور وہ ہمیشہ کے لیے سوتے رہیں گے، اور جاگیں گے نہیں، بادشاہ کہتا ہے، جس کا نام لشکروں کا رب ہے۔\n58۔ ایسا فرماتا ہے رب لشکر؛ بابل کی چوڑی دیواریں مکمل طور پر ٹوٹ جائیں گی، اور اس کے اونچے دروازے آگ سے جل جائیں گے؛ اور لوگ بے سود محنت کریں گے، اور لوگ آگ میں، اور وہ تھکے ہوئے ہوں گے۔ {وسیع...: یا، وسیع بابل کی دیواریں} {ٹوٹا ہوا: یا، ننگا کر دیا گیا}\n59۔ وہ کلام جو یرمیاہ نبی نے نرییاہ کے بیٹے سریاہ کو حکم دیا، جب وہ یہوداہ کے بادشاہ زدقیاہ کے ساتھ اپنی حکومت کے چوتھے سال میں بابل گیا۔ اور یہ سرایا ایک خاموش شہزادہ تھا۔ {ساتھ: یا، اس کی طرف سے} {خاموش...: یا، مینوچا کے شہزادے، یا، چیف چیمبرلین}\n60۔ تو یرمیاہ نے ایک کتاب میں وہ تمام برائی لکھی جو بابل پر آنا چاہیے، {حتیٰ کہ} یہ تمام الفاظ جو بابل کے خلاف لکھے گئے ہیں۔\n61۔ اور یرمیاہ نے سریاہ سے کہا، جب تم بابل آؤ گے، اور دیکھو گے اور یہ سب الفاظ پڑھو گے؛\n62. پھر تم کہو گے، اے خداوند، تو نے اس جگہ کے خلاف بات کی ہے، اسے کاٹنے کے لیے، کہ اس میں کوئی نہیں رہے گا، نہ انسان نہ جانور، بلکہ یہ ہمیشہ کے لیے ویران رہے گی۔ {ویران آواز: عبرانی۔ ویرانی}\n63. اور جب تم اس کتاب کو پڑھنا ختم کر دو گے، تو تم اس پر ایک پتھر باندھو گے، اور اسے فرات کے بیچ میں پھینک دو گے:\n64. اور تم کہو گے، یوں بابل ڈوب جائے گا، اور اس برائی سے نہیں اٹھے گا جو میں اس پر لاؤں گا: اور وہ تھک جائیں گے۔ اب تک یرمیاہ کے الفاظ ہیں۔","1. صدقیہ {تھا} جب اس نے حکومت شروع کی تو وہ ایک اور بیس سال کا تھا، اور یروشلم میں گیارہ سال حکومت کیا۔ اور اس کی والدہ کا نام حموتال تھا، جو یرمیاہ آف لبنہ کی بیٹی تھی۔ {شروع ہوا...: عبرانی۔ حکومت کی}\n2۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا، جیسا کہ یہویاقیم نے کیا تھا۔\n3۔ کیونکہ خداوند کے غصے کی وجہ سے یروشلم اور یہوداہ میں، یہاں تک کہ اس نے انہیں اپنی موجودگی سے نکال دیا، کہ صدقیہ نے بابل کے بادشاہ کے خلاف بغاوت کی۔\n4۔ اور یہ اس کی حکومت کے نویں سال میں، دسویں مہینے میں، مہینے کے دسویں دن میں ہوا، جب بابل کا بادشاہ نبوکدرز آیا، اس نے اپنی پوری فوج کے ساتھ یروشلم کے خلاف حملہ کیا، اس کے گرد قلعے تعمیر کیے۔\n5۔ یوں شہر بادشاہ صدقیاہ کے گیارہویں سال تک محاصرے میں رہا۔\n6۔ اور چوتھے مہینے میں، مہینے کے نویں دن، شہر میں قحط شدید تھا، یہاں تک کہ لوگوں کے لیے روٹی نہیں تھی۔\n7۔ پھر شہر کو توڑ دیا گیا، اور تمام جنگجو بھاگ گئے، اور رات کو شہر سے باہر نکل گئے، دو دیواروں کے درمیان دروازے کے راستے جو بادشاہ کے باغ کے پاس تھا؛ (اب کلدانی شہر کے آس پاس تھے:) اور وہ میدان کے راستے سے گزرے۔\n8۔ لیکن کلدانیوں کی فوج نے بادشاہ کا پیچھا کیا اور یریحو کے میدانوں میں صدقیہ کو پکڑ لیا؛ اور اس کی ساری فوج اس سے منتشر ہو گئی۔\n9۔ پھر انہوں نے بادشاہ کو لے کر اسے بابل کے بادشاہ کے پاس لے جا کر حمتھ کی سرزمین ربلہ میں لے گئے؛ جہاں اس نے اس پر فیصلہ سنایا۔\n10۔ اور بابل کے بادشاہ نے زدقیاہ کے بیٹوں کو اپنی آنکھوں کے سامنے قتل کر دیا: اس نے یہوداہ کے تمام شہزادوں کو بھی ربلہ میں قتل کر دیا۔\n11۔ پھر اس نے صدقیاہ کی آنکھیں بجھا دیں؛ اور بابل کے بادشاہ نے اسے زنجیروں میں باندھ کر بابل لے جا کر موت تک قید میں رکھا۔ {آؤٹ آؤٹ: ہیب۔ اندھا} {زنجیریں: یا، زنجیریں} {جیل: عبرانی۔ وارڈز کا گھر}\n12۔ اب پانچویں مہینے میں، مہینے کے دسویں دن، جو بابل کے بادشاہ نبوکدرز کا انیسواں سال تھا، نبوزاردان، محافظ کا کپتان، جو بابل کے بادشاہ کی خدمت کرتا تھا، یروشلم آیا، {کپتان...: یا، چیف مارشل: عبرانی۔ چیف آف دی ایگزیکیوشنرز، یا سلاٹرمین} {خدمت کردہ: عبرانی۔ سامنے کھڑا تھا}\n13۔ اور خداوند کے گھر اور بادشاہ کے گھر کو جلا دیا؛ اور یروشلم کے تمام گھر، اور عظیم لوگوں کے تمام گھروں نے آگ سے جلا دیا:\n14۔ اور تمام کلدانیوں کی فوج، جو گارڈ کے کپتان کے ساتھ تھی، یروشلم کی تمام دیواریں توڑ دیتی ہے۔\n15۔ پھر محافظوں کے کپتان نبوزاردان نے لوگوں کے غریبوں میں سے کچھ کو قید کر لیا، اور شہر میں باقی ماندہ لوگوں کے باقیات اور جو گر گئے، جو بابل کے بادشاہ اور باقی ہجوم کے ہاتھوں گر گئے۔\n16۔ لیکن محافظ کے کپتان نیبوزارادان نے {کچھ غریب} انگور بنانے والوں اور کسانوں کے لیے چھوڑ دیا۔\n17. اسی طرح وہ پیتل کے ستون جو خداوند کے گھر میں تھے، اور اس کے بنیادیں، اور وہ برسن سمندر جو خداوند کے گھر میں تھا، کلدانی نے توڑ دیا، اور ان کے تمام پیتل کو بابل لے گئے۔\n18۔ دیتزا، بیلچے، سنفرز، پیالے، چمچ، اور تمام پیتل کے برتن جن سے وہ خدمت کرتے تھے، انہیں لے گئے۔ {بیلچے: یا، راکھ ہٹانے کے آلات} {باؤلز: اور، بیسنز}\n19۔ اور بیسن، اور آگ کے برتن، اور پیالے، اور دیالے، اور موم بتی کے اسٹکس، اور چمچ، اور پیالی؛ {و} جو {تھا} سونے {میں} سونے کا، اور {و} جو {تھا} چاندی کا {تھا} چاندی کا، گارڈ کے کپتان کو لے گیا۔ {فائر پینز: یا، سنسرز}\n20۔ دو ستون، ایک سمندر، اور بارہ براسن بیل جو بنیادوں کے نیچے تھے، جو بادشاہ سلیمان نے خداوند کے گھر میں بنائے تھے: ان تمام برتنوں کا پیتل بے وزن تھا۔ {دی برس: ہیب۔ ان کے پیتل}\n21۔ اور {ستونوں کے حوالے سے} ایک ستون کی اونچائی {تھی} اٹھارہ کیوبٹ؛ اور اس کے گرد بارہ کیوبٹ کا ایک فلیٹ تھا؛ اور اس کی موٹائی {چار انگلیاں} تھی: {یہ} کھوکھلی تھی۔ {فلیٹ: عبوری۔ تھریڈ}\n22۔ اور اس پر پیتل کا ایک چپیٹر تھا؛ اور ایک چپٹر کی اونچائی پانچ کیوبٹ تھی، جس کے گرد چپٹر پر جال اور انار تھے، سب پیتل کے۔ دوسرا ستون اور انار بھی ان جیسے تھے۔\n23۔ اور ایک طرف نوے اور چھ انار تھے؛ {اور} نیٹ ورک پر موجود تمام انار {سو کے ارد گرد تھے}۔\n24۔ اور محافظوں کے سردار نے سریاہ سردار کاہن، زفانیاہ دوسرے پادری کو، اور دروازے کے تین محافظوں کو لیا: {دروازہ: عبرانی۔ تھریش ہولڈ}\n25۔ اس نے شہر سے ایک خواجہ سرا کو بھی نکالا، جو جنگجوؤں کی نگرانی کرتا تھا؛ اور ان میں سے سات مرد جو بادشاہ کے قریب تھے، جو شہر میں ملے؛ اور فوج کا مرکزی کاتب، جو ملک کے لوگوں کو جمع کرتا تھا؛ اور اس ملک کے تین ساٹھ آدمی، جو شہر کے بیچ میں پائے گئے۔ {ہم قریب تھے...: عبرانی۔ بادشاہ کا چہرہ دیکھا} {پرنسپل...: یا، فوج کے کپتان کا کاتب}\n26۔ تو محافظوں کے کپتان نبوزاردان نے انہیں لے کر بابل کے بادشاہ کے پاس ربلہ لے آیا۔\n27۔ اور بابل کے بادشاہ نے انہیں شکست دی اور انہیں ربلہ میں حمات کی سرزمین میں قتل کر دیا۔ یوں یہوداہ کو اس کی سرزمین سے قیدی بنا لیا گیا۔\n28۔ یہ وہ لوگ ہیں جنہیں نبوکدرز نے قید کیا: ساتویں سال تین ہزار یہودی اور تین بیس:\n29۔ نبوکدرز کے اٹھارہویں سال میں اس نے یروشلم سے آٹھ سو تیس اور دو افراد کو قید کر لیا: {افراد: عبرانی۔ روحیں}\n30۔ نبوکدرززار کے تیسرے اور بیسویں سال میں محافظ نبوزاردان نے یہودیوں کے قیدی سات سو پینتالیس افراد کو اغوا کیا: تمام افراد چار ہزار چھ سو تھے۔\n31۔ اور یہ واقعہ یہوداہ کے بادشاہ یہویاکین کی قید کے ساتویں اور تیسویں سال میں، بارہویں مہینے میں، مہینے کے پانچویں اور بیسویں دن میں ہوا، کہ بابل کے بادشاہ ایول میروداخ نے اپنی حکومت کے پہلے سال میں یہوئخین بادشاہ یہوداہ کا سر اٹھایا اور اسے قید سے باہر نکالا۔\n32۔ اور اس سے مہربانی سے بات کی، اور اس کا تخت ان بادشاہوں کے تخت پر رکھ دیا جو بابل میں اس کے ساتھ تھے، {مہربانی سے...: عبرانی۔ اس کے ساتھ اچھی باتیں}\n33۔ اور قید خانے کے کپڑے بدلے: اور اپنی زندگی کے سارے دن اس کے سامنے روٹی کھاتا رہا۔\n34۔ اور اس کی خوراک کے لیے، بابل کے بادشاہ کی طرف سے اسے مسلسل خوراک دی جاتی تھی، ہر روز اس کی موت تک ایک حصہ دیا جاتا تھا، اس کی زندگی کے تمام دن۔ {ہر...: عبرانی۔ یہ اس کے دن کا معاملہ ہے}"];
